document.querySelectorAll('.app-bottombar .tab').forEach(tab=>{
  tab.addEventListener('click',(e)=>{

    // ripple
    let r=document.createElement('span');
    let rect=tab.getBoundingClientRect();
    let size=Math.max(rect.width,rect.height);

    r.className='nav-ripple';
    r.style.width=r.style.height=size+'px';
    r.style.left=(e.clientX-rect.left-size/2)+'px';
    r.style.top=(e.clientY-rect.top-size/2)+'px';

    tab.appendChild(r);
    setTimeout(()=>r.remove(),600);

    // active switch
    document.querySelectorAll('.app-bottombar .tab')
      .forEach(t=>t.classList.remove('active'));

    tab.classList.add('active');
  });
});

let lastScroll=0;

window.addEventListener('scroll',()=>{
  const bar=document.querySelector('.app-bottombar');
  let current=window.pageYOffset;

  if(!bar) return;

  if(current>lastScroll){
    bar.classList.add('hide');
  }else{
    bar.classList.remove('hide');
  }
  lastScroll=current;
});

/* swipe navigation removed: navigation now works only via menu clicks */
/* sync active page with showPage */
const oldShow = window.showPage;
if(oldShow){
  window.showPage = function(page){
    oldShow(page);
    document.querySelectorAll('.app-bottombar .tab')
      .forEach(t=>t.classList.remove('active'));

    const map={
      home:0,
      apk:1,
      shadowmenu:2,
      vipmenu:3
    };

    const tabs=document.querySelectorAll('.app-bottombar .tab');
    let idx=map[page];
    if(tabs[idx]){
      tabs[idx].classList.add('active');
    }

    window.ZUSMO&&window.ZUSMO.vibrate(20);
  }
}

