function bvToggleCard(card){
  var wasOpen = card.classList.contains('open');
  document.querySelectorAll('#bvPackageGrid .vpl-card.open').forEach(function(c){
    if(c !== card) c.classList.remove('open');
  });
  card.classList.toggle('open', !wasOpen);
  var label = card.querySelector('.vpl-more span');
  if(label) label.textContent = card.classList.contains('open') ? 'Sembunyikan' : 'Lihat manfaat';
}

