function bvOpenPayment(key){
  if(!bvSelectedPackage){
    bvToast('Pilih paket dulu.');
    bvGo('bvScreenPaket');
    return;
  }

  if(key === 'wa'){
    var msg = 'Halo Admin, saya mau order manual *VPN ZUSMO SHADOW*\n\n' +
      '📦 Paket : ' + bvSelectedPackage.name + '\n' +
      '⏳ Durasi : ' + bvSelectedPackage.durasi + '\n' +
      '💰 Harga : ' + bvSelectedPackage.price + '\n\n' +
      'Mohon dibantu proses pemesanan manual, terima kasih.';
    window.open('https://wa.me/' + VPNBUY_DATA.waNumber + '?text=' + encodeURIComponent(msg), '_blank', 'noopener');
    return;
  }

  bvSelectedMethod = VPNBUY_DATA.payments[key];
  bvPaymentStartedAt = Date.now();

  bv$('bvDetailPackage').textContent = bvSelectedPackage.name;
  bv$('bvDetailPrice').textContent = bvSelectedPackage.price;
  bv$('bvDetailMethod').textContent = bvSelectedMethod.label;

  var methodMeta = BV_METHOD_META[key] || { icon:'fa-wallet' };
  var iconEl = bv$('bvMethodIcon');
  iconEl.className = 'vpd-icon' + (methodMeta.cls ? ' ' + methodMeta.cls : '');
  iconEl.innerHTML = methodMeta.imgSrc
    ? '<img src="' + methodMeta.imgSrc + '" alt="' + bvSelectedMethod.label + '" onerror="this.style.display=\'none\'"/>'
    : '<i class="fa-solid ' + methodMeta.icon + '"></i>';

  bv$('bvQrisPanel').style.display = 'none';
  bv$('bvNumberPanel').style.display = 'none';
  bv$('bvLinkPanel').style.display = 'none';

  if(bvSelectedMethod.type === 'image'){
    var qrisImgEl = bv$('bvQrisImg');
    var qrisFallbackEl = bv$('bvQrisFallback');
    qrisImgEl.style.display = '';
    if(qrisFallbackEl) qrisFallbackEl.style.display = 'none';
    qrisImgEl.src = bvSelectedMethod.value;
    bv$('bvQrisLink').href = bvSelectedMethod.value;
    bv$('bvQrisPanel').style.display = 'block';
  }else if(bvSelectedMethod.type === 'links'){
    bv$('bvLinkPanel').style.display = 'block';
    if(bvSelectedMethod.value){
      bv$('bvWalletNumber').textContent = bvSelectedMethod.value;
      bv$('bvNumberPanel').style.display = 'block';
    }
  }else{
    bv$('bvWalletNumber').textContent = bvSelectedMethod.value;
    bv$('bvNumberPanel').style.display = 'block';
  }

  bvGo('bvScreenPayment');
}

function bvCopyText(text, successMessage){
  var value = String(text || '').trim();
  if(!value){ bvToast('Tidak ada data untuk disalin.'); return; }
  var fallback = function(){
    var ta = document.createElement('textarea');
    ta.value = value;
    ta.className = 'allow-copy';
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    ta.style.left = '-9999px';
    document.body.appendChild(ta);
    ta.focus(); ta.select(); ta.setSelectionRange(0, ta.value.length);
    try{ document.execCommand('copy'); bvToast(successMessage); }
    catch(e){ bvToast('Salin manual: ' + value); }
    ta.remove();
  };
  if(navigator.clipboard && window.isSecureContext){
    navigator.clipboard.writeText(value).then(function(){ bvToast(successMessage); }).catch(fallback);
  }else{ fallback(); }
}

