var BV_BACK_MAP = {
  bvScreenMethod: 'bvScreenPaket',
  bvScreenPayment: 'bvScreenMethod',
  bvScreenFailed: 'bvScreenPayment'
};

function bvHandleBack(){
  var activeScreen = bv$('vpnBuyRoot').querySelector('.vpnbuy-screen.active');
  var id = activeScreen ? activeScreen.id : null;
  var target = id ? BV_BACK_MAP[id] : null;
  if (target) {
    bvGo(target);
  } else {
    closeVpnBuyFlow();
  }
}

function bvBackDashboard(){
  var msg = bvSelectedPackage ? (bvSelectedPackage.name + ' berhasil aktif.') : undefined;
  closeVpnBuyFlow();
  if (typeof window.__zsBackToVpnDashboardAfterPurchase === 'function') {
    window.__zsBackToVpnDashboardAfterPurchase(msg);
  }
}

