// Wallpaper Zusmo Shadow VIP: ikut wallpaper yang lagi dipakai di aplikasi (default / wallpaper 1-30)
function vipWpApply(){
  var v = document.getElementById('vipWallpaperBg');
  if(!v) return;
  var src = (typeof window.__zsGetActiveWallpaperVideo === 'function') ? window.__zsGetActiveWallpaperVideo() : '';
  if(src){
    if(v.getAttribute('data-cur') !== src){
      v.setAttribute('data-cur', src);
      v.setAttribute('src', src);
      v.load();
    }
    v.play().catch(function(){});
  }else if(v.hasAttribute('src')){
    v.removeAttribute('src');
    v.removeAttribute('data-cur');
    v.load(); // balik nampilin poster (wallpaper default)
  }
}
function openVipShadowApp(){
  document.getElementById('vipAppRoot').classList.add('vipapp-show');
  vipWpApply();
}
function closeVipShadowApp(){
  document.getElementById('vipAppRoot').classList.remove('vipapp-show');
  var v = document.getElementById('vipWallpaperBg');
  if(v) v.pause();
}

(function(){
  function isExempt(el){
    while(el){
      if(el.nodeType===1){
        var tag=el.tagName;
        if(tag==='INPUT'||tag==='TEXTAREA') return true;
        if(el.isContentEditable) return true;
        if(el.classList && el.classList.contains('allow-copy')) return true;
      }
      el=el.parentNode;
    }
    return false;
  }
  document.addEventListener('contextmenu', function(e){
    if(isExempt(e.target)) return;
    e.preventDefault();
  }, false);
  document.addEventListener('dragstart', function(e){
    if(isExempt(e.target)) return;
    e.preventDefault();
  }, false);
  document.addEventListener('selectstart', function(e){
    if(isExempt(e.target)) return;
    e.preventDefault();
  }, false);
  document.addEventListener('copy', function(e){
    if(isExempt(e.target)) return;
    e.preventDefault();
  }, false);
})();

