const ZS_VERIFIED_ACCOUNT_KEY='zsVerifiedAccount';
function zsSaveVerifiedAccount(uid,serverCode,nickname){
  try{
    const serverObj=vplServers.find(s=>s.code===serverCode)||vplServers[0];
    localStorage.setItem(ZS_VERIFIED_ACCOUNT_KEY,JSON.stringify({
      uid:uid,
      server:serverObj.code,
      serverFlag:serverObj.flag,
      serverName:serverObj.name,
      nickname:nickname,
      ts:Date.now()
    }));
  }catch(e){}
}
function zsGetVerifiedAccount(){
  try{
    const raw=localStorage.getItem(ZS_VERIFIED_ACCOUNT_KEY);
    return raw?JSON.parse(raw):null;
  }catch(e){ return null; }
}
