function sendProofToEmailJs(params){
  if(typeof emailjs==='undefined') return Promise.reject(new Error('emailjs belum siap'));
  return emailjs.send(PROOF_EMAILJS_SERVICE_ID, PROOF_EMAILJS_TEMPLATE_ID, params);
}
