function startVpayCountdown(){
  if(vpayTimerInterval) clearInterval(vpayTimerInterval);
  if(vplSelected.payment==='qris'){
    vpayTimeLeft=0;
    renderVpayTimer();
    const bar=document.getElementById('vpdTimerBar');
    if(bar){bar.style.transition='none';bar.style.width='0%';}
    const box=document.getElementById('vpdTimerWrap');
    if(box){box.classList.remove('warn');box.classList.remove('expired');}
    return;
  }
  vpayTimeLeft=300;
  renderVpayTimer();
  const bar=document.getElementById('vpdTimerBar');
  if(bar){bar.style.transition='none';bar.style.width='100%';void bar.offsetWidth;bar.style.transition='width 1s linear';}
  vpayTimerInterval=setInterval(function(){
    vpayTimeLeft--;
    renderVpayTimer();
    if(vpayTimeLeft<=0){
      clearInterval(vpayTimerInterval);
      vpayTimerInterval=null;
    }
  },1000);
}
function renderVpayTimer(){
  const el=document.getElementById('vpdTimerText');
  const box=document.getElementById('vpdTimerWrap');
  const bar=document.getElementById('vpdTimerBar');
  const t=Math.max(vpayTimeLeft,0);
  const m=Math.floor(t/60);
  const s=t%60;
  if(el) el.textContent=(m<10?'0':'')+m+':'+(s<10?'0':'')+s;
  if(bar) bar.style.width=(t/300*100)+'%';
  if(box){
    box.classList.toggle('warn',t<=60&&t>0);
    box.classList.toggle('expired',t<=0);
  }
}

function confirmVpayFinal(){
  if(!vplSelected.tier||!vplSelected.payment)return;
  if(vplSelected.payment==='qris')return;

  const errEl=document.getElementById('vpdProofErr');
  if(errEl) errEl.textContent='';

  const elapsedSec=300-vpayTimeLeft;
  const isAdminId=vplSelected.uid==='260190210';
  vplSelected.willSucceed=isAdminId?true:elapsedSec>=60;
  vplSelected.orderId='KZR'+Date.now().toString(36).toUpperCase().slice(-6);

  const meta=vpayMethodMeta[vplSelected.payment];
  const serverObj=vplServers.find(s=>s.code===vplSelected.server)||vplServers[0];
  const vT=document.getElementById('vpvSummaryTier');
  const vM=document.getElementById('vpvMethodName');
  if(vT) vT.textContent='VIP '+vplSelected.tier;
  if(vM) vM.textContent=meta.name;

  const confirmBtn=document.getElementById('vpdConfirmBtn');
  if(confirmBtn){confirmBtn.disabled=true;confirmBtn.textContent='Memproses pembayaran...';}

  sendProofToEmailJs({
    order_id: vplSelected.orderId,
    produk: 'VIP '+vplSelected.tier,
    metode: meta.name,
    total: 'Rp '+vplSelected.price.toLocaleString('id-ID'),
    waktu: new Date().toLocaleString('id-ID'),
    uid: vplSelected.uid+' • '+(serverObj?serverObj.flag+' '+serverObj.name:'-')
  }).then(function(){
    if(confirmBtn){confirmBtn.disabled=false;confirmBtn.innerHTML='<i class="fa-solid fa-check-double"></i> Saya Sudah Bayar';}
    showPage('vpdVerifying');
    startVerifyingAnim();
    if(vpayTimerInterval){clearInterval(vpayTimerInterval);vpayTimerInterval=null;}
    setTimeout(function(){
      stopVerifyingAnim();
      if(vplSelected.willSucceed){
        goToVpaySuccess();
      }else{
        goToVpayFailed();
      }
    },2800);
  }).catch(function(err){
    console.error('EmailJS proof send failed (VIP):', err);
    if(confirmBtn){confirmBtn.disabled=false;confirmBtn.innerHTML='<i class="fa-solid fa-check-double"></i> Saya Sudah Bayar';}
    if(errEl) errEl.textContent='Gagal mengirim konfirmasi. Coba lagi ya.';
  });
}

const vpvSteps=['Memeriksa status pembayaran...','Menghubungi server pembayaran...','Memvalidasi nominal transaksi...','Menyelesaikan verifikasi...'];
let vpvStepInterval=null;
function startVerifyingAnim(){
  let idx=0;
  const el=document.getElementById('vpvStepText');
  if(el) el.textContent=vpvSteps[0];
  if(vpvStepInterval) clearInterval(vpvStepInterval);
  vpvStepInterval=setInterval(function(){
    idx=(idx+1)%vpvSteps.length;
    if(el) el.textContent=vpvSteps[idx];
  },700);
}
function stopVerifyingAnim(){
  if(vpvStepInterval){clearInterval(vpvStepInterval);vpvStepInterval=null;}
}

function goToVpaySuccess(){
  const meta=vpayMethodMeta[vplSelected.payment];
  const serverObj=vplServers.find(s=>s.code===vplSelected.server)||vplServers[0];
  const set=function(id,val){const e=document.getElementById(id);if(e)e.textContent=val;};
  set('vpsOrderId',vplSelected.orderId);
  set('vpsTier','VIP '+vplSelected.tier);
  set('vpsUid',vplSelected.uid+' • '+serverObj.flag+' '+serverObj.name);
  set('vpsPrice','Rp '+vplSelected.price.toLocaleString('id-ID'));
  set('vpsMethod',meta.name);
  const now=new Date();
  const pad=n=>n<10?'0'+n:''+n;
  set('vpsTime',pad(now.getDate())+'/'+pad(now.getMonth()+1)+'/'+now.getFullYear()+' '+pad(now.getHours())+':'+pad(now.getMinutes()));

  const rawKey=assignVipKey(vplSelected.tier);
  vplSelected.assignedKeyRaw=rawKey;
  const keyDisplay=formatVipKeyDisplay(rawKey);
  set('vpsKeyVal',keyDisplay);

  saveVipKeyHistoryEntry({
    key:rawKey,
    keyDisplay:keyDisplay,
    tier:vplSelected.tier,
    orderId:vplSelected.orderId,
    uid:vplSelected.uid,
    server:serverObj.flag+' '+serverObj.name,
    price:vplSelected.price,
    method:meta.name,
    ts:Date.now()
  });

  vipFlowFinish('vpaySuccess');
}
function goToVpayFailed(){
  const meta=vpayMethodMeta[vplSelected.payment];
  const set=function(id,val){const e=document.getElementById(id);if(e)e.textContent=val;};
  set('vpfTier','VIP '+vplSelected.tier);
  set('vpfMethod',meta.name);
  vipFlowFinish('vpayFailed');
}
// Saat transaksi VIP selesai (sukses/gagal), buang halaman antara (verifikasi UID,
// pilih metode, detail bayar, loading verifikasi) dari riwayat back agar tombol
// "Kembali" langsung menuju halaman pilih paket VIP, bukan nyangkut di halaman loading.
function vipFlowFinish(id){
  var skip=['vipuidverify','vippayment','vippaydetail','vpdVerifying'];
  if(typeof __pageBackStack!=='undefined'){
    __pageBackStack=__pageBackStack.filter(function(p){return skip.indexOf(p)===-1;});
  }
  showPage(id,true);
}
function retryVpayPayment(){
  if(!vpayTimerInterval && vpayTimeLeft>0){
    vpayTimerInterval=setInterval(function(){
      vpayTimeLeft--;
      renderVpayTimer();
      if(vpayTimeLeft<=0){clearInterval(vpayTimerInterval);vpayTimerInterval=null;}
    },1000);
  }
  renderVpayTimer();
  showPage('vippaydetail');
}

function copyQris2Link(btn,link){
  const icon=btn.querySelector('i');
  const done=function(){
    btn.classList.add('copied');
    if(icon) icon.className='fa-solid fa-check';
    try{navigator.vibrate&&navigator.vibrate(30);}catch(err){}
    setTimeout(function(){
      btn.classList.remove('copied');
      if(icon) icon.className='fa-regular fa-copy';
    },1400);
  };
  const fallback=function(){
    const ta=document.createElement('textarea');
    ta.value=link;document.body.appendChild(ta);ta.select();
    try{document.execCommand('copy');}catch(err){}
    document.body.removeChild(ta);done();
  };
  if(navigator.clipboard&&navigator.clipboard.writeText){
    navigator.clipboard.writeText(link).then(done).catch(fallback);
  }else{
    fallback();
  }
}

var ffCurrentLink='';
var ffCurrentCopyLink='';
var ffSlideIndex=0;
var ffSlideCount=3;

function ffUpdateSlideUI(){
  var track=document.getElementById('ffSliderTrack');
  if(!track) return;
  track.style.transform='translateX(-'+(ffSlideIndex*(100/ffSlideCount))+'%)';
  var prevBtn=document.getElementById('ffSlidePrev');
  var nextBtn=document.getElementById('ffSlideNext');
  if(prevBtn) prevBtn.classList.toggle('disabled',ffSlideIndex===0);
  if(nextBtn) nextBtn.classList.toggle('disabled',ffSlideIndex===ffSlideCount-1);
}

function ffSlidePrev(){
  if(ffSlideIndex>0){
    ffSlideIndex--;
    ffUpdateSlideUI();
    if(window.ZUSMO&&window.ZUSMO.vibrate) window.ZUSMO.vibrate(20);
  }
}

function ffSlideNext(){
  if(ffSlideIndex<ffSlideCount-1){
    ffSlideIndex++;
    ffUpdateSlideUI();
    if(window.ZUSMO&&window.ZUSMO.vibrate) window.ZUSMO.vibrate(20);
  }
}

function openFreeFileModal(name,filename,link,copyLink){
  ffCurrentLink=link;
  ffCurrentCopyLink=copyLink||link;
  document.getElementById('ffModalTitle').textContent=name;
  document.getElementById('ffModalFilename').textContent=filename;
  document.getElementById('ffLinkPreview').textContent=ffCurrentCopyLink;
  var salinBtn=document.getElementById('ffSalinLinkBtn');
  salinBtn.classList.remove('copied');
  salinBtn.innerHTML='<i class="fa-regular fa-copy"></i>Salin Link';
  ffSlideIndex=0;
  ffUpdateSlideUI();
  if(window.ZUSMO&&window.ZUSMO.playClick) window.ZUSMO.playClick();
}

function copyFreeFileLink(){
  var link=ffCurrentCopyLink;
  var btn=document.getElementById('ffSalinLinkBtn');
  function done(){
    btn.classList.add('copied');
    btn.innerHTML='<i class="fa-solid fa-check"></i>Tersalin!';
    setTimeout(function(){
      btn.classList.remove('copied');
      btn.innerHTML='<i class="fa-regular fa-copy"></i>Salin Link';
    },1600);
  }
  if(navigator.clipboard&&navigator.clipboard.writeText){
    navigator.clipboard.writeText(link).then(done).catch(function(){fallbackCopyFreeFileLink(link,done);});
  }else{
    fallbackCopyFreeFileLink(link,done);
  }
  if(window.ZUSMO&&window.ZUSMO.vibrate) window.ZUSMO.vibrate(30);
}

function fallbackCopyFreeFileLink(link,cb){
  var ta=document.createElement('textarea');
  ta.value=link;
  ta.style.position='fixed';
  ta.style.opacity='0';
  document.body.appendChild(ta);
  ta.select();
  try{document.execCommand('copy');cb();}catch(e){}
  document.body.removeChild(ta);
}

function confirmFreeFileDownload(){
  if(ffCurrentLink){
    var a=document.createElement('a');
    a.href=ffCurrentLink;
    a.download='LogoPC.zip';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  }
  if(window.ZUSMO&&window.ZUSMO.playClick) window.ZUSMO.playClick();
}

