let qrgenInstance=null;
const QRGEN_COST=30;

function qrgenUpdateColorPreview(){
  const dark=document.getElementById('qrgenDarkColor').value;
  const light=document.getElementById('qrgenLightColor').value;
  document.getElementById('qrgenDarkPreview').style.background=dark;
  document.getElementById('qrgenLightPreview').style.background=light;
  document.getElementById('qrgenDarkText').textContent=dark.toUpperCase();
  document.getElementById('qrgenLightText').textContent=light.toUpperCase();
}
document.getElementById('qrgenDarkColor').addEventListener('input',qrgenUpdateColorPreview);
document.getElementById('qrgenLightColor').addEventListener('input',qrgenUpdateColorPreview);

function qrgenShake(el){
  if(!el)return;
  el.classList.remove('shake');
  void el.offsetWidth;
  el.classList.add('shake');
}

function qrgenGenerate(){
  const inp=document.getElementById('qrgenText');
  const text=inp?inp.value.trim():'';
  if(!text){ qrgenShake(inp); return; }
  if(!cidPreCheckDiamond(QRGEN_COST,'qrgenBtn')) return;
  cidDeductDiamond(QRGEN_COST,'QR Generator','Teks/link: '+text.slice(0,60));

  const size=parseInt(document.getElementById('qrgenSize').value);
  const dark=document.getElementById('qrgenDarkColor').value;
  const light=document.getElementById('qrgenLightColor').value;

  const box=document.getElementById('qrgenCanvasBox');
  box.innerHTML='';

  qrgenInstance=new QRCode(box,{
    text:text,
    width:size,
    height:size,
    colorDark:dark,
    colorLight:light,
    correctLevel:QRCode.CorrectLevel.H
  });

  document.getElementById('qrgenResult').classList.add('show');
  const dlBtn=document.getElementById('qrgenDownloadBtn');
  dlBtn.style.display='none';

  setTimeout(()=>{
    const canvas=box.querySelector('canvas');
    if(canvas) dlBtn.style.display='flex';
  },600);
}

function qrgenDownload(){
  const canvas=document.querySelector('#qrgenCanvasBox canvas');
  if(!canvas){ alert('QR Code belum dibuat!'); return; }

  try{
    const borderSize=35;
    const scaleFactor=2;

    const finalCanvas=document.createElement('canvas');
    finalCanvas.width=(canvas.width*scaleFactor)+(borderSize*2);
    finalCanvas.height=(canvas.height*scaleFactor)+(borderSize*2);

    const ctx=finalCanvas.getContext('2d');
    ctx.imageSmoothingEnabled=false;
    ctx.fillStyle='#ffffff';
    ctx.fillRect(0,0,finalCanvas.width,finalCanvas.height);
    ctx.drawImage(canvas,borderSize,borderSize,canvas.width*scaleFactor,canvas.height*scaleFactor);

    finalCanvas.toBlob(function(blob){
      if(!blob){ alert('Gagal membuat gambar!'); return; }
      const blobUrl=URL.createObjectURL(blob);
      const link=document.createElement('a');
      link.href=blobUrl;
      link.download='KZRIZUSMO-QR-'+Date.now()+'.png';
      link.click();
      URL.revokeObjectURL(blobUrl);
    },'image/png',1.0);
  }catch(err){
    alert('Download gagal, coba lagi!');
  }
}

