function saiHideSuggest(){
  const box=document.getElementById('saiSuggest');
  if(box){ box.classList.remove('show'); box.innerHTML=''; }
}

function saiFilterDevice(){
  const inp=document.getElementById('saiDevice');
  const box=document.getElementById('saiSuggest');
  if(!inp||!box) return;
  const q=inp.value.trim().toLowerCase();
  if(!q){ saiHideSuggest(); return; }

  const matches=SAI_DEVICES.filter(d=>d.toLowerCase().includes(q)).slice(0,8);
  if(!matches.length){
    box.innerHTML='<div class="sai-suggest-empty">Device tidak ditemukan, tetap bisa generate manual</div>';
    box.classList.add('show');
    return;
  }

  box.innerHTML=matches.map(d=>
    '<div class="sai-suggest-item" onmousedown="saiPickDevice(\''+d.replace(/'/g,"\\'")+'\')"><i class="fa-solid fa-mobile-screen-button"></i>'+d+'</div>'
  ).join('');
  box.classList.add('show');
}

function saiPickDevice(name){
  const inp=document.getElementById('saiDevice');
  if(inp) inp.value=name;
  saiHideSuggest();
}

const SAI_CATEGORIES=[
  {key:'general',label:'Lihat Sekeliling',icon:'fa-eye'},
  {key:'reddot',label:'Red Dot Sight',icon:'fa-dot-circle'},
  {key:'scope2x',label:'2× Scope',icon:'fa-circle-dot'},
  {key:'scope4x',label:'4× Scope',icon:'fa-bullseye'},
  {key:'sniper',label:'Sniper Scope',icon:'fa-crosshairs'},
  {key:'freelook',label:'Tombol Kamera Bebas',icon:'fa-camera-rotate'}
];
const SAI_SENS_MAX=200;
const SAI_DPI_MIN=400;
const SAI_DPI_MAX=800;
let saiLastResult=null;

function saiShake(el){
  if(!el)return;
  el.classList.remove('shake');
  void el.offsetWidth;
  el.classList.add('shake');
}

function saiSeedFromDevice(device){
  // FNV-1a hash -> angka seed yang konsisten untuk teks device yang sama
  const str=device.trim().toLowerCase();
  let h=2166136261;
  for(let i=0;i<str.length;i++){
    h^=str.charCodeAt(i);
    h=Math.imul(h,16777619);
  }
  return h>>>0;
}
function saiMakeRng(seed){
  // mulberry32: PRNG deterministik dari seed
  let a=seed;
  return function(){
    a|=0;a=a+0x6D2B79F5|0;
    let t=Math.imul(a^a>>>15,1|a);
    t=t+Math.imul(t^t>>>7,61|t)^t;
    return ((t^t>>>14)>>>0)/4294967296;
  };
}
function saiRandomVal(rng){
  return Math.floor(rng()*(SAI_SENS_MAX+1)); // 0-200
}
function saiRandomDpi(rng){
  return Math.floor(SAI_DPI_MIN+rng()*(SAI_DPI_MAX-SAI_DPI_MIN+1)); // 400-800
}

function saiRenderItems(values){
  const box=document.getElementById('saiItemsBox');
  box.innerHTML=SAI_CATEGORIES.map(cat=>{
    const val=values[cat.key];
    const pct=(val/SAI_SENS_MAX)*100;
    return '<div class="sai-item">'
      +'<div class="sai-item-top">'
        +'<div class="sai-item-name"><i class="fa-solid '+cat.icon+'"></i>'+cat.label+'</div>'
        +'<div class="sai-item-val">'+val+'</div>'
      +'</div>'
      +'<div class="sai-bar">'
        +'<div class="sai-bar-fill" style="width:'+pct+'%;"></div>'
        +'<div class="sai-bar-dot" style="left:'+pct+'%;"></div>'
      +'</div>'
    +'</div>';
  }).join('');
}

function saiRenderDpi(dpi){
  const box=document.getElementById('saiDpiBox');
  box.innerHTML='<div class="sai-dpi-item">'
    +'<div class="sai-item-name"><i class="fa-solid fa-satellite-dish"></i>DPI</div>'
    +'<div class="sai-item-val">'+dpi+'</div>'
  +'</div>';
}

function saiGenerate(){
  const inp=document.getElementById('saiDevice');
  const device=inp?inp.value.trim():'';
  if(!device){ saiShake(inp); return; }
  saiHideSuggest();

  const SAI_COST=150;
  const btn=document.getElementById('saiBtn');
  if(typeof window.getDiamond!=='function' || typeof window.setDiamond!=='function'){ return; }
  if(window.getDiamond() < SAI_COST){
    if(btn){
      btn.classList.remove('shake'); void btn.offsetWidth; btn.classList.add('shake');
      setTimeout(function(){ btn.classList.remove('shake'); },550);
    }
    if(typeof window.zxShowToast==='function') window.zxShowToast('Diamond kamu tidak cukup (butuh 150, saldo: '+window.getDiamond()+')','error');
    if(window.ZUSMO && window.ZUSMO.playClick) window.ZUSMO.playClick();
    return;
  }
  window.setDiamond(window.getDiamond() - SAI_COST);
  if(typeof window.addHistoryEntry==='function') window.addHistoryEntry('buy','Generate Sensi AI','Sensitivitas AI: '+device,-SAI_COST);

  const loading=document.getElementById('saiLoading');
  const result=document.getElementById('saiResult');

  result.classList.remove('show');
  loading.classList.add('show');
  btn.disabled=true;
  btn.dataset.origHtml=btn.innerHTML;
  btn.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> MEMPROSES...';

  const duration=3000+Math.floor(Math.random()*3001); // 3-6 detik acak

  setTimeout(()=>{
    const rng=saiMakeRng(saiSeedFromDevice(device));
    const values={};
    SAI_CATEGORIES.forEach(cat=>{ values[cat.key]=saiRandomVal(rng); });
    const dpi=saiRandomDpi(rng);

    saiLastResult={device,values,dpi};
    document.getElementById('saiResultDevice').textContent=device;
    saiRenderItems(values);
    saiRenderDpi(dpi);

    loading.classList.remove('show');
    result.classList.add('show');
    btn.disabled=false;
    if(btn.dataset.origHtml) btn.innerHTML=btn.dataset.origHtml;
  },duration);
}

/* ============================================================================
   XYUREI API KEY — dipakai bareng oleh semua fitur yang lewat
   sylvatica.my.id: AI Chat, Game, Islam, Komiku, dan Sosmed Downloader.
   ============================================================================ */
const XYUREI_API_KEY='kzrizusmo';

// Menilai apakah sebuah respons dianggap gagal (limit/invalid/error server)
// untuk apiKey yang sedang dipakai, sehingga harus lanjut ke apiKey berikutnya.
function xyureiIsFailure(res,json){
  if(res&&!res.ok) return true; // HTTP non-2xx (401/403/429/5xx dst) -> key ini bermasalah
  if(json&&typeof json==='object'){
    if(json.status===false||json.status==='false'||json.success===false) return true;
    const msg=String(json.message||json.msg||json.error||'').toLowerCase();
    if(msg&&/limit|quota|kuota|habis|apikey|api key|unauthorized|invalid.*key|expired|forbidden/.test(msg)) return true;
  }
  return false;
}

/* zsFetchTimeout(url,options,ms)
   - fetch() biasa TIDAK punya batas waktu bawaan: kalau server/proxy hang (bukan error,
     cuma diem gak respon), request bisa "loading" sampai lama banget / kelihatan macet.
     Helper ini bungkus fetch() pakai AbortController supaya kalau lewat `ms` milidetik
     belum juga dapat respons, request langsung dibatalkan (dianggap gagal) dan lanjut
     ke fallback berikutnya, bukan nunggu tanpa kepastian. */
function zsFetchTimeout(url,options,ms){
  options=options||{};
  ms=ms||12000;
  const ctrl=new AbortController();
  const timer=setTimeout(function(){ ctrl.abort(); },ms);
  return fetch(url,Object.assign({},options,{signal:ctrl.signal})).finally(function(){ clearTimeout(timer); });
}

/* xyureiRequest(pathBuilder, opts)
   - pathBuilder(key): (string apiKey)=>URL lengkap dengan apikey itu terpasang.
   - opts.isDataOk(json): opsional, validasi tambahan (mis. "media ketemu?").
   - Fetch langsung dulu, fallback proxy kalau fetch langsung gagal
     (mis. karena CORS/jaringan). Melempar error kalau tetap gagal. */
async function xyureiRequest(pathBuilder,opts){
  opts=opts||{};
  const url=pathBuilder(XYUREI_API_KEY);
  let lastDetail='Tidak ada detail (belum sempat request).';
  let usedProxy=false;
  try{
    let res,text;
    try{
      res=await zsFetchTimeout(url,{method:(opts.method||'GET'),headers:{'Accept':'application/json'}},12000);
      text=await res.text();
    }catch(networkErr){
      usedProxy=true;
      console.warn('[xyurei] fetch langsung gagal/timeout (kemungkinan CORS/jaringan), coba proxy allorigins:',url,networkErr);
      try{
        res=await zsFetchTimeout('https://api.allorigins.win/raw?url='+encodeURIComponent(url),{},12000);
        text=await res.text();
      }catch(proxyErr){
        console.warn('[xyurei] proxy allorigins juga gagal/timeout, coba proxy corsproxy.io:',proxyErr);
        try{
          res=await zsFetchTimeout('https://corsproxy.io/?url='+encodeURIComponent(url),{},12000);
          text=await res.text();
        }catch(proxy2Err){
          lastDetail='Fetch langsung GAGAL ('+((networkErr&&networkErr.message)||networkErr)+'), proxy allorigins GAGAL ('+((proxyErr&&proxyErr.message)||proxyErr)+'), dan proxy corsproxy.io JUGA gagal ('+((proxy2Err&&proxy2Err.message)||proxy2Err)+').';
          console.error('[xyurei] semua proxy gagal:',proxy2Err);
          const finalErr=new Error(proxy2Err&&proxy2Err.message||'Semua metode fetch gagal.');
          finalErr.debugDetail=lastDetail;
          throw finalErr;
        }
      }
    }
    let json=null;
    try{ json=JSON.parse(text); }catch(parseErr){
      lastDetail='HTTP '+(res&&res.status)+' ('+(usedProxy?'via proxy':'langsung')+'). Respons BUKAN JSON valid. Cuplikan: '+String(text).slice(0,180);
      console.warn('[xyurei]',lastDetail);
    }
    if(xyureiIsFailure(res,json)){
      const apiMsg=json&&(json.error||json.message||json.msg);
      lastDetail='HTTP '+(res&&res.status)+' ('+(usedProxy?'via proxy':'langsung')+'). Request gagal/limit.'+(apiMsg?' Pesan API: '+apiMsg:' (tidak ada pesan dari API)');
      console.warn('[xyurei]',lastDetail,'url:',url,'json:',json);
      const finalErr=new Error('Request gagal atau limit.');
      finalErr.debugDetail=lastDetail;
      throw finalErr;
    }
    if(json===null){
      const finalErr=new Error('Respons bukan JSON');
      finalErr.debugDetail=lastDetail;
      throw finalErr;
    }
    if(opts.isDataOk&&!opts.isDataOk(json)){
      lastDetail='HTTP '+(res&&res.status)+'. Respons JSON valid tapi dianggap "tidak ada data" oleh isDataOk check.';
      const finalErr=new Error('Data tidak ditemukan');
      finalErr.debugDetail=lastDetail;
      throw finalErr;
    }
    return json;
  }catch(e){
    if(e&&e.debugDetail) throw e;
    lastDetail='Exception tak terduga: '+((e&&e.message)||e);
    console.error('[xyurei] exception saat fetch (bisa jadi CORS/blocked/proxy down):',url,e);
    const finalErr=new Error((e&&e.message)||'Request gagal.');
    finalErr.debugDetail=lastDetail;
    throw finalErr;
  }
}

/* ============================================================================
   FALLBACK API (api-xyurei.my.id) — KHUSUS untuk Sosmed Downloader AIO,
   Facebook, Threads, Pinterest, Mediafire, Spotify.
   Default utama TETAP sylvatica.my.id dengan 1 apiKey 'kzrizusmo' (lewat
   xyureiRequest di atas). Kalau request ke sylvatica.my.id gagal/limit,
   otomatis lanjut coba salah satu dari 10 apiKey xyurei di bawah ini
   (urutan diacak tiap kali request) di base https://api-xyurei.my.id/api
   sampai salah satu berhasil, atau berhenti kalau semuanya gagal juga.
   ============================================================================ */
const XYUREI_FALLBACK_BASE='https://api-xyurei.my.id/api';
const XYUREI_FALLBACK_KEYS=[
  'xyureifree-139c2','xyureifree-0ffcc','xyureifree-2cd85','xyureifree-264fb','xyureifree-f912f',
  'xyureifree-3aeac','xyureifree-7eef6','xyureifree-07fb7','xyureifree-8c291','xyureifree-68556'
];

// Fisher-Yates shuffle: urutan percobaan apiKey fallback diacak tiap kali dipanggil
function xyureiFallbackShuffledKeys(){
  const arr=XYUREI_FALLBACK_KEYS.slice();
  for(let i=arr.length-1;i>0;i--){
    const j=Math.floor(Math.random()*(i+1));
    const tmp=arr[i]; arr[i]=arr[j]; arr[j]=tmp;
  }
  return arr;
}

/* smdlDownloadRequest(endpoint,url,opts)
   - endpoint: nama endpoint setelah /api/download/ (mis. 'fbdl','aio-downloader','threads', dst)
   - url: link yang mau didownload user (akan di-encode otomatis)
   - opts.isDataOk(json): optional, validasi tambahan (mis. "media ketemu?")
   - Coba dulu sylvatica.my.id (apiKey default 'kzrizusmo') via xyureiRequest.
     Kalau gagal/limit, baru coba tiap apiKey xyurei (acak) di api-xyurei.my.id
     satu-satu sampai ada yang berhasil. Melempar error kalau SEMUA (sylvatica +
     10 apiKey xyurei) sudah dicoba dan tetap gagal. */
async function smdlDownloadRequest(endpoint,url,opts){
  opts=opts||{};
  const query='?url='+encodeURIComponent(url)+'&apikey=';
  try{
    return await xyureiRequest(function(key){
      return 'https://sylvatica.my.id/api/download/'+endpoint+query+key;
    },opts);
  }catch(primaryErr){
    console.warn('[SMDL] sylvatica.my.id gagal/limit untuk endpoint "'+endpoint+'", coba fallback api-xyurei.my.id...',primaryErr);
    const keys=xyureiFallbackShuffledKeys();
    let lastErr=primaryErr;
    for(let i=0;i<keys.length;i++){
      const key=keys[i];
      const fbUrl=XYUREI_FALLBACK_BASE+'/download/'+endpoint+query+key;
      try{
        let res,text,usedProxy=false;
        try{
          res=await zsFetchTimeout(fbUrl,{headers:{'Accept':'application/json'}},10000);
          text=await res.text();
        }catch(networkErr){
          usedProxy=true;
          res=await zsFetchTimeout('https://api.allorigins.win/raw?url='+encodeURIComponent(fbUrl),{},10000);
          text=await res.text();
        }
        let json=null;
        try{ json=JSON.parse(text); }catch(parseErr){
          lastErr=new Error('Respons fallback bukan JSON valid.');
          console.warn('[SMDL][fallback]',lastErr.message,'url:',fbUrl,'usedProxy:',usedProxy);
          continue;
        }
        if(xyureiIsFailure(res,json)){
          lastErr=new Error('apiKey fallback gagal/limit.');
          console.warn('[SMDL][fallback]',lastErr.message,'url:',fbUrl);
          continue;
        }
        if(opts.isDataOk&&!opts.isDataOk(json)){
          lastErr=new Error('Data tidak ditemukan (fallback).');
          continue;
        }
        return json;
      }catch(e){
        lastErr=e; console.warn('[SMDL][fallback] exception:',fbUrl,e); continue;
      }
    }
    console.error('[SMDL] SEMUA sumber gagal (sylvatica.my.id + 10 apiKey xyurei) untuk endpoint "'+endpoint+'".');
    throw lastErr;
  }
}

/* aiEndpointFallbackRequest(endpointPath,queryBuilder,opts)
   - endpointPath: nama endpoint setelah /api/ai/ (mis. 'tts')
   - queryBuilder(key): fungsi yang mengembalikan query string (diawali '?'), berisi apikey=key
   - Coba dulu sylvatica.my.id (apiKey default 'kzrizusmo') via xyureiRequest. Kalau gagal/limit,
     baru coba tiap apiKey xyurei (acak) di api-xyurei.my.id satu-satu sampai ada yang berhasil.
     Dipakai supaya fitur AI generatif (mis. Text to Speech) tidak langsung "mati total" hanya
     karena satu sumber sedang down/limit — sama seperti pola fallback di smdlDownloadRequest. */
async function aiEndpointFallbackRequest(endpointPath,queryBuilder,opts){
  opts=opts||{};
  try{
    return await xyureiRequest(function(key){
      return 'https://sylvatica.my.id/api/ai/'+endpointPath+queryBuilder(key);
    },opts);
  }catch(primaryErr){
    console.warn('[AI-FB] sylvatica.my.id gagal/limit/timeout untuk endpoint "'+endpointPath+'", coba fallback api-xyurei.my.id...',primaryErr);
    const keys=xyureiFallbackShuffledKeys().slice(0,4); // cukup 4 key biar gak numpuk lama
    let lastErr=primaryErr;
    for(let i=0;i<keys.length;i++){
      const key=keys[i];
      const fbUrl=XYUREI_FALLBACK_BASE+'/ai/'+endpointPath+queryBuilder(key);
      try{
        let res,text;
        try{
          res=await zsFetchTimeout(fbUrl,{headers:{'Accept':'application/json'}},8000);
          text=await res.text();
        }catch(networkErr){
          res=await zsFetchTimeout('https://api.allorigins.win/raw?url='+encodeURIComponent(fbUrl),{},8000);
          text=await res.text();
        }
        let json=null;
        try{ json=JSON.parse(text); }catch(parseErr){
          lastErr=new Error('Respons fallback bukan JSON valid.');
          console.warn('[AI-FB][fallback]',lastErr.message,'url:',fbUrl);
          continue;
        }
        if(xyureiIsFailure(res,json)){
          lastErr=new Error('apiKey fallback gagal/limit.');
          console.warn('[AI-FB][fallback]',lastErr.message,'url:',fbUrl);
          continue;
        }
        if(opts.isDataOk&&!opts.isDataOk(json)){
          lastErr=new Error('Data tidak ditemukan (fallback).');
          continue;
        }
        return json;
      }catch(e){
        lastErr=e; console.warn('[AI-FB][fallback] exception:',fbUrl,e); continue;
      }
    }
    console.error('[AI-FB] SEMUA sumber gagal (sylvatica.my.id + 10 apiKey xyurei) untuk endpoint "'+endpointPath+'".');
    throw lastErr;
  }
}

