  claude:{kind:'claude',label:'Claude Sonnet'},
  deepai:{kind:'deepai',label:'Deep AI'},
  gpt5:{kind:'simpleq',endpoint:'gpt5',label:'GPT-5'},
  deepsek:{kind:'simpleq',endpoint:'deepsek',label:'DeepSeek AI'},
  feeb:{kind:'sessionq',endpoint:'feeb',sessKey:'feebSession',label:'Feel Better Bot'},
  gptanon:{kind:'sessionq',endpoint:'gptanon',sessKey:'gptanonSession',label:'GPTAnon AI'},
