/* ── CHIP PILIHAN CEPAT: rasio, model, dll — pengganti input teks bebas ── */
function aicSelectChip(el){
  const group=el.closest('.aic-chipgroup');
  if(!group) return;
  const target=document.getElementById(group.getAttribute('data-target'));
  const wasActive=el.classList.contains('active');
  group.querySelectorAll('.aic-chip').forEach(function(c){ c.classList.remove('active'); });
  if(wasActive){
    if(target){ target.value=''; if(target.type==='text'){ target.style.display='none'; } }
    return;
  }
  el.classList.add('active');
  if(target){
    target.value=el.getAttribute('data-value')||'';
    if(target.type==='text'){ target.style.display='none'; }
  }
}

function aicSyncChipGroup(groupId,value){
  const group=document.getElementById(groupId);
  if(!group) return;
  const target=document.getElementById(group.getAttribute('data-target'));
  let matched=false;
  group.querySelectorAll('.aic-chip').forEach(function(c){
    const isMatch=c.getAttribute('data-value')===value&&c.getAttribute('data-value')!=='__custom__';
    c.classList.toggle('active',isMatch);
    if(isMatch) matched=true;
  });
  if(target){
    target.value=value||'';
    if(target.type==='text') target.style.display=matched?'none':'block';
  }
  if(!matched&&value){
    const customChip=group.querySelector('.aic-chip-custom');
    if(customChip) customChip.classList.add('active');
  }
}

function ttsToggleCustomModel(el){
  const group=el.closest('.aic-chipgroup');
  const inp=document.getElementById('ttsModelInput');
  if(!group) return;
  group.querySelectorAll('.aic-chip').forEach(function(c){ c.classList.remove('active'); });
  el.classList.add('active');
  if(inp){ inp.style.display='block'; inp.value=''; inp.focus(); }
}

function aicToggleCustomChip(el,targetId){
  const group=el.closest('.aic-chipgroup');
  const inp=document.getElementById(targetId);
  if(!group) return;
  group.querySelectorAll('.aic-chip').forEach(function(c){ c.classList.remove('active'); });
  el.classList.add('active');
  if(inp){ inp.style.display='block'; inp.value=''; inp.focus(); }
}

