function aicFallbackCopy(text,cb){
  try{
    const ta=document.createElement('textarea');
    ta.value=text;
    ta.style.position='fixed';ta.style.opacity='0';ta.className='allow-copy';
    document.body.appendChild(ta);
    ta.focus();ta.select();
    document.execCommand('copy');
    document.body.removeChild(ta);
    if(cb) cb();
  }catch(e){console.error('[AIC] copy fallback gagal',e);}
}

function aicCopyMsg(idx,btnEl){
  const m=aicHistory[idx];
  if(!m) return;
  const text=(m.kind==='bypass'||m.kind==='img2prompt'||m.kind==='detectai')?m.output:m.text;
  function done(){
    if(!btnEl) return;
    const orig=btnEl.innerHTML;
    btnEl.classList.add('copied');
    btnEl.innerHTML='<i class="fa-solid fa-check"></i>Tersalin';
    setTimeout(function(){ btnEl.classList.remove('copied'); btnEl.innerHTML=orig; },1500);
  }
  if(navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(text).then(done).catch(function(){ aicFallbackCopy(text,done); });
  }else{
    aicFallbackCopy(text,done);
  }
}

function aicShowTyping(show){
  const box=document.getElementById('aicChatbox');
  if(!box) return;
  let typ=document.getElementById('aicTyping');
  if(show){
    if(typ) return;
    typ=document.createElement('div');
    typ.className='aic-typing';
    typ.id='aicTyping';
    typ.innerHTML='<span></span><span></span><span></span>';
    box.appendChild(typ);
    box.scrollTop=box.scrollHeight;
  }else if(typ){
    typ.remove();
  }
}

function aicDeepFindText(obj,depth,best){
  if(depth>4||obj==null) return best;
  if(typeof obj==='string'){
    const t=obj.trim();
    if(t.length>0 && t.length>(best?best.length:-1)) return t;
    return best;
  }
  if(Array.isArray(obj)){
    for(let i=0;i<obj.length;i++) best=aicDeepFindText(obj[i],depth+1,best);
    return best;
  }
  if(typeof obj==='object'){
    for(const k in obj) best=aicDeepFindText(obj[k],depth+1,best);
    return best;
  }
  return best;
}

function aicExtractText(json){
  if(!json) return null;
  const candidates=[json];
  if(json.result!==undefined) candidates.push(json.result);
  if(json.data!==undefined) candidates.push(json.data);
  for(const c of candidates){
    if(typeof c==='string' && c.trim()) return c.trim();
    if(c && typeof c==='object'){
      const f=c.message||c.response||c.answer||c.reply||c.output||c.text||c.content||c.result;
      if(typeof f==='string' && f.trim()) return f.trim();
    }
  }
  return aicDeepFindText(json,0,null);
}

function aicExtractSessionId(json){
  if(!json) return null;
  const candidates=[json,json.result,json.data];
  for(const c of candidates){
    if(c&&typeof c==='object'&&typeof c.session_id==='string'&&c.session_id.trim()) return c.session_id.trim();
  }
  return null;
}

function aicExtractChatId(json){
  if(!json) return null;
  const candidates=[json,json.result,json.data];
  for(const c of candidates){
    if(c&&typeof c==='object'&&c.chat_id!=null&&String(c.chat_id).trim()) return String(c.chat_id).trim();
  }
  return null;
}

function aicExtractAuth(json){
  if(!json) return null;
  const candidates=[json,json.result,json.data];
  for(const c of candidates){
    if(c&&typeof c==='object'&&c.auth!=null){
      if(typeof c.auth==='string'&&c.auth.trim()) return c.auth.trim();
      if(typeof c.auth==='object') return JSON.stringify(c.auth);
    }
  }
  return null;
}

function aicExtractSessionField(json){
  if(!json) return null;
  const candidates=[json,json.result,json.data];
  for(const c of candidates){
    if(c&&typeof c==='object'&&c.session!=null&&String(c.session).trim()) return String(c.session).trim();
  }
  return null;
}

async function aicSend(){
  const inp=document.getElementById('aicInput');
  const btn=document.getElementById('aicSendBtn');
  const text=inp?inp.value.trim():'';
  if(!text) return;
  if(!cidPreCheckDiamond(AIC_CHAT_COST,'aicSendBtn')) return;
  const modelKey=aicActiveModel;
  const cfg=AIC_MODELS[modelKey];
  aicHistory.push({kind:'chat',role:'user',text:text});
  aicTouchSession(text);
  inp.value='';
  aicAutoGrow(inp);
  aicRenderChat();
  btn.disabled=true;
  aicShowTyping(true);
  const sess=aicActiveSession();
  try{
    const json=await xyureiRequest(function(key){
      if(cfg.kind==='aiseek'){
        const sid=(sess&&sess.seekSessionId)?sess.seekSessionId:'';
        return AISEEK_ENDPOINT+'?prompt='+encodeURIComponent(text)+'&model='+encodeURIComponent(cfg.apiModel)+'&action=&session_id='+encodeURIComponent(sid)+'&apikey='+key;
      }
      if(cfg.kind==='chatgpt'){
        const cid=(sess&&sess.gptChatId)?sess.gptChatId:'';
        const auth=(sess&&sess.gptAuth)?sess.gptAuth:'';
        return 'https://sylvatica.my.id/api/ai/chatgpt?prompt='+encodeURIComponent(text)+'&chat_id='+encodeURIComponent(cid)+'&auth='+encodeURIComponent(auth)+'&apikey='+key;
      }
      if(cfg.kind==='claude'){
        return 'https://sylvatica.my.id/api/ai/claude?q='+encodeURIComponent(text)+'&files=&apikey='+key;
      }
      if(cfg.kind==='deepai'){
        return 'https://sylvatica.my.id/api/ai/deepai?q='+encodeURIComponent(text)+'&model=&apikey='+key;
      }
      if(cfg.kind==='simpleq'){
        const pname=cfg.paramName||'q';
        return 'https://sylvatica.my.id/api/ai/'+cfg.endpoint+'?'+pname+'='+encodeURIComponent(text)+'&apikey='+key;
      }
      if(cfg.kind==='notrack'){
        return 'https://sylvatica.my.id/api/ai/notrack?q='+encodeURIComponent(text)+'&persona=&apikey='+key;
      }
      if(cfg.kind==='sessionq'){
        const sv=(sess&&sess[cfg.sessKey])?sess[cfg.sessKey]:'';
        return 'https://sylvatica.my.id/api/ai/'+cfg.endpoint+'?q='+encodeURIComponent(text)+'&session='+encodeURIComponent(sv)+'&apikey='+key;
      }
      return 'https://sylvatica.my.id/api/ai/'+cfg.endpoint+'?text='+encodeURIComponent(text)+'&apikey='+key;
    },{
      isDataOk:function(j){ return !!aicExtractText(j); }
    });
    const answer=aicExtractText(json);
    if(cfg.kind==='aiseek'&&sess){
      const sid=aicExtractSessionId(json);
      if(sid){ sess.seekSessionId=sid; aicSaveSessions(); }
    }
    if(cfg.kind==='chatgpt'&&sess){
      const cid=aicExtractChatId(json);
      const auth=aicExtractAuth(json);
      if(cid) sess.gptChatId=cid;
      if(auth) sess.gptAuth=auth;
      if(cid||auth) aicSaveSessions();
    }
    if(cfg.kind==='sessionq'&&sess){
      const sv=aicExtractSessionField(json);
      if(sv){ sess[cfg.sessKey]=sv; aicSaveSessions(); }
    }
    aicShowTyping(false);
    if(answer){
      cidDeductDiamond(AIC_CHAT_COST,'Chat AI','Model: '+(cfg&&cfg.label?cfg.label:modelKey));
      aicHistory.push({kind:'chat',role:'ai',text:answer,modelKey:modelKey});
    }else{
      aicHistory.push({kind:'chat',role:'err',text:'Respon AI tidak dikenali. Coba lagi.'});
    }
  }catch(e){
    console.error('[AIC]['+modelKey+']',e);
    aicShowTyping(false);
    aicHistory.push({kind:'chat',role:'err',text:'Gagal menghubungi server AI. Coba lagi nanti.'});
  }
  btn.disabled=false;
  aicRenderChat();
  aicSaveSessions();
}

const AIC_MODE_LABEL={chat:'Chat',art:'AI Art',filter:'AI Filter',song:'AI Song',anime:'Anime to Real',bypass:'Bypass AI',imagenai:'Imagen AI',img2prompt:'Image to Prompt',detectai:'AI Detector',nanobanana:'Nano Banana',txt2img:'Text to Image',text2vid:'Text to Video',tts:'Text to Speech',toonmix:'Toonmix AI'};
function aicTouchSession(firstText){
  const s=aicActiveSession();
  if(!s) return;
  if(s.title==='Obrolan baru'&&firstText) s.title=firstText.slice(0,42);
  s.mode=aicCurrentMode;
  s.updatedAt=Date.now();
  const idx=aicSessions.indexOf(s);
  if(idx>0){ aicSessions.splice(idx,1); aicSessions.unshift(s); }
  aicSaveSessions();
  aicRenderSessions();
}

