function aicSwitchMode(tab){
  aicCurrentMode=tab;
  try{ localStorage.setItem(AIC_MODE_KEY,tab); }catch(e){}
  aicCloseModeMenus();
  const icon=document.getElementById('aicModeIcon');
  if(icon) icon.className='fa-solid '+AIC_MODE_ICONS[tab];
  AIC_MODE_PANELS.forEach(function(m){
    const item=document.getElementById('aicModeItem_'+m);
    if(item) item.classList.toggle('active',m===tab);
  });
  const bars={
    chat:document.getElementById('aicInputBarChat'),
    art:document.getElementById('aicInputBarChat'),
    filter:document.getElementById('aicInputBarFilter'),
    song:document.getElementById('aicInputBarSong'),
    anime:document.getElementById('aicInputBarAnime'),
    bypass:document.getElementById('aicInputBarBypass'),
    imagenai:document.getElementById('aicInputBarImagen'),
    img2prompt:document.getElementById('aicInputBarImg2Prompt'),
    detectai:document.getElementById('aicInputBarDetectAI'),
    nanobanana:document.getElementById('aicInputBarNanoBanana'),
    txt2img:document.getElementById('aicInputBarTxt2Img'),
    text2vid:document.getElementById('aicInputBarText2Vid'),
    tts:document.getElementById('aicInputBarTts'),
    toonmix:document.getElementById('aicInputBarToonmix')
  };
  const shown=bars[tab];
  Object.keys(bars).forEach(function(k){
    const el=bars[k];
    if(!el) return;
    el.style.display=(el===shown)?'flex':'none';
  });
  const inp=document.getElementById('aicInput');
  if(inp) inp.placeholder=AIC_MODE_PLACEHOLDER[tab]||'Tulis pesan...';
  const sendIcon=document.getElementById('aicSendIcon');
  if(sendIcon) sendIcon.className='fa-solid '+(tab==='art'?'fa-wand-magic-sparkles':'fa-paper-plane');
  const modelbar=document.querySelector('#aicChatActions .aic-modelbar');
  if(modelbar) modelbar.style.display=(tab==='chat')?'flex':'none';
  aiCloseLightbox();
  aicRenderChat();
}

