/* ================= RECOVERY MEDIA GAGAL MUAT (fix WebView APK) =================
   Root cause: di WebView APK, tag <img>/<video>/<audio> yang load URL CDN langsung
   sering trigger onerror walau file-nya valid (bug jalur network native WebView utk
   media - redirect/header beda dari browser biasa). Makanya media sempat kelihatan
   sekilas lalu dianggap gagal, padahal kalau dibuka manual di browser selalu sukses.
   Fix: sebelum nyerah, coba ambil ulang media via fetch()+blob lalu tampilkan sebagai
   blob URL (jalur network yang lebih reliable, tidak lewat native media loader
   WebView). Baru kalau itu juga gagal beberapa kali, tampilkan fallback "tap buka
   langsung". Dipakai oleh SEMUA endpoint media (AI art/filter, sosmed download,
   random image, dll) karena semua elemen media memanggil aiImgErr yang sama. */
function aiImgErr(el){
  try{ aiImgRecover(el,0); }catch(e){}
}

function aiImgRecover(el,attempt){
  try{
    if(!el) return;
    const wrap=el.closest('.aiart-imgwrap')||el.parentElement;
    if(!wrap) return;
    const origUrl=el.getAttribute('data-origsrc')||el.currentSrc||el.src;
    if(!origUrl) return;
    if(!el.getAttribute('data-origsrc')) el.setAttribute('data-origsrc',origUrl);

    const MAX_NATIVE=2;   // percobaan reload native pakai url yg SAMA persis (jangan ditambah query,
                           // banyak url media pakai signed-token yg langsung invalid kalau query diubah)
    const MAX_TOTAL=4;    // total percobaan sebelum benar2 nyerah
    if(attempt>=MAX_TOTAL){
      // jangan pernah tampilkan teks/pesan error apapun - biarkan tampilan media apa adanya
      // (kelihatan kosong/putih kaya masih loading), tombol Download di bawah tetap bisa dipakai buka linknya
      el.style.opacity='0.55';
      return;
    }

    // jangan langsung tampilkan pesan gagal, coba pulihkan dulu secara diam-diam
    el.style.opacity='0.35';

    if(attempt<MAX_NATIVE){
      // percobaan 1-2: reload native apa adanya. Banyak kasus gagal di WebView APK cuma
      // race-condition/timeout sesaat, url yg sama sering sukses kalau dicoba ulang.
      setTimeout(function(){
        el.onerror=function(){ aiImgRecover(el,attempt+1); };
        el.removeAttribute('src');
        el.src=origUrl;
        el.style.opacity='';
        if(el.tagName==='VIDEO'||el.tagName==='AUDIO'){ try{ el.load(); }catch(e){} }
      },400);
      return;
    }

    // percobaan lanjutan: fetch()+blob. Ini cuma jalan kalau CDN mengizinkan CORS -
    // kalau tidak, fetch akan gagal cepat dan lanjut ke percobaan berikutnya / fallback.
    fetch(origUrl,{cache:'no-store'}).then(function(res){
      if(!res.ok) throw new Error('http '+res.status);
      return res.blob();
    }).then(function(blob){
      if(!blob||!blob.size) throw new Error('blob kosong');
      const blobUrl=URL.createObjectURL(blob);
      el.onerror=function(){ aiImgRecover(el,attempt+1); };
      el.src=blobUrl;
      el.style.opacity='';
      if(el.tagName==='VIDEO'||el.tagName==='AUDIO'){ try{ el.load(); }catch(e){} }
    }).catch(function(){
      setTimeout(function(){ aiImgRecover(el,attempt+1); },450);
    });
  }catch(e){}
}

function aiartEscAttr(str){
  return String(str==null?'':str).replace(/'/g,'&#39;').replace(/"/g,'&quot;');
}
function aiartEscapeHtml(str){
  return String(str==null?'':str).replace(/[&<>"']/g,function(c){
    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
  });
}

function aiartExtractUrl(json){
  if(!json) return null;
  if(json.data&&typeof json.data.url==='string'&&json.data.url.trim()) return json.data.url.trim();
  if(json.data&&typeof json.data.audio_url==='string'&&json.data.audio_url.trim()) return json.data.audio_url.trim();
  if(typeof json.url==='string'&&json.url.trim()) return json.url.trim();
  if(typeof json.audio_url==='string'&&json.audio_url.trim()) return json.audio_url.trim();
  if(json.result&&typeof json.result.url==='string'&&json.result.url.trim()) return json.result.url.trim();
  if(json.result&&typeof json.result.audio_url==='string'&&json.result.audio_url.trim()) return json.result.audio_url.trim();
  if(typeof json.result==='string'&&/^https?:\/\//.test(json.result)) return json.result.trim();
  return null;
}

