/* ============================================================================
   AI FILTER — https://sylvatica.my.id/api/ai/aifilter?url=...&filter=...&apikey=...
   Respons: {creator,filter,result:{prompt_id,queue_info:{status},results:[{index,nsfw,origin,thumb}]},status}
   ============================================================================ */
const AIFLT_ENDPOINT='https://sylvatica.my.id/api/ai/aifilter';
let aifltLoading=false;
let aifltLoadingLabel='';

function aifltEscAttr(str){
  return String(str==null?'':str).replace(/'/g,'&#39;').replace(/"/g,'&quot;');
}
function aifltEscapeHtml(str){
  return String(str==null?'':str).replace(/[&<>"']/g,function(c){
    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
  });
}

function aifltExtractImages(json){
  if(!json) return null;
  const res=json.result||json.data||json;
  const list=res&&Array.isArray(res.results)?res.results:null;
  if(!list||!list.length) return null;
  const images=list.map(function(it){
    return {url:(it&&(it.origin||it.thumb||it.url))||'',nsfw:!!(it&&it.nsfw)};
  }).filter(function(it){ return !!it.url; });
  return images.length?images:null;
}

