/* ============================================================================
   TEXT TO VIDEO — https://sylvatica.my.id/api/ai/text2vid?prompt=...&ratio=...&sound=...&apikey=...
   ============================================================================ */
const TEXT2VID_ENDPOINT='https://sylvatica.my.id/api/ai/text2vid';
let text2vidLoading=false;
let text2vidLoadingPrompt='';
let text2vidStartTime=0;
let text2vidProgressTimer=null;
const TEXT2VID_ESTIMATED_SECONDS=75; // estimasi rata-rata durasi render text-to-video

function aicStartText2vidProgress(){
  aicStopText2vidProgress();
  text2vidStartTime=Date.now();
  aicUpdateText2vidProgress();
  text2vidProgressTimer=setInterval(aicUpdateText2vidProgress,1000);
}
function aicStopText2vidProgress(){
  if(text2vidProgressTimer){ clearInterval(text2vidProgressTimer); text2vidProgressTimer=null; }
}
function aicUpdateText2vidProgress(){
  const fill=document.getElementById('text2vidProgressFill');
  const pctEl=document.getElementById('text2vidProgressPct');
  const timeEl=document.getElementById('text2vidProgressTime');
  const stageEl=document.getElementById('text2vidProgressStage');
  if(!fill&&!pctEl&&!timeEl&&!stageEl) return;
  const elapsed=Math.max(0,(Date.now()-text2vidStartTime)/1000);
  const pct=Math.min(94,Math.round(100*(1-Math.exp(-elapsed/(TEXT2VID_ESTIMATED_SECONDS*0.6)))));
  let stage='Menyiapkan permintaan...';
  if(elapsed>8&&elapsed<=35) stage='Merender frame video...';
  else if(elapsed>35&&elapsed<=70) stage='Menggabungkan & menghaluskan hasil...';
  else if(elapsed>70) stage='Hampir selesai, mohon tunggu...';
  if(fill) fill.style.width=pct+'%';
  if(pctEl) pctEl.textContent=pct+'%';
  if(stageEl) stageEl.textContent=stage;
  if(timeEl) timeEl.textContent=Math.floor(elapsed)+'dtk · estimasi ~'+TEXT2VID_ESTIMATED_SECONDS+'dtk';
}

