function islRenderJadwal(kota){
  const area=islArea();
  area.innerHTML='<div class="isl-searchrow">'+
    '<input class="isl-searchinput" id="islKotaInput" type="text" placeholder="Nama kota (kosongkan = Jakarta)" value="'+islEsc(kota||'')+'" onkeydown="if(event.key===\'Enter\'){event.preventDefault();islSearchJadwal();}">'+
    '<button class="isl-searchbtn" onclick="islSearchJadwal()"><i class="fa-solid fa-magnifying-glass"></i></button>'+
  '</div>'+
  '<div id="islJadwalResult"><div class="isl-loading"><i class="fa-solid fa-spinner fa-spin"></i> Memuat jadwal...</div></div>';
  islFetchJadwal(kota);
}

function islSearchJadwal(){
  const input=document.getElementById('islKotaInput');
  const kota=input?input.value.trim():'';
  const result=document.getElementById('islJadwalResult');
  if(result) result.innerHTML='<div class="isl-loading"><i class="fa-solid fa-spinner fa-spin"></i> Memuat jadwal...</div>';
  islFetchJadwal(kota);
}

function islFetchJadwal(kota){
  const extra='kota='+encodeURIComponent(kota&&kota.trim()?kota.trim():'jakarta');
  islFetchJson('jadwalshalat',extra).then(function(json){
    const result=document.getElementById('islJadwalResult');
    if(!result) return;
    if(!json||json.status===false||!json.data){
      const apiMsg=json&&(json.message||json.msg||json.error);
      result.innerHTML='<div class="isl-fetcherror"><i class="fa-solid fa-triangle-exclamation"></i> Kota tidak ditemukan / gagal memuat.'+(apiMsg?'<br><span style="font-size:11px;opacity:.7;">'+islEsc(apiMsg)+'</span>':'')+'</div>';
      return;
    }
    const d=json.data;
    const rows=[
      {lbl:'Imsyak',val:d.imsyak,type:'extra'},{lbl:'Shubuh',val:d.shubuh,type:'wajib'},{lbl:'Terbit',val:d.terbit,type:'extra'},
      {lbl:'Dhuha',val:d.dhuha,type:'extra'},{lbl:'Dzuhur',val:d.dzuhur,type:'wajib'},{lbl:'Ashr',val:d.ashr,type:'wajib'},
      {lbl:'Maghrib',val:d.maghrib,type:'wajib'},{lbl:'Isya',val:d.isya,type:'wajib'}
    ];
    result.innerHTML='<div class="isl-schedcard">'+
      '<div class="isl-sched-city">'+islEsc(json.kota||'Jadwal Shalat')+'</div>'+
      '<div class="isl-sched-date">'+islEsc(d.tanggal_hijriyah||'')+(d.tanggal_masehi?' &middot; Tgl '+islEsc(d.tanggal_masehi):'')+'</div>'+
      '<div class="isl-sched-grid">'+
        rows.map(function(r){ return r.val?('<div class="isl-sched-item '+r.type+'"><div class="isl-sched-lbl">'+r.lbl+'</div><div class="isl-sched-val">'+islEsc(r.val)+'</div></div>'):''; }).join('')+
      '</div>'+
    '</div>';
  }).catch(function(err){
    const result=document.getElementById('islJadwalResult');
    if(result) result.innerHTML='<div class="isl-fetcherror"><i class="fa-solid fa-triangle-exclamation"></i> Gagal memuat jadwal.<br><span style="font-size:11px;opacity:.7;">'+islEsc((err&&err.message)||'')+'</span></div>';
  });
}

