function islIsImageUrl(str){
  if(typeof str!=='string') return false;
  if(!/^https?:\/\//i.test(str)) return false;
  return /\.(jpe?g|png|gif|webp|bmp)(\?.*)?$/i.test(str) || /blogspot|googleusercontent|imgur|cloudinary|ggpht/i.test(str);
}

function islPrettyLabel(key){
  return String(key).replace(/_/g,' ').replace(/([a-z0-9])([A-Z])/g,'$1 $2').replace(/\b\w/g,function(c){return c.toUpperCase();});
}

function islFlattenFields(data){
  if(data==null) return '<div class="isl-empty"><i class="fa-solid fa-inbox"></i>Data tidak tersedia</div>';
  if(typeof data==='string'){
    if(islIsImageUrl(data)) return '<img src="'+islEsc(data)+'" style="max-width:100%;border-radius:10px;margin:8px 0;display:block;" onerror="this.style.display=\'none\'">';
    return '<div class="isl-val" style="white-space:pre-line;">'+islEsc(data)+'</div>';
  }
  if(Array.isArray(data)) return data.map(islFlattenFields).join('');
  if(typeof data==='object'){
    const skip=['status','creator','metadata','author_skrep','kesayangan'];
    return Object.keys(data).filter(function(k){return skip.indexOf(k)===-1;}).map(function(k){
      const v=data[k];
      if(v===null||v===undefined||v==='') return '';
      if(typeof v==='string'){
        if(islIsImageUrl(v)) return '<img src="'+islEsc(v)+'" style="max-width:100%;border-radius:10px;margin:8px 0;display:block;" onerror="this.style.display=\'none\'">';
        return '<div class="isl-field"><span class="isl-lbl">'+islEsc(islPrettyLabel(k))+'</span><div class="isl-val" style="white-space:pre-line;margin-top:4px;">'+islEsc(v)+'</div></div>';
      }
      if(typeof v==='number'||typeof v==='boolean'){
        return '<div class="isl-field"><span class="isl-lbl">'+islEsc(islPrettyLabel(k))+'</span><div class="isl-val" style="margin-top:4px;">'+islEsc(String(v))+'</div></div>';
      }
      return '<div class="isl-field"><span class="isl-lbl">'+islEsc(islPrettyLabel(k))+'</span>'+islFlattenFields(v)+'</div>';
    }).join('');
  }
  return '<div class="isl-val">'+islEsc(String(data))+'</div>';
}

function islEsc(str){
  return String(str==null?'':str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

const KMK_BASE='https://www.api-xyurei.my.id/api/komiku/';
const KMK_MENU=[
  {key:'komiku-search',label:'Cari Komik',icon:'fa-magnifying-glass',type:'search'},
  {key:'komiku-info',label:'Info Komik',icon:'fa-circle-info',type:'info'},
  {key:'komiku-chapter-img',label:'Baca Chapter',icon:'fa-book-open',type:'chapter'},
  {key:'komiku-last',label:'Update Terbaru',icon:'fa-clock-rotate-left',type:'last'}
];

let kmkActiveKey=null;
let kmkGridBuilt=false;
const kmkCache={};

function kmkBuildGrid(){
  const grid=document.getElementById('kmkGrid');
  if(!grid||kmkGridBuilt) return;
  grid.innerHTML=KMK_MENU.map(function(m){
    return '<div class="kmk-tile" id="kmkTile_'+m.key+'" onclick="kmkSelect(\''+m.key+'\')">'+
      '<div class="kmk-tile-icon"><i class="fa-solid '+m.icon+'"></i></div><span>'+m.label+'</span></div>';
  }).join('');
  kmkGridBuilt=true;
}
document.addEventListener('DOMContentLoaded',kmkBuildGrid);

function kmkSelect(key){
  kmkActiveKey=key;
  document.querySelectorAll('#komiku .kmk-tile').forEach(function(t){t.classList.remove('active');});
  const tile=document.getElementById('kmkTile_'+key);
  if(tile) tile.classList.add('active');
  const menu=KMK_MENU.find(function(m){return m.key===key;});
  if(!menu) return;
  if(menu.type==='search') kmkRenderSearchForm();
  else if(menu.type==='info') kmkRenderInfoForm();
  else if(menu.type==='chapter') kmkRenderChapterForm();
  else if(menu.type==='last') kmkLoadLast();
}

function kmkArea(){ return document.getElementById('kmkArea'); }

function kmkFetchJson(endpoint,extraParams){
  return (async function(){
    const keys=xyureiFallbackShuffledKeys();
    let lastErr=null;
    for(let i=0;i<keys.length;i++){
      const key=keys[i];
      let url=KMK_BASE+endpoint+'?apikey='+encodeURIComponent(key);
      if(extraParams) url+='&'+extraParams;
      try{
        let res,text;
        try{
          res=await fetch(url,{headers:{'Accept':'application/json'}});
          text=await res.text();
        }catch(networkErr){
          res=await fetch('https://api.allorigins.win/raw?url='+encodeURIComponent(url));
          text=await res.text();
        }
        let json=null;
        try{ json=JSON.parse(text); }catch(parseErr){ lastErr=new Error('Respons bukan JSON valid.'); continue; }
        if(xyureiIsFailure(res,json)){ lastErr=new Error('apiKey xyurei gagal/limit.'); continue; }
        return json;
      }catch(e){ lastErr=e; continue; }
    }
    throw lastErr||new Error('Semua apiKey xyurei gagal.');
  })();
}

// ===== CARI KOMIK =====
function kmkRenderSearchForm(){
  const area=kmkArea();
  area.innerHTML='<div class="kmk-formrow">'+
    '<div class="kmk-searchrow">'+
      '<input class="kmk-searchinput" id="kmkSearchInput" type="text" placeholder="Judul komik..." onkeydown="if(event.key===\'Enter\'){event.preventDefault();kmkDoSearch();}">'+
      '<button class="kmk-searchbtn" onclick="kmkDoSearch()"><i class="fa-solid fa-magnifying-glass"></i></button>'+
    '</div>'+
  '</div><div id="kmkSearchResult"></div>';
}

function kmkDoSearch(){
  const input=document.getElementById('kmkSearchInput');
  const q=input?input.value.trim():'';
  const result=document.getElementById('kmkSearchResult');
  if(!q){ if(result) result.innerHTML='<div class="kmk-empty"><i class="fa-solid fa-magnifying-glass"></i>Masukkan judul komik dulu</div>'; return; }
  if(result) result.innerHTML='<div class="kmk-loading"><i class="fa-solid fa-spinner fa-spin"></i> Mencari...</div>';
  kmkFetchJson('komiku-search','query='+encodeURIComponent(q)).then(function(json){
    if(json&&json.status===false){
      const apiMsg=json.error||json.message||json.msg||'Tidak ada hasil ditemukan.';
      if(result) result.innerHTML='<div class="kmk-fetcherror"><i class="fa-solid fa-triangle-exclamation"></i> '+kmkEsc(apiMsg)+'</div>';
      return;
    }
    const items=(json&&(json.result||json.data))||[];
    kmkRenderSearchResult(items);
  }).catch(function(err){
    if(result) result.innerHTML='<div class="kmk-fetcherror"><i class="fa-solid fa-triangle-exclamation"></i> Gagal mencari.<br><span style="font-size:11px;opacity:.7;">'+kmkEsc((err&&err.message)||'')+'</span></div>';
  });
}

function kmkRenderSearchResult(items){
  const result=document.getElementById('kmkSearchResult');
  if(!result) return;
  if(!items||!items.length){ result.innerHTML='<div class="kmk-empty"><i class="fa-solid fa-inbox"></i>Tidak ada hasil</div>'; return; }
  result.innerHTML=items.map(function(it){
    const slug=it.slug||it.endpoint||'';
    const title=it.title||it.judul||it.name||kmkSlugToTitle(slug);
    const thumb=it.thumbnail||it.image||it.cover||'';
    const type=it.type||it.jenis||'';
    const status=it.status||'';
    const chapterRaw=it.chapter||it.lastChapter||'';
    const meta=[type,status,chapterRaw?('Chapter '+chapterRaw):''].filter(Boolean).join(' &middot; ');
    return '<div class="kmk-comicitem" onclick="kmkGoToInfo(\''+kmkEscAttr(slug)+'\')">'+
      (thumb?'<img class="kmk-comicthumb" src="'+kmkEsc(thumb)+'" onerror="this.outerHTML=\'<div class=&quot;kmk-thumbph sm&quot;><i class=&quot;fa-solid fa-book&quot;></i></div>\'">':'<div class="kmk-thumbph sm"><i class="fa-solid fa-book"></i></div>')+
      '<div class="kmk-comicbody">'+
        '<div class="kmk-comicname">'+kmkEsc(title)+'</div>'+
        (meta?'<div class="kmk-comicmeta">'+kmkEsc(meta)+'</div>':'')+
        (slug?'<span class="kmk-comicchip">Lihat Info</span>':'')+
      '</div>'+
    '</div>';
  }).join('');
}

function kmkGoToInfo(slug){
  if(!slug) return;
  kmkSelect('komiku-info');
  setTimeout(function(){
    const input=document.getElementById('kmkInfoInput');
    if(input) input.value=slug;
    kmkDoInfo();
  },0);
}

// ===== INFO KOMIK =====
function kmkRenderInfoForm(){
  const area=kmkArea();
  area.innerHTML='<div class="kmk-formrow">'+
    '<div class="kmk-searchrow">'+
      '<input class="kmk-searchinput" id="kmkInfoInput" type="text" placeholder="Slug komik..." onkeydown="if(event.key===\'Enter\'){event.preventDefault();kmkDoInfo();}">'+
      '<button class="kmk-searchbtn" onclick="kmkDoInfo()"><i class="fa-solid fa-magnifying-glass"></i></button>'+
    '</div>'+
  '</div><div id="kmkInfoResult"></div>';
}

function kmkDoInfo(){
  const input=document.getElementById('kmkInfoInput');
  const slug=input?input.value.trim():'';
  const result=document.getElementById('kmkInfoResult');
  if(!slug){ if(result) result.innerHTML='<div class="kmk-empty"><i class="fa-solid fa-circle-info"></i>Masukkan slug komik dulu</div>'; return; }
  if(kmkCache['info_'+slug]){ kmkRenderInfo(kmkCache['info_'+slug],slug); return; }
  if(result) result.innerHTML='<div class="kmk-loading"><i class="fa-solid fa-spinner fa-spin"></i> Memuat info...</div>';
  kmkFetchJson('komiku-info','slug='+encodeURIComponent(slug)).then(function(json){
    if(json&&json.status===false){
      const apiMsg=json.error||json.message||json.msg||'Komik tidak ditemukan.';
      if(result) result.innerHTML='<div class="kmk-fetcherror"><i class="fa-solid fa-triangle-exclamation"></i> '+kmkEsc(apiMsg)+'</div>';
      return;
    }
    const data=(json&&(json.result||json.data))||json;
    kmkCache['info_'+slug]=data;
    kmkRenderInfo(data,slug);
  }).catch(function(err){
    if(result) result.innerHTML='<div class="kmk-fetcherror"><i class="fa-solid fa-triangle-exclamation"></i> Gagal memuat info.<br><span style="font-size:11px;opacity:.7;">'+kmkEsc((err&&err.message)||'')+'</span></div>';
  });
}

function kmkRenderInfo(data,slug){
  const result=document.getElementById('kmkInfoResult');
  if(!result) return;
  if(!data){ result.innerHTML='<div class="kmk-empty"><i class="fa-solid fa-inbox"></i>Data tidak ditemukan</div>'; return; }
  const comicSlug=data.slug||slug;
  const title=data.title||data.judul||kmkSlugToTitle(comicSlug);
  const thumb=data.thumbnail||data.image||data.cover||'';
  const type=data.type||'';
  const author=data.author||data.penulis||'';
  const status=data.status||'';
  const genreArr=Array.isArray(data.genres)?data.genres:(Array.isArray(data.genre)?data.genre:null);
  const genre=genreArr?genreArr.join(', '):(data.genre||'');
  const sinopsis=data.sinopsis||data.synopsis||data.description||'';
  const chapterRaw=data.chapter||'';
  const chapters=(Array.isArray(data.chapters)?data.chapters:(Array.isArray(data.chapterList)?data.chapterList:[])).slice().sort(function(a,b){
    const na=parseFloat(a.num||a.chapter||a.title||a.name||0)||0;
    const nb=parseFloat(b.num||b.chapter||b.title||b.name||0)||0;
    return nb-na;
  });
  result.innerHTML='<div class="kmk-infocard">'+
    '<div class="kmk-infotop">'+
      '<div id="kmkInfoThumbSlot">'+(thumb?'<img class="kmk-infothumb" src="'+kmkEsc(thumb)+'" onerror="this.outerHTML=\'<div class=&quot;kmk-thumbph md&quot;><i class=&quot;fa-solid fa-book&quot;></i></div>\'">':'<div class="kmk-thumbph md"><i class="fa-solid fa-book"></i></div>')+'</div>'+
      '<div style="flex:1;min-width:0;">'+
        '<div class="kmk-infotitle">'+kmkEsc(title)+'</div>'+
        (type?'<div class="kmk-infoline"><b>Tipe:</b> '+kmkEsc(type)+'</div>':'')+
        (author?'<div class="kmk-infoline"><b>Penulis:</b> '+kmkEsc(author)+'</div>':'')+
        (status?'<div class="kmk-infoline"><b>Status:</b> '+kmkEsc(status)+'</div>':'')+
        (genre?'<div class="kmk-infoline"><b>Genre:</b> '+kmkEsc(genre)+'</div>':'')+
        (chapterRaw&&!chapters.length?'<div class="kmk-infoline"><b>Chapter Terbaru:</b> '+kmkEsc(chapterRaw)+'</div>':'')+
      '</div>'+
    '</div>'+
    (sinopsis?'<div class="kmk-infosinopsis">'+kmkEsc(sinopsis)+'</div>':'')+
  '</div>'+
  (chapterRaw&&!chapters.length?'<div class="kmk-chapteritem" onclick="kmkGoToChapter(\''+kmkEscAttr(comicSlug)+'\',\''+kmkEscAttr(String(chapterRaw))+'\',true)">'+
    '<div><div class="kmk-chaptername">Baca Chapter '+kmkEsc(chapterRaw)+'</div></div>'+
    '<i class="fa-solid fa-chevron-right"></i>'+
  '</div>':'')+
  (chapters.length?'<div id="kmkChapterList"></div>':'');
  if(chapters.length){
    const list=document.getElementById('kmkChapterList');
    if(list){
      list.innerHTML=chapters.map(function(c){
        const cnum=c.num||c.chapter||c.title||c.name||'';
        const cname=cnum?('Chapter '+cnum):(c.title||c.name||'Chapter');
        const cdate=c.date||c.tanggal||'';
        const cslug=cnum||c.slug||c.endpoint||cname;
        return '<div class="kmk-chapteritem" onclick="kmkGoToChapter(\''+kmkEscAttr(comicSlug)+'\',\''+kmkEscAttr(String(cslug))+'\',true)">'+
          '<div><div class="kmk-chaptername">'+kmkEsc(cname)+'</div>'+(cdate?'<div class="kmk-chapterdate">'+kmkEsc(cdate)+'</div>':'')+'</div>'+
          '<i class="fa-solid fa-chevron-right"></i>'+
        '</div>';
      }).join('');
    }
  }
  if(!thumb&&chapterRaw&&comicSlug){
    kmkLoadThumbFromChapter(comicSlug,(chapters.length?(chapters[0].num||chapters[0].chapter||chapterRaw):chapterRaw));
  }
}

function kmkLoadThumbFromChapter(slug,chapter){
  const cacheKey='thumbimg_'+slug;
  if(kmkCache[cacheKey]){
    if(kmkCache[cacheKey]==='__none__') kmkFallbackThumbSlot();
    else kmkApplyThumbSlot(kmkCache[cacheKey]);
    return;
  }
  kmkFetchJson('komiku-chapter-img','slug='+encodeURIComponent(slug)+'&chapter='+encodeURIComponent(chapter)).then(function(json){
    if(json&&json.status===false){ kmkCache[cacheKey]='__none__'; kmkFallbackThumbSlot(); return; }
    const data=(json&&(json.result||json.data))||json;
    const images=Array.isArray(data)?data:(data&&data.images)||[];
    if(!images.length){ kmkCache[cacheKey]='__none__'; kmkFallbackThumbSlot(); return; }
    const first=images[0];
    const src=typeof first==='string'?first:(first.url||first.image||first.src||'');
    if(!src){ kmkCache[cacheKey]='__none__'; kmkFallbackThumbSlot(); return; }
    kmkCache[cacheKey]=src;
    kmkApplyThumbSlot(src);
  }).catch(function(){
    kmkFallbackThumbSlot();
  });
}

function kmkFallbackThumbSlot(){
  const slot=document.getElementById('kmkInfoThumbSlot');
  if(!slot) return;
  slot.innerHTML='<div class="kmk-thumbph md"><i class="fa-solid fa-book"></i></div>';
}

function kmkApplyThumbSlot(src){
  const slot=document.getElementById('kmkInfoThumbSlot');
  if(!slot) return;
  slot.innerHTML='<img class="kmk-infothumb" src="'+kmkEsc(src)+'" onerror="this.outerHTML=\'<div class=&quot;kmk-thumbph md&quot;><i class=&quot;fa-solid fa-book&quot;></i></div>\'">';
}

let kmkChapterInfoSlug=null;

function kmkGoToChapter(slug,chapter,fromInfo){
  kmkChapterInfoSlug=fromInfo?slug:null;
  kmkSelect('komiku-chapter-img');
  setTimeout(function(){
    const slugInput=document.getElementById('kmkChapterSlugInput');
    const chapterInput=document.getElementById('kmkChapterNumInput');
    if(slugInput) slugInput.value=slug;
    if(chapterInput) chapterInput.value=chapter;
    kmkDoChapter();
  },0);
}

// ===== BACA CHAPTER =====
function kmkRenderChapterForm(){
  const area=kmkArea();
  area.innerHTML='<div class="kmk-formrow">'+
    '<input class="kmk-searchinput" id="kmkChapterSlugInput" type="text" placeholder="Slug komik...">'+
    '<div class="kmk-searchrow">'+
      '<input class="kmk-searchinput" id="kmkChapterNumInput" type="text" placeholder="Chapter (contoh: 1)" onkeydown="if(event.key===\'Enter\'){event.preventDefault();kmkDoChapter();}">'+
      '<button class="kmk-searchbtn" onclick="kmkDoChapter()"><i class="fa-solid fa-book-open"></i></button>'+
    '</div>'+
  '</div><div id="kmkChapterResult"></div>';
}

function kmkChapterStep(delta){
  const chapterInput=document.getElementById('kmkChapterNumInput');
  if(!chapterInput) return;
  const cur=parseFloat(chapterInput.value);
  if(isNaN(cur)) return;
  let next=cur+delta;
  if(next<0) next=0;
  if(Number.isInteger(cur)) next=Math.round(next);
  chapterInput.value=String(next);
  kmkDoChapter();
}

function kmkBackToInfo(){
  if(!kmkChapterInfoSlug) return;
  kmkSelect('komiku-info');
  setTimeout(function(){
    const input=document.getElementById('kmkInfoInput');
    if(input) input.value=kmkChapterInfoSlug;
    kmkDoInfo();
  },0);
}

function kmkDoChapter(){
  const slugInput=document.getElementById('kmkChapterSlugInput');
  const chapterInput=document.getElementById('kmkChapterNumInput');
  const slug=slugInput?slugInput.value.trim():'';
  const chapter=chapterInput?chapterInput.value.trim():'';
  const result=document.getElementById('kmkChapterResult');
  if(!slug||!chapter){ if(result) result.innerHTML='<div class="kmk-empty"><i class="fa-solid fa-book-open"></i>Lengkapi slug dan chapter dulu</div>'; return; }
  if(result) result.innerHTML='<div class="kmk-loading"><i class="fa-solid fa-spinner fa-spin"></i> Memuat halaman chapter...</div>';
  window.scrollTo(0,0);
  kmkFetchJson('komiku-chapter-img','slug='+encodeURIComponent(slug)+'&chapter='+encodeURIComponent(chapter)).then(function(json){
    if(json&&json.status===false){
      const apiMsg=json.error||json.message||json.msg||'Chapter tidak ditemukan.';
      if(result) result.innerHTML=kmkChapterNav(slug,chapter)+'<div class="kmk-fetcherror"><i class="fa-solid fa-triangle-exclamation"></i> '+kmkEsc(apiMsg)+'</div>';
      return;
    }
    const data=(json&&(json.result||json.data))||json;
    const images=Array.isArray(data)?data:(data&&data.images)||[];
    if(!images.length){
      if(result) result.innerHTML=kmkChapterNav(slug,chapter)+'<div class="kmk-fetcherror"><i class="fa-solid fa-triangle-exclamation"></i> Halaman chapter kosong. Kemungkinan chapter ini belum tersedia di sumbernya, coba nomor chapter lain.</div>';
      return;
    }
    kmkRenderChapterImages(images,slug,chapter);
  }).catch(function(err){
    if(result) result.innerHTML=kmkChapterNav(slug,chapter)+'<div class="kmk-fetcherror"><i class="fa-solid fa-triangle-exclamation"></i> Gagal memuat chapter.<br><span style="font-size:11px;opacity:.7;">'+kmkEsc((err&&err.message)||'')+'</span></div>';
  });
}

function kmkChapterNav(slug,chapter){
  const backBtn=kmkChapterInfoSlug?'<button class="kmk-backbtn" onclick="kmkBackToInfo()"><i class="fa-solid fa-arrow-left"></i> Info Komik</button>':'';
  return '<div class="kmk-backrow">'+
    backBtn+
    '<button class="kmk-backbtn" onclick="kmkChapterStep(-1)"><i class="fa-solid fa-chevron-left"></i> Prev</button>'+
    '<button class="kmk-backbtn" onclick="kmkChapterStep(1)">Next <i class="fa-solid fa-chevron-right"></i></button>'+
  '</div>';
}

function kmkRenderChapterImages(images,slug,chapter){
  const result=document.getElementById('kmkChapterResult');
  if(!result) return;
  const list=Array.isArray(images)?images:[];
  const nav=kmkChapterNav(slug,chapter);
  if(!list.length){ result.innerHTML=nav+'<div class="kmk-empty"><i class="fa-solid fa-inbox"></i>Tidak ada halaman ditemukan</div>'; return; }
  const pages=list.map(function(img){
    const src=typeof img==='string'?img:(img.url||img.image||img.src||'');
    return src?'<img class="kmk-readerpage" src="'+kmkEsc(src)+'" loading="lazy" onerror="this.style.display=\'none\'">':'';
  }).join('');
  result.innerHTML=nav+pages+nav;
}

// ===== UPDATE TERBARU =====
function kmkLoadLast(){
  const area=kmkArea();
  area.innerHTML='<div class="kmk-loading"><i class="fa-solid fa-spinner fa-spin"></i> Memuat update terbaru...</div>';
  if(kmkCache.last){ kmkRenderLast(kmkCache.last); return; }
  kmkFetchJson('komiku-last').then(function(json){
    const items=(json&&(json.result||json.data))||[];
    kmkCache.last=items;
    kmkRenderLast(items);
  }).catch(function(err){
    area.innerHTML='<div class="kmk-fetcherror"><i class="fa-solid fa-triangle-exclamation"></i> Gagal memuat update terbaru.<br><span style="font-size:11px;opacity:.7;">'+kmkEsc((err&&err.message)||'')+'</span></div>';
  });
}

function kmkSlugToTitle(slug){
  if(!slug) return 'Tanpa Judul';
  return String(slug).replace(/-/g,' ').replace(/\b\w/g,function(c){return c.toUpperCase();});
}

function kmkRenderLast(items){
  const area=kmkArea();
  if(!items||!items.length){ area.innerHTML='<div class="kmk-empty"><i class="fa-solid fa-inbox"></i>Belum ada data</div>'; return; }
  area.innerHTML='<div class="kmk-lastgrid">'+items.map(function(it){
    const slug=it.slug||it.endpoint||'';
    const title=it.title||it.judul||it.name||kmkSlugToTitle(slug);
    const thumb=it.thumbnail||it.image||it.cover||'';
    const chapterRaw=it.chapter||it.lastChapter||'';
    const chapter=chapterRaw?('Chapter '+chapterRaw):'';
    return '<div class="kmk-lastcard" onclick="kmkGoToInfo(\''+kmkEscAttr(slug)+'\')">'+
      (thumb?'<img class="kmk-lastthumb" src="'+kmkEsc(thumb)+'" onerror="this.outerHTML=\'<div class=&quot;kmk-thumbph lg&quot;><i class=&quot;fa-solid fa-book&quot;></i></div>\'">':'<div class="kmk-thumbph lg"><i class="fa-solid fa-book"></i></div>')+
      '<div class="kmk-lastbody">'+
        '<div class="kmk-lastname">'+kmkEsc(title)+'</div>'+
        (chapter?'<div class="kmk-lastmeta">'+kmkEsc(chapter)+'</div>':'')+
      '</div>'+
    '</div>';
  }).join('')+'</div>';
}

function kmkEsc(str){
  return String(str==null?'':str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function kmkEscAttr(str){
  return String(str==null?'':str).replace(/'/g,'&#39;').replace(/"/g,'&quot;');
}

/* ================= ANIME (MangaDex / NontonAnimeID / Otakotaku / Otakudesu) =================
   ENDPOINT MENYUSUL: isi URL di ANM_BASE & ANM_ENDPOINTS di bawah kalau API-nya sudah ada.
   Struktur form/UI sudah lengkap, tinggal isi string endpoint-nya saja tanpa perlu ubah kode lain. */
/* ================= ANIME (MangaDex / NontonAnimeID / Otakotaku / Otakudesu) =================
   ENDPOINT MENYUSUL untuk provider lain: isi di ANM_BASE & ANM_ENDPOINTS di bawah.
   MangaDex sudah diisi -> pakai sylvatica.my.id (apikey sama dengan fitur STALK/lain,
   lewat xyureiRequest supaya otomatis fallback apiKey kalau limit). */
