let anmActiveKey=null;
let anmGridBuilt=false;
let anmGroupOrder=[];

function anmSlotId(group){
  return 'anmSlot_'+group.replace(/[^a-zA-Z0-9]/g,'');
}

function anmBuildGrid(){
  const grid=document.getElementById('anmGrid');
  if(!grid||anmGridBuilt) return;
  let html='';
  let lastGroup=null;
  anmGroupOrder=[];
  ANM_MENU.forEach(function(m){
    if(m.group!==lastGroup){
      if(lastGroup!==null){
        html+='<div class="anm-groupslot" id="'+anmSlotId(lastGroup)+'"></div>';
      }
      html+='<div class="anm-grouplabel">'+m.group+'</div>';
      anmGroupOrder.push(m.group);
      lastGroup=m.group;
    }
    html+='<div class="anm-tile" id="anmTile_'+m.key+'" onclick="anmSelect(\''+m.key+'\')">'+
      '<div class="anm-tile-icon"><i class="fa-solid '+m.icon+'"></i></div><span>'+m.label+'</span></div>';
  });
  if(lastGroup!==null){
    html+='<div class="anm-groupslot" id="'+anmSlotId(lastGroup)+'"></div>';
  }
  grid.innerHTML=html;
  anmGridBuilt=true;
}
document.addEventListener('DOMContentLoaded',anmBuildGrid);

function anmCloseAllSlots(){
  anmGroupOrder.forEach(function(g){
    const slot=document.getElementById(anmSlotId(g));
    if(slot) slot.innerHTML='';
  });
  document.querySelectorAll('#anime .anm-tile').forEach(function(t){t.classList.remove('active');});
}

function anmSelect(key){
  const menu=ANM_MENU.find(function(m){return m.key===key;});
  if(!menu) return;
  const wasOpen=anmActiveKey===key;
  anmCloseAllSlots();
  if(wasOpen){
    anmActiveKey=null;
    return;
  }
  anmActiveKey=key;
  const tile=document.getElementById('anmTile_'+key);
  if(tile) tile.classList.add('active');
  anmRenderForm(menu);
}

function anmRenderForm(menu){
  const area=document.getElementById(anmSlotId(menu.group));
  if(!area) return;
  const inputsHtml=menu.inputs.map(function(inp){
    return '<div class="anm-formrow"><span class="anm-label">'+anmEsc(inp.label)+'</span>'+
      '<input class="anm-searchinput" id="anmInput_'+menu.key+'_'+inp.id+'" type="text" placeholder="'+anmEsc(inp.placeholder||'')+'"/></div>';
  }).join('');
  area.innerHTML=
    '<div class="anm-formcard">'+
      '<div class="anm-formtitle"><i class="fa-solid '+menu.icon+'"></i> '+anmEsc(menu.group)+' — '+anmEsc(menu.label)+'</div>'+
      inputsHtml+
      '<button class="anm-searchbtn" id="anmBtn_'+menu.key+'" onclick="anmSubmit(\''+menu.key+'\')"><i class="fa-solid fa-magnifying-glass"></i> '+(menu.inputs.length?'Cari':'Tampilkan')+'</button>'+
    '</div>'+
    '<div id="anmResult_'+menu.key+'"></div>';
}

async function anmSubmit(key){
  const menu=ANM_MENU.find(function(m){return m.key===key;});
  if(!menu) return;
  const values={};
  for(let i=0;i<menu.inputs.length;i++){
    const inp=menu.inputs[i];
    const el=document.getElementById('anmInput_'+key+'_'+inp.id);
    let v=el?el.value.trim():'';
    if(!v){
      if(inp.optional){
        v=inp.default!==undefined?inp.default:'';
      }else{
        if(el){el.style.borderColor='#ff2b2b';el.focus();setTimeout(function(){el.style.borderColor='';},900);}
        return;
      }
    }
    values[inp.id]=v;
  }
  const area=document.getElementById('anmResult_'+key);
  const btn=document.getElementById('anmBtn_'+key);
  if(!area) return;
  const endpoint=menu.sylvatica?menu.sylvatica:ANM_ENDPOINTS[key];
  if(!endpoint){
    area.innerHTML='<div class="anm-notice"><i class="fa-solid fa-circle-info"></i> Endpoint API untuk "'+anmEsc(menu.group+' - '+menu.label)+'" belum diisi (menyusul).</div>';
    return;
  }
  const origHtml=btn?btn.innerHTML:'';
  if(btn){btn.disabled=true;btn.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> Memuat...';}
  area.innerHTML='<div class="anm-loading"><i class="fa-solid fa-spinner fa-spin"></i> Memuat...</div>';
  try{
    const qs=Object.keys(values).map(function(k){return k+'='+encodeURIComponent(values[k]);}).join('&');
    let json;
    if(menu.sylvatica){
      json=await xyureiRequest(function(apikey){
        return ANM_SYLVATICA_BASE+menu.sylvatica+'?'+qs+(qs?'&':'')+'apikey='+apikey;
      });
    }else{
      const url=ANM_BASE+endpoint+(qs?('?'+qs):'');
      json=await anmFetchAny(url);
    }
    anmRenderGeneric(area,json,menu);
  }catch(err){
    const detail=(err&&err.debugDetail)?' ('+err.debugDetail+')':'';
    area.innerHTML='<div class="anm-fetcherror"><i class="fa-solid fa-triangle-exclamation"></i> Gagal memuat data.<br><span style="font-size:11px;opacity:.7;">'+anmEsc(((err&&err.message)||'')+detail)+'</span></div>';
  }
  if(btn){btn.disabled=false;btn.innerHTML=origHtml;}
}

async function anmFetchAny(url){

  try{
    return await tryOnce(url);
  }catch(directErr){
    try{
      return await tryOnce('https://api.allorigins.win/raw?url='+encodeURIComponent(url));
    }catch(proxyErr){
      throw new Error(directErr.message+' | proxy: '+proxyErr.message);
    }
  }
}

const ANM_SKIP_KEYS=['thumbnail','thumb','image','cover','poster','img','picture','photo','avatar','title','name','judul','nama','displayName','type','status','synopsis','description','desc','genre'];

function anmFindThumb(obj){
  if(!obj||typeof obj!=='object') return '';
  const keys=['thumbnail','thumb','image','cover','poster','img','picture','photo'];
  for(let i=0;i<keys.length;i++){ if(typeof obj[keys[i]]==='string'&&obj[keys[i]]) return obj[keys[i]]; }
  return '';
}
function anmFindTitle(obj,fallback){
  if(!obj||typeof obj!=='object') return fallback||'';
  const keys=['title','name','judul','nama','displayName'];
  for(let i=0;i<keys.length;i++){ if(typeof obj[keys[i]]==='string'&&obj[keys[i]]) return obj[keys[i]]; }
  return fallback||'';
}
function anmFindSub(obj){
  if(!obj||typeof obj!=='object') return '';
  const keys=['type','status','episode','chapter','genre','synopsis','description','desc'];
  for(let i=0;i<keys.length;i++){
    const v=obj[keys[i]];
    if(typeof v==='string'&&v) return v;
    if(Array.isArray(v)&&v.length) return v.join(', ');
  }
  return '';
}
function anmRenderRows(obj){
  if(!obj||typeof obj!=='object') return '';
  let rows='';
  Object.keys(obj).forEach(function(key){
    if(ANM_SKIP_KEYS.indexOf(key)!==-1) return;
    const val=obj[key];
    if(val==null||val==='') return;
    if(typeof val==='object') return;
    rows+='<div class="anm-inforow"><b>'+anmEsc(anmPrettyLabel(key))+'</b><span>'+anmEsc(String(val))+'</span></div>';
  });
  return rows;
}
function anmPrettyLabel(key){
  return key.replace(/_/g,' ').replace(/([a-z])([A-Z])/g,'$1 $2').replace(/\b\w/g,function(c){return c.toUpperCase();});
}

function anmCopyId(el,val){
  const badge=el.querySelector('.anm-itemid');
  function done(){
    if(badge){ const orig=badge.innerHTML; badge.innerHTML='Disalin!'; setTimeout(function(){badge.innerHTML=orig;},1200); }
  }
  function fallback(){
    try{
      const ta=document.createElement('textarea');
      ta.value=val;
      ta.style.position='fixed';ta.style.left='-9999px';
      document.body.appendChild(ta);ta.select();
      document.execCommand('copy');
      document.body.removeChild(ta);
    }catch(e){}
    done();
  }
  if(navigator.clipboard&&navigator.clipboard.writeText){
    navigator.clipboard.writeText(val).then(done).catch(fallback);
  }else{
    fallback();
  }
}

function anmRenderGeneric(area,json,menu){
  let d=(json&&(json.result||json.data||json.results||json.list))||json;
  // beberapa API membungkus array di dalam key lain (mis. animeList/mangaList/episodes/chapters)
  if(d&&typeof d==='object'&&!Array.isArray(d)){
    const nestKeys=['animeList','mangaList','episodes','chapters','anime','episodeList','ongoing','popular'];
    for(let i=0;i<nestKeys.length;i++){
      if(Array.isArray(d[nestKeys[i]])){ d=d[nestKeys[i]]; break; }
    }
  }

  if(menu.key==='md-pages'){
    const arr=Array.isArray(d)?d:((d&&d.images)||[]);
    if(!arr.length){ area.innerHTML='<div class="anm-empty"><i class="fa-solid fa-inbox"></i>Tidak ada halaman ditemukan</div>'; return; }
    area.innerHTML=arr.map(function(img){
      const src=typeof img==='string'?img:((img&&(img.url||img.image||img.src))||'');
      return src?'<img class="anm-readerpage" src="'+anmEsc(src)+'" loading="lazy" onerror="this.style.display=\'none\'">':'';
    }).join('');
    return;
  }

  if(Array.isArray(d)){
    if(!d.length){ area.innerHTML='<div class="anm-empty"><i class="fa-solid fa-inbox"></i>Tidak ada data ditemukan</div>'; return; }
    area.innerHTML=d.map(function(it){
      if(typeof it!=='object'||it===null) return '';
      const thumb=anmFindThumb(it);
      const title=anmFindTitle(it,'-');
      const sub=anmFindSub(it);
      const idVal=it.id||it.slug||it.mangaId||it.animeId||it.episodeId||it.chapterId||it.url||it.link||it.href||'';
      return '<div class="anm-listitem"'+(idVal?(' onclick="anmCopyId(this,\''+anmEscAttr(String(idVal))+'\')"'):'')+'>'+
        (thumb?'<img class="anm-thumb" src="'+anmEsc(thumb)+'" onerror="this.outerHTML=\'<div class=&quot;anm-thumbph&quot;><i class=&quot;fa-solid fa-clapperboard&quot;></i></div>\'">':'<div class="anm-thumbph"><i class="fa-solid fa-clapperboard"></i></div>')+
        '<div class="anm-itembody">'+
          '<div class="anm-itemname">'+anmEsc(title)+'</div>'+
          (sub?'<div class="anm-itemmeta">'+anmEsc(sub)+'</div>':'')+
          (idVal?'<div class="anm-itemid">ID: '+anmEsc(String(idVal))+' <i class="fa-regular fa-copy"></i></div>':'')+
        '</div>'+
      '</div>';
    }).join('');
    return;
  }

  if(d&&typeof d==='object'&&Object.keys(d).length){
    const thumb=anmFindThumb(d);
    const title=anmFindTitle(d,menu.label);
    const sub=anmFindSub(d);
    const rows=anmRenderRows(d);
    area.innerHTML='<div class="anm-infocard">'+
      '<div class="anm-infotop">'+
        (thumb?'<img class="anm-infothumb" src="'+anmEsc(thumb)+'" onerror="this.style.display=\'none\'">':'')+
        '<div><div class="anm-infotitle">'+anmEsc(title)+'</div>'+(sub?'<div class="anm-infoline">'+anmEsc(sub)+'</div>':'')+'</div>'+
      '</div>'+
      (rows||'')+
    '</div>';
    return;
  }

  // Bentuk data tidak dikenali sama sekali -> tampilkan JSON mentah (bukan cuma "kosong")
  // supaya bisa dicek bentuk aslinya, alih-alih terlihat seperti tidak berfungsi.
  let raw='';
  try{ raw=JSON.stringify(json,null,2); }catch(e){ raw=String(json); }
  area.innerHTML='<div class="anm-fetcherror"><i class="fa-solid fa-circle-info"></i> Data diterima tapi format tidak dikenali. Respons mentah:<br>'+
    '<pre style="white-space:pre-wrap;text-align:left;font-size:10px;margin-top:8px;max-height:220px;overflow:auto;">'+anmEsc(raw.slice(0,1500))+'</pre></div>';
}

