    '<input class="mkr-input" id="mkrExtraVal_'+idx+'" type="text" placeholder="nilai">'+
    '<button class="mkr-extraremove" onclick="mkrRemoveExtraField('+idx+')"><i class="fa-solid fa-xmark"></i></button>';
