function mkrShake(el){
  if(!el)return;
  el.classList.remove('shake');
  void el.offsetWidth;
  el.classList.add('shake');
}

function mkrGenerate(){
  const menu=MKR_MENU.find(function(m){return m.key===mkrActiveKey;});
  if(!menu) return;
  const params=[];
  let missingRequired=false;
  menu.fields.forEach(function(f,i){
    const inp=document.getElementById('mkrField_'+i);
    const val=inp?inp.value.trim():'';
    if(f.required && !val){ mkrShake(inp); missingRequired=true; return; }
    if(val) params.push(f.name+'='+encodeURIComponent(val));
  });
  if(missingRequired) return;
  if(!cidPreCheckDiamond(MKR_COST,'mkrGenBtn')) return;
  for(let i=0;i<mkrExtraCount;i++){
    const keyInp=document.getElementById('mkrExtraKey_'+i);
    const valInp=document.getElementById('mkrExtraVal_'+i);
    if(!keyInp||!valInp) continue;
    const k=keyInp.value.trim();
    const v=valInp.value.trim();
    if(k&&v) params.push(encodeURIComponent(k)+'='+encodeURIComponent(v));
  }

  const btn=document.getElementById('mkrGenBtn');
  const result=document.getElementById('mkrResult');
  if(btn){ btn.disabled=true; btn.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> MEMBUAT...'; }
  if(result){ result.classList.remove('show'); result.innerHTML=''; }

  const queryBase=params.join('&');
  mkrTryKey(menu,queryBase);
}

// Cari media (URL gambar/base64) di dalam JSON respons, siapa tahu API tidak
// mengirim byte gambar langsung tapi membungkusnya dalam JSON (mis. {result:"..."}).
function mkrExtractMedia(json,mimeHint){
  if(!json) return null;
  const mime=(mimeHint&&/^(image|video)\//i.test(mimeHint))?mimeHint:'image/png';
  function fromString(s){
    s=String(s).trim();
    if(!s) return null;
    if(/^https?:\/\//i.test(s)) return s;
    if(/^data:/i.test(s)) return s;
    if(s.length>100 && /^[A-Za-z0-9+/=\r\n]+$/.test(s)) return 'data:'+mime+';base64,'+s.replace(/\s+/g,'');
    return null;
  }
  function deep(obj,depth){
    if(depth>5||obj==null) return null;
    if(typeof obj==='string') return fromString(obj);
    if(Array.isArray(obj)){
      for(let i=0;i<obj.length;i++){ const r=deep(obj[i],depth+1); if(r) return r; }
      return null;
    }
    if(typeof obj==='object'){
      const priorityKeys=['result','url','image','media','file','link','src','data','output','buffer'];
      for(const k of priorityKeys){
        if(obj[k]!==undefined){ const r=deep(obj[k],depth+1); if(r) return r; }
      }
      for(const k in obj){
        if(priorityKeys.indexOf(k)!==-1) continue;
        const r=deep(obj[k],depth+1); if(r) return r;
      }
    }
    return null;
  }
  return deep(json,0);
}

async function mkrTryKey(menu,queryBase){
  const btn=document.getElementById('mkrGenBtn');
  const result=document.getElementById('mkrResult');
  const sep=queryBase?'&':'';
  const url=MKR_BASE+menu.key+'?'+queryBase+sep+'apikey='+encodeURIComponent(XYUREI_API_KEY);

  function fail(){
    if(btn){ btn.disabled=false; btn.innerHTML='<i class="fa-solid fa-wand-magic-sparkles"></i> GENERATE'; }
    if(result){
      result.classList.add('show');
      result.innerHTML='<div class="mkr-fetcherror" style="margin:14px;"><i class="fa-solid fa-triangle-exclamation"></i> Gagal membuat gambar. Coba lagi nanti.</div>';
    }
  }

  try{
    let res;
    try{
      // referrerPolicy 'no-referrer' meniru curl (tanpa header Referer),
      // menghindari server yang memblokir hotlink berbasis Referer.
      res=await fetch(url,{headers:{'Accept':'image/*, application/json, */*'},referrerPolicy:'no-referrer-when-downgrade'});
    }catch(networkErr){
      res=await fetch('https://api.allorigins.win/raw?url='+encodeURIComponent(url));
    }
    const contentType=(res.headers.get('content-type')||'').toLowerCase();

    if(/^image\//.test(contentType)){
      if(!res.ok) throw new Error('HTTP '+res.status);
      const blob=await res.blob();
      if(blob.size<200) throw new Error('Gambar kosong/terlalu kecil, kemungkinan error tersamar sebagai gambar.');
      const blobUrl=URL.createObjectURL(blob);
      mkrShowResult(menu,blobUrl);
      return;
    }

    const text=await res.text();
    let json=null;
    try{ json=JSON.parse(text); }catch(parseErr){}
    if(!res.ok || (json&&(json.status===false||json.status==='false'||json.success===false))){
      return fail();
    }
    const mimeHint=json&&(json.info||json.mime||json.mimetype||json.contentType);
    const media=json?mkrExtractMedia(json,mimeHint):null;
    if(!media){
      return fail();
    }
    mkrShowResult(menu,media);
  }catch(e){
    return fail();
  }
}

function mkrShowResult(menu,mediaUrl){
  cidDeductDiamond(MKR_COST,menu.label,'Maker: '+menu.label);
  const btn=document.getElementById('mkrGenBtn');
  const result=document.getElementById('mkrResult');
  if(btn){ btn.disabled=false; btn.innerHTML='<i class="fa-solid fa-wand-magic-sparkles"></i> GENERATE'; }
  if(result){
    result.classList.add('show');
    result.innerHTML='<img class="mkr-result-media" src="'+mkrEscAttr(mediaUrl)+'" alt="'+mkrEscAttr(menu.label)+'" referrerpolicy="no-referrer">'+
      '<div class="mkr-result-body">'+
        '<button class="mkr-dlbtn" onclick="mkrDownload(\''+mkrEscAttr(mediaUrl)+'\',\''+mkrEscAttr(menu.key)+'\')"><i class="fa-solid fa-download"></i> DOWNLOAD</button>'+
        '<button class="mkr-dlbtn mkr-alt" onclick="mkrSelect(\''+mkrEscAttr(menu.key)+'\')"><i class="fa-solid fa-rotate-right"></i> ULANGI</button>'+
      '</div>';
  }
}

async function mkrDownload(url,keyName){
  try{
    const res=await fetch(url,{referrerPolicy:'no-referrer-when-downgrade'});
    const blob=await res.blob();
    const blobUrl=URL.createObjectURL(blob);
    const link=document.createElement('a');
    link.href=blobUrl;
    link.download='KZRIZUSMO-'+keyName+'-'+Date.now()+'.png';
    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(blobUrl);
  }catch(e){
    if(typeof showToast==='function') showToast('Gagal simpan langsung, membuka file...');
    aiSaveMediaFallback(url);
  }
}

