function clbShowState(which){
  ['clbStateIdle','clbStateLoading','clbStateError'].forEach(function(id){
    const el=document.getElementById(id);
    if(el) el.classList.toggle('show',id===which);
  });
  const result=document.getElementById('clbResult');
  if(result) result.classList.toggle('show',which===null);
}

function clbSetLoadingBtn(loading){
  const btn=document.getElementById('clbSetBtn');
  if(!btn) return;
  if(loading){
    btn.disabled=true;
    btn.dataset.origHtml=btn.innerHTML;
    btn.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i>MEMPROSES...';
  }else{
    btn.disabled=false;
    if(btn.dataset.origHtml) btn.innerHTML=btn.dataset.origHtml;
  }
}

function clbShake(elId){
  const inp=document.getElementById(elId);
  if(!inp) return;
  inp.classList.remove('cid-shake');
  void inp.offsetWidth;
  inp.classList.add('cid-shake');
  inp.focus();
}

// Petakan status error dari API (yang bukan lewat field "error", tapi lewat
// field "status" sendiri, mis. {"status":"Unauthorized (Invalid JWT)","code":401})
// jadi pesan yang lebih enak dibaca. Kalau statusnya belum dikenal, tampilkan
// apa adanya dari server supaya tetap informatif.
function clbFriendlyStatusText(status,code){
  const s=String(status||'').toLowerCase();
  if(s.indexOf('invalid jwt')>-1||s.indexOf('unauthorized')>-1){
    return 'JWT token tidak valid atau sudah kadaluarsa. Ambil ulang JWT token akun kamu, lalu coba lagi.';
  }
  if(s.indexOf('guest login failed')>-1){
    return 'Login gagal. Pastikan JWT token yang dipakai masih aktif.';
  }
  return String(status)+(code?' (kode '+code+')':'');
}

