let clbGenToken='';
function clbExtractTokenFromInput(raw){
  raw=raw.trim();
  if(!raw) return '';
  const keys=['eat','access_token','accessToken','token','jwt','id_token','auth_token','key'];
  if(/^https?:\/\//i.test(raw)){
    try{
      const u=new URL(raw);
      const search=new URLSearchParams(u.search);
      const hash=new URLSearchParams(u.hash.replace(/^#/,''));
      for(const k of keys){
        if(search.get(k)) return search.get(k);
        if(hash.get(k)) return hash.get(k);
      }
    }catch(e){}
    return raw;
  }
  const m=raw.match(/[?&#](?:eat|access_token|accessToken|token|jwt|id_token|auth_token|key)=([^&\s]+)/i);
  if(m) return decodeURIComponent(m[1]);
  return raw;
}
function clbGenerateAccess(){
  const inp=document.getElementById('clbUrlInput');
  const btn=document.getElementById('clbGenBtn');
  const raw=inp?inp.value:'';
  if(!raw||!raw.trim()){
    if(inp){inp.classList.add('cid-shake');setTimeout(function(){inp.classList.remove('cid-shake');},400);}
    return;
  }
  clbGenToken=clbExtractTokenFromInput(raw);
  const resBox=document.getElementById('clbGenResult');
  const resText=document.getElementById('clbGenResultText');
  if(resText) resText.textContent=clbGenToken;
  if(resBox) resBox.style.display='block';
}
function clbFallbackCopy(text,cb){
  try{
    const ta=document.createElement('textarea');
    ta.value=text;
    ta.style.position='fixed';ta.style.opacity='0';ta.className='allow-copy';
    document.body.appendChild(ta);
    ta.focus();ta.select();
    document.execCommand('copy');
    document.body.removeChild(ta);
    if(cb) cb();
  }catch(e){console.error('[CLB] copy fallback gagal',e);}
}
function clbCopyGenResult(ev){
  if(!clbGenToken) return;
  const btn=(ev&&ev.currentTarget)?ev.currentTarget:document.querySelector('.clb-gen-mini-btn[onclick^="clbCopyGenResult"]');
  function done(){
    if(!btn) return;
    const orig=btn.innerHTML;
    btn.classList.add('copied');
    btn.innerHTML='<i class="fa-solid fa-check"></i>Tersalin';
    setTimeout(function(){ btn.classList.remove('copied'); btn.innerHTML=orig; },1500);
  }
  if(navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(clbGenToken).then(done).catch(function(){ clbFallbackCopy(clbGenToken,done); });
  }else{
    clbFallbackCopy(clbGenToken,done);
  }
}
function clbUseGenResult(){
  if(!clbGenToken) return;
  if(clbActiveMethod==='access'){
    const el=document.getElementById('clbAccessInput');
    if(el) el.value=clbGenToken;
  }else if(clbActiveMethod==='uidpass'){
    return;
  }else{
    const el=document.getElementById('clbJwtInput');
    if(el) el.value=clbGenToken;
  }
}

let clbActiveMethod='jwt';
function clbSwitchMethod(method){
  clbActiveMethod=method;
  const tabsWrap=document.getElementById('clbMethodTabs');
  if(tabsWrap){
    tabsWrap.querySelectorAll('.cid-rank-tab').forEach(function(t){
      t.classList.toggle('active',t.getAttribute('data-method')===method);
    });
  }
  const jwtWrap=document.getElementById('clbJwtWrap');
  const accessWrap=document.getElementById('clbAccessWrap');
  const uidPassWrap=document.getElementById('clbUidPassWrap');
  if(jwtWrap) jwtWrap.style.display=(method==='jwt')?'':'none';
  if(accessWrap) accessWrap.style.display=(method==='access')?'':'none';
  if(uidPassWrap) uidPassWrap.style.display=(method==='uidpass')?'':'none';
}

async function clbUpdateBio(){
  const bioInp=document.getElementById('clbBioInput');
  const jwtInp=document.getElementById('clbJwtInput');
  const accessInp=document.getElementById('clbAccessInput');
  const uidInp=document.getElementById('clbUidInput');
  const passInp=document.getElementById('clbPassInput');
  const bio=bioInp?bioInp.value.trim():'';
  const jwt=jwtInp?jwtInp.value.trim():'';
  const access=accessInp?accessInp.value.trim():'';
  const uid=uidInp?uidInp.value.trim():'';
  const pass=passInp?passInp.value.trim():'';
  const isUidPass=(clbActiveMethod==='uidpass');
  const useAccess=(clbActiveMethod==='access');
  const authVal=isUidPass?(uid&&pass):(useAccess?access:jwt);
  const authFieldId=isUidPass?(uid?'clbPassInput':'clbUidInput'):(useAccess?'clbAccessInput':'clbJwtInput');

  if(!bio){ clbShake('clbBioInput'); return; }
  if(!authVal){ clbShake(authFieldId); return; }
  if(!cidPreCheckDiamond(CID_ACTION_COST,'clbSetBtn')) return;

  clbShowState('clbStateLoading');
  clbSetLoadingBtn(true);

  try{
    let authParam;
    if(isUidPass) authParam='&uid='+encodeURIComponent(uid)+'&pass='+encodeURIComponent(pass);
    else if(useAccess) authParam='&access='+encodeURIComponent(access);
    else authParam='&jwt='+encodeURIComponent(jwt);
    const url=TFF_BASE+'/longbio/bio_upload?bio='+encodeURIComponent(bio)+authParam+'&key='+encodeURIComponent(TFF_KEY);
    const json=await stkFetchJsonSmart(url);

    if(!json){
      throw Object.assign(new Error('Gagal menghubungi server API.'),{raw:json});
    }
    if(json.error){
      const errLower=String(json.error).toLowerCase();
      let friendly=String(json.error);
      if(errLower.indexOf('jwt')>-1||errLower.indexOf('access')>-1||errLower.indexOf('token')>-1) friendly='Token belum diisi atau tidak valid. ('+json.error+')';
      else if(errLower.indexOf('bio')>-1) friendly='Teks bio belum diisi atau tidak valid. ('+json.error+')';
      throw Object.assign(new Error(friendly),{raw:json});
    }
    const statusLower=json.status?String(json.status).toLowerCase():'';
    if(statusLower&&statusLower!=='success'){
      throw Object.assign(new Error(clbFriendlyStatusText(json.status,json.code)),{raw:json});
    }
    cidDeductDiamond(CID_ACTION_COST,'Update Bio Panjang FF','Update bio: '+bio.slice(0,40));

    const rowsEl=document.getElementById('clbInfoRows');
    if(rowsEl){
      let rows='';
      rows+='<div class="cid-info-row"><b>Nama Akun</b><span>'+tffEsc(json.name||'-')+'</span></div>';
      rows+='<div class="cid-info-row"><b>UID</b><span>'+tffEsc(json.uid||'-')+'</span></div>';
      rows+='<div class="cid-info-row"><b>Region</b><span>'+tffEsc(json.region||'-')+'</span></div>';
      rows+='<div class="cid-info-row"><b>Metode Login</b><span>'+tffEsc(json.login_method||'-')+'</span></div>';
      rows+='<div class="cid-info-row"><b>Bio Baru</b><span>'+tffEsc(json.bio||bio)+'</span></div>';
      rows+='<div class="cid-info-row"><b>Status</b><span>'+tffEsc(json.status||'-')+'</span></div>';
      if(json.generated_jwt){
        rows+='<div class="cid-info-row"><b>Generated JWT</b><span style="word-break:break-all;">'+tffEsc(json.generated_jwt)+'</span></div>';
      }
      rowsEl.innerHTML=rows;
    }

    clbShowState(null);
  }catch(e){
    console.error('[CLB]',e,(e&&e.raw)||'');
    const errMsg=document.getElementById('clbErrorMsg');
    if(errMsg) errMsg.textContent=(e&&e.message)||'Gagal update bio. Periksa kembali teks bio & token kamu.';
    clbShowState('clbStateError');
  }
  clbSetLoadingBtn(false);
}

