const CID_CHECK_COST=100;
const CID_POPULER_UIDS=['260190210','55558144','131069134','105581609','15555555554'];

/* Helper generik dipakai semua fitur CEK INFO FF berbayar (Cek Outfit, Cek
   Banner, Statistik Ranked, Info Guild, Cek Exp Level, Info Craftland,
   Craftland Detail): cek saldo dulu sebelum request dimulai (biar gak buang
   request kalau diamond kurang), shake+toast kalau kurang. Pemotongan
   saldo aslinya (cidDeductDiamond) baru dipanggil masing-masing fungsi
   SETELAH hasil sukses didapat, supaya percobaan yang gagal (ID/kode tidak
   ketemu) tidak memotong diamond. */
function cidPreCheckDiamond(cost,btnId){
  if(typeof window.getDiamond!=='function' || typeof window.setDiamond!=='function'){ return false; }
  if(window.getDiamond() < cost){
    const btn=btnId?document.getElementById(btnId):null;
    if(btn){ btn.classList.remove('shake'); void btn.offsetWidth; btn.classList.add('shake'); setTimeout(function(){ btn.classList.remove('shake'); },550); }
    if(typeof window.zxShowToast==='function') window.zxShowToast('Diamond kamu tidak cukup (butuh '+cost+', saldo: '+window.getDiamond()+')','error');
    if(window.ZUSMO && window.ZUSMO.playClick) window.ZUSMO.playClick();
    return false;
  }
  return true;
}
function cidDeductDiamond(cost,title,desc){
  window.setDiamond(window.getDiamond() - cost);
  if(typeof window.addHistoryEntry==='function') window.addHistoryEntry('buy',title,desc,-cost);
}
const CID_SUB_COST=50;
const CID_ACTION_COST=90;

async function cidCheck(){
  const inp=document.getElementById('cidUidInput');
  const uid=inp?inp.value.trim():'';
  if(!uid||uid.length<6){ cidShake(); return; }

  const isPopuler=CID_POPULER_UIDS.indexOf(uid)!==-1;
  if(!isPopuler){
    if(typeof window.getDiamond!=='function' || typeof window.setDiamond!=='function'){ return; }
    if(window.getDiamond() < CID_CHECK_COST){
      const btn=document.getElementById('cidCheckBtn');
      if(btn){ btn.classList.remove('shake'); void btn.offsetWidth; btn.classList.add('shake'); setTimeout(function(){ btn.classList.remove('shake'); },550); }
      if(typeof window.zxShowToast==='function') window.zxShowToast('Diamond kamu tidak cukup (butuh '+CID_CHECK_COST+', saldo: '+window.getDiamond()+')','error');
      if(window.ZUSMO && window.ZUSMO.playClick) window.ZUSMO.playClick();
      return;
    }
  }

  cidShowState('cidStateLoading');
  cidSetLoadingBtn(true);

  let lastErr=null;
  let charged=false;
  for(let i=0;i<TFF_ALL_REGIONS.length;i++){
    const region=TFF_ALL_REGIONS[i];
    const queryBase='key='+encodeURIComponent(TFF_KEY)+'&uid='+encodeURIComponent(uid)+'&region='+encodeURIComponent(region);
    try{
      const json=await xyureiRequest(function(){
        return TFF_BASE+'/freefireinfo/bhau?'+queryBase;
      },{isDataOk:function(j){ return !!(j&&(j.basicInfo||j.data||j.result)); }});

      if(json&&json.error){ throw Object.assign(new Error(json.error),{raw:json}); }
      const b=json.basicInfo||{};
      const nickname=stkPick(b,['nickname']);
      if(!nickname){ throw Object.assign(new Error('Nickname tidak ditemukan.'),{raw:json}); }
      const uidVal=stkPick(b,['accountId','account_id'])||uid;

      if(!isPopuler && !charged){
        window.setDiamond(window.getDiamond() - CID_CHECK_COST);
        if(typeof window.addHistoryEntry==='function') window.addHistoryEntry('buy','Cek Info FF','Cek info player: '+uidVal,-CID_CHECK_COST);
        charged=true;
      }

      // Banner (gambar PNG langsung dari server, berisi avatar+nama+guild+level)
      // & statistik ranked BR/CS dianggap pelengkap: kalau gagal/limit,
      // profil utama tetap tampil tanpa bagian itu.
      const bannerUrl=tffBuildBannerUrl(uidVal,region);
      let statsBr=null,statsCs=null,statsBrErr=null,statsCsErr=null;
      try{ statsBr=await tffFetchStats(uidVal,region,'br','RANKED'); console.log('[CID] statistik BR:',statsBr); }catch(e){ statsBr=null; statsBrErr=(e&&e.debugDetail)||(e&&e.message)||'Gagal memuat.'; console.warn('[CID] statistik BR gagal:',e); }
      try{ statsCs=await tffFetchStats(uidVal,region,'cs','RANKED'); console.log('[CID] statistik CS:',statsCs); }catch(e){ statsCs=null; statsCsErr=(e&&e.debugDetail)||(e&&e.message)||'Gagal memuat.'; console.warn('[CID] statistik CS gagal:',e); }

      const profileHeadEl=document.getElementById('cidProfileHead');
      if(profileHeadEl){ profileHeadEl.innerHTML=tffBuildProfileHead(json,{bannerUrl:bannerUrl,showItems:true},'cidCheck()'); tffFitBioText(profileHeadEl); }
      const devFlagEl=document.getElementById('cidDevFlag');
      if(devFlagEl) devFlagEl.style.display=(String(uidVal)==='260190210')?'flex':'none';
      const bannerAvatarEl=document.getElementById('cidBannerAvatar');
      if(bannerAvatarEl){
        bannerAvatarEl.innerHTML=bannerUrl?(
          '<div class="cid-banner-full"><img src="'+tffAttrEsc(bannerUrl)+'" alt="banner profil" referrerpolicy="no-referrer" onerror="this.parentElement.style.display=\'none\'"></div>'
        ):'<div class="cid-info-row-error" style="border-top:none;justify-content:center;"><i class="fa-solid fa-triangle-exclamation"></i>Banner tidak tersedia.</div>';
      }
      cidRankData.br=stkPick(b,['rankingPoints','ranking_points','rankingpoints']);
      cidRankData.cs=stkPick(b,['csRankingPoints','cs_ranking_points','csrankingpoints']);
      cidRankActiveGame='br';
      const rankTabsEl=document.getElementById('cidRankTabs');
      if(rankTabsEl) rankTabsEl.querySelectorAll('.cid-rank-tab').forEach(function(t){ t.classList.toggle('active',t.dataset.game==='br'); });
      const rankBodyEl=document.getElementById('cidRankBody');
      if(rankBodyEl) rankBodyEl.innerHTML=cidBuildRankBody(cidRankData.br,'br');
      const infoRows=document.getElementById('cidInfoRows');
      if(infoRows){ infoRows.innerHTML=cidRenderInfoSections(json,{statsBr:statsBr,statsCs:statsCs,statsBrErr:statsBrErr,statsCsErr:statsCsErr}); infoRows.style.display='none'; }
      const infoToggleBtn=document.getElementById('cidInfoToggleBtn');
      if(infoToggleBtn){ infoToggleBtn.classList.remove('open'); infoToggleBtn.innerHTML='Tampilkan<i class="fa-solid fa-chevron-down"></i>'; }

      cidLoadOutfit(uidVal,region);

      cidShowState(null);
      cidSetLoadingBtn(false);
      return;
    }catch(e){
      lastErr=e;
      console.warn('[CID] region '+region+' gagal, coba region berikutnya...',(e&&e.debugDetail)||e);
    }
  }

  console.error('[CID]',lastErr,(lastErr&&lastErr.raw)||'');
  const msg=(lastErr&&lastErr.isNetwork)?'Gagal menghubungi server. Coba lagi beberapa saat.':'ID Free Fire tidak ditemukan. Periksa kembali ID kamu.';
  const errMsg=document.getElementById('cidErrorMsg');
  if(errMsg) errMsg.textContent=msg;
  cidShowState('cidStateError');
  cidSetLoadingBtn(false);
}

/* Download KHUSUS kolom 1 (kartu profil utama CEK INFO FF) jadi gambar PNG.
   Tampilan normal di layar TIDAK diubah sama sekali. Saat proses:
   1) tombol download berubah jadi ikon loading (spinner) & gak bisa
      diklik dobel, tapi tetap kelihatan di layar (cuma DIKECUALIKAN dari
      hasil capture lewat ignoreElements, bukan disembunyikan lewat CSS).
   2) class cid-export-solid ditempel sebentar cuma buat mematikan efek
      shine pojok & bikin background solid KHUSUS di hasil unduhan (lihat
      CSS-nya), lalu dilepas lagi setelah selesai.
   3) html2canvas capture pakai backgroundColor:null (transparan) supaya
      cuma bentuk kartu yang ke-render (siku-siku tumpul, sama kayak
      tampilan sebelum diunduh), lalu hasilnya ditaruh di tengah kanvas
      baru berukuran rasio 9:16 (sisanya transparan) biar file yang
      terunduh selalu 9:16.
   4) begitu link download ke-klik, tombol berubah jadi ikon ceklis
      sebentar sebagai tanda selesai, baru balik ke ikon download lagi. */
function cidDownloadCard1(){
  const card=document.getElementById('cidCard1');
  if(!card||typeof html2canvas!=='function') return;
  const btn=card.querySelector('.cid-card-download-btn');
  const icon=btn?btn.querySelector('i'):null;
  if(btn&&btn.classList.contains('cid-dl-busy')) return; // cegah klik dobel
  if(btn){ btn.classList.add('cid-dl-busy'); btn.classList.remove('cid-dl-done'); }
  if(icon){ icon.className='fa-solid fa-spinner fa-spin'; }
  card.classList.add('cid-export-solid');
  html2canvas(card,{
    backgroundColor:null,
    useCORS:true,
    scale:2,
    ignoreElements:function(el){ return !!(el&&el.classList&&el.classList.contains('cid-card-download-btn')); }
  }).then(function(canvas){
    card.classList.remove('cid-export-solid');
    // Kanvas baru rasio 9:16. Kartu TIDAK PERNAH dipotong (siku-sikunya
    // yang tumpul tetap utuh): kalau muat penuh di lebar frame, kartu
    // dipas-in mentok atas-bawah + margin transparan kiri-kanan. Kalau
    // kartu lebih lebar dari frame, baru diperkecil proporsional (gak
    // gepeng) biar tetap masuk penuh, jadi ada margin transparan
    // atas-bawah sebagai gantinya. Intinya kartu selalu utuh & center.
    const W=canvas.width, H=canvas.height;
    const outH=H, outW=Math.round(H*9/16);
    const outCanvas=document.createElement('canvas');
    outCanvas.width=outW; outCanvas.height=outH;
    const ctx=outCanvas.getContext('2d');
    let drawW=W,drawH=H,offX=0,offY=0;
    if(W>outW){
      const s=outW/W;
      drawW=outW; drawH=Math.round(H*s);
      offY=Math.round((outH-drawH)/2);
    }else{
      offX=Math.round((outW-W)/2);
    }
    ctx.drawImage(canvas,offX,offY,drawW,drawH);
    const link=document.createElement('a');
    link.download='kzrizusmo-infoplayer-'+Date.now()+'.png';
    link.href=outCanvas.toDataURL('image/png');
    document.body.appendChild(link);
    link.click();
    link.remove();
    if(btn){ btn.classList.remove('cid-dl-busy'); btn.classList.add('cid-dl-done'); }
    if(icon){ icon.className='fa-solid fa-check'; }
    setTimeout(function(){
      if(btn) btn.classList.remove('cid-dl-done');
      if(icon) icon.className='fa-solid fa-download';
    },1800);
  }).catch(function(e){
    card.classList.remove('cid-export-solid');
    if(btn){ btn.classList.remove('cid-dl-busy'); }
    if(icon){ icon.className='fa-solid fa-download'; }
    console.error('[CID] Gagal download kolom 1 jadi gambar',e);
  });
}

/* Susun beberapa bagian info (akun, guild, ketua guild, pet, sosial, harga, skor kredit, profil)
   memakai kamus label & formatter yang sama dengan STALK FREE FIRE (TFF_*), ditampilkan
   dalam gaya baris cid-info-row supaya konsisten dengan tampilan halaman ini. */
function cidRenderInfoSections(json,extra){
  extra=extra||{};
  const statsBrOk=!!extra.statsBr, statsCsOk=!!extra.statsCs;
  const sections=[
    ['fa-user-shield','Info Akun',json.basicInfo,['nickname','accountid','level','liked','region','primelevel','createat','lastloginat','signature'],null,null],
    ['fa-ranking-star','Statistik Ranked BR',null,[],extra.statsBrErr,statsBrOk?tffUnwrap(extra.statsBr):null],
    ['fa-chess-board','Statistik Ranked CS',null,[],extra.statsCsErr,statsCsOk?tffUnwrap(extra.statsCs):null],
    ['fa-shield-halved','Info Guild',json.clanBasicInfo,['clanname','id','clanlevel','membernum','captainid'],null,null],
    ['fa-crown','Info Ketua Guild',json.captainBasicInfo,['nickname'],null,null],
    ['fa-paw','Info Peliharaan',json.petInfo,['id','skinid'],null,null],
    ['fa-comment-dots','Info Sosial',json.socialInfo,['signature'],null,null],
    ['fa-gem','Perkiraan Harga',json.diamondCostRes,[],null,null],
    ['fa-star','Skor Kredit',json.creditScoreInfo,[],null,null],
    ['fa-user-astronaut','Info Profil',json.profileInfo,[],null,null]
  ];
  // Chip bergambar (outfit/skin senjata/skin pet/dll) sudah dipindahkan ke
  // kolom 1 (di bawah Bio, lihat cidCombinedItemIconsHtml) jadi tidak
  // diulang lagi di sini.
  let html='';
  sections.forEach(function(sec){
    const rows=cidRenderRows(sec[2],sec[3])||(sec[5]!=null?cidStatsRowsHtml(sec[5]):'');
    const head='<div class="cid-section-title"><i class="fa-solid '+sec[0]+'"></i>'+tffEsc(sec[1])+'</div>';
    if(rows){
      html+=head+rows;
    }else if(sec[4]){
      html+=head+'<div class="cid-info-row-error"><i class="fa-solid fa-triangle-exclamation"></i>Gagal memuat: '+tffEsc(String(sec[4]))+'</div>';
    }else if(sec[5]!==undefined&&sec[5]!==null){
      // Fetch berhasil (bukan error), cuma field-nya kosong/semua null -> artinya
      // pemain ini memang belum pernah main mode ranked tsb (bukan bug/gagal fetch).
      // Tampilkan pesan yang jelas, TANPA dump JSON mentah (kelihatan kayak error).
      html+=head+'<div class="cid-info-row-error"><i class="fa-solid fa-circle-info"></i>Belum ada data untuk mode ini (kemungkinan pemain belum pernah main '+tffEsc(sec[1])+').</div>';
    }
  });
  return html;
}
// Field ID tunggal (banner/avatar/pin/badge) bisa muncul di basicInfo atau
// profileInfo tergantung respons API — dicoba dari keduanya biar gak kelewat.
function cidPickId(json,key){
  const a=json.basicInfo&&json.basicInfo[key];
  if(a!=null&&a!=='') return a;
  const b=json.profileInfo&&json.profileInfo[key];
  if(b!=null&&b!=='') return b;
  return null;
}
// Sama seperti cidPickId, tapi nama field dicocokkan case-insensitive (besar/
// kecil huruf diabaikan). Dipakai untuk field yang casing aslinya dari API
// belum pasti (mis. headPic/title/equipedSkills), biar tetap ketemu walau
// beda huruf besar-kecil — sama seperti TFF_ROW_SKIP_KEYS yang juga
// dicocokkan lewat key.toLowerCase().
function cidPickAnyCI(obj,keyLower){
  if(!obj||typeof obj!=='object') return undefined;
  const keys=Object.keys(obj);
  for(let i=0;i<keys.length;i++){
    if(keys[i].toLowerCase()===keyLower) return obj[keys[i]];
  }
  return undefined;
}
function cidPickIdCI(json,keyLower){
  const a=cidPickAnyCI(json.basicInfo,keyLower);
  if(a!=null&&a!=='') return a;
  const b=cidPickAnyCI(json.profileInfo,keyLower);
  if(b!=null&&b!=='') return b;
  return null;
}

function cidRenderRows(obj,extraSkip){
  if(!obj||typeof obj!=='object') return '';
  const skipExtra=extraSkip||[];
  const keys=Object.keys(obj).filter(function(key){
    if(TFF_ROW_SKIP_KEYS.indexOf(key.toLowerCase())!==-1) return false;
    if(skipExtra.indexOf(key.toLowerCase())!==-1) return false;
    const val=obj[key];
    return !(val==null||val===''||typeof val==='object');
  });
  keys.sort(function(a,b){
    const ia=TFF_FIELD_ORDER.indexOf(a.toLowerCase());
    const ib=TFF_FIELD_ORDER.indexOf(b.toLowerCase());
    const pa=ia===-1?999:ia, pb=ib===-1?999:ib;
    return pa-pb;
  });
  const TFF_DATE_KEYS=['lastloginat','createat'];
  let rows='';
  keys.forEach(function(key){
    const val=obj[key];
    const label=tffPrettyLabel(key);
    const kLower=key.toLowerCase();
    let displayVal;
    if(TFF_DATE_KEYS.indexOf(kLower)!==-1){
      displayVal=tffRelativeTime(val)||tffPrettyValue(key,val);
    }else{
      displayVal=tffPrettyValue(key,val);
    }
    rows+='<div class="cid-info-row"><b>'+tffEsc(label)+'</b><span>'+tffEsc(displayVal)+'</span></div>';
  });
  return rows;
}

/* Kolom "Pangkat Ranked" di CEK INFO FF: tab Battle Royale / Clash Squad,
   pakai tabel ambang poin TFF_RANK_BR_TABLE/TFF_RANK_CS_TABLE yang sama
   dengan badge pangkat di STALK FREE FIRE supaya tier & ikonnya konsisten. */
let cidRankData={br:null,cs:null};
let cidRankActiveGame='br';
function cidRankSwitch(game){
  cidRankActiveGame=game;
  const tabsEl=document.getElementById('cidRankTabs');
  if(tabsEl) tabsEl.querySelectorAll('.cid-rank-tab').forEach(function(t){ t.classList.toggle('active',t.dataset.game===game); });
  const bodyEl=document.getElementById('cidRankBody');
  if(bodyEl) bodyEl.innerHTML=cidBuildRankBody(cidRankData[game],game);
}
function cidBuildRankBody(points,game){
  if(points==null||points===''){
    return '<div class="cid-rank-panel"><div class="cid-rank-empty"><i class="fa-solid fa-circle-info"></i>Data pangkat '+(game==='cs'?'Clash Squad':'Battle Royale')+' tidak tersedia.</div></div>';
  }
  const table=game==='cs'?TFF_RANK_CS_TABLE:TFF_RANK_BR_TABLE;
  const entry=tffRankLookup(points,table);
  if(!entry){
    return '<div class="cid-rank-panel"><div class="cid-rank-empty"><i class="fa-solid fa-circle-info"></i>Data pangkat '+(game==='cs'?'Clash Squad':'Battle Royale')+' tidak tersedia.</div></div>';
  }
  const idx=table.indexOf(entry);
  const next=idx>=0&&idx<table.length-1?table[idx+1]:null;
  let barPct=100,nextHtml='<i class="fa-solid fa-crown"></i> Pangkat tertinggi tercapai';
  if(next){
    const span=next.min-entry.min;
    const prog=span>0?((Number(points)-entry.min)/span)*100:100;
    barPct=Math.max(2,Math.min(100,prog));
    const remaining=Math.max(0,next.min-Number(points));
    nextHtml='Kurang <b style="color:#eee">'+tffEsc(String(remaining))+'</b> poin ke '+tffEsc(next.label);
  }
  const file=game+entry.tier+'.png';
  return '<div class="cid-rank-panel"><div class="cid-rank-body">'+
      '<img class="cid-rank-icon" src="zusmo-asset/'+file+'" alt="'+tffAttrEsc(entry.label)+'" onerror="this.style.visibility=\'hidden\'">'+
      '<div class="cid-rank-info">'+
        '<div class="cid-rank-tier">'+tffEsc(entry.label)+'</div>'+
        '<div class="cid-rank-points"><i class="fa-solid fa-bolt"></i>'+tffEsc(String(points))+' Poin</div>'+
        '<div class="cid-rank-bar-wrap"><div class="cid-rank-bar-fill" style="width:'+barPct+'%"></div></div>'+
        '<div class="cid-rank-next">'+nextHtml+'</div>'+
      '</div>'+
    '</div></div>';
}

/* Kolom outfit di CEK INFO FF: memakai endpoint /outfits/outfit & fungsi retry
   antar-region (cofTryRegion) yang sama dengan halaman CEK OUTFIT, ditampilkan
   dalam bingkai persegi (1x1) supaya pas jadi satu kolom kecil. Dijalankan
   belakangan (tidak di-await) supaya profil utama tetap tampil cepat walau
   outfit masih dimuat/gagal. */
function cidLoadOutfit(uidVal,region){
  const frame=document.getElementById('cidOutfitFrame');
  if(!frame) return;
  frame.innerHTML='<div class="cid-rank-empty"><i class="fa-solid fa-spinner fa-spin"></i>Memuat outfit...</div>';
  const regions=[region].concat(TFF_ALL_REGIONS.filter(function(r){ return r!==region; }));
  cofTryRegion(uidVal,regions,0).then(function(res){
    const f=document.getElementById('cidOutfitFrame');
    if(f) f.innerHTML='<img class="cid-outfit-img" src="'+tffAttrEsc(res.url)+'" alt="outfit" referrerpolicy="no-referrer">'+
      '<img class="cid-outfit-watermark" src="zusmo-asset/677288085_miwamikadono.jpg" alt="KZRIZUSMO">';
  }).catch(function(){
    const f=document.getElementById('cidOutfitFrame');
    if(f) f.innerHTML='<div class="cid-rank-empty"><i class="fa-solid fa-triangle-exclamation"></i>Outfit tidak tersedia.</div>';
  });
}

