/* Muat gambar jadi elemen <img> lewat Promise. crossOrigin='anonymous' WAJIB
   dipasang untuk gambar outfit (beda domain) supaya canvas tidak "tainted"
   dan boleh diekspor (toBlob/getImageData) -- kalau server API tidak
   mengizinkan CORS, pemuatan ini akan gagal dan cofDownload otomatis
   fallback ke file asli (lihat catch di cofDownload). Watermark tidak perlu
   crossOrigin karena filenya satu domain dengan web ini. */
function cofLoadImgEl(src,crossOrigin){
  return new Promise(function(resolve,reject){
    const img=new Image();
    if(crossOrigin) img.crossOrigin=crossOrigin;
    img.referrerPolicy='no-referrer';
    img.onload=function(){ resolve(img); };
    img.onerror=function(e){ reject(e); };
    img.src=src;
  });
}

/* Bikin ulang persis efek yang dilihat user di tampilan (filter suhu warna
   SVG + contrast/brightness/saturate CSS + watermark bulat pojok kanan
   bawah), tapi kali ini "dibakar" langsung ke piksel gambar lewat canvas
   supaya file PNG yang diunduh sama seperti yang ditampilkan -- bukan cuma
   efek CSS yang hilang begitu file dibuka di luar web ini. */
async function cofBuildDownloadBlob(){
  const outfitImg=await cofLoadImgEl(cofCurrentUrl,'anonymous');
  const w=outfitImg.naturalWidth||outfitImg.width;
  const h=outfitImg.naturalHeight||outfitImg.height;
  if(!w||!h) throw new Error('Ukuran gambar outfit tidak valid');

  // Tahap 1: replikasi feColorMatrix (#cofPhotoFilter) -> merah x0.96, biru x1.06.
  const c1=document.createElement('canvas');
  c1.width=w; c1.height=h;
  const ctx1=c1.getContext('2d');
  ctx1.drawImage(outfitImg,0,0,w,h);
  const imgData=ctx1.getImageData(0,0,w,h); // lempar error kalau canvas tainted (CORS gagal)
  const data=imgData.data;
  for(let i=0;i<data.length;i+=4){
    data[i]=Math.min(255,data[i]*0.96);
    data[i+2]=Math.min(255,data[i+2]*1.06);
  }
  ctx1.putImageData(imgData,0,0);

  // Tahap 2: replikasi contrast(1.15) brightness(1.25) saturate(1.20) dari CSS.
  const c2=document.createElement('canvas');
  c2.width=w; c2.height=h;
  const ctx2=c2.getContext('2d');
  ctx2.filter='contrast(1.15) brightness(1.25) saturate(1.20)';
  ctx2.drawImage(c1,0,0,w,h);
  ctx2.filter='none';

  // Tahap 3: tempel watermark bulat di pojok kanan bawah, ukuran & jarak
  // dibuat proporsional terhadap resolusi asli gambar (di tampilan tetap
  // 34px/10px karena framenya kecil, di file asli resolusinya jauh lebih
  // besar jadi dipersentasekan biar posisinya tetap pas).
  try{
    const wm=await cofLoadImgEl('zusmo-asset/677288085_miwamikadono.jpg');
    const wmSize=Math.max(1,Math.round(w*0.09));
    const margin=Math.round(w*0.028);
    const cx=w-margin-wmSize/2;
    const cy=h-margin-wmSize/2;
    ctx2.save();
    ctx2.beginPath();
    ctx2.arc(cx,cy,wmSize/2,0,Math.PI*2);
    ctx2.closePath();
    ctx2.clip();
    ctx2.drawImage(wm,cx-wmSize/2,cy-wmSize/2,wmSize,wmSize);
    ctx2.restore();
  }catch(e){
    console.warn('[COF] watermark gagal ditempel ke file unduhan, lanjut tanpa watermark:',e);
  }

  return new Promise(function(resolve,reject){
    c2.toBlob(function(blob){
      if(blob) resolve(blob); else reject(new Error('canvas.toBlob gagal'));
    },'image/png');
  });
}

async function cofDownload(){
  if(!cofCurrentUrl) return;
  const btn=document.getElementById('cofDownloadBtn');
  const origHtml=btn?btn.innerHTML:null;
  if(btn){ btn.disabled=true; btn.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i>MENYIAPKAN...'; }
  try{
    const blob=await cofBuildDownloadBlob();
    const blobUrl=URL.createObjectURL(blob);
    const a=document.createElement('a');
    a.href=blobUrl;
    a.download='kzrizusmo-outfit.png';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(function(){ URL.revokeObjectURL(blobUrl); },4000);
  }catch(e){
    // Gagal (biasanya karena server API tidak mengizinkan CORS buat canvas) ->
    // fallback ke unduhan file asli seperti sebelumnya (tanpa filter/watermark
    // ter-bake) daripada tombol unduh sama sekali tidak berfungsi.
    console.warn('[COF] gagal membuat file unduhan dgn filter & watermark, fallback ke file asli:',e);
    if(window.aiSaveMediaFallback){ window.aiSaveMediaFallback(cofCurrentUrl); }
    else{ window.open(cofCurrentUrl,'_blank'); }
  }
  if(btn){ btn.disabled=false; btn.innerHTML=origHtml; }
}

