async function cisCheck(){
  const inp=document.getElementById('cisUidInput');
  const uid=inp?inp.value.trim():'';
  if(!uid||uid.length<6){ cisShake(); return; }
  if(!cidPreCheckDiamond(CID_SUB_COST,'cisCheckBtn')) return;

  cisShowState('cisStateLoading');
  cisSetLoadingBtn(true);

  let lastErr=null;
  for(let i=0;i<TFF_ALL_REGIONS.length;i++){
    const region=TFF_ALL_REGIONS[i];
    const queryBase='key='+encodeURIComponent(TFF_KEY)+'&uid='+encodeURIComponent(uid)+'&region='+encodeURIComponent(region);
    try{
      const json=await xyureiRequest(function(){
        return TFF_BASE+'/freefireinfo/bhau?'+queryBase;
      },{isDataOk:function(j){ return !!(j&&(j.basicInfo||j.data||j.result)); }});

      if(json&&json.error){ throw Object.assign(new Error(json.error),{raw:json}); }
      const b=json.basicInfo||{};
      const nickname=stkPick(b,['nickname']);
      if(!nickname){ throw Object.assign(new Error('Nickname tidak ditemukan.'),{raw:json}); }
      const uidVal=stkPick(b,['accountId','account_id'])||uid;
      cidDeductDiamond(CID_SUB_COST,'Statistik Ranked FF','Cek statistik: '+uidVal);
      const rankPointsBr=stkPick(b,['rankingPoints','ranking_points','rankingpoints']);
      const rankPointsCs=stkPick(b,['csRankingPoints','cs_ranking_points','csrankingpoints']);

      let statsBr=null,statsCs=null;
      try{ statsBr=await tffFetchStats(uidVal,region,'br','RANKED'); }catch(e){ statsBr=null; console.warn('[CIS] statistik BR gagal:',e); }
      try{ statsCs=await tffFetchStats(uidVal,region,'cs','RANKED'); }catch(e){ statsCs=null; console.warn('[CIS] statistik CS gagal:',e); }

      const statsAreaEl=document.getElementById('cisStatsArea');
      if(statsAreaEl){
        const rankBadges=[];
        if(rankPointsBr!=null) rankBadges.push(tffRankBadgeHtml(rankPointsBr,'br'));
        if(rankPointsCs!=null) rankBadges.push(tffRankBadgeHtml(rankPointsCs,'cs'));
        const rankBadgesHtml=rankBadges.filter(Boolean).join('');
        let statsHtml=(rankBadgesHtml?'<div class="tff-rank-badges" style="margin-top:0;margin-bottom:14px;">'+rankBadgesHtml+'</div>':'')
          +tffStatsSection('fa-ranking-star','Statistik Ranked BR',statsBr?tffUnwrap(statsBr):null)
          +tffStatsSection('fa-chess-board','Statistik Ranked CS',statsCs?tffUnwrap(statsCs):null);
        if(!statsHtml) statsHtml='<div class="cid-info-row-error" style="border-top:none;"><i class="fa-solid fa-triangle-exclamation"></i>Statistik ranked belum tersedia untuk akun ini.</div>';
        statsAreaEl.innerHTML=statsHtml;
      }

      cisShowState(null);
      cisSetLoadingBtn(false);
      return;
    }catch(e){
      lastErr=e;
      console.warn('[CIS] region '+region+' gagal, coba region berikutnya...',(e&&e.debugDetail)||e);
    }
  }

  console.error('[CIS]',lastErr,(lastErr&&lastErr.raw)||'');
  const msg=(lastErr&&lastErr.isNetwork)?'Gagal menghubungi server. Coba lagi beberapa saat.':'ID Free Fire tidak ditemukan. Periksa kembali ID kamu.';
  const errMsg=document.getElementById('cisErrorMsg');
  if(errMsg) errMsg.textContent=msg;
  cisShowState('cisStateError');
  cisSetLoadingBtn(false);
}

