async function cpkCheck(){
  const inp=document.getElementById('cpkUidInput');
  const uid=inp?inp.value.trim():'';
  if(!uid||uid.length<6){ cpkShake(); return; }
  if(!cidPreCheckDiamond(CID_SUB_COST,'cpkCheckBtn')) return;

  cpkShowState('cpkStateLoading');
  cpkSetLoadingBtn(true);

  let lastErr=null;
  for(let i=0;i<TFF_ALL_REGIONS.length;i++){
    const region=TFF_ALL_REGIONS[i];
    const queryBase='key='+encodeURIComponent(TFF_KEY)+'&uid='+encodeURIComponent(uid)+'&region='+encodeURIComponent(region);
    try{
      const json=await xyureiRequest(function(){
        return TFF_BASE+'/freefireinfo/bhau?'+queryBase;
      },{isDataOk:function(j){ return !!(j&&(j.basicInfo||j.data||j.result)); }});

      if(json&&json.error){ throw Object.assign(new Error(json.error),{raw:json}); }
      const b=json.basicInfo||{};
      const nickname=stkPick(b,['nickname']);
      if(!nickname){ throw Object.assign(new Error('Nickname tidak ditemukan.'),{raw:json}); }
      const uidVal=stkPick(b,['accountId','account_id'])||uid;
      cidDeductDiamond(CID_SUB_COST,'Cek Prime FF','Cek prime: '+uidVal);
      const primeLevelRaw=stkPick(b,['primeLevel','prime_level'])||(b.primeInfo&&stkPick(b.primeInfo,['primeLevel','prime_level']));
      const primeLevelNum=primeLevelRaw!=null?parseInt(primeLevelRaw,10):0;

      const nickEl=document.getElementById('cpkNickname');
      if(nickEl) nickEl.textContent=nickname;
      const idChipEl=document.getElementById('cpkIdChip');
      if(idChipEl) idChipEl.innerHTML='<i class="fa-solid fa-hashtag"></i> '+tffEsc(String(uidVal));

      const nickIconEl=document.getElementById('cpkNickIcon');
      if(nickIconEl){
        const primeIconUrl=(primeLevelNum>0 && typeof TFF_PRIME_ICONS!=='undefined')?TFF_PRIME_ICONS[primeLevelNum]:null;
        if(primeIconUrl){
          nickIconEl.outerHTML='<img id="cpkNickIcon" src="'+tffAttrEsc(primeIconUrl)+'" alt="Prime '+tffAttrEsc(String(primeLevelNum))+'" style="width:20px;height:20px;object-fit:contain;flex-shrink:0;" onerror="this.outerHTML=\'<i class=&quot;fa-solid fa-gem&quot; id=&quot;cpkNickIcon&quot; style=&quot;color:#ff6b6b;&quot;></i>\'">';
        }else{
          nickIconEl.outerHTML='<i class="fa-solid fa-gem" id="cpkNickIcon" style="color:#ff6b6b;"></i>';
        }
      }

      const rowsEl=document.getElementById('cpkInfoRows');
      if(rowsEl){
        let rows='';
        if(primeLevelNum>0 && typeof primeLevels!=='undefined' && primeLevels[primeLevelNum-1]){
          const p=primeLevels[primeLevelNum-1];
          const totalDm=p.dm;
          const totalHarga=totalDm*(typeof HARGA_PER_DM!=='undefined'?HARGA_PER_DM:126);
          rows+='<div class="cid-info-row"><b>Level Prime</b><span>'+tffEsc(p.name)+'</span></div>';
          rows+='<div class="cid-info-row"><b>Point Prime (Diamond)</b><span>'+totalDm.toLocaleString('id-ID')+'</span></div>';
          rows+='<div class="cid-info-row"><b>Estimasi Nilai</b><span>Rp '+totalHarga.toLocaleString('id-ID')+'</span></div>';
          rows+='<div class="cid-info-row-error" style="color:#8f8f8f;"><i class="fa-solid fa-circle-info" style="color:#ff6b6b;"></i>Estimasi harga Rp 126 per 1 Diamond.</div>';
        }else{
          rows+='<div class="cid-info-row-error"><i class="fa-solid fa-triangle-exclamation"></i>Akun ini belum memiliki level Prime.</div>';
        }
        rowsEl.innerHTML=rows;
      }

      cpkShowState(null);
      cpkSetLoadingBtn(false);
      return;
    }catch(e){
      lastErr=e;
      console.warn('[CPK] region '+region+' gagal, coba region berikutnya...',(e&&e.debugDetail)||e);
    }
  }

  console.error('[CPK]',lastErr,(lastErr&&lastErr.raw)||'');
  const msg=(lastErr&&lastErr.isNetwork)?'Gagal menghubungi server. Coba lagi beberapa saat.':'ID Free Fire tidak ditemukan. Periksa kembali ID kamu.';
  const errMsg=document.getElementById('cpkErrorMsg');
  if(errMsg) errMsg.textContent=msg;
  cpkShowState('cpkStateError');
  cpkSetLoadingBtn(false);
}

/* Download kartu hasil CEK PRIME jadi gambar PNG.
   - Kartu diunduh APA ADANYA (ukuran asli kartu, tidak dipaksa jadi rasio
     9:16 dengan bidang transparan tambahan di atas/bawah — makanya dulu
     hasilnya kelihatan ada "kotak putih" kosong).
   - Shine/efek pojok (radial glow putih & merah) DIMATIKAN khusus di hasil
     unduhan lewat class cid-export-solid (tampilan normal di layar tetap
     apa adanya, tidak berubah).
   - Sebelum html2canvas mulai kerja (yang berat & sinkron, bikin browser
     sempat "freeze" sesaat), kita kasih jeda 1 frame (requestAnimationFrame)
     supaya ikon spinner sempat digambar browser dulu sebelum proses capture
     menahan main thread. */
function cpkDownloadCard1(){
  const card=document.getElementById('cpkCard1');
  if(!card||typeof html2canvas!=='function') return;
  const btn=document.getElementById('cpkDownloadBtn');
  const icon=btn?btn.querySelector('i'):null;
  if(btn&&btn.classList.contains('cid-dl-busy')) return;
  if(btn){ btn.classList.add('cid-dl-busy'); btn.classList.remove('cid-dl-done'); }
  if(icon){ icon.className='fa-solid fa-spinner fa-spin'; }
  card.classList.add('cid-export-solid');

  const doCapture=function(){
    html2canvas(card,{
      backgroundColor:'#0c0c0c',
      useCORS:true,
      scale:2
    }).then(function(canvas){
      card.classList.remove('cid-export-solid');
      const link=document.createElement('a');
      link.download='kzrizusmo-cekprime-'+Date.now()+'.png';
      link.href=canvas.toDataURL('image/png');
      document.body.appendChild(link);
      link.click();
      link.remove();
      if(btn){ btn.classList.remove('cid-dl-busy'); btn.classList.add('cid-dl-done'); }
      if(icon){ icon.className='fa-solid fa-check'; }
      setTimeout(function(){
        if(btn) btn.classList.remove('cid-dl-done');
        if(icon) icon.className='fa-solid fa-download';
      },1800);
    }).catch(function(e){
      card.classList.remove('cid-export-solid');
      if(btn){ btn.classList.remove('cid-dl-busy'); }
      if(icon){ icon.className='fa-solid fa-download'; }
      console.error('[CPK] Gagal download kartu jadi gambar',e);
    });
  };
  // Dua rAF berturut-turut supaya benar-benar 1 frame penuh sudah ke-paint
  // duluan (perubahan icon jadi spinner) sebelum capture berat dimulai.
  requestAnimationFrame(function(){ requestAnimationFrame(doCapture); });
}

