// Render generik: tampilkan tiap field dari respons sukses sebagai baris
// cid-info-row, tanpa terikat skema field yang pasti (skema resmi belum diberi).
function cmgRenderRowsFromJson(json){
  const skip=['success'];
  let rows='';
  Object.keys(json).forEach(function(k){
    if(skip.indexOf(k)>-1) return;
    let v=json[k];
    if(v&&typeof v==='object') v=JSON.stringify(v);
    const label=k.replace(/_/g,' ').replace(/\b\w/g,function(c){ return c.toUpperCase(); });
    rows+='<div class="cid-info-row"><b>'+tffEsc(label)+'</b><span>'+tffEsc(String(v))+'</span></div>';
  });
  return rows;
}

async function cmgCreate(){
  const nameInp=document.getElementById('cmgNameInput');
  const sloganInp=document.getElementById('cmgSloganInput');
  const avatarInp=document.getElementById('cmgAvatarInput');
  const minLevelInp=document.getElementById('cmgMinLevelInput');
  const tagsInp=document.getElementById('cmgTagsInput');
  const paymentSel=document.getElementById('cmgPaymentSelect');
  const autoApprovalSel=document.getElementById('cmgAutoApprovalSelect');
  const jwtInp=document.getElementById('cmgJwtInput');

  const guildName=nameInp?nameInp.value.trim():'';
  const jwt=jwtInp?jwtInp.value.trim():'';

  if(!guildName){ cmgShake('cmgNameInput'); return; }
  if(!jwt){ cmgShake('cmgJwtInput'); return; }
  if(!cidPreCheckDiamond(CID_ACTION_COST,'cmgCreateBtn')) return;

  const tags=(tagsInp?tagsInp.value:'').split(',').map(function(s){ return parseInt(s.trim(),10); }).filter(function(n){ return !isNaN(n); });

  const body={
    guild_name:guildName,
    slogan:sloganInp?sloganInp.value.trim():'',
    payment:parseInt(paymentSel?paymentSel.value:'0',10)||0,
    auto_approval:parseInt(autoApprovalSel?autoApprovalSel.value:'2',10)||0,
    avatar:parseInt(avatarInp&&avatarInp.value?avatarInp.value:'0',10)||0,
    tags:tags,
    min_level:parseInt(minLevelInp&&minLevelInp.value?minLevelInp.value:'0',10)||0
  };

  cmgShowState('cmgStateLoading');
  cmgSetLoadingBtn(true);

  try{
    const url=TFF_BASE+'/guild/create?key='+encodeURIComponent(TFF_KEY);
    let res,text;
    try{
      res=await zsFetchTimeout(url,{
        method:'POST',
        headers:{'Content-Type':'application/json','Accept':'application/json','Authorization':'Bearer '+jwt},
        body:JSON.stringify(body)
      },15000);
      text=await res.text();
    }catch(networkErr){
      throw Object.assign(new Error('Gagal menghubungi server. Coba lagi beberapa saat.'),{raw:null});
    }

    let json=null;
    try{ json=JSON.parse(text); }catch(parseErr){
      throw Object.assign(new Error('Respons server tidak valid.'),{raw:text});
    }

    if(!res.ok||!json||json.success===false||json.error){
      const errLower=String((json&&json.error)||'').toLowerCase();
      let friendly='Gagal membuat guild. Periksa kembali data & JWT token kamu.';
      if(errLower.indexOf('jwt')>-1||errLower.indexOf('auth')>-1||errLower.indexOf('token')>-1) friendly='JWT token tidak valid atau sudah kedaluwarsa. Coba ambil ulang JWT token kamu.';
      else if(errLower.indexOf('name')>-1) friendly='Nama guild tidak valid atau sudah dipakai.';
      else if(errLower.indexOf('already')>-1||errLower.indexOf('member')>-1) friendly='Akun ini sudah tergabung/memiliki guild, tidak bisa membuat guild baru.';
      throw Object.assign(new Error(friendly),{raw:json});
    }
    cidDeductDiamond(CID_ACTION_COST,'Buat Guild FF','Buat guild: '+guildName);

    const rowsEl=document.getElementById('cmgInfoRows');
    if(rowsEl) rowsEl.innerHTML=cmgRenderRowsFromJson(json)||'<div class="cid-info-row"><b>Guild</b><span>'+tffEsc(guildName)+'</span></div>';

    cmgShowState(null);
  }catch(e){
    console.error('[CMG]',e,(e&&e.raw)||'');
    const errMsg=document.getElementById('cmgErrorMsg');
    if(errMsg) errMsg.textContent=(e&&e.message)||'Gagal membuat guild. Periksa kembali data & JWT token kamu.';
    cmgShowState('cmgStateError');
  }
  cmgSetLoadingBtn(false);
}

