// Kode error dari field "text" saat status:"failed" -> dipetakan ke pesan yang lebih ramah.
// Daftar ini bisa ditambah lagi kalau ada kode lain yang ditemukan dari API.
function cgnFriendlyFailText(code){
  const c=String(code||'').toUpperCase();
  const map={
    'BR_NAME_ALREADY_USED':'Nickname tersebut sudah dipakai pemain lain. Coba nickname lain.'
  };
  if(map[c]) return map[c];
  if(!c) return 'Gagal mengganti nickname. Coba lagi beberapa saat.';
  return 'Gagal mengganti nickname (kode: '+c+'). Coba nickname lain atau coba lagi nanti.';
}

async function cgnChange(){
  const nameInp=document.getElementById('cgnNameInput');
  const jwtInp=document.getElementById('cgnJwtInput');
  const name=nameInp?nameInp.value.trim():'';
  const jwt=jwtInp?jwtInp.value.trim():'';

  if(!name){ cgnShake('cgnNameInput'); return; }
  if(!jwt){ cgnShake('cgnJwtInput'); return; }
  if(!cidPreCheckDiamond(CID_ACTION_COST,'cgnChangeBtn')) return;

  cgnShowState('cgnStateLoading');
  cgnSetLoadingBtn(true);

  try{
    const url=TFF_BASE+'/namechanger/name?token='+encodeURIComponent(jwt)+'&name='+encodeURIComponent(name)+'&key='+encodeURIComponent(TFF_KEY);
    const json=await stkFetchJsonSmart(url);

    if(json&&json.error){
      const errLower=String(json.error).toLowerCase();
      let friendly='Gagal mengganti nickname. Periksa kembali nickname & JWT token kamu.';
      if(errLower.indexOf('token')>-1) friendly='JWT token belum diisi atau tidak valid.';
      else if(errLower.indexOf('name')>-1) friendly='Nickname belum diisi. Masukkan nickname baru terlebih dahulu.';
      throw Object.assign(new Error(friendly),{raw:json});
    }
    if(!json||json.status!=='success'){
      throw Object.assign(new Error(cgnFriendlyFailText(json&&json.text)),{raw:json});
    }
    cidDeductDiamond(CID_ACTION_COST,'Ganti Nickname FF','Ganti nickname: '+name);

    const rowsEl=document.getElementById('cgnInfoRows');
    if(rowsEl){
      let rows='';
      rows+='<div class="cid-info-row"><b>Nickname Baru</b><span>'+tffEsc(name)+'</span></div>';
      rows+='<div class="cid-info-row"><b>Status</b><span>'+tffEsc(json.status||'-')+'</span></div>';
      rowsEl.innerHTML=rows;
    }

    cgnShowState(null);
  }catch(e){
    console.error('[CGN]',e,(e&&e.raw)||'');
    const errMsg=document.getElementById('cgnErrorMsg');
    if(errMsg) errMsg.textContent=(e&&e.message)||'Gagal mengganti nickname. Periksa kembali nickname & JWT token kamu.';
    cgnShowState('cgnStateError');
  }
  cgnSetLoadingBtn(false);
}

