async function ccdCheck(){
  const mapInp=document.getElementById('ccdMapCodeInput');
  const regionInp=document.getElementById('ccdRegionInput');
  const langInp=document.getElementById('ccdLangInput');
  const mapCode=mapInp?mapInp.value.trim():'';
  const region=(regionInp&&regionInp.value.trim())||'ID';
  const lang=(langInp&&langInp.value.trim())||'id';

  if(!mapCode){ ccdShake(); return; }
  if(!cidPreCheckDiamond(CID_SUB_COST,'ccdCheckBtn')) return;

  ccdShowState('ccdStateLoading');
  ccdSetLoadingBtn(true);

  try{
    const url=TFF_BASE+'/craftlands/map_details?map_code='+encodeURIComponent(mapCode)+'&region='+encodeURIComponent(region)+'&lang='+encodeURIComponent(lang)+'&key='+encodeURIComponent(TFF_KEY);
    const json=await stkFetchJsonSmart(url);

    if(json&&json.error){
      const errLower=String(json.error).toLowerCase();
      let friendly='Map Craftland tidak ditemukan. Periksa kembali Map Code kamu.';
      if(errLower.indexOf('required')>-1) friendly='Map Code belum diisi. Masukkan Map Code terlebih dahulu.';
      else if(errLower.indexOf('404')>-1) friendly='Map Craftland tidak ditemukan (kode tidak valid).';
      else if(errLower.indexOf('status')>-1) friendly='Gagal menghubungi server Craftland. Coba lagi beberapa saat.';
      throw Object.assign(new Error(friendly),{raw:json});
    }
    if(!json||json.status!=='success'||!json.data){
      throw Object.assign(new Error('Data map tidak ditemukan. Periksa kembali Map Code kamu.'),{raw:json});
    }
    cidDeductDiamond(CID_SUB_COST,'Craftland Detail FF','Cek detail craftland: '+mapCode);

    const d=json.data;
    const basic=d.basic_info||{};
    const gameplay=d.gameplay_info||{};
    const social=d.social_info||{};
    const dl=d.download_info||{};
    const regionInfo=d.region_info||{};
    const tags=Array.isArray(d.tags)?d.tags:[];

    const coverBox=document.getElementById('ccdCoverImgBox');
    if(coverBox){
      coverBox.innerHTML=social.map_cover_url?'<div class="ccl-share-img"><img src="'+tffAttrEsc(social.map_cover_url)+'" alt="craftland map" referrerpolicy="no-referrer"/></div>':'';
    }

    const mapNameEl=document.getElementById('ccdMapName');
    if(mapNameEl) mapNameEl.textContent=basic.map_name||'-';

    const codeChip=document.getElementById('ccdCodeChip');
    if(codeChip) codeChip.innerHTML='<i class="fa-solid fa-hashtag"></i> '+tffEsc(basic.workshop_code||mapCode);

    const descBox=document.getElementById('ccdDescBox');
    if(descBox){
      const descText=basic.description||basic.short_description;
      if(descText){ descBox.textContent=descText; descBox.style.display=''; }
      else{ descBox.style.display='none'; }
    }

    const tagsBox=document.getElementById('ccdTagsBox');
    if(tagsBox){
      tagsBox.innerHTML=tags.length?tags.map(function(t){
        return '<span class="ccl-tag-chip"><i class="fa-solid fa-tag"></i>'+tffEsc(t&&t.name?t.name:t)+'</span>';
      }).join(''):'';
    }

    const gameMode=gameplay.game_mode||{};
    const modeTemplate=gameplay.mode_template||{};

    const rowsEl=document.getElementById('ccdInfoRows');
    if(rowsEl){
      let rows='';
      rows+='<div class="cid-info-row"><b>Author</b><span>'+tffEsc(basic.author||'-')+'</span></div>';
      rows+='<div class="cid-info-row"><b>Jumlah Tim</b><span>'+tffEsc(gameplay.team_count!=null?gameplay.team_count:'-')+'</span></div>';
      rows+='<div class="cid-info-row"><b>Game Mode</b><span>'+tffEsc(gameMode.name||(gameMode.id!=null?gameMode.id:'-'))+'</span></div>';
      rows+='<div class="cid-info-row"><b>Mode Template</b><span>'+tffEsc(modeTemplate.name||(modeTemplate.id!=null?modeTemplate.id:'-'))+'</span></div>';
      rows+='<div class="cid-info-row"><b>Jumlah Ronde</b><span>'+tffEsc(gameplay.round_count!=null?gameplay.round_count:'-')+'</span></div>';
      rows+='<div class="cid-info-row"><b>Estimasi Main</b><span>'+tffEsc(gameplay.estimated_play_time||'-')+'</span></div>';
      rows+='<div class="cid-info-row"><b>Subscriber</b><span>'+cgiFmtNum(social.subscribe_count)+'</span></div>';
      rows+='<div class="cid-info-row"><b>Like</b><span>'+cgiFmtNum(social.like_count)+'</span></div>';
      rows+='<div class="cid-info-row"><b>Region</b><span>'+tffEsc(regionInfo.region||region)+'</span></div>';
      rows+='<div class="cid-info-row"><b>Bahasa</b><span>'+tffEsc(regionInfo.language||lang)+'</span></div>';
      rowsEl.innerHTML=rows;
    }

    const linksRow=document.getElementById('ccdLinksRow');
    if(linksRow){
      let links='';
      if(dl.android) links+='<a href="'+tffAttrEsc(dl.android)+'" target="_blank" rel="noopener"><i class="fa-brands fa-google-play"></i>Android</a>';
      if(dl.ios) links+='<a href="'+tffAttrEsc(dl.ios)+'" target="_blank" rel="noopener"><i class="fa-brands fa-app-store-ios"></i>iOS</a>';
      if(dl.ugc_portal) links+='<a href="'+tffAttrEsc(dl.ugc_portal)+'" target="_blank" rel="noopener"><i class="fa-solid fa-arrow-up-right-from-square"></i>UGC Portal</a>';
      linksRow.innerHTML=links;
    }

    ccdShowState(null);
  }catch(e){
    console.error('[CCD]',e,(e&&e.raw)||'');
    const errMsg=document.getElementById('ccdErrorMsg');
    if(errMsg) errMsg.textContent=(e&&e.message)||'Map Craftland tidak ditemukan. Periksa kembali Map Code kamu.';
    ccdShowState('ccdStateError');
  }
  ccdSetLoadingBtn(false);
}

