const TFF_BASE='https://siambhau69.eu.cc';
const TFF_KEY='FFAPI-PREM-30-kzrizusmo-X07';
const TFF_ALL_REGIONS=['BD'];
const TFF_MENU=[
  {key:'freefireinfo',label:'Free Fire Info',icon:'fa-user-shield',desc:'Cek info akun Free Fire lewat UID',
    path:'/freefireinfo/bhau',
    fields:[
      {name:'uid',label:'UID Free Fire',placeholder:'Contoh: 260190210',required:true}
    ]}
];

/* ============================================================
   TAMBAHAN: Banner profil, statistik ranked BR & CS, dan daftar
   teman (via JWT). Sama-sama lewat base siambhau69.eu.cc, format
   {base}/<group>/<endpoint>?param=VALUE&key=TFF_KEY.
   - /banner/profile?uid=&region=&key=        -> banner profil
   - /freefireinfo/stats?uid=&region=&key=    -> statistik umum
   - /freefireinfo/stats?...&gamemode=br&matchmode=RANKED&key=  -> ranked BR
   - /freefireinfo/stats?...&gamemode=cs&matchmode=RANKED&key=  -> ranked CS
   - /friends/list?jwt=&key=                  -> daftar teman
   Banner & statistik dianggap pelengkap (kalau gagal, profil utama
   tetap tampil) sama seperti pola wishlist di stkStalkFreeFireOb54. ============================================================ */
// Endpoint ini balikin GAMBAR PNG langsung (bukan JSON) — banner profil yang
// sudah berisi avatar+nama+guild+level dirender di server. Jadi cukup bangun
// URL-nya aja buat dipakai sebagai src <img>, gak perlu di-fetch di sini.
function tffBuildBannerUrl(uid,region){
  const queryBase='key='+encodeURIComponent(TFF_KEY)+'&uid='+encodeURIComponent(uid)+'&region='+encodeURIComponent(region);
  return TFF_BASE+'/banner/profile?'+queryBase;
}
async function tffFetchStats(uid,region,gamemode,matchmode){
  let queryBase='key='+encodeURIComponent(TFF_KEY)+'&uid='+encodeURIComponent(uid)+'&region='+encodeURIComponent(region);
  if(gamemode) queryBase+='&gamemode='+encodeURIComponent(gamemode);
  if(matchmode) queryBase+='&matchmode='+encodeURIComponent(matchmode);
  return xyureiRequest(function(){ return TFF_BASE+'/freefireinfo/stats?'+queryBase; },{isDataOk:function(j){ return !!(j&&!j.error); }});
}
async function tffFetchFriends(jwt){
  const queryBase='key='+encodeURIComponent(TFF_KEY)+'&jwt='+encodeURIComponent(jwt);
  return xyureiRequest(function(){ return TFF_BASE+'/friends/list?'+queryBase; },{isDataOk:function(j){ return !!(j&&!j.error); }});
}
// Beberapa endpoint tambahan ini kemungkinan bungkus datanya di field data/stats/result;
// unwrap dulu sebelum dirender, biar tffRenderRows/tffSection bisa baca field-nya langsung.
function tffUnwrap(json){
  if(!json||typeof json!=='object') return json;
  return json.data||json.stats||json.result||json;
}

function tffEsc(str){
  return String(str==null?'':str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function tffAttrEsc(str){
  return String(str==null?'':str).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
/* Bio/signature Free Fire memakai kode warna gaya "[FF0000]teks" — TANPA tag
   penutup, warna berlaku sampai kode warna berikutnya muncul atau baris
   berakhir (mirip format chat game). Style [B]/[I]/[U] tetap pakai tag
   penutup eksplisit [/B] dst. Parser ini jalan per-baris (newline mereset
   warna) supaya warna satu baris tidak "bocor" ke baris berikutnya yang
   tidak diberi kode warna. Teks di luar tag tetap di-escape aman. */
/* Lebar wrap bio Free Fire: 41 karakter TAMPIL per baris (termasuk spasi),
   tidak termasuk kode warna/style [FF0000], [B], [/I] dst — meniru cara
   game membungkus baris signature di layar profil. */
const TFF_BIO_WRAP_WIDTH=41;
function tffFormatBio(raw){
  /* Wrap per KATA (bukan potong tengah kata) supaya rapi dibaca, tapi tiap
     baris tetap dibatasi maksimal 41 karakter tampil (termasuk spasi).
     Enter/baris baru asli yang diketik pemain di dalam bio game TETAP
     diabaikan sebagai titik patah baris (diganti spasi) -> satu-satunya
     sumber baris baru di hasil akhir adalah wrap kata otomatis di bawah. */
  const line=String(raw==null?'':raw).replace(/\r\n|\r|\n|\t/g,' ');
  const styleTokenRe=/\[\/?(B|I|U)\]/gi;
  const colorTokenRe=/^\[([0-9A-Fa-f]{6})\]/;
  const map={B:'b',I:'i',U:'u'};
  let pos=0,currentColor=null;
  const styleStack=[];
  const words=[];
  let cur={html:'',visible:0};
  const pushWord=function(){
    if(cur.html!==''||cur.visible>0) words.push(cur);
    cur={html:'',visible:0};
  };
  while(pos<line.length){
    const rest=line.slice(pos);
    const colorMatch=rest.match(colorTokenRe);
    if(colorMatch){
      if(currentColor) cur.html+='</span>';
      cur.html+='<span style="color:#'+colorMatch[1].toUpperCase()+'">';
      currentColor=colorMatch[1];
      pos+=colorMatch[0].length;
      continue;
    }
    styleTokenRe.lastIndex=0;
    const styleMatch=styleTokenRe.exec(rest);
    if(styleMatch&&styleMatch.index===0){
      const tag=styleMatch[1].toUpperCase();
      const isClose=styleMatch[0].charAt(1)==='/';
      if(isClose){
        cur.html+='</'+map[tag]+'>';
        const idx=styleStack.lastIndexOf(tag);
        if(idx!==-1) styleStack.splice(idx,1);
      }else{
        cur.html+='<'+map[tag]+'>';
        styleStack.push(tag);
      }
      pos+=styleMatch[0].length;
      continue;
    }
    const ch=line.charAt(pos);
    if(ch===' '){
      pushWord();
      pos++;
      continue;
    }
    cur.html+=tffEsc(ch);
    cur.visible++;
    pos++;
  }
  pushWord();
  let html='',lineVisible=0;
  words.forEach(function(word){
    if(lineVisible>0&&lineVisible+1+word.visible>TFF_BIO_WRAP_WIDTH){
      html+='\n';
      lineVisible=0;
    }else if(lineVisible>0){
      html+=' ';
      lineVisible+=1;
    }
    html+=word.html;
    lineVisible+=word.visible;
  });
  while(styleStack.length){
    const tag=styleStack.pop();
    html+='</'+map[tag]+'>';
  }
  if(currentColor) html+='</span>';
  return html;
}
function tffStripBioTags(raw){
  return String(raw==null?'':raw)
    .replace(/\[[0-9A-Fa-f]{6}\]/g,'')
    .replace(/\[\/?(B|I|U)\]/gi,'');
}
function tffCopyVal(btn){
  if(!btn) return;
  const val=btn.getAttribute('data-val')||'';
  const done=function(){
    btn.classList.add('copied');
    btn.innerHTML='<i class="fa-solid fa-check"></i>';
    setTimeout(function(){ btn.classList.remove('copied'); btn.innerHTML='<i class="fa-solid fa-copy"></i>'; },1200);
  };
  const fallbackCopy=function(){
    try{
      const ta=document.createElement('textarea');
      ta.value=val; ta.style.position='fixed'; ta.style.top='0'; ta.style.left='0'; ta.style.opacity='0';
      document.body.appendChild(ta); ta.focus(); ta.select();
      document.execCommand('copy');
      document.body.removeChild(ta);
    }catch(e){}
    done();
  };
  if(navigator.clipboard&&navigator.clipboard.writeText&&window.isSecureContext){
    navigator.clipboard.writeText(val).then(done).catch(fallbackCopy);
  }else{
    fallbackCopy();
  }
}

function tffShake(el){
  if(!el) return;
  el.classList.remove('tff-shake');
  void el.offsetWidth;
  el.classList.add('tff-shake');
  el.focus();
}

