// Urutan tampil field yang dianggap penting duluan; sisanya menyusul sesuai urutan asli JSON.
const TFF_FIELD_ORDER=['nickname','accountid','level','exp','rank','rankingpoints','maxrank','csrank','csrankingpoints','csmaxrank','liked','badgecnt','region','clanname','clanlevel','membernum','capacity','captainid','id','skinid','selectedskillid','gender','language','signature','rankshow','diamondcost','creditscore','rewardstate','accounttype','seasonid','createat','lastloginat','releaseversion','showbrrank','showcsrank','primelevel','clanid','periodicsummaryendtime'];

function tffPrettyLabel(key){
  const mapped=TFF_LABEL_MAP[key.toLowerCase()];
  if(mapped) return mapped;
  return key.replace(/_/g,' ').replace(/([a-z])([A-Z])/g,'$1 $2').replace(/\b\w/g,function(c){return c.toUpperCase();});
}
const TFF_ENUM_MAP={
  gender_male:'Laki-laki',gender_female:'Perempuan',
  language_en:'Inggris',language_id:'Indonesia',language_bd:'Bengali',
  rankshow_br:'Battle Royale',rankshow_cs:'Clash Squad',
  reward_state_unclaimed:'Belum Diklaim',reward_state_claimed:'Sudah Diklaim',
  unlocktype_link:'Terhubung Akun',accounttype_1:'Akun Utama'
};
const TFF_BOOL_MAP={true:'Ya',false:'Tidak'};
function tffPrettyValue(key,val){
  const k=key.toLowerCase();
  if(k==='lastloginat'||k==='createat'||k==='periodicsummaryendtime'){
    const n=Number(val);
    if(n>1000000000){ try{ return new Date(n*1000).toLocaleString('id-ID',{dateStyle:'medium',timeStyle:'short'}); }catch(e){} }
  }
  if(typeof val==='boolean') return TFF_BOOL_MAP[String(val)]||String(val);
  const enumKey=String(val).toLowerCase();
  if(TFF_ENUM_MAP[enumKey]) return TFF_ENUM_MAP[enumKey];
  if(k==='signature') return tffStripBioTags(String(val).trim())||'-';
  const suffix=TFF_UNIT_SUFFIX_MAP[k];
  if(suffix!=null) return String(val)+suffix;
  return String(val);
}
function tffYearsSince(unixVal){
  const n=Number(unixVal);
  if(!n||n<1000000000) return 0;
  const years=Math.floor((Date.now()-(n*1000))/(365.25*24*3600*1000));
  return years>0?years:0;
}
function tffDetailedAge(unixVal){
  const n=Number(unixVal);
  if(!n||n<1000000000) return '';
  const start=new Date(n*1000), now=new Date();
  let years=now.getFullYear()-start.getFullYear();
  let months=now.getMonth()-start.getMonth();
  let days=now.getDate()-start.getDate();
  if(days<0){ months--; days+=new Date(now.getFullYear(),now.getMonth(),0).getDate(); }
  if(months<0){ years--; months+=12; }
  const parts=[];
  if(years>0) parts.push(years+' tahun');
  if(months>0) parts.push(months+' bulan');
  if(days>0||!parts.length) parts.push(days+' hari');
  return parts.join(', ')+' usia akun';
}
function tffRelativeTime(unixVal){
  const n=Number(unixVal);
  if(!n||n<1000000000) return '';
  const diffMs=Date.now()-(n*1000);
  if(diffMs<0) return '';
  const diffSec=Math.floor(diffMs/1000);
  if(diffSec<60) return 'Baru saja';
  const diffMin=Math.floor(diffSec/60);
  if(diffMin<60) return diffMin+' menit lalu';
  const diffHour=Math.floor(diffMin/60);
  if(diffHour<24) return diffHour+' jam lalu';
  const diffDay=Math.floor(diffHour/24);
  if(diffDay<30) return diffDay+' hari lalu';
  const diffMonth=Math.floor(diffDay/30);
  if(diffMonth<12) return diffMonth+' bulan lalu';
  const diffYear=Math.floor(diffMonth/12);
  return diffYear+' tahun lalu';
}
/* Respons statistik ranked BR datang terbagi per mode (solostats/duostats/
   squadstats), dan tiap mode punya "detailedstats" bersarang satu level lagi
   (deaths, distancetra, dst). tffRenderRows/cidRenderRows cuma baca field
   level-atas yang bukan object, jadi tanpa dipipihkan dulu semua field ini
   ke-skip dan section-nya kelihatan "kosong" padahal datanya ada. */
function tffFlattenStatsObj(obj){
  if(!obj||typeof obj!=='object') return {};
  const out={};
  function walk(o){
    Object.keys(o).forEach(function(key){
      const val=o[key];
      // Sebelumnya cuma object bernama "detailedstats" yang dibuka satu
      // level; kalau ada nesting lebih dalam lagi (mis. BR yang strukturnya
      // lebih berlapis dari CS) field di dalamnya ke-skip karena dianggap
      // object dan dibuang di tffRenderRows. Sekarang dibuka rekursif ke
      // semua level object (bukan array) biar semua field ikut kepakai.
      if(val&&typeof val==='object'&&!Array.isArray(val)){
        walk(val);
      }else if(out[key]===undefined){
        out[key]=val;
      }
    });
  }
  walk(obj);
  return out;
}
const TFF_STATS_MODE_LABEL={solostats:'Solo',duostats:'Duo',squadstats:'Squad',quadstats:'Squad',cssranked:'Ranked',cssstats:'Ranked',cscareer:'Career',brranked:'Ranked',brcareer:'Career'};
// Field ini cuma pengulangan UID yang sudah tampil di bagian lain halaman;
// di dalam tiap blok mode dia cuma bikin penuh tanpa nilai tambah.
function tffStripAccountId(flat){ delete flat.accountid; delete flat.account_id; return flat; }
// Sebagian mode (solostats/duostats/quadstats/cssstats/dst) dibungkus per
// tipe-antrian; sebagian lain (matchmode=CAREER) sudah flat di level atas.
// Deteksi generik: tiap key yang isinya object dianggap 1 blok mode.
function tffStatsModeKeys(statsObj){
  return Object.keys(statsObj).filter(function(k){
    return k.toLowerCase()!=='detailedstats'&&statsObj[k]&&typeof statsObj[k]==='object';
  });
}
function tffStatsRowsHtml(statsObj){
  if(!statsObj||typeof statsObj!=='object') return '';
  const modeKeys=tffStatsModeKeys(statsObj);
  if(modeKeys.length){
    let out='';
    modeKeys.forEach(function(mk){
      const rows=tffRenderRows(tffStripAccountId(tffFlattenStatsObj(statsObj[mk])));
      // Mode yang belum pernah dimainkan cuma nyisa accountid -> tidak
      // informatif, jadi blok mode-nya dilewati saja daripada nampilin
      // judul kosong.
      if(rows) out+='<div class="tff-stats-mode-label">'+tffEsc(TFF_STATS_MODE_LABEL[mk.toLowerCase()]||tffPrettyLabel(mk))+'</div>'+rows;
    });
    if(out) return out;
  }
  return tffRenderRows(tffStripAccountId(tffFlattenStatsObj(statsObj)));
}
/* Sama seperti tffStatsRowsHtml, tapi baris-nya dirender gaya cid-info-row
   (label kiri, nilai kanan, garis pemisah tipis - TANPA kotak/kartu per
   baris) supaya konsisten dengan section lain di halaman Cek Info FF. */
function cidStatsRowsHtml(statsObj){
  if(!statsObj||typeof statsObj!=='object') return '';
  const modeKeys=tffStatsModeKeys(statsObj);
  if(modeKeys.length){
    let out='';
    modeKeys.forEach(function(mk){
      const rows=cidRenderRows(tffStripAccountId(tffFlattenStatsObj(statsObj[mk])));
      if(rows) out+='<div class="cid-stats-mode-label">'+tffEsc(TFF_STATS_MODE_LABEL[mk.toLowerCase()]||tffPrettyLabel(mk))+'</div>'+rows;
    });
    if(out) return out;
  }
  return cidRenderRows(tffStripAccountId(tffFlattenStatsObj(statsObj)));
}
function tffRenderRows(obj,extraSkip){
  if(!obj||typeof obj!=='object') return '';
  const skipExtra=extraSkip||[];
  const keys=Object.keys(obj).filter(function(key){
    if(TFF_ROW_SKIP_KEYS.indexOf(key.toLowerCase())!==-1) return false;
    if(skipExtra.indexOf(key.toLowerCase())!==-1) return false;
    const val=obj[key];
    return !(val==null||val===''||typeof val==='object');
  });
  keys.sort(function(a,b){
    const ia=TFF_FIELD_ORDER.indexOf(a.toLowerCase());
    const ib=TFF_FIELD_ORDER.indexOf(b.toLowerCase());
    const pa=ia===-1?999:ia, pb=ib===-1?999:ib;
    return pa-pb;
  });
  let rows='';
  const TFF_WIDE_KEYS=['nickname','signature','clanname','releaseversion'];
  const TFF_COPY_KEYS=['nickname','signature'];
  const TFF_DATE_KEYS=['lastloginat','createat'];
  keys.forEach(function(key){
    const val=obj[key];
    const label=tffPrettyLabel(key);
    const kLower=key.toLowerCase();
    const isWide=TFF_WIDE_KEYS.indexOf(kLower)!==-1;
    const prettyVal=tffPrettyValue(key,val);
    if(TFF_COPY_KEYS.indexOf(kLower)!==-1){
      rows+='<div class="tff-result-row tff-row-wide"><b>'+tffEsc(label)+'</b>'+
        '<div class="tff-copy-wrap"><span>'+tffEsc(prettyVal)+'</span>'+
        '<button class="stk-copy-btn" data-val="'+tffAttrEsc(prettyVal)+'" onclick="tffCopyVal(this)"><i class="fa-solid fa-copy"></i></button></div>'+
      '</div>';
    }else if(TFF_DATE_KEYS.indexOf(kLower)!==-1){
      const rel=tffRelativeTime(val);
      rows+='<div class="tff-result-row"><b>'+tffEsc(label)+'</b><span>'+tffEsc(rel||prettyVal)+'</span>'+
        (rel?'<span class="tff-date-full">'+tffEsc(prettyVal)+'</span>':'')+
      '</div>';
    }else{
      rows+='<div class="tff-result-row'+(isWide?' tff-row-wide':'')+'"><b>'+tffEsc(label)+'</b><span>'+tffEsc(prettyVal)+'</span></div>';
    }
  });
  return rows;
}
function tffSection(iconCls,title,obj,extraSkip){
  if(!obj||typeof obj!=='object') return '';
  const rows=tffRenderRows(obj,extraSkip);
  if(!rows) return '';
  return '<div class="tff-section">'+
    '<div class="tff-section-head"><i class="fa-solid '+iconCls+'"></i><span>'+tffEsc(title)+'</span></div>'+
    '<div class="tff-result-rows">'+rows+'</div>'+
  '</div>';
}
// Beberapa field balikannya array of Item ID mentah (outfit yang dipakai,
// skin senjata yang dipajang, dst) — sebelumnya field beginian di-skip total
// karena tffRenderRows/cidRenderRows cuma baca field yang bukan array/object,
// jadi kelihatan seperti "hilang". Gak ada database nama item FF di sini,
// jadi ditampilkan per item sebagai chip Item ID (bukan disembunyikan).
// URL gambar item Free Fire per Item ID, dari repo ikon publik ShahGCreator
// (tanpa watermark, diakses lewat jsDelivr CDN). Kalau ID tertentu gak punya
// gambar di repo itu (404), otomatis fallback ke tampilan chip teks biasa
// lewat onerror di bawah, jadi item tetap kelihatan (bukan hilang).
function tffItemIconUrl(id){
  return 'https://cdn.jsdelivr.net/gh/ShahGCreator/icon@main/PNG/'+encodeURIComponent(String(id))+'.png';
}
function tffIdChipsHtml(arr){
  if(!Array.isArray(arr)) return '';
  const list=arr.filter(function(v){ return v!=null&&v!==''; });
  if(!list.length) return '';
  return '<div class="tff-id-chips">'+list.map(function(id,i){
    const idStr=String(id);
    return '<span class="tff-id-chip">'+
      '<span class="tff-id-chip-imgwrap"><img src="'+tffAttrEsc(tffItemIconUrl(idStr))+'" alt="item '+tffAttrEsc(idStr)+'" loading="lazy" referrerpolicy="no-referrer" onerror="this.closest(\'.tff-id-chip\').classList.add(\'tff-id-noimg\')"></span>'+
      '<b>#'+(i+1)+'</b><span class="tff-id-chip-code">'+tffEsc(idStr)+'</span>'+
    '</span>';
  }).join('')+'</div>';
}
function tffIdArraySection(iconCls,title,arr){
  const chips=tffIdChipsHtml(arr);
  if(!chips) return '';
  return '<div class="tff-section">'+
    '<div class="tff-section-head"><i class="fa-solid '+iconCls+'"></i><span>'+tffEsc(title)+'</span></div>'+
    chips+
  '</div>';
}
// Dipakai khusus CEK INFO FF (kolom 1, di ATAS Bio): item yang tersedia dari
// API (foto profil, title, outfit, skin senjata, pet) digabung jadi SATU
// baris gambar saja tanpa label teks kategori.
// CATATAN: API /freefireinfo (siambhau69.eu.cc) TIDAK menyediakan field
// skin kendaraan (mobil/motor/car sport), skin gloo wall, skin granat,
// emote/animasi end, lootbox, atau skin tinju — jadi kategori itu sengaja
// tidak ada di sini, bukan kelewat.
// Urutan mentah "clothes" dari API ternyata: 0 Sepatu, 1 Celana, 2 Makeup,
// 3 Baju, 4 Topi/Kepala, 5 Topeng (dicek langsung dari hasil nyata, BUKAN
// urutan kepala->topeng->makeup->baju->celana->sepatu yang dikira sebelumnya).
// Fungsi ini menyusun ulang jadi urutan tampil yang diminta: Kepala-Topeng-
// Makeup-Baju-Celana-Sepatu. Kalau panjang array bukan 6 (API berubah/data
// tidak lengkap), dibiarkan apa adanya biar gak salah susun/rusak.
function cidReorderClothes(arr){
  if(!Array.isArray(arr)||arr.length<6) return arr;
  const order=[4,5,2,3,1,0];
  const reordered=order.map(function(i){ return arr[i]; });
  if(arr.length>6) reordered.push.apply(reordered,arr.slice(6));
  return reordered;
}
function cidCombinedItemGroups(json){
  const groups=[];
  const pushGroup=function(label,ids){
    const list=(Array.isArray(ids)?ids:[ids]).filter(function(v){ return v!=null&&v!==''; });
    if(list.length) groups.push({label:label,ids:list});
  };
  // Urutan digabung jadi 1 baris tanpa label teks: Outfit (array clothes,
  // sudah disusun ulang lewat cidReorderClothes jadi Kepala->Topeng->Makeup->
  // Baju->Celana->Sepatu) ditaruh PALING DEPAN, langsung disambung Skin
  // Senjata (biar urutannya nyambung tanpa kepotong), baru disusul
  // Foto Profil -> Title -> Pet.
  pushGroup('Outfit',json.profileInfo&&cidReorderClothes(json.profileInfo.clothes));
  pushGroup('Skin Senjata',json.basicInfo&&json.basicInfo.weaponSkinShows);
  pushGroup('Foto Profil',cidPickIdCI(json,'headpic'));
  pushGroup('Title',cidPickIdCI(json,'title'));
  pushGroup('Pet',json.petInfo&&json.petInfo.id);
  return groups;
}
function cidCombinedItemIconsHtml(json){
  const groups=cidCombinedItemGroups(json);
  if(!groups.length) return '';
  const allIds=[];
  groups.forEach(function(g){ allIds.push.apply(allIds,g.ids); });
  return '<div class="tff-profile-items-wrap"><div class="tff-profile-items-groups"><div class="tff-profile-items-row">'+allIds.map(function(id){
    const idStr=String(id);
    return '<img src="'+tffAttrEsc(tffItemIconUrl(idStr))+'" alt="item" loading="lazy" referrerpolicy="no-referrer" onerror="this.style.display=\'none\'">';
  }).join('')+'</div></div></div>';
}
/* Sama seperti tffSection, tapi untuk statistik ranked yang datang terbagi
   per mode (solostats/duostats/squadstats) alih-alih field flat langsung. */
function tffStatsSection(iconCls,title,statsObj){
  if(!statsObj||typeof statsObj!=='object') return '';
  const rows=tffStatsRowsHtml(statsObj);
  if(!rows) return '';
  return '<div class="tff-section">'+
    '<div class="tff-section-head"><i class="fa-solid '+iconCls+'"></i><span>'+tffEsc(title)+'</span></div>'+
    '<div class="tff-result-rows">'+rows+'</div>'+
  '</div>';
}

async function stkFfSubmit(){
  const menu=TFF_MENU[0];
  const inp=document.getElementById('stkFfVal');
  const uidVal=inp?inp.value.trim():'';
  if(!uidVal){ tffShake(inp); return; }

  const btn=document.getElementById('stkFfBtn');
  const result=document.getElementById('stkFfResult');
  if(result){ result.classList.remove('show'); result.innerHTML=''; }

  let lastErr=null;
  for(let i=0;i<TFF_ALL_REGIONS.length;i++){
    const region=TFF_ALL_REGIONS[i];
    if(btn){ btn.disabled=true; btn.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> MENGECEK ('+region+')...'; }
    const queryBase='key='+encodeURIComponent(TFF_KEY)+'&uid='+encodeURIComponent(uidVal)+'&region='+encodeURIComponent(region);
    try{
      const json=await xyureiRequest(function(){
        return TFF_BASE+menu.path+'?'+queryBase;
      },{isDataOk:function(j){ return !!(j&&(j.basicInfo||j.data||j.result)); }});

      // Banner (gambar PNG langsung dari server) & statistik ranked BR/CS
      // dianggap pelengkap: kalau salah satu gagal/limit, profil utama
      // tetap ditampilkan tanpa bagian itu.
      const bannerUrl=tffBuildBannerUrl(uidVal,region);
      let statsBr=null,statsCs=null;
      try{ statsBr=await tffFetchStats(uidVal,region,'br','RANKED'); }catch(e){ statsBr=null; }
      try{ statsCs=await tffFetchStats(uidVal,region,'cs','RANKED'); }catch(e){ statsCs=null; }

      tffRenderResult(result,json,{bannerUrl:bannerUrl,statsBr:statsBr,statsCs:statsCs});
      if(btn){ btn.disabled=false; btn.innerHTML='<i class="fa-solid fa-paper-plane"></i> CEK INFO'; }
      return;
    }catch(e){
      lastErr=e;
      console.warn('[STKFF] region '+region+' gagal, coba region berikutnya...',(e&&e.debugDetail)||e);
    }
  }

  console.error('[STKFF] semua region gagal',lastErr,(lastErr&&lastErr.debugDetail)||'');
  const detail=(lastErr&&lastErr.debugDetail)?' ('+lastErr.debugDetail+')':'';
  if(result){
    result.innerHTML='<div class="tff-result-error"><i class="fa-solid fa-triangle-exclamation"></i>UID tidak ditemukan di semua region.'+tffEsc(detail)+'</div>';
    result.classList.add('show');
  }
  if(btn){ btn.disabled=false; btn.innerHTML='<i class="fa-solid fa-paper-plane"></i> CEK INFO'; }
}

/* Lebar layar tiap HP beda-beda, jadi 41 karakter tidak selalu muat di
   font-size tetap (apalagi bio banyak huruf KAPITAL yang lebih lebar).
   Fungsi ini mengecilkan font bio SEDIKIT DEMI SEDIKIT sampai baris
   terlebar benar-benar pas di lebar kotak -> tidak perlu digeser sama
   sekali. Dipanggil tiap kali profil (berisi bio) baru saja dirender. */
function tffFitBioText(root){
  if(!root||!root.querySelectorAll) return;
  const run=function(){
    const wraps=root.querySelectorAll('.tff-bio-scroll');
    wraps.forEach(function(wrap){
      const textEl=wrap.querySelector('.tff-bio-text');
      if(!textEl) return;
      let size=14;
      textEl.style.fontSize=size+'px';
      let guard=0;
      while(wrap.scrollWidth>wrap.clientWidth+1&&size>8&&guard<40){
        size-=0.5;
        textEl.style.fontSize=size+'px';
        guard++;
      }
    });
  };
  if(window.requestAnimationFrame) requestAnimationFrame(run); else run();
}
