function tffRankLookup(points,table){
  const n=Number(points);
  if(isNaN(n)) return null;
  let found=null;
  for(let i=0;i<table.length;i++){ if(n>=table[i].min) found=table[i]; else break; }
  return found;
}
function tffRankBadgeHtml(points,game){
  const entry=tffRankLookup(points,game==='cs'?TFF_RANK_CS_TABLE:TFF_RANK_BR_TABLE);
  if(!entry) return '';
  const file=game+entry.tier+'.png';
  return '<div class="tff-rank-badge">'+
      '<img src="zusmo-asset/'+file+'" alt="'+tffAttrEsc(entry.label)+'" onerror="this.style.visibility=\'hidden\'">'+
      '<div class="tff-rank-badge-info"><span class="tff-rank-badge-game">'+(game==='cs'?'Rank CS':'Rank BR')+'</span><span class="tff-rank-badge-tier">'+tffEsc(entry.label)+'</span></div>'+
    '</div>';
}
function tffBuildProfileHead(json,extra,refreshAttr){
  extra=extra||{};
  const b=json.basicInfo||{};
  const nickname=stkPick(b,['nickname'])||'-';
  const uidVal=stkPick(b,['accountId','account_id']);
  const region=stkPick(b,['region']);
  const level=stkPick(b,['level']);
  const liked=stkPick(b,['liked']);
  const primeLevel=stkPick(b,['primeLevel','prime_level'])||(b.primeInfo&&stkPick(b.primeInfo,['primeLevel','prime_level']));
  const createAt=stkPick(b,['createAt','create_at']);
  const lastLoginAt=stkPick(b,['lastLoginAt','last_login_at']);
  const rankPointsBr=stkPick(b,['rankingPoints','ranking_points','rankingpoints']);
  const rankPointsCs=stkPick(b,['csRankingPoints','cs_ranking_points','csrankingpoints']);
  const social=json.socialInfo||{};
  const signature=stkPick(b,['signature'])||stkPick(social,['signature']);

  const bioOriginalRaw=signature?String(signature).trim():'';
  const bioOriginalHtml=bioOriginalRaw?tffFormatBio(bioOriginalRaw):'';
  const bioCombinedHtml=bioOriginalHtml;
  const bioCopyVal=bioOriginalRaw;

  // Endpoint /banner/profile langsung balikin GAMBAR PNG jadi (bukan JSON) yang
  // isinya sudah gabungan avatar+nama+guild+level dirender server, ukuran total
  // 200x43 dengan avatar persegi (43x43) nempel di ujung kiri. Kita cuma mau
  // avatarnya aja: wrapper .tff-banner-wrap yang crop bagian kiri itu (lihat CSS).
  const bannerUrl=extra.bannerUrl||'';
  const primeIconForAvatar=primeLevel?TFF_PRIME_ICONS[parseInt(primeLevel,10)]:null;
  const isPrime8=primeLevel&&parseInt(primeLevel,10)===8;
  const avatarInnerHtml=bannerUrl?
    '<div class="tff-banner-wrap"><img class="tff-banner-img" src="'+tffAttrEsc(bannerUrl)+'" alt="avatar profil" referrerpolicy="no-referrer" onerror="this.onerror=null;this.src=\'zusmo-asset/bpjwcf.png\';this.style.width=\'100%\';this.style.objectFit=\'cover\';">'+
    (primeIconForAvatar?'<img class="tff-banner-prime-badge" src="'+tffAttrEsc(primeIconForAvatar)+'" alt="Prime '+tffAttrEsc(String(primeLevel))+'" onerror="this.style.display=\'none\'">':'')+
    '</div>':'';
  // Prime 8: avatar dikasih bingkai emas-kristal ekstra (borderprime.png).
  // Dibungkus wrapper terpisah yang TANPA overflow:hidden biar ujung
  // bingkai yang lebih lebar dari kotak avatar gak kepotong.
  const avatarHtml=bannerUrl?
    '<div class="tff-avatar-frame-wrap'+(isPrime8?' has-prime8-frame':'')+'">'+avatarInnerHtml+
    (isPrime8?'<img class="tff-prime8-frame" src="zusmo-asset/borderprime.png" alt="Bingkai Prime 8" onerror="this.style.display=\'none\'">':'')+
    '</div>':'';

  const metaParts=[];
  if(uidVal) metaParts.push('<span>ID: <b>'+tffEsc(String(uidVal))+'</b></span>');
  if(liked!=null) metaParts.push('<span><img class="tff-meta-icon" src="zusmo-asset/like.png" alt="">Likes: <b>'+tffEsc(Number(liked).toLocaleString('id-ID'))+'</b></span>');
  if(region) metaParts.push('<span><img class="tff-meta-icon" src="zusmo-asset/region.png" alt="">Region: <b>'+tffEsc(String(region))+'</b></span>');

  const badges=[];
  const ffAge=tffYearsSince(createAt);
  // Badge tetap tampil walau akunnya belum genap 1 tahun (tulis "0 Tahun"),
  // asal createAt-nya valid; cuma disembunyikan kalau memang gak ada data.
  if(createAt) badges.push('<span class="tff-profile-badge"><i class="fa-solid fa-cake-candles"></i> '+ffAge+' Tahun</span>');
  if(primeLevel){
    const primeIcon=TFF_PRIME_ICONS[parseInt(primeLevel,10)];
    badges.push(primeIcon?(
      '<span class="tff-profile-badge" style="display:inline-flex;align-items:center;gap:5px;"><img src="'+tffAttrEsc(primeIcon)+'" alt="Prime '+tffAttrEsc(String(primeLevel))+'" style="width:22px;height:22px;object-fit:contain;margin:-3px 0;" onerror="this.style.display=\'none\'">Prime '+tffEsc(String(primeLevel))+'</span>'
    ):(
      '<span class="tff-profile-badge"><i class="fa-solid fa-crown"></i> Prime '+tffEsc(String(primeLevel))+'</span>'
    ));
  }

  const rankBadges=[];
  if(rankPointsBr!=null) rankBadges.push(tffRankBadgeHtml(rankPointsBr,'br'));
  if(rankPointsCs!=null) rankBadges.push(tffRankBadgeHtml(rankPointsCs,'cs'));
  const rankBadgesHtml=rankBadges.filter(Boolean).join('');

  const dateRows=[];
  if(createAt){
    dateRows.push('<div class="tff-profile-date-row"><i class="fa-regular fa-calendar"></i>Akun dibuat '+tffEsc(tffPrettyValue('createAt',createAt))+'</div>');
    const ageStr=tffDetailedAge(createAt);
    if(ageStr) dateRows.push('<div class="tff-profile-date-row"><i class="fa-regular fa-calendar-check"></i>'+tffEsc(ageStr)+'</div>');
  }
  if(lastLoginAt) dateRows.push('<div class="tff-profile-date-row"><i class="fa-regular fa-clock"></i>Login terakhir '+tffEsc(tffPrettyValue('lastLoginAt',lastLoginAt))+'</div>');

  const clan=json.clanBasicInfo||{};
  const clanName=stkPick(clan,['clanName']);
  const clanId=stkPick(clan,['clanId','id']);
  const clanLevel=stkPick(clan,['clanLevel']);
  const memberNum=stkPick(clan,['membernum','memberNum']);
  const captainId=stkPick(clan,['captainId']);
  const captainInfo=json.captainBasicInfo||{};
  const captainName=stkPick(captainInfo,['nickname']);

  return '<div class="tff-profile-head">'+
      '<div class="tff-profile-top-row">'+avatarHtml+(rankBadgesHtml?'<div class="tff-rank-badges tff-rank-badges-top">'+rankBadgesHtml+'</div>':'')+'</div>'+
      '<div class="tff-profile-name-row"><span class="tff-profile-name">'+tffEsc(nickname)+'</span>'+
        (level!=null?'<span class="tff-profile-lvl"><img class="tff-lvl-icon" src="zusmo-asset/level.png" alt="">Lvl. '+tffEsc(String(level))+'</span>':'')+
      '</div>'+
      (metaParts.length?'<div class="tff-profile-meta">'+metaParts.join('')+'</div>':'')+
      (badges.length?'<div class="tff-profile-badges">'+badges.join('')+'</div>':'')+
      (dateRows.length?'<div class="tff-profile-dates">'+dateRows.join('')+'</div>':'')+
      (extra.showItems?cidCombinedItemIconsHtml(json):'')+
      (bioCombinedHtml?(
        '<div class="tff-profile-bio-label">Bio</div>'+
        '<div class="tff-profile-bio-box"><div class="tff-bio-scroll"><span class="tff-bio-text" style="font-family:\'Anton\',sans-serif;font-weight:400!important;text-shadow:.4px 0 currentColor,-.4px 0 currentColor,0 .4px currentColor,0 -.4px currentColor">'+bioCombinedHtml+'</span></div>'+
        '<button class="stk-copy-btn" data-val="'+tffAttrEsc(bioCopyVal)+'" onclick="tffCopyVal(this)"><i class="fa-solid fa-copy"></i></button></div>'
      ):'')+
      (clanName?(
        '<div class="tff-profile-guild-label">Guild</div>'+
        '<div class="tff-profile-guild-chip"><i class="fa-solid fa-people-group"></i>'+tffEsc(String(clanName))+'</div>'+
        '<div class="tff-profile-guild-meta">'+
          (clanId?'<span>ID Guild: <b>'+tffEsc(String(clanId))+'</b></span>':'')+
          (clanLevel!=null?'<span>Level: <b>'+tffEsc(String(clanLevel))+'</b></span>':'')+
          (memberNum!=null?'<span>Member: <b>'+tffEsc(String(memberNum))+'</b></span>':'')+
        '</div>'+
        (captainId?'<div class="tff-profile-captain"><i class="fa-solid fa-user"></i>ID Kapten: <b>'+tffEsc(String(captainId))+(captainName?' &middot; '+tffEsc(String(captainName)):'')+'</b></div>':'')
      ):'')+
    '</div>';
}

function tffRenderResult(box,json,extra){
  if(!box) return;
  extra=extra||{};
  if(json&&json.error){
    box.innerHTML='<div class="tff-result-error"><i class="fa-solid fa-triangle-exclamation"></i>'+tffEsc(json.error)+'</div>';
    box.classList.add('show');
    return;
  }
  const head=tffBuildProfileHead(json,extra,'stkFfSubmit()');
  let html='';
  html+=tffIdArraySection('fa-shirt','Outfit yang Dipakai (Item ID)',json.profileInfo&&json.profileInfo.clothes);
  html+=tffIdArraySection('fa-gun','Skin Senjata Dipajang (Item ID)',json.basicInfo&&json.basicInfo.weaponSkinShows);
  html+=tffIdArraySection('fa-paw','Peliharaan (Item ID)',[json.petInfo&&json.petInfo.id]);
  html+=tffIdArraySection('fa-paw','Skin Peliharaan (Item ID)',[json.petInfo&&json.petInfo.skinid]);
  html+=tffIdArraySection('fa-flag','Banner (Item ID)',[cidPickId(json,'bannerid')]);
  html+=tffIdArraySection('fa-circle-user','Avatar (Item ID)',[cidPickId(json,'avatarid')]);
  html+=tffIdArraySection('fa-thumbtack','Pin (Item ID)',[cidPickId(json,'pinid')]);
  html+=tffIdArraySection('fa-award','Badge (Item ID)',[cidPickId(json,'badgeid')]);
  html+=tffSection('fa-user-shield','Info Akun',json.basicInfo,['nickname','accountid','level','liked','region','primelevel','createat','lastloginat','signature']);
  html+=tffStatsSection('fa-ranking-star','Statistik Ranked BR',extra.statsBr?tffUnwrap(extra.statsBr):null);
  html+=tffStatsSection('fa-chess-board','Statistik Ranked CS',extra.statsCs?tffUnwrap(extra.statsCs):null);
  html+=tffSection('fa-shield-halved','Info Guild',json.clanBasicInfo,['clanname','id','clanlevel','membernum','captainid']);
  html+=tffSection('fa-crown','Info Ketua Guild',json.captainBasicInfo,['nickname']);
  html+=tffSection('fa-paw','Info Peliharaan',json.petInfo,['id','skinid']);
  html+=tffSection('fa-comment-dots','Info Sosial',json.socialInfo,['signature']);
  html+=tffSection('fa-gem','Perkiraan Harga',json.diamondCostRes);
  html+=tffSection('fa-star','Skor Kredit',json.creditScoreInfo);
  html+=tffSection('fa-user-astronaut','Info Profil',json.profileInfo);
  if(!html){
    box.innerHTML='<div class="tff-result-error"><i class="fa-solid fa-triangle-exclamation"></i>Data tidak ditemukan atau UID salah.</div>';
  }else{
    box.innerHTML=head+html;
    tffFitBioText(box);
  }
  box.classList.add('show');
}

function tffFriendsArray(json){
  const d=tffUnwrap(json);
  if(Array.isArray(d)) return d;
  if(d&&typeof d==='object'){
    const arrKeys=['friends','list','friendList','friend_list','items'];
    for(let i=0;i<arrKeys.length;i++){ if(Array.isArray(d[arrKeys[i]])) return d[arrKeys[i]]; }
  }
  return [];
}
function tffRenderFriendsList(box,json){
  if(!box) return;
  if(json&&json.error){
    box.innerHTML='<div class="tff-result-error"><i class="fa-solid fa-triangle-exclamation"></i>'+tffEsc(json.error)+'</div>';
    box.classList.add('show');
    return;
  }
  const friends=tffFriendsArray(json);
  if(!friends.length){
    box.innerHTML='<div class="tff-result-error"><i class="fa-solid fa-user-slash"></i>Daftar teman kosong atau tidak ditemukan.</div>';
    box.classList.add('show');
    return;
  }
  let rows='';
  friends.forEach(function(f){
    if(!f||typeof f!=='object') return;
    const fname=stkPick(f,['nickname','name'])||'-';
    const fuid=stkPick(f,['accountId','account_id','uid']);
    const flevel=stkPick(f,['level']);
    const fsub=[fuid?('UID '+tffEsc(String(fuid))):'',flevel!=null?('Lv. '+tffEsc(String(flevel))):''].filter(Boolean).join(' · ');
    rows+=
      '<div class="tff-friend-row">'+
        '<img class="tff-friend-avatar" src="zusmo-asset/bpjwcf.png" alt="avatar">'+
        '<div style="flex:1;min-width:0;">'+
          '<div class="tff-friend-name">'+tffEsc(fname)+'</div>'+
          (fsub?'<div class="tff-friend-sub">'+fsub+'</div>':'')+
        '</div>'+
      '</div>';
  });
  box.innerHTML='<div class="tff-section-head" style="margin-top:0;border-top:none;padding-top:0;"><i class="fa-solid fa-user-group"></i><span>DAFTAR TEMAN ('+friends.length+')</span></div>'+
    '<div class="tff-friends-list">'+rows+'</div>';
  box.classList.add('show');
}

