let tlsActiveKey=null;
let tlsGridBuilt=false;

/* Biaya diamond: semua Tools (TLS_MENU) = 35 Diamond per pemakaian, kecuali
   Alight Motion Prem yang lebih mahal karena kirim/verifikasi email premium
   = 250 Diamond. Saldo dicek dulu sebelum request jalan (cidPreCheckDiamond);
   dipotong (cidDeductDiamond) begitu respons berhasil didapat. */
const TLS_COST=35;
const TLS_COST_OVERRIDE={alightmotion:250};
function tlsCostFor(key){ return TLS_COST_OVERRIDE[key]||TLS_COST; }

function tlsBuildGrid(){
  const grid=document.getElementById('tlsGrid');
  if(!grid||tlsGridBuilt) return;
  grid.innerHTML=TLS_MENU.map(function(m){
    const iconCls=m.icon.indexOf('fa-')===0?('fa-solid '+m.icon):m.icon;
    return '<div class="tls-tile" id="tlsTile_'+m.key+'" onclick="tlsSelect(\''+m.key+'\')">'+
      '<div class="tls-tile-cost"><img src="zusmo-asset/onzrii.png" alt="diamond"/>'+tlsCostFor(m.key)+'</div>'+
      '<div class="tls-tile-icon"><i class="'+iconCls+'"></i></div><span>'+m.label+'</span></div>';
  }).join('');
  tlsGridBuilt=true;
}
document.addEventListener('DOMContentLoaded',tlsBuildGrid);

function tlsArea(){ return document.getElementById('toolDetailArea'); }

function tlsEsc(str){
  return String(str==null?'':str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function tlsEscAttr(str){
  return String(str==null?'':str).replace(/'/g,'&#39;').replace(/"/g,'&quot;');
}

function tlsSelect(key){
  tlsActiveKey=key;
  document.querySelectorAll('#tools .tls-tile').forEach(function(t){t.classList.remove('active');});
  const tile=document.getElementById('tlsTile_'+key);
  if(tile) tile.classList.add('active');
  const menu=TLS_MENU.find(function(m){return m.key===key;});
  if(!menu) return;
  tlsRenderForm(menu);
  if(typeof showPage==='function') showPage('toolDetail');
}

function tlsRenderForm(menu){
  const area=tlsArea();
  const iconCls=menu.icon.indexOf('fa-')===0?('fa-solid '+menu.icon):menu.icon;
  const titleEl=document.getElementById('toolDetailTitle');
  const subEl=document.getElementById('toolDetailSubtitle');
  const iconEl=document.getElementById('toolDetailIcon');
  if(titleEl) titleEl.textContent=menu.label;
  if(subEl) subEl.textContent=menu.desc;
  if(iconEl) iconEl.className=iconCls;
  const fieldsHtml=menu.fields.map(function(f,i){
    let ctrl;
    if(f.options&&f.options.length){
      const defVal=(f.def!=null&&f.options.indexOf(f.def)!==-1)?f.def:f.options[0];
      const btns=f.options.map(function(opt){
        const active=(opt===defVal)?' active':'';
        return '<button type="button" class="tls-optbtn'+active+'" data-val="'+tlsEscAttr(opt)+'" onclick="tlsSelectOption('+i+',this)">'+tlsEsc(opt)+'</button>';
      }).join('');
      ctrl='<div class="tls-optrow" id="tlsOptRow_'+i+'">'+btns+'</div>'+
        '<input type="hidden" id="tlsField_'+i+'" value="'+tlsEscAttr(defVal)+'">';
    }else if(f.type==='textarea'){
      ctrl='<textarea class="tls-input" id="tlsField_'+i+'" rows="4" style="resize:vertical;font-family:\'Space Mono\',monospace" placeholder="'+tlsEscAttr(f.placeholder||'')+'">'+tlsEsc(f.def||'')+'</textarea>';
    }else{
      ctrl='<input class="tls-input" id="tlsField_'+i+'" type="text" placeholder="'+tlsEscAttr(f.placeholder||'')+'" value="'+tlsEscAttr(f.def||'')+'">';
    }
    if(f.example){
      const examples=Array.isArray(f.example)?f.example:[f.example];
      ctrl+='<div class="tls-example-row"><span class="tls-example-label">Contoh:</span>'+
        examples.map(function(ex){
          return '<button type="button" class="tls-example-chip" data-field-idx="'+i+'" data-example="'+tlsEscAttr(ex)+'" onclick="tlsUseExample(this)">'+tlsEsc(ex)+'</button>';
        }).join('')+
      '</div>';
    }
    return '<div class="tls-field">'+
      '<label>'+tlsEsc(f.label)+'</label>'+
      ctrl+
    '</div>';
  }).join('');
  area.innerHTML=
    '<div class="tls-formcard">'+
      fieldsHtml+
      '<button class="tls-submitbtn" id="tlsSubmitBtn" onclick="tlsSubmit()"><i class="fa-solid fa-paper-plane"></i> KIRIM</button>'+

    '</div>'+
    '<div class="tls-result" id="tlsResult"></div>';
}

// Klik chip "Contoh" -> isi field terkait dengan nilai contohnya langsung,
// biar user gak perlu ngetik/nyari sample sendiri buat nyoba tool-nya.
function tlsUseExample(btn){
  if(!btn) return;
  const idx=btn.getAttribute('data-field-idx');
  const val=btn.getAttribute('data-example');
  const inp=document.getElementById('tlsField_'+idx);
  if(!inp) return;
  inp.value=val;
  inp.classList.remove('tls-shake');
  inp.focus();
}

function tlsSelectOption(idx,btnEl){
  const row=document.getElementById('tlsOptRow_'+idx);
  const hidden=document.getElementById('tlsField_'+idx);
  if(row) row.querySelectorAll('.tls-optbtn').forEach(function(b){b.classList.remove('active');});
  if(btnEl) btnEl.classList.add('active');
  if(hidden) hidden.value=btnEl?btnEl.getAttribute('data-val'):'';
}

function tlsShake(el){
  if(!el) return;
  el.classList.remove('tls-shake');
  void el.offsetWidth;
  el.classList.add('tls-shake');
  el.focus();
}

// ===== Text to QR Code: generate lokal, ikut menu "QR GENERATOR" =====
// Sebelumnya tool ini manggil API eksternal (TLS_BASE+'text2qr') kayak tool
// lain. Sesuai permintaan, sekarang dipakein cara yang SAMA dengan menu
// QR GENERATOR yang sudah ada di app ini (halaman #qrgen): generate QR
// langsung di browser pakai library qrcodejs (window.QRCode, sudah dimuat
// global lewat <script src=".../qrcodejs/1.0.0/qrcode.min.js"> di halaman
// qrgen) — jadi gak perlu request ke server/apikey sama sekali, dan hasilnya
// konsisten sama style/kualitas dgn QR Generator biasa.
function tlsText2QrDownload(){
  const canvas=document.querySelector('#tlsQrBox canvas');
  if(!canvas){ if(typeof showToast==='function') showToast('QR Code belum siap.'); return; }
  try{
    const borderSize=35,scaleFactor=2;
    const finalCanvas=document.createElement('canvas');
    finalCanvas.width=(canvas.width*scaleFactor)+(borderSize*2);
    finalCanvas.height=(canvas.height*scaleFactor)+(borderSize*2);
    const ctx=finalCanvas.getContext('2d');
    ctx.imageSmoothingEnabled=false;
    ctx.fillStyle='#ffffff';
    ctx.fillRect(0,0,finalCanvas.width,finalCanvas.height);
    ctx.drawImage(canvas,borderSize,borderSize,canvas.width*scaleFactor,canvas.height*scaleFactor);
    finalCanvas.toBlob(function(blob){
      if(!blob) return;
      const blobUrl=URL.createObjectURL(blob);
      const link=document.createElement('a');
      link.href=blobUrl;
      link.download='KZRIZUSMO-QR-'+Date.now()+'.png';
      link.click();
      URL.revokeObjectURL(blobUrl);
    },'image/png',1.0);
  }catch(e){
    if(typeof showToast==='function') showToast('Download gagal, coba lagi.');
  }
}
function tlsRenderTextQrResult(box,text){
  if(!box) return;
  box.innerHTML=
    '<div class="tls-qr-wrap"><div id="tlsQrBox"></div></div>'+
    '<button class="tls-download-btn" id="tlsQrDlBtn" onclick="tlsText2QrDownload()" style="display:none;"><i class="fa-solid fa-download"></i> Download PNG</button>';
  box.classList.add('show');
  const mount=document.getElementById('tlsQrBox');
  if(typeof QRCode==='undefined'){
    box.innerHTML='<div class="tls-result-error"><i class="fa-solid fa-triangle-exclamation"></i>Library QR belum siap, coba lagi sebentar.</div>';
    return;
  }
  new QRCode(mount,{
    text:text,
    width:280,
    height:280,
    colorDark:'#000000',
    colorLight:'#ffffff',
    correctLevel:QRCode.CorrectLevel.H
  });
  setTimeout(function(){
    const canvas=mount.querySelector('canvas');
    const dlBtn=document.getElementById('tlsQrDlBtn');
    if(canvas&&dlBtn) dlBtn.style.display='flex';
  },600);
}

async function tlsSubmit(){
  const menu=TLS_MENU.find(function(m){return m.key===tlsActiveKey;});
  if(!menu) return;
  const params=[];
  const values={};
  let missingRequired=false;
  menu.fields.forEach(function(f,i){
    const inp=document.getElementById('tlsField_'+i);
    const val=inp?inp.value.trim():'';
    if(f.required && !val){ tlsShake(inp); missingRequired=true; return; }
    values[f.name]=val;
    if(val) params.push(encodeURIComponent(f.name)+'='+encodeURIComponent(val));
  });
  if(missingRequired) return;
  const tlsCost=tlsCostFor(menu.key);
  if(!cidPreCheckDiamond(tlsCost,'tlsSubmitBtn')) return;

  const result=document.getElementById('tlsResult');
  if(menu.key==='text2qr'){
    if(result){ result.classList.remove('show'); result.innerHTML=''; }
    tlsRenderTextQrResult(result,values.text);
    cidDeductDiamond(tlsCost,menu.label,'Tools: '+menu.label);
    return;
  }

  const btn=document.getElementById('tlsSubmitBtn');
  if(btn){ btn.disabled=true; btn.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> MENGIRIM...'; }
  if(result){ result.classList.remove('show'); result.innerHTML=''; }

  const queryBase=params.join('&');
  try{
    const json=await xyureiRequest(function(key){
      return TLS_BASE+menu.key+'?'+queryBase+'&apikey='+key;
    });
    cidDeductDiamond(tlsCost,menu.label,'Tools: '+menu.label);
    tlsRenderResult(result,json,menu,values);
  }catch(e){
    console.error('[TLS]['+menu.key+']',e,(e&&e.debugDetail)||'');
    const detail=(e&&e.debugDetail)?' ('+e.debugDetail+')':'';
    if(result){
      result.innerHTML='<div class="tls-result-error"><i class="fa-solid fa-triangle-exclamation"></i>Gagal memproses permintaan.'+tlsEsc(detail)+'</div>';
      result.classList.add('show');
    }
  }
  if(btn){ btn.disabled=false; btn.innerHTML='<i class="fa-solid fa-paper-plane"></i> KIRIM'; }
}

// Cari media (audio/gambar) di dalam JSON respons, siapa tahu API membungkusnya
// dalam field seperti result/url/media/file/link/data/output.
function tlsExtractMedia(json){
  function fromString(s){
    s=String(s).trim();
    if(!/^https?:\/\//i.test(s) && !/^data:/i.test(s)) return null;
    let type='';
    if(/\.(mp3|wav|ogg|m4a|aac)(\?|$)/i.test(s)||/^data:audio\//i.test(s)) type='audio';
    else if(/\.(mp4|webm|mov)(\?|$)/i.test(s)||/^data:video\//i.test(s)) type='video';
    else if(/\.(jpg|jpeg|png|webp|gif)(\?|$)/i.test(s)||/^data:image\//i.test(s)) type='image';
    return type?{url:s,type:type}:null;
  }
  function deep(obj,depth){
    if(depth>5||obj==null) return null;
    if(typeof obj==='string') return fromString(obj);
    if(Array.isArray(obj)){
      for(let i=0;i<obj.length;i++){ const r=deep(obj[i],depth+1); if(r) return r; }
      return null;
    }
    if(typeof obj==='object'){
      const priorityKeys=['result','url','audio','video','image','media','file','link','data','output'];
      for(const k of priorityKeys){
        if(obj[k]!==undefined){ const r=deep(obj[k],depth+1); if(r) return r; }
      }
      for(const k in obj){
        if(priorityKeys.indexOf(k)!==-1) continue;
        const r=deep(obj[k],depth+1); if(r) return r;
      }
    }
    return null;
  }
  return deep(json,0);
}

// Cari teks utama (mis. hasil decode base64/biner, atau pesan status) di level manapun.
function tlsExtractText(json){
  if(!json||typeof json!=='object') return typeof json==='string'?json:'';
  const textKeys=['result','text','decoded','output','message','msg','base64'];
  const d=json.data!==undefined?json.data:(json.result!==undefined?json.result:json);
  // Beberapa endpoint (mis. Binary to Text, Base64 to Text) mengembalikan hasilnya
  // LANGSUNG sebagai string di field "data"/"result" (bukan dibungkus lagi di
  // dalam key seperti "text"/"decoded"). Kalau d sendiri sudah berupa string,
  // itu SUDAH jadi teks hasilnya — pakai langsung, jangan sampai ke-skip.
  // Text to Base64 beda lagi: hasilnya DIBUNGKUS di objek {"base64":"..."}
  // (bukan string langsung di "data"), makanya "base64" ditambahkan ke textKeys
  // di atas biar tetap kepetik & tampil sebagai kotak teks yang bisa disalin.
  if(typeof d==='string' && d.trim() && !/^https?:\/\//i.test(d) && !/^data:/i.test(d)) return d;
  const sources=[json,d];
  for(const src of sources){
    if(!src||typeof src!=='object') continue;
    for(const k of textKeys){
      if(typeof src[k]==='string' && src[k].trim() && !/^https?:\/\//i.test(src[k])) return src[k];
    }
  }
  return '';
}

const TLS_ROW_SKIP_KEYS=['status','success','creator','result','url','audio','video','image','media','file','link','data','output','text','decoded','message','msg','base64'];
function tlsPrettyLabel(key){
  return key.replace(/_/g,' ').replace(/([a-z])([A-Z])/g,'$1 $2').replace(/\b\w/g,function(c){return c.toUpperCase();});
}
// Format nilai satu baris hasil. Angka epoch milidetik (nama field berakhiran
// "Millis", mis. expiryTimeMillis/startTimeMillis) diubah jadi tanggal yang
// gampang dibaca, boolean diubah jadi Ya/Tidak, sisanya apa adanya.
function tlsFormatRowValue(key,val){
  if(typeof val==='number' && /millis$/i.test(key) && val>1e11){
    try{
      const d=new Date(val);
      if(!isNaN(d.getTime())){
        return d.toLocaleString('id-ID',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});
      }
    }catch(e){}
  }
  if(typeof val==='boolean') return val?'Ya':'Tidak';
  return String(val);
}
// Susun baris hasil dari objek respons. Objek bersarang (mis. data.verify_data.result
// pada Alight Motion Prem, atau result.data pada Temp Mail) SELALU DITELUSURI
// duluan sebelum key-nya dicek ke daftar skip — soalnya key pembungkus generik
// kayak "data"/"result" dipakai berulang di kedalaman manapun cuma buat
// membungkus payload asli, BUKAN nilai itu sendiri, jadi gak boleh bikin
// seluruh isinya ikut lenyap kalau kebetulan namanya ada di TLS_ROW_SKIP_KEYS.
// TLS_ROW_SKIP_KEYS cuma dicek buat NILAI PRIMITIF (bukan objek) & cuma di
// level paling luar (depth 0), biar key primitif bersarang yang kebetulan
// namanya sama (mis. "status" di dalam verify_data.result) tidak ikut kehapus.
// Array tetap dilewati karena tidak cocok direpresentasikan sebagai baris
// label-nilai. extraSkipKeys dipakai per-tool (lewat menu.hideResultKeys)
// buat nyembunyiin field teknis/internal yang gak berguna ditampilkan ke user
// (mis. questionId/userRegion di NGL Message Sender).
function tlsRenderRows(obj,depth,extraSkipKeys){
  depth=depth||0;
  if(!obj||typeof obj!=='object'||depth>4) return '';
  let rows='';
  Object.keys(obj).forEach(function(key){
    const val=obj[key];
    if(val==null||val==='') return;
    if(Array.isArray(val)) return;
    // Dicek SEBELUM rekursi objek: sebelumnya extraSkipKeys cuma dicek buat nilai
    // primitif (karena objek langsung return duluan di baris rekursi di bawah),
    // jadi key pembungkus besar seperti "daftar_desa_kelurahan" (isinya ratusan
    // pasangan kode->nama desa) tetap ikut ditelusuri & bikin hasil kebanjiran baris.
    if(extraSkipKeys && extraSkipKeys.indexOf(key)!==-1) return;
    if(typeof val==='object'){ rows+=tlsRenderRows(val,depth+1,extraSkipKeys); return; }
    if(depth===0 && TLS_ROW_SKIP_KEYS.indexOf(key)!==-1) return;
    const isMillisDate=typeof val==='number' && /millis$/i.test(key) && val>1e11;
    const label=tlsPrettyLabel(isMillisDate?key.replace(/millis$/i,''):key);
    rows+='<div class="tls-result-row"><b>'+tlsEsc(label)+'</b><span>'+tlsEsc(tlsFormatRowValue(key,val))+'</span></div>';
  });
  return rows;
}

// Isi template "{fieldName}" dengan nilai yang barusan dikirim user, dipakai
// buat menu.successMessage (lihat tlsRenderResult) pada tool yang respons
// suksesnya cuma berisi ID/kode teknis tanpa pesan konfirmasi yang enak dibaca.
function tlsFillTemplate(tpl,values){
  return String(tpl).replace(/\{(\w+)\}/g,function(_,name){
    return (values&&values[name]!=null&&values[name]!=='')?values[name]:'';
  });
}

// ===== Renderer khusus NIK Parser =====
// Dipisah dari renderer generik (tlsRenderRows) karena respons NIK Parser
// punya struktur bersarang (detailTurunan.usia, detailTurunan.ulangTahunBerikutnya,
// lokasi.provinsi/kota_kabupaten/kecamatan) yang kalau diratakan generik jadi
// ambigu (tiga objek beda punya key "id"/"nama" yang sama), plus field
// lokasi.daftar_desa_kelurahan yang isinya bisa puluhan/ratusan pasangan
// kode->nama desa (referensi seluruh kecamatan, BUKAN desa spesifik orangnya,
// karena NIK sendiri tidak menyimpan info desa/kelurahan) sehingga ditaruh
// di panel collapsible terpisah, bukan didaftar sebagai baris biasa.
const TLS_NIK_BULAN=['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
function tlsNikFormatTanggal(str){
  if(!str) return '';
  const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(String(str));
  if(!m) return str;
  const bln=parseInt(m[2],10);
  return parseInt(m[3],10)+' '+(TLS_NIK_BULAN[bln-1]||m[2])+' '+m[1];
}
function tlsNikTitleCase(str){
  return String(str||'').replace(/_/g,' ').replace(/\b\w/g,function(c){return c.toUpperCase();});
}
function tlsNikRow(label,val){
  if(val==null||val==='') return '';
  return '<div class="tls-result-row"><b>'+tlsEsc(label)+'</b><span>'+tlsEsc(val)+'</span></div>';
}
function tlsNikSectionHead(icon,title){
  return '<div class="tls-nik-section-head"><i class="fa-solid '+icon+'"></i><span>'+tlsEsc(title)+'</span></div>';
}
function tlsRenderNikResult(json){
  const d=(json&&(json.data||json.result))||json||{};
  const det=d.detailTurunan||{};
  const usia=det.usia||{};
  const ultah=det.ulangTahunBerikutnya||{};
  const lok=d.lokasi||{};
  const prov=lok.provinsi||{};
  const kab=lok.kota_kabupaten||{};
  const kec=lok.kecamatan||{};
  const desaList=(lok.daftar_desa_kelurahan&&typeof lok.daftar_desa_kelurahan==='object')?lok.daftar_desa_kelurahan:{};
  const desaKeys=Object.keys(desaList);
  const genderMap={laki_laki:'Laki-laki',perempuan:'Perempuan'};
  const genderTxt=genderMap[d.jenisKelamin]||tlsNikTitleCase(d.jenisKelamin);

  let html='';
  html+=tlsNikSectionHead('fa-id-card','Data Utama');
  html+='<div class="tls-result-rows">'+
    tlsNikRow('NIK',d.nik)+
    tlsNikRow('Jenis Kelamin',genderTxt)+
    tlsNikRow('Tanggal Lahir',tlsNikFormatTanggal(d.tanggalLahir))+
    tlsNikRow('Usia',usia.lengkap)+
    tlsNikRow('Kode Unik',d.kodeUnik)+
  '</div>';

  html+=tlsNikSectionHead('fa-star','Info Tambahan');
  html+='<div class="tls-result-rows">'+
    tlsNikRow('Zodiak',tlsNikTitleCase(det.zodiak))+
    tlsNikRow('Pasaran Jawa',tlsNikTitleCase(det.pasaranJawa))+
    tlsNikRow('Ultah Berikutnya',tlsNikFormatTanggal(ultah.tanggal))+
    tlsNikRow('Hitung Mundur',ultah.hitungMundur)+
  '</div>';

  html+=tlsNikSectionHead('fa-location-dot','Lokasi (Sesuai Kode Wilayah NIK)');
  html+='<div class="tls-result-rows">'+
    tlsNikRow('Provinsi',prov.nama)+
    tlsNikRow('Kota/Kabupaten',kab.nama)+
    tlsNikRow('Kecamatan',kec.nama)+
  '</div>';

  if(desaKeys.length){
    const desaRows=desaKeys.map(function(kode){
      return '<div class="tls-result-row"><b>'+tlsEsc(kode)+'</b><span>'+tlsEsc(desaList[kode])+'</span></div>';
    }).join('');
    html+='<details class="tls-nik-desa"><summary>Daftar Desa/Kelurahan di Kecamatan Ini ('+desaKeys.length+')</summary>'+
      '<div class="tls-result-rows" style="margin-top:8px;">'+desaRows+'</div></details>';
  }
  return html;
}

// ===== Renderer khusus SaveWeb2Zip Copier =====
// Respons tool ini balikin "download_url" (link arsip .zip hasil clone website)
// yang sebelumnya cuma ke-render generik sebagai baris teks biasa (tls-result-row),
// bukan tombol unduh yang bisa langsung diklik. Ditambah field "url" (website
// sumber) yang justru KE-SKIP oleh TLS_ROW_SKIP_KEYS karena namanya persis "url"
// (skip list itu buat nyaring key generik "url" pembungkus media di tool lain),
// padahal di sini "url" adalah info yang justru berguna ditampilkan (situs mana
// yang di-clone). Renderer ini juga nyaring size_raw yang null (API ini kadang
// belum ngasih ukuran arsip) biar gak nongol baris kosong.
function tlsSwzRow(label,val){
  if(val==null||val==='') return '';
  return '<div class="tls-result-row"><b>'+tlsEsc(label)+'</b><span>'+tlsEsc(val)+'</span></div>';
}
function tlsSwzFormatBytes(n){
  if(n==null||n===''||isNaN(n)) return null;
  const units=['B','KB','MB','GB','TB'];
  let num=Number(n),i=0;
  while(num>=1024&&i<units.length-1){ num/=1024; i++; }
  return (i===0?num:num.toFixed(1))+' '+units[i];
}
function tlsRenderSavewebResult(json){
  const d=(json&&(json.result||json.data))||json||{};
  const dlUrl=d.download_url||'';
  const html='<div class="tls-result-rows">'+
    tlsSwzRow('Website Sumber',d.url)+
    tlsSwzRow('Jumlah File',d.file_count!=null?(d.file_count+' file'):null)+
    tlsSwzRow('Ukuran Arsip',tlsSwzFormatBytes(d.size_raw))+
  '</div>'+
  (dlUrl?'<button class="tls-download-btn" onclick="aiSaveMediaFallback(\''+dlUrl.replace(/'/g,"\\'")+'\')"><i class="fa-solid fa-file-zipper"></i> Download ZIP</button>':'');
  return html;
}

// ===== Renderer khusus YouTube Summarizer =====
// Field "content" (ringkasan markdown panjang berisi heading # dan ##) sebelumnya
// TIDAK kepetik sama sekali oleh tlsExtractText (yang cuma nyari key text/result/
// decoded/output/message/msg), jadi malah jatuh ke tlsRenderRows dan nampil
// sebagai satu baris label-nilai raksasa berisi ribuan karakter markdown mentah
// (tanda # dan ** ikut kelihatan, gak ke-render). Field teknis kayak message_id/
// progress/subtitle_task_id/sum_status/video_id/video_original_subtitle_status
// juga ikut nongol padahal gak berguna buat user. Renderer ini nampilin thumbnail
// + durasi video, ringkasan markdown yang di-render rapi (heading & paragraf),
// tombol salin ringkasan, dan tombol unduh transkrip SRT/TXT.
function tlsYtsumFormatDuration(sec){
  if(sec==null||isNaN(sec)) return '';
  sec=Math.round(Number(sec));
  const h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60),s=sec%60;
  const mm=String(m).padStart(2,'0'),ss=String(s).padStart(2,'0');
  return h>0?(h+':'+mm+':'+ss):(m+':'+ss);
}
// Konverter markdown->HTML super ringan, cuma nangani yang dipakai API ini:
// "# Judul", "## Subjudul" (termasuk yang ada timestamp "[mm:ss - mm:ss]"),
// paragraf biasa, dan **tebal**. Teks di-escape dulu (tlsEsc) sebelum ditandai
// jadi tag HTML, biar aman dari karakter aneh di transkrip video.
function tlsYtsumMdToHtml(md){
  const esc=tlsEsc(md||'');
  const lines=esc.split(/\r?\n/);
  let html='',para=[];
  function flushPara(){
    if(para.length){ html+='<p class="tls-ytsum-p">'+para.join(' ')+'</p>'; para=[]; }
  }
  lines.forEach(function(line){
    const l=line.trim();
    if(!l){ flushPara(); return; }
    const h1=/^#\s+(.*)$/.exec(l);
    const h2=/^##\s+(.*)$/.exec(l);
    if(h1){ flushPara(); html+='<h3 class="tls-ytsum-h1">'+h1[1]+'</h3>'; return; }
    if(h2){ flushPara(); html+='<h4 class="tls-ytsum-h2">'+h2[1]+'</h4>'; return; }
    para.push(l.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>'));
  });
  flushPara();
  return html;
}
function tlsRenderYtsumResult(json){
  const d=(json&&(json.result||json.data))||json||{};
  const thumb=d.video_thumbnail_url;
  const dur=tlsYtsumFormatDuration(d.video_duration);
  let html='';
  if(thumb){
    html+='<div class="tls-ytsum-thumbwrap">'+
      '<img class="tls-result-media" src="'+tlsEsc(thumb)+'" alt="thumbnail" referrerpolicy="no-referrer">'+
      (dur?'<span class="tls-ytsum-duration">'+tlsEsc(dur)+'</span>':'')+
    '</div>';
  }
  const contentHtml=tlsYtsumMdToHtml(d.content);
  if(contentHtml){
    html+='<div class="tls-ytsum-content" id="tlsYtsumContentVal">'+contentHtml+'</div>'+
      '<button class="tls-ytsum-copybtn" id="tlsYtsumCopyBtn" onclick="tlsYtsumCopyText()"><i class="fa-solid fa-copy"></i> Salin Ringkasan</button>';
  }else{
    html+='<div class="tls-result-rows"><div class="tls-result-row"><span>Ringkasan tidak tersedia.</span></div></div>';
  }
  if(d.srt_url){
    html+='<button class="tls-download-btn" onclick="aiSaveMediaFallback(\''+String(d.srt_url).replace(/'/g,"\\'")+'\')"><i class="fa-solid fa-closed-captioning"></i> Download Subtitle (SRT)</button>';
  }
  if(d.url){
    html+='<button class="tls-download-btn" style="background:linear-gradient(135deg,#3a3a3a 0%,#1a1a1a 100%);box-shadow:none;" onclick="aiSaveMediaFallback(\''+String(d.url).replace(/'/g,"\\'")+'\')"><i class="fa-solid fa-file-lines"></i> Download Transkrip (TXT)</button>';
  }
  return html;
}
function tlsYtsumCopyText(){
  const el=document.getElementById('tlsYtsumContentVal');
  const btn=document.getElementById('tlsYtsumCopyBtn');
  if(!el) return;
  const text=el.textContent||'';
  const done=function(){
    if(btn){
      btn.classList.add('copied');
      btn.innerHTML='<i class="fa-solid fa-check"></i> Tersalin';
      setTimeout(function(){ btn.classList.remove('copied'); btn.innerHTML='<i class="fa-solid fa-copy"></i> Salin Ringkasan'; },1400);
    }
    if(typeof showToast==='function') showToast('Disalin!');
  };
  if(navigator.clipboard&&navigator.clipboard.writeText){
    navigator.clipboard.writeText(text).then(done).catch(done);
  }else{
    const ta=document.createElement('textarea');
    ta.value=text;ta.style.position='fixed';ta.style.opacity='0';
    document.body.appendChild(ta);ta.select();
    try{document.execCommand('copy');}catch(e){}
    document.body.removeChild(ta);
    done();
  }
}

function tlsRenderResult(box,json,menu,values){
  if(menu&&menu.key==='ytsum'){
    if(json&&(json.error||json.status===false)){
      box.innerHTML='<div class="tls-result-error"><i class="fa-solid fa-triangle-exclamation"></i>'+tlsEsc(json.error||'Gagal memproses permintaan.')+'</div>';
      box.classList.add('show');
      return;
    }
    box.innerHTML=tlsRenderYtsumResult(json);
    box.classList.add('show');
    return;
  }
  if(menu&&menu.key==='saveweb'){
    if(json&&(json.error||json.status===false)){
      box.innerHTML='<div class="tls-result-error"><i class="fa-solid fa-triangle-exclamation"></i>'+tlsEsc(json.error||'Gagal memproses permintaan.')+'</div>';
      box.classList.add('show');
      return;
    }
    box.innerHTML=tlsRenderSavewebResult(json);
    box.classList.add('show');
    return;
  }
  if(menu&&menu.key==='nik'){
    if(json&&json.error){
      box.innerHTML='<div class="tls-result-error"><i class="fa-solid fa-triangle-exclamation"></i>'+tlsEsc(json.error)+'</div>';
      box.classList.add('show');
      return;
    }
    box.innerHTML=tlsRenderNikResult(json);
    box.classList.add('show');
    return;
  }
  if(!box) return;
  const d=(json&&(json.result||json.data))||json||{};
  const media=tlsExtractMedia(json);
  let text=tlsExtractText(json);
  // Sebagian endpoint (mis. NGL Message Sender) cuma balikin field teknis
  // (questionId/userRegion) tanpa pesan konfirmasi apa pun kalau sukses.
  // Kalau gak ada teks yang kepetik & requestnya jelas sukses (status true,
  // gak ada error), pakai successMessage dari konfigurasi tool (kalau ada)
  // biar user tetap dapet konfirmasi yang jelas & enak dibaca.
  if(!text && menu && menu.successMessage && json && json.status!==false && !json.error){
    text=tlsFillTemplate(menu.successMessage,values);
  }
  // Kalau payload utamanya (data/result) berupa string biasa, itu sudah
  // sepenuhnya terwakili oleh `text` di atas — jangan jatuhkan balik ke
  // seluruh objek json mentah buat baris (bikin field lain kayak "timestamp"
  // ikut nongol padahal bukan bagian dari hasilnya).
  const rows=typeof d==='object'?tlsRenderRows(d,0,menu&&menu.hideResultKeys):'';

  let html='';
  if(media){
    if(media.type==='audio'){
      html+='<audio class="tls-result-media" controls src="'+tlsEsc(media.url)+'"></audio>';
    }else if(media.type==='video'){
      html+='<video class="tls-result-media" controls src="'+tlsEsc(media.url)+'"></video>';
    }else{
      html+='<img class="tls-result-media" src="'+tlsEsc(media.url)+'" alt="hasil" referrerpolicy="no-referrer">';
    }
  }
  if(text){
    html+='<div class="tls-result-text-wrap"><div class="tls-result-text" id="tlsResultTextVal">'+tlsEsc(text)+'</div>'+
      '<button class="tls-result-copy" id="tlsResultCopyBtn" onclick="tlsCopyResultText()"><i class="fa-solid fa-copy"></i></button></div>';
  }
  if(rows){
    html+='<div class="tls-result-rows">'+rows+'</div>';
  }
  if(!media && !text && !rows){
    html+='<div class="tls-result-rows"><div class="tls-result-row"><span>Permintaan berhasil diproses.</span></div></div>';
  }
  box.innerHTML=html;
  box.classList.add('show');
}

function tlsCopyResultText(){
  const el=document.getElementById('tlsResultTextVal');
  const btn=document.getElementById('tlsResultCopyBtn');
  if(!el) return;
  const text=el.textContent||'';
  const done=function(){
    if(btn){
      btn.classList.add('copied');
      btn.innerHTML='<i class="fa-solid fa-check"></i>';
      setTimeout(function(){ btn.classList.remove('copied'); btn.innerHTML='<i class="fa-solid fa-copy"></i>'; },1400);
    }
    if(typeof showToast==='function') showToast('Disalin!');
  };
  if(navigator.clipboard&&navigator.clipboard.writeText){
    navigator.clipboard.writeText(text).then(done).catch(done);
  }else{
    const ta=document.createElement('textarea');
    ta.value=text;ta.style.position='fixed';ta.style.opacity='0';
    document.body.appendChild(ta);ta.select();
    try{document.execCommand('copy');}catch(e){}
    document.body.removeChild(ta);
    done();
  }
}

