function reArea(){ return document.getElementById('reDetailArea'); }

function reEsc(str){
  return String(str==null?'':str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function reEscAttr(str){
  return String(str==null?'':str).replace(/'/g,'&#39;').replace(/"/g,'&quot;');
}

function reSelect(key){
  reActiveKey=key;
  document.querySelectorAll('#re .tls-tile').forEach(function(t){t.classList.remove('active');});
  const tile=document.getElementById('reTile_'+key);
  if(tile) tile.classList.add('active');
  const menu=RE_MENU.find(function(m){return m.key===key;});
  if(!menu) return;
  reRenderForm(menu);
  if(typeof showPage==='function') showPage('reDetail');
}

function reRenderForm(menu){
  const area=reArea();
  const iconCls=menu.icon.indexOf('fa-')===0?('fa-solid '+menu.icon):menu.icon;
  const titleEl=document.getElementById('reDetailTitle');
  const subEl=document.getElementById('reDetailSubtitle');
  const iconEl=document.getElementById('reDetailIcon');
  if(titleEl) titleEl.textContent=menu.label;
  if(subEl) subEl.textContent=menu.desc;
  if(iconEl) iconEl.className=iconCls;
  const fieldsHtml=menu.fields.map(function(f,i){
    let ctrl;
    if(f.options&&f.options.length){
      const defVal=(f.def!=null&&f.options.indexOf(f.def)!==-1)?f.def:f.options[0];
      const btns=f.options.map(function(opt){
        const active=(opt===defVal)?' active':'';
        return '<button type="button" class="tls-optbtn'+active+'" data-val="'+reEscAttr(opt)+'" onclick="reSelectOption('+i+',this)">'+reEsc(opt)+'</button>';
      }).join('');
      ctrl='<div class="tls-optrow" id="reOptRow_'+i+'">'+btns+'</div>'+
        '<input type="hidden" id="reField_'+i+'" value="'+reEscAttr(defVal)+'">';
    }else if(f.type==='textarea'){
      ctrl='<textarea class="tls-input" id="reField_'+i+'" rows="4" style="resize:vertical;font-family:\'Space Mono\',monospace" placeholder="'+reEscAttr(f.placeholder||'')+'">'+reEsc(f.def||'')+'</textarea>';
    }else{
      ctrl='<input class="tls-input" id="reField_'+i+'" type="text" placeholder="'+reEscAttr(f.placeholder||'')+'" value="'+reEscAttr(f.def||'')+'">';
    }
    return '<div class="tls-field">'+
      '<label>'+reEsc(f.label)+'</label>'+
      ctrl+
    '</div>';
  }).join('');
  area.innerHTML=
    '<div class="tls-formcard">'+
      fieldsHtml+
      '<button class="tls-submitbtn" id="reSubmitBtn" onclick="reSubmit()"><i class="fa-solid fa-paper-plane"></i> KIRIM</button>'+
    '</div>'+
    '<div class="tls-result" id="reResult"></div>';
}

function reSelectOption(idx,btnEl){
  const row=document.getElementById('reOptRow_'+idx);
  const hidden=document.getElementById('reField_'+idx);
  if(row) row.querySelectorAll('.tls-optbtn').forEach(function(b){b.classList.remove('active');});
  if(btnEl) btnEl.classList.add('active');
  if(hidden) hidden.value=btnEl?btnEl.getAttribute('data-val'):'';
}

function reShake(el){
  if(!el) return;
  el.classList.remove('tls-shake');
  void el.offsetWidth;
  el.classList.add('tls-shake');
  el.focus();
}

async function reSubmit(){
  const menu=RE_MENU.find(function(m){return m.key===reActiveKey;});
  if(!menu) return;
  const params=[];
  let missingRequired=false;
  menu.fields.forEach(function(f,i){
    const inp=document.getElementById('reField_'+i);
    const val=inp?inp.value.trim():'';
    if(f.required && !val){ reShake(inp); missingRequired=true; return; }
    if(val) params.push(encodeURIComponent(f.name)+'='+encodeURIComponent(val));
  });
  if(missingRequired) return;
  if(!cidPreCheckDiamond(RE_COST,'reSubmitBtn')) return;

  const btn=document.getElementById('reSubmitBtn');
  const result=document.getElementById('reResult');
  if(btn){ btn.disabled=true; btn.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> MENGIRIM...'; }
  if(result){ result.classList.remove('show'); result.innerHTML=''; }

  const queryBase=params.join('&');
  try{
    const json=await xyureiRequest(function(key){
      return RE_BASE+menu.key+'?'+queryBase+'&apikey='+key;
    });
    cidDeductDiamond(RE_COST,menu.label,'RE: '+menu.label);
    tlsRenderResult(result,json);
  }catch(e){
    console.error('[RE]['+menu.key+']',e,(e&&e.debugDetail)||'');
    const detail=(e&&e.debugDetail)?' ('+e.debugDetail+')':'';
    if(result){
      result.innerHTML='<div class="tls-result-error"><i class="fa-solid fa-triangle-exclamation"></i>Gagal memproses permintaan.'+reEsc(detail)+'</div>';
      result.classList.add('show');
    }
  }
  if(btn){ btn.disabled=false; btn.innerHTML='<i class="fa-solid fa-paper-plane"></i> KIRIM'; }
}

