let ptActiveKey=null;
let ptGridBuilt=false;

function ptBuildGrid(){
  const grid=document.getElementById('ptGrid');
  if(!grid||ptGridBuilt) return;
  grid.innerHTML=PT_MENU.map(function(m){
    const iconCls=m.icon.indexOf('fa-')===0?('fa-solid '+m.icon):m.icon;
    return '<div class="tls-tile" id="ptTile_'+m.key+'" onclick="ptSelect(\''+m.key+'\')">'+
      '<div class="tls-tile-icon"><i class="'+iconCls+'"></i></div><span>'+m.label+'</span></div>';
  }).join('');
  ptGridBuilt=true;
}
document.addEventListener('DOMContentLoaded',ptBuildGrid);

function ptArea(){ return document.getElementById('ptDetailArea'); }

function ptEsc(str){
  return String(str==null?'':str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function ptEscAttr(str){
  return String(str==null?'':str).replace(/'/g,'&#39;').replace(/"/g,'&quot;');
}

function ptSelect(key){
  ptActiveKey=key;
  document.querySelectorAll('#pterodactyl .tls-tile').forEach(function(t){t.classList.remove('active');});
  const tile=document.getElementById('ptTile_'+key);
  if(tile) tile.classList.add('active');
  const menu=PT_MENU.find(function(m){return m.key===key;});
  if(!menu) return;
  ptRenderForm(menu);
  if(typeof showPage==='function') showPage('pterodactylDetail');
}

function ptRenderForm(menu){
  const area=ptArea();
  const iconCls=menu.icon.indexOf('fa-')===0?('fa-solid '+menu.icon):menu.icon;
  const titleEl=document.getElementById('ptDetailTitle');
  const subEl=document.getElementById('ptDetailSubtitle');
  const iconEl=document.getElementById('ptDetailIcon');
  if(titleEl) titleEl.textContent=menu.label;
  if(subEl) subEl.textContent=menu.desc;
  if(iconEl) iconEl.className=iconCls;
  const fieldsHtml=menu.fields.map(function(f,i){
    let ctrl;
    if(f.options&&f.options.length){
      const defVal=(f.def!=null&&f.options.indexOf(f.def)!==-1)?f.def:f.options[0];
      const btns=f.options.map(function(opt){
        const active=(opt===defVal)?' active':'';
        return '<button type="button" class="tls-optbtn'+active+'" data-val="'+ptEscAttr(opt)+'" onclick="ptSelectOption('+i+',this)">'+ptEsc(opt)+'</button>';
      }).join('');
      ctrl='<div class="tls-optrow" id="ptOptRow_'+i+'">'+btns+'</div>'+
        '<input type="hidden" id="ptField_'+i+'" value="'+ptEscAttr(defVal)+'">';
    }else if(f.type==='textarea'){
      ctrl='<textarea class="tls-input" id="ptField_'+i+'" rows="4" style="resize:vertical;font-family:\'Space Mono\',monospace" placeholder="'+ptEscAttr(f.placeholder||'')+'">'+ptEsc(f.def||'')+'</textarea>';
    }else{
      ctrl='<input class="tls-input" id="ptField_'+i+'" type="text" placeholder="'+ptEscAttr(f.placeholder||'')+'" value="'+ptEscAttr(f.def||'')+'">';
    }
    return '<div class="tls-field">'+
      '<label>'+ptEsc(f.label)+'</label>'+
      ctrl+
    '</div>';
  }).join('');
  area.innerHTML=
    '<div class="tls-formcard">'+
      fieldsHtml+
      '<button class="tls-submitbtn" id="ptSubmitBtn" onclick="ptSubmit()"><i class="fa-solid fa-paper-plane"></i> KIRIM</button>'+
    '</div>'+
    '<div class="tls-result" id="ptResult"></div>';
}

function ptSelectOption(idx,btnEl){
  const row=document.getElementById('ptOptRow_'+idx);
  const hidden=document.getElementById('ptField_'+idx);
  if(row) row.querySelectorAll('.tls-optbtn').forEach(function(b){b.classList.remove('active');});
  if(btnEl) btnEl.classList.add('active');
  if(hidden) hidden.value=btnEl?btnEl.getAttribute('data-val'):'';
}

function ptShake(el){
  if(!el) return;
  el.classList.remove('tls-shake');
  void el.offsetWidth;
  el.classList.add('tls-shake');
  el.focus();
}

async function ptSubmit(){
  const menu=PT_MENU.find(function(m){return m.key===ptActiveKey;});
  if(!menu) return;
  const params=[];
  let missingRequired=false;
  menu.fields.forEach(function(f,i){
    const inp=document.getElementById('ptField_'+i);
    const val=inp?inp.value.trim():'';
    if(f.required && !val){ ptShake(inp); missingRequired=true; return; }
    if(val) params.push(encodeURIComponent(f.name)+'='+encodeURIComponent(val));
  });
  if(missingRequired) return;

  const btn=document.getElementById('ptSubmitBtn');
  const result=document.getElementById('ptResult');
  if(btn){ btn.disabled=true; btn.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> MENGIRIM...'; }
  if(result){ result.classList.remove('show'); result.innerHTML=''; }

  const queryBase=params.join('&');
  try{
    const json=await xyureiRequest(function(key){
      return PT_BASE+menu.key+'?'+queryBase+'&apikey='+key;
    });
    tlsRenderResult(result,json);
  }catch(e){
    console.error('[PT]['+menu.key+']',e,(e&&e.debugDetail)||'');
    const detail=(e&&e.debugDetail)?' ('+e.debugDetail+')':'';
    if(result){
      result.innerHTML='<div class="tls-result-error"><i class="fa-solid fa-triangle-exclamation"></i>Gagal memproses permintaan.'+ptEsc(detail)+'</div>';
      result.classList.add('show');
    }
  }
  if(btn){ btn.disabled=false; btn.innerHTML='<i class="fa-solid fa-paper-plane"></i> KIRIM'; }
}

