let srhActiveKey=null;
let srhGridBuilt=false;
const srhCache={};

/* Biaya diamond: semua menu di halaman Search (Apple Music, Bing, Google, Pinterest,
   dst — seluruh SRH_MENU) = 25 Diamond per pencarian. Saldo dicek dulu sebelum request
   jalan (cidPreCheckDiamond); dipotong (cidDeductDiamond) begitu API mengembalikan
   respons yang bukan error, sebelum hasil dirender ke berbagai jenis tampilan menu. */
const SRH_COST=25;

// Nama parameter query beda-beda tiap endpoint di /api/search/ (bukan selalu "text").
// SRH_PARAM_OVERRIDE = nama yang sudah dipastikan benar. Sisanya di-deteksi otomatis
// dari pesan error API ("Parameter 'xxx' diperlukan") lalu disimpan di srhParamCache
// supaya pencarian berikutnya di menu yang sama langsung pakai nama yang benar.
const SRH_PARAM_OVERRIDE={cuaca:'q',dafont:'q',kodepos:'q',bing:'q',applemusic:'q',countryinfo:'q',danbooru:'q',github:'q',google:'q',lyrics:'q',mangatoon:'q',mcpedl:'q',npm:'q',pinterest:'query',pixiv:'q',group:'query',wallcraft:'query',subdomain:'url',spotify:'q',resepkoki:'q',prompt:'q',play:'q',yts:'q'};
const srhParamCache={};

function srhParamNameFor(key){
  return srhParamCache[key]||SRH_PARAM_OVERRIDE[key]||'text';
}

// Cocokkan pesan error semacam: "Parameter 'kota' diperlukan" / 'Parameter "q" wajib diisi' dst.
function srhExtractParamName(detail){
  if(!detail) return null;
  const m=String(detail).match(/parameter\s*[:\-]?\s*['"]?([a-zA-Z_]+)['"]?\s*(?:diperlukan|wajib|required|missing)/i);
  return m?m[1]:null;
}

function srhBuildGrid(){
  const grid=document.getElementById('srhGrid');
  if(!grid||srhGridBuilt) return;
  grid.innerHTML=SRH_MENU.map(function(m){
    const flag=m.status==='maintenance'
      ? '<span class="srh-tile-flag maint">MAINT</span>'
      : (m.premium?'<span class="srh-tile-flag premium">VIP</span>':'');
    return '<div class="srh-tile'+(m.status==='maintenance'?' srh-maint':'')+'" id="srhTile_'+m.key+'" onclick="srhSelect(\''+m.key+'\')">'+
      flag+
      '<div class="srh-tile-cost"><img src="zusmo-asset/onzrii.png" alt="diamond"/>'+SRH_COST+'</div>'+
      '<div class="srh-tile-icon"><i class="fa-solid '+m.icon+'"></i></div><span>'+m.label+'</span></div>';
  }).join('');
  srhGridBuilt=true;
}
document.addEventListener('DOMContentLoaded',srhBuildGrid);

function srhArea(){ return document.getElementById('srhArea'); }

function srhEsc(str){
  return String(str==null?'':str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function srhEscAttr(str){
  return String(str==null?'':str).replace(/'/g,'&#39;').replace(/"/g,'&quot;');
}

/* ================= RECOVERY GAMBAR SEARCH GAGAL MUAT (multi-proxy) =================
   Sebelumnya thumbnail di halaman Search cuma punya 1 fallback (images.weserv.nl).
   Kalau proxy itu down/lambat/diblokir jaringan tertentu, gambar gagal total tanpa
   jalan lain. Sekarang kalau src asli gagal, dicoba fetch()+blob lewat 3 proxy
   berantai (wsrv.nl -> allorigins -> corsproxy) - sama seperti pola yang sudah
   terbukti jalan di fitur Stalk Pinterest - baru kalau semuanya gagal, tampilkan
   ikon placeholder. */
async function srhImgFallbackBlob(url){
  if(!url) return null;
  const bare=url.replace(/^https?:\/\//,'');
  try{
    const res=await zsFetchTimeout('https://wsrv.nl/?url='+encodeURIComponent(bare),{},12000);
    if(res&&res.ok){ const b=await res.blob(); if(b&&b.size) return b; }
  }catch(e){}
  try{
    const res=await zsFetchTimeout('https://api.allorigins.win/raw?url='+encodeURIComponent(url),{},12000);
    if(res&&res.ok){ const b=await res.blob(); if(b&&b.size) return b; }
  }catch(e){}
  try{
    const res=await zsFetchTimeout('https://corsproxy.io/?url='+encodeURIComponent(url),{},12000);
    if(res&&res.ok){ const b=await res.blob(); if(b&&b.size) return b; }
  }catch(e){}
  return null;
}
function srhImgOnError(imgEl,iconClass){
  if(!imgEl||imgEl.dataset.srhTried) return;
  imgEl.dataset.srhTried='1';
  const url=imgEl.src;
  const cls=imgEl.className;
  imgEl.classList.add('srh-thumb-loading');
  srhImgFallbackBlob(url).then(function(blob){
    if(!imgEl.isConnected) return;
    if(blob){
      imgEl.src=URL.createObjectURL(blob);
      imgEl.classList.remove('srh-thumb-loading');
    }else{
      const ph=document.createElement('div');
      ph.className=cls.replace('srh-thumb-loading','').trim()+' srh-thumbph';
      ph.innerHTML='<i class="fa-solid '+(iconClass||'fa-image')+'"></i>';
      imgEl.replaceWith(ph);
    }
  });
}

function srhFetchJson(endpoint,extraParams){
  return xyureiRequest(function(key){
    let url=SRH_BASE+endpoint+'?apikey='+encodeURIComponent(key);
    if(extraParams) url+='&'+extraParams;
    return url;
  });
}

function srhIsPremiumUnlocked(){
  const role=(localStorage.getItem('role')||'FREE').toUpperCase();
  return role!=='FREE'&&role!=='';
}

function srhSelect(key){
  const menu=SRH_MENU.find(function(m){return m.key===key;});
  if(!menu) return;
  if(menu.status==='maintenance'){
    if(typeof showToast==='function') showToast('Menu ini sedang dalam perbaikan.');
    return;
  }
  if(menu.premium&&!srhIsPremiumUnlocked()){
    const area=srhArea();
    srhSetDetailHeader(menu);
    area.innerHTML='<div class="srh-fetcherror"><i class="fa-solid fa-crown"></i> Fitur ini khusus member PREMIUM. Upgrade role kamu dulu untuk memakainya.</div>';
    document.querySelectorAll('#search .srh-tile').forEach(function(t){t.classList.remove('active');});
    if(typeof showPage==='function') showPage('searchDetail');
    return;
  }
  srhActiveKey=key;
  document.querySelectorAll('#search .srh-tile').forEach(function(t){t.classList.remove('active');});
  const tile=document.getElementById('srhTile_'+key);
  if(tile) tile.classList.add('active');
  srhRenderForm(menu);
  if(typeof showPage==='function') showPage('searchDetail');
}

function srhSetDetailHeader(menu){
  const titleEl=document.getElementById('searchDetailTitle');
  const subEl=document.getElementById('searchDetailSubtitle');
  const iconEl=document.getElementById('searchDetailIcon');
  if(titleEl) titleEl.textContent=menu.label;
  if(subEl) subEl.textContent=menu.placeholder||'';
  if(iconEl) iconEl.className='fa-solid '+(menu.icon||'fa-magnifying-glass');
}

function srhRenderForm(menu){
  const area=srhArea();
  srhSetDetailHeader(menu);
  const extraHtml=(menu.extraParams||[]).map(function(ep,idx){
    return '<div class="srh-searchrow" style="margin-top:8px;">'+
      '<input class="srh-searchinput" id="srhExtraInput_'+idx+'" type="text" placeholder="'+srhEscAttr(ep.placeholder||'')+'" onkeydown="if(event.key===\'Enter\'){event.preventDefault();srhDoSearch();}">'+
    '</div>';
  }).join('');
  area.innerHTML='<div class="srh-formrow">'+
    '<div class="srh-searchrow">'+
      '<input class="srh-searchinput" id="srhSearchInput" type="text" placeholder="'+srhEscAttr(menu.placeholder||'Kata kunci pencarian...')+'" onkeydown="if(event.key===\'Enter\'){event.preventDefault();srhDoSearch();}">'+
      '<button class="srh-searchbtn" id="srhSearchBtn" onclick="srhDoSearch()"><i class="fa-solid fa-magnifying-glass"></i></button>'+
    '</div>'+
    extraHtml+
  '</div><div id="srhSearchResult"></div>';
  const input=document.getElementById('srhSearchInput');
  if(input) input.focus();
}

function srhDoSearch(){
  const menu=SRH_MENU.find(function(m){return m.key===srhActiveKey;});
  if(!menu) return;
  const input=document.getElementById('srhSearchInput');
  const q=input?input.value.trim():'';
  const result=document.getElementById('srhSearchResult');
  if(!q){ if(result) result.innerHTML='<div class="srh-empty"><i class="fa-solid fa-magnifying-glass"></i>Masukkan kata kunci dulu</div>'; return; }
  if(!cidPreCheckDiamond(SRH_COST,'srhSearchBtn')) return;
  let extra='';
  (menu.extraParams||[]).forEach(function(ep,idx){
    const extraInput=document.getElementById('srhExtraInput_'+idx);
    const extraVal=extraInput?extraInput.value.trim():'';
    if(extraVal) extra+='&'+encodeURIComponent(ep.name)+'='+encodeURIComponent(extraVal);
  });
  if(result) result.innerHTML='<div class="srh-loading"><i class="fa-solid fa-spinner fa-spin"></i> Mencari...</div>';
  if(menu.key==='bing') srhBingActiveTab='images';
  srhRunSearch(menu,q,result,false,extra);
}

// Bing punya struktur khusus: result = {images:[...], videos:[...], web:[...]}
// (bukan array flat seperti provider lain), jadi butuh render bertab.
function srhIsBingShape(obj){
  return obj&&typeof obj==='object'&&!Array.isArray(obj)&&
    (Array.isArray(obj.images)||Array.isArray(obj.videos)||Array.isArray(obj.web));
}

// Kodepos: array flat tapi field-nya desa/kecamatan/kota/provinsi/kodepos,
// tidak cocok dengan pola title/thumb/link generic -> render list alamat sendiri.
function srhIsKodeposItem(it){
  return it&&typeof it==='object'&&('kodepos' in it)&&('desa' in it||'kecamatan' in it);
}

function srhRenderKodeposResult(items){
  const result=document.getElementById('srhSearchResult');
  if(!result) return;
  result.innerHTML='<div class="srh-meta" style="margin-bottom:8px;">'+items.length+' hasil ditemukan</div>'+
    items.map(function(it){
      const lines=[it.kecamatan,it.kota,it.provinsi].filter(Boolean).join(', ');
      return '<div class="srh-item">'+
        '<div class="srh-thumbph"><i class="fa-solid fa-location-dot"></i></div>'+
        '<div class="srh-body">'+
          '<div class="srh-name">'+srhEsc(it.desa||'-')+' <span style="opacity:.7;font-weight:600;">&middot; '+srhEsc(it.kodepos||'-')+'</span></div>'+
          (lines?'<div class="srh-meta">'+srhEsc(lines)+'</div>':'')+
        '</div>'+
      '</div>';
    }).join('');
}

// Info Negara: object nested result.data dengan field detail (bendera, koordinat,
// tetangga, dsb), bukan array flat -> render kartu profil negara sendiri.
function srhIsCountryInfoShape(obj){
  return obj&&typeof obj==='object'&&!Array.isArray(obj)&&
    typeof obj.name==='string'&&(('capital' in obj)||('isoCode' in obj)||('continent' in obj));
}

function srhRenderCountryInfoResult(d){
  const result=document.getElementById('srhSearchResult');
  if(!result) return;
  const rows=[
    ['Ibu kota',d.capital],
    ['Benua',d.continent&&(d.continent.emoji?d.continent.emoji+' ':'')+d.continent.name],
    ['Mata uang',d.currency],
    ['Kode telepon',d.phoneCode],
    ['Domain internet',d.internetTLD],
    ['Bentuk negara',d.constitutionalForm],
    ['Bahasa',d.languages&&d.languages.native&&d.languages.native.join(', ')],
    ['Sisi berkendara',d.drivingSide],
    ['Terkurung daratan',d.landlocked===true?'Ya':(d.landlocked===false?'Tidak':undefined)],
    ['Luas wilayah',d.area&&(d.area.squareKilometers?d.area.squareKilometers.toLocaleString('id-ID')+' km&sup2;':undefined)],
    ['Kode ISO',d.isoCode&&[d.isoCode.alpha2,d.isoCode.alpha3].filter(Boolean).join(' / ').toUpperCase()],
    ['Terkenal dengan',d.famousFor]
  ].filter(function(r){return r[1];});
  const rowsHtml=rows.map(function(r){
    return '<div style="display:flex;justify-content:space-between;gap:12px;padding:8px 0;border-bottom:1px solid var(--srh-hair);font-size:12.5px;">'+
      '<span style="color:var(--srh-dim);">'+srhEsc(r[0])+'</span><span style="text-align:right;font-weight:600;">'+r[1]+'</span>'+
    '</div>';
  }).join('');
  const neighbors=Array.isArray(d.neighbors)&&d.neighbors.length?
    '<div class="srh-meta" style="margin:12px 0 6px;">Negara tetangga</div>'+
    '<div style="display:flex;gap:8px;flex-wrap:wrap;">'+
      d.neighbors.map(function(n){
        return '<div style="display:flex;align-items:center;gap:6px;background:var(--srh-surface2);border:1px solid var(--srh-hair-strong);border-radius:20px;padding:5px 12px 5px 5px;font-size:12px;">'+
          (n.flag?'<img src="'+srhEsc(n.flag)+'" referrerpolicy="no-referrer" loading="lazy" style="width:22px;height:22px;border-radius:50%;object-fit:cover;" onerror="srhImgOnError(this,\'fa-flag\')">':'')+
          srhEsc(n.name)+
        '</div>';
      }).join('')+
    '</div>':'';
  result.innerHTML=
    '<div class="srh-item" style="align-items:center;">'+
      (d.flag?'<img class="srh-thumb" src="'+srhEsc(d.flag)+'" referrerpolicy="no-referrer" loading="lazy" style="object-fit:contain;background:var(--srh-surface2);" onerror="srhImgOnError(this,\'fa-earth-asia\')">':'<div class="srh-thumbph"><i class="fa-solid fa-earth-asia"></i></div>')+
      '<div class="srh-body">'+
        '<div class="srh-name" style="font-size:16px;">'+srhEsc(d.name)+'</div>'+
        (d.googleMapsLink?'<div class="srh-actions"><a class="srh-actbtn" href="'+srhEscAttr(d.googleMapsLink)+'" target="_blank" rel="noopener"><i class="fa-solid fa-map-location-dot"></i> Lihat di Maps</a></div>':'')+
      '</div>'+
    '</div>'+
    '<div style="margin-top:6px;">'+rowsHtml+'</div>'+
    neighbors;
}

// Cuaca: format OpenWeatherMap (main/weather/wind/sys), object tunggal bukan array
// -> render kartu cuaca sendiri, bukan list item generic.
function srhIsWeatherShape(obj){
  return obj&&typeof obj==='object'&&!Array.isArray(obj)&&
    obj.main&&typeof obj.main==='object'&&Array.isArray(obj.weather);
}

// Dafont: field "name" sebenarnya nama author/studio (bukan nama font), nama font
// asli ada di query (root respons, sama untuk semua item) dan "preview" sering
// kosong -> render sendiri biar labelnya benar, bukan disangka title generic.
function srhIsDafontItem(it){
  return it&&typeof it==='object'&&('download' in it)&&('downloads' in it)&&('name' in it);
}

function srhRenderDafontResult(items,query){
  const result=document.getElementById('srhSearchResult');
  if(!result) return;
  result.innerHTML=items.map(function(it){
    const preview=it.preview||'';
    return '<div class="srh-item">'+
      (preview?'<img class="srh-thumb" src="'+srhEsc(preview)+'" referrerpolicy="no-referrer" loading="lazy" onerror="srhImgOnError(this,\'fa-font\')">':'<div class="srh-thumbph"><i class="fa-solid fa-font"></i></div>')+
      '<div class="srh-body">'+
        '<div class="srh-name">'+srhEsc(query||'Font')+'</div>'+
        '<div class="srh-meta">oleh '+srhEsc(it.name||'-')+(it.downloads?' &middot; '+srhEsc(it.downloads):'')+'</div>'+
        (it.download?'<div class="srh-actions"><a class="srh-actbtn" href="'+srhEscAttr(it.download)+'" target="_blank" rel="noopener"><i class="fa-solid fa-download"></i> Unduh</a></div>':'')+
      '</div>'+
    '</div>';
  }).join('');
}

// GitHub: field-nya full_name/stars/forks/watchers/url, bukan title/thumb generic
// -> render kartu repo sendiri dengan statistik dan link clone.
function srhIsGithubItem(it){
  return it&&typeof it==='object'&&('full_name' in it)&&('clone_url' in it);
}

function srhRenderGithubResult(items){
  const result=document.getElementById('srhSearchResult');
  if(!result) return;
  result.innerHTML=items.map(function(it){
    const stats=[
      it.stars!=null?'<i class="fa-solid fa-star"></i> '+it.stars:'',
      it.forks!=null?'<i class="fa-solid fa-code-branch"></i> '+it.forks:'',
      it.watchers!=null?'<i class="fa-solid fa-eye"></i> '+it.watchers:'',
      it.open_issues!=null?'<i class="fa-solid fa-circle-exclamation"></i> '+it.open_issues:''
    ].filter(Boolean).join(' &nbsp; ');
    return '<div class="srh-item">'+
      '<div class="srh-thumbph"><i class="fa-brands fa-github"></i></div>'+
      '<div class="srh-body">'+
        '<div class="srh-name">'+srhEsc(it.full_name||'-')+(it.is_fork?' <span style="opacity:.6;font-weight:500;font-size:11px;">(fork)</span>':'')+'</div>'+
        (it.description?'<div class="srh-meta">'+srhEsc(it.description)+'</div>':'')+
        (stats?'<div class="srh-meta" style="margin-top:4px;">'+stats+'</div>':'')+
        (it.updated_at?'<div class="srh-meta" style="opacity:.7;">Update terakhir: '+srhEsc(it.updated_at)+'</div>':'')+
        '<div class="srh-actions">'+
          (it.url?'<a class="srh-actbtn" href="'+srhEscAttr(it.url)+'" target="_blank" rel="noopener"><i class="fa-solid fa-arrow-up-right-from-square"></i> Buka</a>':'')+
          (it.clone_url?'<a class="srh-actbtn" href="'+srhEscAttr(it.clone_url)+'" target="_blank" rel="noopener"><i class="fa-solid fa-code"></i> Clone</a>':'')+
        '</div>'+
      '</div>'+
    '</div>';
  }).join('');
}

// Google (news): field-nya diberi nama generik/diobfuskasi (resource_title,
// origin_node, resolved_endpoint, temporal_stamp) padahal isinya hasil berita
// Google News -> render list berita dengan label yang benar.
function srhIsGoogleNewsItem(it){
  return it&&typeof it==='object'&&('resource_title' in it)&&('resolved_endpoint' in it);
}

function srhGoogleFmtDate(str){
  if(!str) return '';
  const d=new Date(str);
  if(isNaN(d.getTime())) return str;
  return d.toLocaleString('id-ID',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});
}

function srhRenderGoogleNewsResult(items){
  const result=document.getElementById('srhSearchResult');
  if(!result) return;
  result.innerHTML='<div class="srh-meta" style="margin-bottom:8px;">'+items.length+' berita ditemukan</div>'+
    items.map(function(it){
      return '<div class="srh-item">'+
        '<div class="srh-thumbph"><i class="fa-solid fa-newspaper"></i></div>'+
        '<div class="srh-body">'+
          '<div class="srh-name">'+srhEsc(it.resource_title||'-')+'</div>'+
          '<div class="srh-meta">'+srhEsc(it.origin_node||'-')+(it.temporal_stamp?' &middot; '+srhEsc(srhGoogleFmtDate(it.temporal_stamp)):'')+'</div>'+
          (it.resolved_endpoint?'<div class="srh-actions"><a class="srh-actbtn" href="'+srhEscAttr(it.resolved_endpoint)+'" target="_blank" rel="noopener"><i class="fa-solid fa-arrow-up-right-from-square"></i> Baca</a></div>':'')+
        '</div>'+
      '</div>';
    }).join('');
}

// Lyrics: field-nya trackName/artistName/albumName/plainLyrics/syncedLyrics.
// Lirik ditampilkan tersembunyi di belakang tombol "Lihat Lirik" per item,
// bukan langsung terbuka semua saat render list hasil pencarian.
function srhIsLyricsItem(it){
  return it&&typeof it==='object'&&('trackName' in it)&&(('plainLyrics' in it)||('syncedLyrics' in it));
}

function srhLyricsFmtDuration(sec){
  if(sec==null) return '';
  const s=Math.round(sec);
  const m=Math.floor(s/60);
  const r=String(s%60).padStart(2,'0');
  return m+':'+r;
}

function srhLyricsToggle(btn,idx){
  const box=document.getElementById('srhLyricsBox_'+idx);
  if(!box) return;
  const open=box.style.display!=='none';
  box.style.display=open?'none':'block';
  btn.innerHTML=open?'<i class="fa-solid fa-align-left"></i> Lihat Lirik':'<i class="fa-solid fa-chevron-up"></i> Sembunyikan';
}

function srhRenderLyricsResult(items){
  const result=document.getElementById('srhSearchResult');
  if(!result) return;
  srhCache.lyrics=items;
  result.innerHTML=items.map(function(it,idx){
    const meta=[it.artistName,it.albumName].filter(Boolean).join(' &middot; ');
    const lyricsText=it.plainLyrics||(typeof it.syncedLyrics==='string'?it.syncedLyrics.replace(/\[\d{2}:\d{2}(?:\.\d+)?\]\s*/g,''):'');
    return '<div class="srh-item">'+
      '<div class="srh-thumbph"><i class="fa-solid fa-music"></i></div>'+
      '<div class="srh-body">'+
        '<div class="srh-name">'+srhEsc(it.trackName||it.name||'-')+'</div>'+
        (meta?'<div class="srh-meta">'+srhEsc(meta)+(it.duration?' &middot; '+srhLyricsFmtDuration(it.duration):'')+'</div>':'')+
        (it.instrumental?'<div class="srh-meta" style="opacity:.7;">Instrumental (tanpa lirik)</div>':
          (lyricsText?'<div class="srh-actions"><button class="srh-actbtn" onclick="srhLyricsToggle(this,'+idx+')" style="border:none;cursor:pointer;font:inherit;"><i class="fa-solid fa-align-left"></i> Lihat Lirik</button></div>'+
          '<div class="srh-raw" id="srhLyricsBox_'+idx+'" style="display:none;margin-top:8px;">'+srhEsc(lyricsText)+'</div>':'')
        )+
      '</div>'+
    '</div>';
  }).join('');
}

// Mangatoon: hasil terbagi per kategori (komik/novel), masing-masing berisi
// array beranggotakan satu object {items, resultCount} -> perlu render bertab.
// Link dari API sering dobel domain ("mangatoon.mobihttps://mangatoon.mobi/..")
// jadi perlu dibersihkan dulu sebelum dipakai.
function srhIsMangatoonShape(obj){
  return obj&&typeof obj==='object'&&!Array.isArray(obj)&&
    (Array.isArray(obj.komik)||Array.isArray(obj.novel));
}

function srhMangatoonFixLink(link){
  if(!link) return '';
  const m=link.match(/(https?:\/\/.*)$/);
  return m?m[1]:link;
}

let srhMangatoonActiveTab='komik';
function srhMangatoonTabLabel(t){ return t==='komik'?'Komik':'Novel'; }

function srhRenderMangatoonResult(data){
  const result=document.getElementById('srhSearchResult');
  if(!result) return;
  const tabs=['komik','novel'].filter(function(t){
    return Array.isArray(data[t])&&data[t][0]&&Array.isArray(data[t][0].items)&&data[t][0].items.length;
  });
  if(!tabs.length){
    result.innerHTML='<div class="srh-fetcherror"><i class="fa-solid fa-triangle-exclamation"></i> Tidak ada hasil ditemukan.</div>';
    return;
  }
  if(tabs.indexOf(srhMangatoonActiveTab)===-1) srhMangatoonActiveTab=tabs[0];
  const tabsHtml='<div class="srh-formrow" style="display:flex;gap:8px;margin-bottom:10px;">'+
    tabs.map(function(t){
      return '<button class="srh-searchbtn" style="flex:1;'+(t===srhMangatoonActiveTab?'':'opacity:.55;')+'" onclick="srhMangatoonActiveTab=\''+t+'\';srhRenderMangatoonResult(srhCache.mangatoon);"><i class="fa-solid fa-book-open"></i> '+srhMangatoonTabLabel(t)+'</button>';
    }).join('')+
  '</div>';
  const bucket=data[srhMangatoonActiveTab][0];
  const items=bucket.items||[];
  const bodyHtml='<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:10px;">'+
    items.map(function(it){
      const link=srhMangatoonFixLink(it.link);
      return '<a href="'+srhEscAttr(link)+'" target="_blank" rel="noopener" style="display:block;text-decoration:none;">'+
        (it.image?'<img src="'+srhEsc(it.image)+'" referrerpolicy="no-referrer" loading="lazy" onerror="srhImgOnError(this,\'fa-book-open\')" style="width:100%;aspect-ratio:3/4;object-fit:cover;border-radius:10px;background:var(--srh-surface2);border:1px solid var(--srh-hair-strong);">':'<div class="srh-thumbph" style="width:100%;aspect-ratio:3/4;border-radius:10px;"><i class="fa-solid fa-book-open"></i></div>')+
        '<div style="font-size:11.5px;color:var(--srh-dim);margin-top:4px;line-height:1.4;">'+srhEsc(it.title||'-')+'</div>'+
      '</a>';
    }).join('')+
  '</div>';
  result.innerHTML=(bucket.resultCount?'<div class="srh-meta" style="margin-bottom:8px;">'+srhEsc(bucket.resultCount)+'</div>':'')+tabsHtml+bodyHtml;
}

// NPM Package: field name/version/description/author/links{npm,homepage,repository}.
// "links" itu object nested (generic renderer cuma baca it.url/it.link string),
// dan description sering berisi markdown badge mentah -> perlu dibersihkan & render sendiri.
function srhIsNpmItem(it){
  return it&&typeof it==='object'&&('version' in it)&&it.links&&typeof it.links==='object';
}

function srhNpmCleanDesc(desc){
  if(!desc) return '';
  // Buang badge markdown ![alt](url) dan link [text](url) mentah yang sering
  // dipakai sebagai "description" oleh sebagian package (contoh: badge NPM/CI).
  const cleaned=desc.replace(/!?\[([^\]]*)\]\([^)]*\)/g,'').trim();
  return cleaned||desc;
}

function srhRenderNpmResult(items){
  const result=document.getElementById('srhSearchResult');
  if(!result) return;
  result.innerHTML=items.map(function(it){
    const desc=srhNpmCleanDesc(it.description);
    const keywords=(Array.isArray(it.keywords)&&it.keywords.length)?it.keywords.slice(0,6).join(', '):'';
    const links=it.links||{};
    return '<div class="srh-item">'+
      '<div class="srh-thumbph"><i class="fa-brands fa-npm" style="color:#cb3837;"></i></div>'+
      '<div class="srh-body">'+
        '<div class="srh-name">'+srhEsc(it.name||'-')+' <span style="opacity:.6;font-weight:600;font-size:12px;">v'+srhEsc(it.version||'-')+'</span></div>'+
        (desc?'<div class="srh-meta">'+srhEsc(desc)+'</div>':'')+
        (keywords?'<div class="srh-meta" style="opacity:.7;">'+srhEsc(keywords)+'</div>':'')+
        (it.author&&it.author!=='N/A'?'<div class="srh-meta" style="opacity:.7;">oleh '+srhEsc(it.author)+'</div>':'')+
        '<div class="srh-actions">'+
          (links.npm?'<a class="srh-actbtn" href="'+srhEscAttr(links.npm)+'" target="_blank" rel="noopener"><i class="fa-brands fa-npm"></i> NPM</a>':'')+
          (links.homepage?'<a class="srh-actbtn" href="'+srhEscAttr(links.homepage)+'" target="_blank" rel="noopener"><i class="fa-solid fa-house"></i> Homepage</a>':'')+
        '</div>'+
      '</div>'+
    '</div>';
  }).join('');
}

function srhWeatherIconUrl(icon){
  return icon?'https://openweathermap.org/img/wn/'+encodeURIComponent(icon)+'@2x.png':'';
}

// Pinterest: konten visual (pin gambar), field title/image/source/username/board
// tidak cocok list item generic (link ada di "source", bukan url/link) -> render
// grid gambar dengan caption, mirip pola Bing images / Mangatoon.
function srhIsPinterestItem(it){
  return it&&typeof it==='object'&&('board' in it)&&('username' in it)&&('image' in it);
}

function srhRenderPinterestResult(items){
  const result=document.getElementById('srhSearchResult');
  if(!result) return;
  result.innerHTML='<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:10px;">'+
    items.map(function(it){
      const link=it.source||'';
      return '<a href="'+srhEscAttr(link)+'" target="_blank" rel="noopener" style="display:block;text-decoration:none;">'+
        (it.image?'<img src="'+srhEsc(it.image)+'" referrerpolicy="no-referrer" loading="lazy" onerror="srhImgOnError(this,\'fa-thumbtack\')" style="width:100%;aspect-ratio:3/4;object-fit:cover;border-radius:10px;background:var(--srh-surface2);border:1px solid var(--srh-hair-strong);">':'<div class="srh-thumbph" style="width:100%;aspect-ratio:3/4;border-radius:10px;"><i class="fa-solid fa-thumbtack"></i></div>')+
        '<div style="font-size:11px;color:var(--srh-dim);margin-top:4px;line-height:1.4;">'+srhEsc((it.title||'').slice(0,70))+'</div>'+
        (it.username?'<div style="font-size:10.5px;color:var(--srh-faint);margin-top:2px;">@'+srhEsc(it.username)+(it.board?' &middot; '+srhEsc(it.board):'')+'</div>':'')+
      '</a>';
    }).join('')+
  '</div>';
}

function srhIsPixivItem(it){
  return it&&typeof it==='object'&&Array.isArray(it.urls)&&it.urls.length>0&&('title' in it||'author' in it);
}

function srhRenderPixivResult(items){
  const result=document.getElementById('srhSearchResult');
  if(!result) return;
  srhPxvItems=items;
  result.innerHTML='<div class="srh-pxv-grid">'+
    items.map(function(it,idx){
      const thumb=(it.urls&&it.urls[0])||'';
      const pages=it.pageCount||(it.urls?it.urls.length:1);
      return '<div class="srh-pxv-card" onclick="srhPxvOpen('+idx+')">'+
        (thumb?'<img class="srh-pxv-thumb" src="'+srhEsc(thumb)+'" referrerpolicy="no-referrer" loading="lazy" onerror="srhImgOnError(this,\'fa-palette\')">':'<div class="srh-pxv-thumb srh-thumbph"><i class="fa-solid fa-palette"></i></div>')+
        (pages>1?'<div class="srh-pxv-pages"><i class="fa-solid fa-images"></i> '+pages+'</div>':'')+
        '<div class="srh-pxv-body">'+
          '<div class="srh-pxv-title">'+srhEsc(it.title||'Untitled')+'</div>'+
          (it.author?'<div class="srh-pxv-author"><i class="fa-solid fa-user"></i> '+srhEsc(it.author)+'</div>':'')+
        '</div>'+
      '</div>';
    }).join('')+
  '</div>';
}

let srhPxvItems=[];
let srhPxvIdx=0;
let srhPxvPage=0;

function srhPxvItem(){ return srhPxvItems[srhPxvIdx]||{}; }

function srhPxvOpen(idx){
  srhPxvIdx=idx;
  srhPxvPage=0;
  const box=document.getElementById('srhPxvLightbox');
  if(!box) return;
  box.classList.add('show');
  srhPxvRenderStage();
}

function srhPxvClose(){
  const box=document.getElementById('srhPxvLightbox');
  if(box) box.classList.remove('show');
}

function srhPxvRenderStage(){
  const it=srhPxvItem();
  const urls=it.urls||[];
  const titleEl=document.getElementById('srhPxvLbTitle');
  const countEl=document.getElementById('srhPxvLbCount');
  const img=document.getElementById('srhPxvLbImg');
  const prevBtn=document.getElementById('srhPxvLbPrev');
  const nextBtn=document.getElementById('srhPxvLbNext');
  if(titleEl) titleEl.textContent=it.title||'Untitled';
  if(countEl) countEl.textContent=(srhPxvPage+1)+' / '+(urls.length||1);
  if(img) img.src=urls[srhPxvPage]||'';
  if(prevBtn) prevBtn.style.visibility=srhPxvPage>0?'visible':'hidden';
  if(nextBtn) nextBtn.style.visibility=srhPxvPage<urls.length-1?'visible':'hidden';
}

function srhPxvNav(dir){
  const it=srhPxvItem();
  const urls=it.urls||[];
  const next=srhPxvPage+dir;
  if(next<0||next>=urls.length) return;
  srhPxvPage=next;
  srhPxvRenderStage();
}

function srhPxvDownload(){
  const it=srhPxvItem();
  const url=(it.urls||[])[srhPxvPage];
  if(url&&window.aiSaveMediaFallback) window.aiSaveMediaFallback(url);
}

function srhWeatherFmtTime(unixSec,tzOffsetSec){
  if(!unixSec) return '';
  const d=new Date((unixSec+(tzOffsetSec||0))*1000);
  const hh=String(d.getUTCHours()).padStart(2,'0');
  const mm=String(d.getUTCMinutes()).padStart(2,'0');
  return hh+':'+mm;
}

function srhRenderWeatherResult(d){
  const result=document.getElementById('srhSearchResult');
  if(!result) return;
  const w=(d.weather&&d.weather[0])||{};
  const iconUrl=srhWeatherIconUrl(w.icon);
  const place=[d.name,d.sys&&d.sys.country].filter(Boolean).join(', ');
  const rows=[
    ['Terasa seperti',d.main&&(Math.round(d.main.feels_like)+'&deg;C')],
    ['Kelembapan',d.main&&(d.main.humidity+'%')],
    ['Tekanan udara',d.main&&(d.main.pressure+' hPa')],
    ['Angin',d.wind&&(d.wind.speed+' m/s'+(d.wind.deg!=null?', '+d.wind.deg+'&deg;':''))],
    ['Awan',d.clouds&&(d.clouds.all+'%')],
    ['Jarak pandang',d.visibility!=null?(d.visibility/1000)+' km':undefined],
    ['Terbit',srhWeatherFmtTime(d.sys&&d.sys.sunrise,d.timezone)],
    ['Terbenam',srhWeatherFmtTime(d.sys&&d.sys.sunset,d.timezone)]
  ].filter(function(r){return r[1];});
  const rowsHtml=rows.map(function(r){
    return '<div style="display:flex;justify-content:space-between;gap:12px;padding:8px 0;border-bottom:1px solid var(--srh-hair);font-size:12.5px;">'+
      '<span style="color:var(--srh-dim);">'+srhEsc(r[0])+'</span><span style="text-align:right;font-weight:600;">'+r[1]+'</span>'+
    '</div>';
  }).join('');
  result.innerHTML=
    '<div class="srh-item" style="align-items:center;">'+
      (iconUrl?'<img class="srh-thumb" src="'+srhEsc(iconUrl)+'" referrerpolicy="no-referrer" loading="lazy" style="object-fit:contain;background:var(--srh-surface2);" onerror="srhImgOnError(this,\'fa-cloud-sun\')">':'<div class="srh-thumbph"><i class="fa-solid fa-cloud-sun"></i></div>')+
      '<div class="srh-body">'+
        '<div class="srh-name" style="font-size:16px;">'+srhEsc(place||'-')+'</div>'+
        '<div class="srh-meta" style="text-transform:capitalize;">'+srhEsc(w.description||'')+'</div>'+
      '</div>'+
    '</div>'+
    '<div style="display:flex;gap:14px;align-items:baseline;margin:10px 0 4px;">'+
      '<span style="font-size:34px;font-weight:800;">'+(d.main?Math.round(d.main.temp):'-')+'&deg;C</span>'+
      (d.main?'<span style="font-size:12px;color:var(--srh-dim);">min '+Math.round(d.main.temp_min)+'&deg; &middot; maks '+Math.round(d.main.temp_max)+'&deg;</span>':'')+
    '</div>'+
    '<div>'+rowsHtml+'</div>';
}

function srhIsPlayShape(obj){
  return obj&&typeof obj==='object'&&obj.media&&typeof obj.media==='object'&&('url' in obj.media);
}

function srhRenderPlayResult(d){
  const result=document.getElementById('srhSearchResult');
  if(!result) return;
  const media=d.media||{};
  const title=media.title||'Media';
  const url=media.url||'';
  const orig=d.original_query||'';
  result.innerHTML=
    '<div class="srh-play-card">'+
      (url?'<video class="srh-play-media" src="'+srhEscAttr(url)+'" controls playsinline preload="metadata"></video>':'')+
      '<div class="srh-play-body">'+
        '<div class="srh-play-title">'+srhEsc(title)+'</div>'+
        (orig?'<div class="srh-play-sub">'+srhEsc(orig)+'</div>':'')+
        '<div class="srh-play-actions">'+
          (url?'<button class="srh-play-btn primary" onclick="aiSaveMediaFallback(\''+url.replace(/'/g,"\\'")+'\')"><i class="fa-solid fa-download"></i> Download</button>':'')+
          (url?'<a class="srh-play-btn alt" href="'+srhEscAttr(url)+'" target="_blank" rel="noopener"><i class="fa-solid fa-arrow-up-right-from-square"></i> Buka</a>':'')+
        '</div>'+
      '</div>'+
    '</div>';
}

function srhIsPromptShape(obj){
  return obj&&typeof obj==='object'&&Array.isArray(obj.items);
}

let srhPrmItems=[];
let srhPrmIdx=0;

function srhRenderPromptResult(items){
  const result=document.getElementById('srhSearchResult');
  if(!result) return;
  srhPrmItems=items;
  result.innerHTML='<div class="srh-prm-grid">'+
    items.map(function(it,idx){
      const asset=it.asset||{};
      const p=it.prompt||{};
      const thumb=asset.canonicalUrl||asset.url||'';
      const model=[p.modelUsed,p.modelUsedVersion].filter(Boolean).join(' ');
      return '<div class="srh-prm-card" onclick="srhPrmOpen('+idx+')">'+
        (thumb?'<img class="srh-prm-thumb" src="'+srhEsc(thumb)+'" referrerpolicy="no-referrer" loading="lazy" onerror="srhImgOnError(this,\'fa-wand-magic-sparkles\')">':'<div class="srh-prm-thumb srh-thumbph"><i class="fa-solid fa-wand-magic-sparkles"></i></div>')+
        (model?'<div class="srh-prm-badge">'+srhEsc(model)+'</div>':'')+
        (p.isNsfw?'<div class="srh-prm-nsfw">NSFW</div>':'')+
        '<div class="srh-prm-body">'+
          '<div class="srh-prm-title">'+srhEsc(p.title||'Untitled Prompt')+'</div>'+
          '<div class="srh-prm-meta">'+
            (p.favCount!=null?'<span><i class="fa-solid fa-heart"></i> '+p.favCount+'</span>':'')+
            (p.viewCount!=null?'<span><i class="fa-solid fa-eye"></i> '+p.viewCount+'</span>':'')+
          '</div>'+
        '</div>'+
      '</div>';
    }).join('')+
  '</div>';
}

function srhPrmItem(){ return srhPrmItems[srhPrmIdx]||{}; }

function srhPrmOpen(idx){
  srhPrmIdx=idx;
  const box=document.getElementById('srhPrmLightbox');
  if(!box) return;
  const it=srhPrmItem();
  const asset=it.asset||{};
  const p=it.prompt||{};
  const img=document.getElementById('srhPrmLbImg');
  const titleEl=document.getElementById('srhPrmLbTitle');
  const metaEl=document.getElementById('srhPrmLbMeta');
  const promptEl=document.getElementById('srhPrmLbPrompt');
  if(img) img.src=asset.canonicalUrl||asset.url||'';
  if(titleEl) titleEl.textContent=p.title||'Untitled Prompt';
  if(metaEl){
    const chips=[];
    if(p.modelUsed) chips.push(srhEsc(p.modelUsed+(p.modelUsedVersion?' '+p.modelUsedVersion:'')));
    if(p.category) chips.push(srhEsc(p.category));
    if(p.favCount!=null) chips.push('<i class="fa-solid fa-heart"></i> '+p.favCount);
    if(p.viewCount!=null) chips.push('<i class="fa-solid fa-eye"></i> '+p.viewCount);
    metaEl.innerHTML=chips.map(function(c){return '<span class="srh-prm-lb-chip">'+c+'</span>';}).join('');
  }
  if(promptEl) promptEl.textContent=p.prompt||'-';
  box.classList.add('show');
}

function srhPrmClose(){
  const box=document.getElementById('srhPrmLightbox');
  if(box) box.classList.remove('show');
}

function srhPrmCopyPrompt(){
  const it=srhPrmItem();
  const text=(it.prompt&&it.prompt.prompt)||'';
  if(!text) return;
  if(navigator.clipboard&&navigator.clipboard.writeText){
    navigator.clipboard.writeText(text).catch(function(){});
  }
}

function srhPrmDownload(){
  const it=srhPrmItem();
  const url=(it.asset&&(it.asset.canonicalUrl||it.asset.url))||'';
  if(url&&window.aiSaveMediaFallback) window.aiSaveMediaFallback(url);
}

