    const chips=[];
    if(it.waktu_masak) chips.push('<i class="fa-regular fa-clock"></i> '+srhEsc(it.waktu_masak));
    if(it.tingkat_kesulitan) chips.push('<i class="fa-solid fa-gauge"></i> '+srhEsc(it.tingkat_kesulitan));
