function srhIsWallcraftItem(it){
  return it&&typeof it==='object'&&it.urls&&typeof it.urls==='object'&&('original' in it.urls);
}

let srhWlpItems=[];
let srhWlpIdx=0;

function srhWlpFmtNum(n){
  n=Number(n)||0;
  if(n>=1000000) return (n/1000000).toFixed(1).replace(/\.0$/,'')+'jt';
  if(n>=1000) return (n/1000).toFixed(1).replace(/\.0$/,'')+'rb';
  return String(n);
}

function srhRenderWallcraftResult(items){
  const result=document.getElementById('srhSearchResult');
  if(!result) return;
  srhWlpItems=items;
  result.innerHTML='<div class="srh-wlp-grid">'+
    items.map(function(it,idx){
      const urls=it.urls||{};
      const thumb=urls.preview_small||urls.adapted||urls.original||'';
      return '<div class="srh-wlp-card" onclick="srhWlpOpen('+idx+')">'+
        (thumb?'<img class="srh-wlp-thumb" src="'+srhEsc(thumb)+'" referrerpolicy="no-referrer" loading="lazy" onerror="srhImgOnError(this,\'fa-panorama\')">':'<div class="srh-wlp-thumb srh-thumbph"><i class="fa-solid fa-panorama"></i></div>')+
        (it.downloads!=null?'<div class="srh-wlp-badge"><i class="fa-solid fa-download"></i> '+srhWlpFmtNum(it.downloads)+'</div>':'')+
        '<div class="srh-wlp-body">'+
          '<div class="srh-wlp-title">'+srhEsc((it.description||'Wallpaper').slice(0,70))+'</div>'+
          (it.author?'<div class="srh-wlp-author"><i class="fa-solid fa-user"></i> '+srhEsc(it.author)+'</div>':'')+
        '</div>'+
      '</div>';
    }).join('')+
  '</div>';
}

