function srhIsYtsItem(it){
  return it&&typeof it==='object'&&('videoId' in it)&&('thumbnail' in it);
}

let srhYtsItems=[];
let srhYtsIdx=0;

function srhYtsFmtDuration(d){
  if(!d) return '';
  return String(d).replace(/\./g,':');
}

function srhRenderYtsResult(items){
  const result=document.getElementById('srhSearchResult');
  if(!result) return;
  srhYtsItems=items;
  result.innerHTML='<div class="srh-yts-list">'+
    items.map(function(it,idx){
      const thumb=it.thumbnail||'';
      const dur=srhYtsFmtDuration(it.duration);
      return '<div class="srh-yts-card">'+
        '<div class="srh-yts-thumbwrap" onclick="srhYtsPlay('+idx+')">'+
          (thumb?'<img class="srh-yts-thumb" src="'+srhEsc(thumb)+'" referrerpolicy="no-referrer" loading="lazy" onerror="srhImgOnError(this,\'fa-play\')">':'<div class="srh-yts-thumb srh-thumbph"><i class="fa-solid fa-play"></i></div>')+
          (dur?'<div class="srh-yts-dur">'+srhEsc(dur)+'</div>':'')+
          '<div class="srh-yts-playbtn"><i class="fa-solid fa-play"></i></div>'+
        '</div>'+
        '<div class="srh-yts-body">'+
          '<div class="srh-yts-title">'+srhEsc(it.title||'-')+'</div>'+
          '<div class="srh-yts-meta">'+[it.views,it.uploaded].filter(Boolean).map(function(s){return srhEsc(s);}).join(' &middot; ')+'</div>'+
          '<div class="srh-yts-actions">'+
            '<button class="srh-yts-actbtn primary" onclick="srhYtsPlay('+idx+')"><i class="fa-solid fa-play"></i> Putar</button>'+
            '<a class="srh-yts-actbtn alt" href="'+srhEscAttr(it.url||'')+'" target="_blank" rel="noopener"><i class="fa-brands fa-youtube"></i> Buka</a>'+
          '</div>'+
        '</div>'+
      '</div>';
    }).join('')+
  '</div>';
}

function srhYtsItem(){ return srhYtsItems[srhYtsIdx]||{}; }

function srhYtsPlay(idx){
  srhYtsIdx=idx;
  const it=srhYtsItem();
  const box=document.getElementById('srhYtsLightbox');
  if(!box) return;
  const titleEl=document.getElementById('srhYtsLbTitle');
  const body=document.getElementById('srhYtsLbBody');
  if(titleEl) titleEl.textContent=it.title||'-';
  if(body) body.innerHTML='<div class="srh-yts-lb-loading"><i class="fa-solid fa-spinner fa-spin"></i> Memuat video...</div>';
  box.classList.add('show');
  srhFetchJson('play','q='+encodeURIComponent(it.url||('https://youtu.be/'+it.videoId))).then(function(json){
    if(!body) return;
    if(json&&(json.status===false||json.status==='false')){
      body.innerHTML='<div class="srh-fetcherror"><i class="fa-solid fa-triangle-exclamation"></i> '+srhEsc(json.error||json.message||'Gagal memuat video.')+'</div>';
      return;
    }
    const media=(json&&json.media)||{};
    const url=media.url||'';
    if(!url){
      body.innerHTML='<div class="srh-fetcherror"><i class="fa-solid fa-triangle-exclamation"></i> Video tidak tersedia untuk diputar.</div>';
      return;
    }
    body.innerHTML='<video class="srh-yts-lb-video" src="'+srhEscAttr(url)+'" controls playsinline autoplay preload="metadata"></video>'+
      '<button class="srh-yts-lb-dl" onclick="aiSaveMediaFallback(\''+url.replace(/'/g,"\\'")+'\')"><i class="fa-solid fa-download"></i> Download</button>';
  }).catch(function(){
    if(body) body.innerHTML='<div class="srh-fetcherror"><i class="fa-solid fa-triangle-exclamation"></i> Gagal memuat video.</div>';
  });
}

function srhYtsClose(){
  const box=document.getElementById('srhYtsLightbox');
  if(!box) return;
  box.classList.remove('show');
  const v=box.querySelector('video');
  if(v) v.pause();
}

function srhRunSearch(menu,q,result,isRetry,extra){
  const paramName=srhParamNameFor(menu.key);
  srhFetchJson(menu.key,paramName+'='+encodeURIComponent(q)+(extra||'')).then(function(json){
    if(json&&(json.status===false||json.status==='false')){
      const apiMsg=json.error||json.message||json.msg||'Tidak ada hasil ditemukan.';
      if(result) result.innerHTML='<div class="srh-fetcherror"><i class="fa-solid fa-triangle-exclamation"></i> '+srhEsc(apiMsg)+'</div>';
      return;
    }
    cidDeductDiamond(SRH_COST,'Search: '+menu.label,'Kata kunci: '+q.slice(0,60));
    if(menu.key==='play'&&srhIsPlayShape(json)){
      srhCache[menu.key]=json;
      srhRenderPlayResult(json);
      return;
    }
    if(menu.key==='subdomain'&&srhIsSubdomainShape(json)){
      srhCache[menu.key]=json;
      srhRenderSubdomainResult(json);
      return;
    }
    const rawResult=(json&&(json.result!==undefined?json.result:json.data));
    if(menu.key==='bing'&&srhIsBingShape(rawResult)){
      srhCache[menu.key]=rawResult;
      srhRenderBingResult(rawResult);
      return;
    }
    if(menu.key==='countryinfo'){
      const countryData=(rawResult&&rawResult.data)?rawResult.data:rawResult;
      if(srhIsCountryInfoShape(countryData)){
        srhCache[menu.key]=countryData;
        srhRenderCountryInfoResult(countryData);
        return;
      }
    }
    if(menu.key==='cuaca'&&srhIsWeatherShape(rawResult)){
      srhCache[menu.key]=rawResult;
      srhRenderWeatherResult(rawResult);
      return;
    }
    if(menu.key==='mangatoon'&&srhIsMangatoonShape(rawResult)){
      srhCache[menu.key]=rawResult;
      srhMangatoonActiveTab='komik';
      srhRenderMangatoonResult(rawResult);
      return;
    }
    if(menu.key==='prompt'&&srhIsPromptShape(rawResult)){
      srhCache[menu.key]=rawResult.items;
      srhRenderPromptResult(rawResult.items);
      return;
    }
    let items=(rawResult!==undefined?rawResult:undefined);
    if(items===undefined) items=json;
    if(!Array.isArray(items)) items=(items?[items]:[]);
    if(!items.length){
      if(result) result.innerHTML='<div class="srh-fetcherror"><i class="fa-solid fa-triangle-exclamation"></i> Respons berhasil tapi tidak ada item ditemukan.</div>';
      return;
    }
    srhCache[menu.key]=items;
    if(menu.key==='kodepos'&&srhIsKodeposItem(items[0])){
      srhRenderKodeposResult(items);
      return;
    }
    if(menu.key==='dafont'&&srhIsDafontItem(items[0])){
      srhRenderDafontResult(items,json&&json.query);
      return;
    }
    if(menu.key==='github'&&srhIsGithubItem(items[0])){
      srhRenderGithubResult(items);
      return;
    }
    if(menu.key==='google'&&srhIsGoogleNewsItem(items[0])){
      srhRenderGoogleNewsResult(items);
      return;
    }
    if(menu.key==='lyrics'&&srhIsLyricsItem(items[0])){
      srhRenderLyricsResult(items);
      return;
    }
    if(menu.key==='npm'&&srhIsNpmItem(items[0])){
      srhRenderNpmResult(items);
      return;
    }
    if(menu.key==='pinterest'&&srhIsPinterestItem(items[0])){
      srhRenderPinterestResult(items);
      return;
    }
    if(menu.key==='pixiv'&&srhIsPixivItem(items[0])){
      srhRenderPixivResult(items);
      return;
    }
    if(menu.key==='resepkoki'&&srhIsResepkokiItem(items[0])){
      srhRenderResepkokiResult(items);
      return;
    }
    if(menu.key==='spotify'&&srhIsSpotifyItem(items[0])){
      srhRenderSpotifyResult(items);
      return;
    }
    if(menu.key==='wallcraft'&&srhIsWallcraftItem(items[0])){
      srhRenderWallcraftResult(items);
      return;
    }
    if(menu.key==='yts'&&srhIsYtsItem(items[0])){
      srhRenderYtsResult(items);
      return;
    }
    srhRenderResult(menu,items);
  }).catch(function(err){
    const detail=(err&&err.debugDetail)||(err&&err.message)||'';
    const guessedParam=srhExtractParamName(detail);
    // API kasih tau nama parameter yang benar & kita belum coba nama itu -> retry sekali otomatis.
    if(!isRetry&&guessedParam&&guessedParam!==paramName){
      srhParamCache[menu.key]=guessedParam;
      srhRunSearch(menu,q,result,true,extra);
      return;
    }
    if(result) result.innerHTML='<div class="srh-fetcherror"><i class="fa-solid fa-triangle-exclamation"></i> Gagal mencari.<br><span style="font-size:11px;opacity:.7;">'+srhEsc(detail)+'</span></div>';
  });
}

function srhRenderResult(menu,items){
  const result=document.getElementById('srhSearchResult');
  if(!result) return;
  result.innerHTML=items.map(function(it){
    if(typeof it!=='object'||it===null){
      return '<div class="srh-item"><div class="srh-body"><div class="srh-name">'+srhEsc(String(it))+'</div></div></div>';
    }
    const title=it.title||it.judul||it.name||it.nama||it.text||it.lyrics&&'Lirik Lagu'||menu.label;
    const thumb=it.thumbnail||it.thumb||it.image||it.img||it.cover||'';
    const desc=it.description||it.desc||it.artist||it.author||it.channel||it.location||it.city||'';
    const rating=(it.rating!=null?it.rating:(it.stars!=null?it.stars:(it.score!=null?it.score:'')));
    const ratingHtml=rating!==''?'<i class="fa-solid fa-star" style="color:#f5b400;"></i> '+srhEsc(String(rating)):'';
    const metaText=[desc,(it.duration||it.size||it.date||'')].filter(Boolean).join(' &middot; ');
    const metaHtml=[metaText?srhEsc(metaText):'',ratingHtml].filter(Boolean).join(' &middot; ');
    const link=it.url||it.link||it.download||it.video||it.play_url||'';
    const rawText=(!thumb&&!link&&typeof it.lyrics==='string')?it.lyrics:'';
    const thumbIcon=menu.icon||'fa-magnifying-glass';
    return '<div class="srh-item">'+
      (thumb?'<img class="srh-thumb" src="'+srhEsc(thumb)+'" referrerpolicy="no-referrer" loading="lazy" onerror="srhImgOnError(this,\''+thumbIcon+'\')">':'<div class="srh-thumbph"><i class="fa-solid '+thumbIcon+'"></i></div>')+
      '<div class="srh-body">'+
        '<div class="srh-name">'+srhEsc(title)+'</div>'+
        (metaHtml?'<div class="srh-meta">'+metaHtml+'</div>':'')+
        (rawText?'<div class="srh-raw" style="margin-top:8px;">'+srhEsc(rawText)+'</div>':'')+
        (link?'<div class="srh-actions"><a class="srh-actbtn" href="'+srhEscAttr(link)+'" target="_blank" rel="noopener"><i class="fa-solid fa-arrow-up-right-from-square"></i> Buka</a></div>':'')+
      '</div>'+
    '</div>';
  }).join('');
}

let srhBingActiveTab='images';
function srhBingTabIcon(t){ return t==='images'?'fa-image':(t==='videos'?'fa-video':'fa-globe'); }
function srhBingTabLabel(t){ return t==='images'?'Gambar':(t==='videos'?'Video':'Web'); }

function srhBingThumbHtml(src){
  if(!src) return '<div class="srh-thumbph"><i class="fa-solid fa-image"></i></div>';
  return '<img class="srh-thumb" src="'+srhEsc(src)+'" referrerpolicy="no-referrer" loading="lazy" onerror="srhImgOnError(this,\'fa-image\')">';
}

function srhRenderBingResult(data){
  const result=document.getElementById('srhSearchResult');
  if(!result) return;
  const tabs=['images','videos','web'].filter(function(t){return Array.isArray(data[t])&&data[t].length;});
  if(!tabs.length){
    result.innerHTML='<div class="srh-fetcherror"><i class="fa-solid fa-triangle-exclamation"></i> Tidak ada hasil ditemukan.</div>';
    return;
  }
  if(tabs.indexOf(srhBingActiveTab)===-1) srhBingActiveTab=tabs[0];
  const tabsHtml='<div class="srh-formrow" style="display:flex;gap:8px;margin-bottom:10px;">'+
    tabs.map(function(t){
      return '<button class="srh-searchbtn" style="flex:1;'+(t===srhBingActiveTab?'':'opacity:.55;')+'" onclick="srhBingActiveTab=\''+t+'\';srhRenderBingResult(srhCache.bing);"><i class="fa-solid '+srhBingTabIcon(t)+'"></i> '+srhBingTabLabel(t)+'</button>';
    }).join('')+
  '</div>';

  const items=data[srhBingActiveTab]||[];
  let bodyHtml='';
  if(srhBingActiveTab==='images'){
    bodyHtml='<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:10px;">'+
      items.map(function(it){
        const primaryImg=it.thumbnail||it.mediaUrl||'';
        const altImg=it.mediaUrl||it.thumbnail||'';
        const link=it.mediaUrl||it.sourceUrl||'';
        return '<a href="'+srhEscAttr(link)+'" target="_blank" rel="noopener" style="display:block;text-decoration:none;">'+
          (primaryImg?'<img src="'+srhEsc(primaryImg)+'" data-alt-src="'+srhEscAttr(altImg)+'" referrerpolicy="no-referrer" loading="lazy" onerror="if(this.dataset.altSrc&&this.src!==this.dataset.altSrc&&!this.dataset.triedAlt){this.dataset.triedAlt=\'1\';this.src=this.dataset.altSrc;}else{srhImgOnError(this,\'fa-image\')}" style="width:100%;aspect-ratio:1;object-fit:cover;border-radius:10px;background:var(--srh-surface2);border:1px solid var(--srh-hair-strong);">':'<div class="srh-thumbph" style="width:100%;aspect-ratio:1;border-radius:10px;"><i class="fa-solid fa-image"></i></div>')+
          '<div style="font-size:11px;color:var(--srh-dim);margin-top:4px;line-height:1.4;">'+srhEsc((it.title||'').slice(0,60))+'</div>'+
        '</a>';
      }).join('')+
    '</div>';
  }else if(srhBingActiveTab==='videos'){
    bodyHtml=items.map(function(it){
      const thumb=it.thumbnail||'';
      const link=it.link||'';
      return '<div class="srh-item">'+
        srhBingThumbHtml(thumb)+
        '<div class="srh-body">'+
          '<div class="srh-name">'+srhEsc(it.title||'Video')+'</div>'+
          (link?'<div class="srh-actions"><a class="srh-actbtn" href="'+srhEscAttr(link)+'" target="_blank" rel="noopener"><i class="fa-solid fa-arrow-up-right-from-square"></i> Buka</a></div>':'')+
        '</div>'+
      '</div>';
    }).join('');
  }else{
    bodyHtml=items.map(function(it){
      const link=it.link||'';
      return '<div class="srh-item">'+
        '<div class="srh-thumbph"><i class="fa-solid fa-globe"></i></div>'+
        '<div class="srh-body">'+
          '<div class="srh-name">'+srhEsc(it.title||'')+'</div>'+
          (it.displayUrl?'<div class="srh-meta">'+srhEsc(it.displayUrl)+'</div>':'')+
          (it.snippet?'<div class="srh-raw" style="margin-top:8px;">'+srhEsc(it.snippet)+'</div>':'')+
          (link?'<div class="srh-actions"><a class="srh-actbtn" href="'+srhEscAttr(link)+'" target="_blank" rel="noopener"><i class="fa-solid fa-arrow-up-right-from-square"></i> Buka</a></div>':'')+
        '</div>'+
      '</div>';
    }).join('');
  }
  result.innerHTML=tabsHtml+bodyHtml;
}

const SMDL_TAB_ORDER=['cc','tt','ig','yt','ytdl','fb','dy','th','x','pin','vd','cpc','sp','sc','am','mf','tb','gh','xnxx'];

function smdlSwitchTab(tab){
  SMDL_TAB_ORDER.forEach(t=>{
    const tabEl=document.getElementById('smdlTab_'+t);
    const panelEl=document.getElementById('smdlPanel_'+t);
    if(tabEl) tabEl.classList.toggle('active',t===tab);
    if(panelEl) panelEl.classList.toggle('active',t===tab);
  });
}

function smdlSwitchCat(cat){
  document.querySelectorAll('.smdl-cat').forEach(b=>b.classList.toggle('active',b.dataset.cat===cat));
  let firstVisible=null;
  SMDL_TAB_ORDER.forEach(t=>{
    const tabEl=document.getElementById('smdlTab_'+t);
    if(!tabEl) return;
    const show=(cat==='all')||(tabEl.dataset.cat===cat);
    tabEl.style.display=show?'':'none';
    if(show&&!firstVisible) firstVisible=t;
  });
  const activeTab=document.querySelector('.smdl-tab.active');
  if((!activeTab||activeTab.style.display==='none')&&firstVisible) smdlSwitchTab(firstVisible);
}

function smdlSetLoading(btn,loading,label){
  if(!btn)return;
  if(loading){
    btn.disabled=true;
    btn.dataset.origHtml=btn.innerHTML;
    btn.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> '+label;
  }else{
    btn.disabled=false;
    if(btn.dataset.origHtml) btn.innerHTML=btn.dataset.origHtml;
  }
}

function smdlLooksLikeUrl(v){
  return typeof v==='string' && /^https?:\/\//i.test(v);
}
function smdlLooksLikeVideoUrl(v){
  return smdlLooksLikeUrl(v) && (/\.(mp4|mov|m3u8|webm)(\?|$)/i.test(v) || /video/i.test(v));
}
function smdlLooksLikeImageUrl(v){
  return smdlLooksLikeUrl(v) && /\.(jpg|jpeg|png|webp|gif)(\?|$)/i.test(v);
}

/* Menjelajahi seluruh object/array response secara rekursif untuk menemukan
   URL video & gambar, karena setiap API downloader beda-beda struktur field-nya
   (tidak semua pakai nama field yang sama seperti "video" / "images"). */
function smdlDeepFindMedia(node,depth,videos,images){
  if(depth>6||node==null) return;
  if(typeof node==='string'){
    if(smdlLooksLikeVideoUrl(node)) videos.push(node);
    else if(smdlLooksLikeImageUrl(node)) images.push(node);
    return;
  }
  if(Array.isArray(node)){
    node.forEach(item=>smdlDeepFindMedia(item,depth+1,videos,images));
    return;
  }
  if(typeof node==='object'){
    Object.keys(node).forEach(key=>{
      const val=node[key];
      const keyLower=key.toLowerCase();
      if(typeof val==='string'&&smdlLooksLikeUrl(val)){
        if(/video|no_?watermark|hd|download|play/.test(keyLower)&&!/thumb|cover|avatar|icon/.test(keyLower)){
          videos.push(val);
        }else if(/image|photo|slide|picture/.test(keyLower)){
          images.push(val);
        }else{
          smdlDeepFindMedia(val,depth+1,videos,images);
        }
      }else{
        smdlDeepFindMedia(val,depth+1,videos,images);
      }
    });
  }
}

function smdlExtractMedia(json,platform){
  if(!json) return null;
  const d=json.data||json.result||json.results||json;

  // Struktur khusus TikTok (endpoint ttdl): result.video adalah array mp4
  if(platform==='tt'){
    const v=d&&d.video;
    const videoUrl=Array.isArray(v)?v[0]:(smdlLooksLikeUrl(v)?v:null);
    if(videoUrl){
      return {videoUrl,imageList:null,title:d.title||d.title_audio||'',thumb:d.thumbnail||d.cover||''};
    }
  }

  // Struktur khusus Instagram (endpoint igdl): result.url adalah link video final
  // (bukan file .mp4 langsung, tapi endpoint proxy CDN dengan token)
  if(platform==='ig'){
    if(smdlLooksLikeUrl(d&&d.url)){
      return {videoUrl:d.url,imageList:null,title:d.title||d.caption||'',thumb:d.thumbnail||d.cover||''};
    }
    // beberapa response IG punya banyak slide (carousel)
    const slides=d&&(d.medias||d.slides||d.images);
    if(Array.isArray(slides)&&slides.length){
      const urls=slides.map(s=>typeof s==='string'?s:(s&&(s.url||s.link))).filter(smdlLooksLikeUrl);
      if(urls.length) return {videoUrl:urls.length===1?urls[0]:null,imageList:urls.length>1?urls:null,title:d.title||'',thumb:d.thumbnail||''};
    }
  }

  // Struktur khusus Facebook (endpoint facebook): result.links = [{quality,url}],
  // ambil kualitas tertinggi (parse angka di depan "quality", mis. "720p (HD)")
  if(platform==='fb'){
    const fbLinks=d&&Array.isArray(d.links)?d.links:null;
    if(fbLinks&&fbLinks.length){
      let best=null,bestScore=-1;
      fbLinks.forEach(function(l){
        if(!l||!smdlLooksLikeUrl(l.url)) return;
        const q=parseInt(String(l.quality||'').replace(/[^0-9]/g,''),10);
        const score=isNaN(q)?0:q;
        if(score>bestScore){ bestScore=score; best=l; }
      });
      if(best) return {videoUrl:best.url,imageList:null,title:d.title||'',thumb:d.img||d.thumbnail||''};
    }
    const fbVideo=d&&(d.hd||d.sd||d.url_hd||d.url_sd||d.HD||d.SD||d.video||d.video_url||d.url);
    if(smdlLooksLikeUrl(fbVideo)){
      return {videoUrl:fbVideo,imageList:null,title:d.title||d.caption||'',thumb:d.thumbnail||d.cover||d.img||''};
    }
  }

  // Struktur khusus AIO (endpoint aio-downloader): all-in-one, mendukung banyak platform
  // (semua sosmed), umumnya field video/url/hd/no_watermark atau array "medias"/"links"
  if(platform==='cc'){
    // Format baru endpoint /api/download/aio: result.media = [{type:'video'|'audio',
    // resources:[{download_url,quality,format,size}], thumbnail}]. Ambil resource video
    // dengan kualitas tertinggi (angka di depan "quality", mis. "720P" > "540P").
    const ccMediaList=d&&Array.isArray(d.media)?d.media:null;
    if(ccMediaList&&ccMediaList.length){
      const videoItem=ccMediaList.find(function(m){ return m&&m.type==='video'; });
      const audioItem=ccMediaList.find(function(m){ return m&&m.type==='audio'; });
      function ccBestResource(item){
        if(!item||!Array.isArray(item.resources)||!item.resources.length) return null;
        let best=null,bestScore=-1;
        item.resources.forEach(function(r){
          if(!r||!smdlLooksLikeUrl(r.download_url)) return;
          const q=parseInt(String(r.quality||'').replace(/[^0-9]/g,''),10);
          const score=isNaN(q)?(r.size||0):q;
          if(score>bestScore){ bestScore=score; best=r; }
        });
        return best;
      }
      const bestVideo=ccBestResource(videoItem);
      const bestAudio=ccBestResource(audioItem);
      if(bestVideo){
        return {
          videoUrl:bestVideo.download_url,
          imageList:null,
          title:d.title||'',
          thumb:(videoItem&&videoItem.thumbnail)||d.thumbnail||''
        };
      }
      if(bestAudio){
        return {videoUrl:null,imageList:null,audioUrl:bestAudio.download_url,title:d.title||'',thumb:(audioItem&&audioItem.thumbnail)||d.thumbnail||''};
      }
    }
    const ccVideo=d&&(d.video||d.video_url||d.no_watermark||d.hd||d.url||d.download_url);
    if(smdlLooksLikeUrl(ccVideo)){
      return {videoUrl:ccVideo,imageList:null,title:d.title||d.desc||'',thumb:d.thumbnail||d.cover||''};
    }
    const ccList=d&&(d.medias||d.links||d.downloads);
    if(Array.isArray(ccList)&&ccList.length){
      const urls=ccList.map(s=>typeof s==='string'?s:(s&&(s.url||s.link))).filter(smdlLooksLikeUrl);
      if(urls.length) return {videoUrl:urls[0],imageList:null,title:d.title||'',thumb:d.thumbnail||''};
    }
  }

  // CapCut: endpoint /api/download/capcut -> data.video_url langsung, data.cover_url,
  // data.title, data.author
  if(platform==='capcut'){
    if(smdlLooksLikeUrl(d&&d.video_url)){
      return {videoUrl:d.video_url,imageList:null,title:(d.title||'')+(d.author?(' - '+d.author):''),thumb:d.cover_url||''};
    }
  }

  // SoundCloud: belum ada contoh response resmi, pakai pola field umum yg sama dengan
  // downloader audio lain di keluarga sylvatica.my.id (link/download/url utk mp3 + judul/artist)
  if(platform==='sc'){
    const scAudio=d&&(d.download||d.download_url||d.url||d.audio||d.mp3||d.link||(d.links&&d.links.mp3));
    if(smdlLooksLikeUrl(scAudio)){
      const scTitle=(d.title||d.name||(d.metadata&&d.metadata.name)||'')+
        ((d.artist||d.author||(d.metadata&&d.metadata.artist))?(' - '+(d.artist||d.author||(d.metadata&&d.metadata.artist))):'');
      return {videoUrl:null,imageList:null,audioUrl:scAudio,title:scTitle,thumb:d.image||d.cover||d.thumbnail||(d.links&&d.links.cover)||(d.metadata&&d.metadata.cover)||''};
    }
  }

  // Struktur umum video sederhana (Douyin, Threads, X, Videy): biasanya field video/hd/no_watermark/url
  if(platform==='dy'||platform==='th'||platform==='x'||platform==='vd'){
    const vUrl=d&&(d.video||d.video_url||d.no_watermark||d.hd||d.play||d.url||d.download_url);
    if(smdlLooksLikeUrl(vUrl)){
      return {videoUrl:vUrl,imageList:null,title:d.title||d.desc||d.caption||'',thumb:d.thumbnail||d.cover||''};
    }
    // Threads/X kadang berupa carousel foto+video
    const slides=d&&(d.medias||d.slides||d.images||d.photos);
    if(Array.isArray(slides)&&slides.length){
      const urls=slides.map(s=>typeof s==='string'?s:(s&&(s.url||s.link))).filter(smdlLooksLikeUrl);
      if(urls.length) return {videoUrl:urls.length===1?urls[0]:null,imageList:urls.length>1?urls:null,title:d.title||'',thumb:d.thumbnail||''};
    }
  }

  // Pinterest: response endpoint /api/download/pinterest = GraphQL asli Pinterest,
  // struktur json.data.d1/d2 -> data.v3GetPinQueryv2.data (nested). Gali khusus field
  // "images_orig.url" (resolusi asli) atau "imageLargeUrl" sebagai fallback, supaya
  // gak ikut kepancing avatar/thumbnail user yang juga punya "image" di nama field-nya.
  if(platform==='pin'){
    function pinGetQueryData(branch){
      return branch&&branch.data&&branch.data.v3GetPinQueryv2&&branch.data.v3GetPinQueryv2.data;
    }
    const pinRoot=d||{};
    const c1=pinGetQueryData(pinRoot.d1);
    const c2=pinGetQueryData(pinRoot.d2);
    const pinData=(c2&&c2.images_orig&&smdlLooksLikeUrl(c2.images_orig.url))?c2:
      (c1&&c1.images_orig&&smdlLooksLikeUrl(c1.images_orig.url))?c1:(c2||c1);
    if(pinData){
      const imgUrl=(pinData.images_orig&&pinData.images_orig.url)||pinData.imageLargeUrl||
        (pinData.images_736x&&pinData.images_736x.url)||'';
      const title=pinData.title||pinData.closeupUnifiedTitle||pinData.gridTitle||'';
      // pin video jika ada (jarang, kebanyakan pin cuma gambar statis)
      let pinVideoUrl=null;
      const vids=pinData.videos;
      if(vids&&typeof vids==='object'){
        const vl=vids.video_list||vids;
        const cand=Object.values(vl||{}).map(function(v){ return v&&(v.url||v.URL); }).find(smdlLooksLikeUrl);
        if(cand) pinVideoUrl=cand;
      }
      if(pinVideoUrl) return {videoUrl:pinVideoUrl,imageList:null,title,thumb:imgUrl};
      if(smdlLooksLikeUrl(imgUrl)) return {videoUrl:null,imageList:[imgUrl],title,thumb:''};
    }
    const pinVideo=d&&(d.video||d.video_url);
    if(smdlLooksLikeUrl(pinVideo)){
      return {videoUrl:pinVideo,imageList:null,title:d.title||'',thumb:d.thumbnail||''};
    }
    const pinImg=d&&(d.image||d.image_url||d.url||d.images);
    if(Array.isArray(pinImg)){
      const urls=pinImg.filter(smdlLooksLikeUrl);
      if(urls.length) return {videoUrl:null,imageList:urls,title:d.title||'',thumb:''};
    }
    if(smdlLooksLikeUrl(pinImg)){
      return {videoUrl:null,imageList:[pinImg],title:d.title||'',thumb:''};
    }
  }

  // Mediafire: link file generik (bisa apa saja, bukan cuma video)
  if(platform==='mf'){
    const fileUrl=d&&(d.url||d.link||d.download_url||d.direct_link);
    if(smdlLooksLikeUrl(fileUrl)){
      // filename kadang berupa string HTML mentah dari API-nya (mis. "<a href=...>MediaFire</a>"),
      // dibersihkan dulu tag HTML-nya sebelum ditampilkan
      const rawName=d.filename||d.name||d.title||'';
      const cleanName=String(rawName).replace(/<[^>]+>/g,'').trim();
      return {videoUrl:null,imageList:null,audioUrl:null,fileUrl,title:cleanName,thumb:''};
    }
  }

  // Spotify: hasil berupa link audio mp3 + metadata lagu
  if(platform==='sp'){
    const spLinks=d&&d.links;
    const spMeta=d&&d.metadata;
    if(spLinks&&smdlLooksLikeUrl(spLinks.mp3)){
      const title=(spMeta&&spMeta.name||d.title||d.name||'')+((spMeta&&spMeta.artist)||d.artist?(' - '+((spMeta&&spMeta.artist)||d.artist)):'');
      return {videoUrl:null,imageList:null,audioUrl:spLinks.mp3,title,thumb:spLinks.cover||(spMeta&&spMeta.cover)||''};
    }
    const audioUrl=d&&(d.download||d.download_url||d.url||d.audio||d.mp3);
    if(smdlLooksLikeUrl(audioUrl)){
      return {videoUrl:null,imageList:null,audioUrl,title:(d.title||d.name||'')+(d.artist?(' - '+d.artist):''),thumb:d.image||d.cover||d.thumbnail||''};
    }
  }

  // YouTube MP4/MP3 (endpoint ytmp4 / ytmp3): hasil berupa link download langsung
  if(platform==='ytdlmp4'||platform==='ytdlmp3'){
    const dlUrl=d&&(d.download||d.download_url||d.url||d.link);
    if(smdlLooksLikeUrl(dlUrl)){
      if(platform==='ytdlmp3'){
        return {videoUrl:null,imageList:null,audioUrl:dlUrl,title:d.title||'',thumb:d.thumbnail||d.image||''};
      }
      return {videoUrl:dlUrl,imageList:null,title:d.title||'',thumb:d.thumbnail||d.image||''};
    }
  }

  // Fallback umum: field bernama umum di berbagai API downloader
  const directVideo=d&&(d.video||d.video_url||d.videoUrl||d.no_watermark||d.hd||d.play||d.download_url||d.url||(Array.isArray(d.video)?d.video[0]:null));
  const directImages=d&&(d.images||d.image||d.photo||d.slides);
  const title=(d&&(d.title||d.desc||d.caption))||json.title||'';
  const thumb=(d&&(d.cover||d.thumbnail||d.thumb))||'';

  let videoUrl=smdlLooksLikeUrl(directVideo)?directVideo:null;
  let imageList=Array.isArray(directImages)?directImages.filter(smdlLooksLikeUrl):null;

  // Kalau field umum tidak ketemu / bukan URL valid, telusuri seluruh response
  if(!videoUrl && !(imageList&&imageList.length)){
    const foundVideos=[],foundImages=[];
    smdlDeepFindMedia(json,0,foundVideos,foundImages);
    if(foundVideos.length) videoUrl=foundVideos[0];
    else if(foundImages.length) imageList=foundImages;
  }

  if(!videoUrl && !(imageList&&imageList.length)) return null;
  return {videoUrl:videoUrl||null,imageList:imageList&&imageList.length?imageList:null,title,thumb};
}

function smdlHasMedia(media){
  return !!(media&&(media.videoUrl||media.audioUrl||media.fileUrl||(media.imageList&&media.imageList.length)));
}

async function smdlFetchApi(url){
  try{
    const res=await fetch(url,{headers:{'Accept':'application/json'}});
    return await res.json();
  }catch(directErr){
    console.warn('[SMDL] fetch langsung gagal, coba proxy...',directErr);
    const res=await fetch('https://api.allorigins.win/raw?url='+encodeURIComponent(url));
    return await res.json();
  }
}

