async function smdlSimpleDownload(type){
  const cfg=SMDL_SIMPLE_CONFIG[type];
  const inp=document.getElementById(cfg.input);
  const btn=document.getElementById(cfg.btn);
  const box=document.getElementById(cfg.box);
  const url=inp?inp.value.trim():'';
  if(!url){ smdlShakeInput(inp); return; }
  if(!cidPreCheckDiamond(SMDL_COST,cfg.btn)) return;
  box.classList.remove('show'); box.innerHTML='';
  smdlSetLoading(btn,true,'MEMPROSES...');
  try{
    const isDataOk=function(j){ return smdlHasMedia(smdlExtractMedia(j,type)); };
    const json=cfg.fallback
      ? await smdlDownloadRequest(cfg.endpoint,url,{isDataOk:isDataOk})
      : await xyureiRequest(function(key){
          return 'https://sylvatica.my.id/api/download/'+cfg.endpoint+'?url='+encodeURIComponent(url)+'&apikey='+key;
        },{isDataOk:isDataOk});
    const media=smdlExtractMedia(json,type);
    cidDeductDiamond(SMDL_COST,'Sosmed Downloader','Download '+cfg.label+': '+url);
    smdlRenderTtIg(box,media,cfg.label);
  }catch(e){
    console.error('[SMDL]['+type+']',e);
    smdlRenderError(box,'Gagal mengambil media. '+cfg.err);
  }
  smdlSetLoading(btn,false);
}

