/* API youtube/search cuma balikin 1 hasil teratas per query. Supaya user dapat
   lebih banyak pilihan (target ~20), kita kirim banyak variasi query terkait
   secara paralel lalu gabungkan hasilnya (dedupe berdasarkan videoId). */
async function smdlYtMultiSearch(q){
  const variations=[
    q,
    q+' tutorial',
    q+' terbaru',
    q+' lengkap',
    q+' pemula',
    q+' 2026',
    q+' terbaik',
    q+' full',
    q+' indonesia',
    q+' mudah',
    q+' dasar',
    q+' cepat',
    q+' gratis',
    q+' review',
    q+' tips',
    q+' cara',
    q+' panduan',
    q+' step by step',
    q+' update',
    q+' viral'
  ];
  const results=await Promise.allSettled(
    variations.map(vq=>smdlFetchApi('https://api.saipulanuar.eu.org/api/youtube/search?query='+encodeURIComponent(vq)))
  );
  const seen=new Set();
  const merged=[];
  results.forEach(r=>{
    if(r.status!=='fulfilled') return;
    const json=r.value;
    const list=(json&&(json.results||json.data||json.result))||[];
    if(!Array.isArray(list)) return;
    list.forEach(item=>{
      const key=item.videoId||item.url||item.id;
      if(!key||seen.has(key)) return;
      seen.add(key);
      merged.push(item);
    });
  });
  return merged.slice(0,20);
}

function smdlShakeInput(inp){
  if(!inp)return;
  inp.classList.remove('pc-shake');void inp.offsetWidth;inp.classList.add('pc-shake');
  inp.style.borderColor='#ff2b2b';
  inp.style.boxShadow='0 0 0 3px rgba(255,43,43,.22)';
  setTimeout(()=>{inp.style.boxShadow='';inp.style.borderColor='rgba(255,43,43,.38)';},900);
}

function smdlRenderError(box,msg,rawJson){
  let html='<div class="smdl-empty"><i class="fa-solid fa-triangle-exclamation"></i>'+msg+'</div>';
  if(rawJson){
    const rid='smdlRaw_'+Math.random().toString(36).slice(2,8);
    let jsonStr='';
    try{ jsonStr=JSON.stringify(rawJson,null,2); }catch(e){ jsonStr=String(rawJson); }
    jsonStr=jsonStr.replace(/</g,'&lt;').replace(/>/g,'&gt;');
    html+='<div style="text-align:center;padding-bottom:16px;">'+
      '<button type="button" class="smdl-dlbtn smdl-alt" style="margin:0 15px;width:calc(100% - 30px);" onclick="const el=document.getElementById(\''+rid+'\');el.style.display=el.style.display===\'none\'?\'block\':\'none\';">'+
      '<i class="fa-solid fa-code"></i> Lihat Response Mentah</button>'+
      '<pre id="'+rid+'" style="display:none;text-align:left;margin:10px 15px 0;padding:12px;border-radius:10px;background:rgba(0,0,0,.5);border:1px solid rgba(255,255,255,.08);color:#9ad1ff;font-size:10px;line-height:1.5;max-height:260px;overflow:auto;white-space:pre-wrap;word-break:break-word;">'+jsonStr+'</pre>'+
    '</div>';
  }
  box.innerHTML=html;
  box.classList.add('show');
}

function smdlRenderTtIg(box,media,platform){
  let mediaHtml='';
  if(media.imageList&&media.imageList.length){
    mediaHtml='<img class="smdl-result-media" src="'+media.imageList[0]+'" alt="preview" referrerpolicy="no-referrer" onerror="aiImgErr(this)">';
  }else if(media.videoUrl){
    mediaHtml='<video class="smdl-result-media" src="'+media.videoUrl+'" controls playsinline poster="'+(media.thumb||'')+'" referrerpolicy="no-referrer" onerror="aiImgErr(this)"></video>';
  }else if(media.audioUrl){
    mediaHtml=(media.thumb?'<img class="smdl-result-media" src="'+media.thumb+'" alt="cover" style="max-height:220px;" referrerpolicy="no-referrer" onerror="aiImgErr(this)">':'')+
      '<audio style="width:100%;display:block;margin-top:10px;" src="'+media.audioUrl+'" controls referrerpolicy="no-referrer" onerror="aiImgErr(this)"></audio>';
  }
  const dlHref=media.videoUrl||media.audioUrl||media.fileUrl||(media.imageList&&media.imageList[0])||'#';
  const dlExt=media.videoUrl?'mp4':(media.audioUrl?'mp3':'jpg');
  box.innerHTML=mediaHtml+
    '<div class="smdl-result-body">'+
      '<p class="smdl-result-title">'+(media.title?media.title:platform+' media siap diunduh')+'</p>'+
      '<div class="smdl-result-actions">'+
        '<button class="smdl-dlbtn" onclick="aiSaveMediaFallback(\''+dlHref.replace(/'/g,"\\'")+'\')"><i class="fa-solid fa-download"></i> Download</button>'+
      '</div>'+
    '</div>';
  box.classList.add('show');
}

function smdlYtFormatDuration(d){
  if(!d) return '';
  if(typeof d==='string') return d;
  if(typeof d==='object') return d.timestamp||'';
  return '';
}
function smdlYtFormatViews(v){
  if(v==null) return '';
  const n=Number(v);
  if(isNaN(n)) return '';
  if(n>=1000000) return (n/1000000).toFixed(1).replace(/\.0$/,'')+'JT x ditonton';
  if(n>=1000) return (n/1000).toFixed(1).replace(/\.0$/,'')+'RB x ditonton';
  return n+' x ditonton';
}
function smdlRenderYtList(box,list){
  let html='<div style="font-size:10.5px;color:#888;margin-bottom:10px;padding:0 2px;">'+list.length+' video ditemukan</div>';
  list.forEach(item=>{
    const title=item.title||item.judul||'Tanpa judul';
    const thumb=item.thumbnail||item.thumb||item.image||'';
    const channel=(item.author&&item.author.name)||item.channel||item.uploader||'';
    const duration=smdlYtFormatDuration(item.duration);
    const views=smdlYtFormatViews(item.views);
    const ago=item.ago||'';
    const meta=[channel,duration,views||ago].filter(Boolean).join(' • ');
    const link=item.url||item.link||('https://www.youtube.com/watch?v='+(item.videoId||item.id||''));
    html+='<div class="smdl-yt-item">'+
      '<img class="smdl-yt-thumb" src="'+thumb+'" alt="thumb" onerror="this.style.visibility=\'hidden\'">'+
      '<div class="smdl-yt-info"><h5>'+title+'</h5><small>'+meta+'</small></div>'+
      '<a class="smdl-yt-link" href="'+link+'" target="_blank" rel="noopener"><i class="fa-solid fa-play"></i></a>'+
    '</div>';
  });
  box.innerHTML=html;
  box.classList.add('show');
}

