let nhPreviewCheckTimer=null;
let nhPreviewCheckToken=0;
function updateNhPreview(){
  const inp=document.getElementById('nhPreviewInput');
  const box=document.getElementById('nhPreviewNickBox');
  const textEl=document.getElementById('nhPreviewText');
  const counterEl=document.getElementById('nhPreviewCounter');
  let v=inp.value.replace(/[^0-9]/g,'');
  if(v.length>13) v=v.slice(0,13);
  if(v!==inp.value) inp.value=v;
  if(counterEl) counterEl.textContent=v.length+'/13';

  if(nhPreviewCheckTimer){clearTimeout(nhPreviewCheckTimer);nhPreviewCheckTimer=null;}
  const myToken=++nhPreviewCheckToken;

  if(v.length<8){
    if(textEl) textEl.textContent='NICKNAME';
    if(box){box.style.display='none';box.className='pc-uid-nick-box';box.innerHTML='';}
    return;
  }

  if(textEl) textEl.textContent='MENGECEK...';
  if(box){
    box.style.display='flex';
    box.className='pc-uid-nick-box state-loading';
    box.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i><span>Mengecek UID...</span>';
  }

  nhPreviewCheckTimer=setTimeout(function(){
    fetchFFNickname(v).then(function(nickname){
      if(myToken!==nhPreviewCheckToken) return;
      if(textEl) textEl.textContent=nickname;
      if(box){
        box.className='pc-uid-nick-box state-found';
        box.innerHTML='<i class="fa-solid fa-circle-check"></i><span>Nickname: '+nickname+'</span>';
      }
    }).catch(function(e){
      if(myToken!==nhPreviewCheckToken) return;
      if(textEl) textEl.textContent='NICKNAME';
      const msg=(e&&e.isNetwork)?'Gagal mengecek UID, coba lagi.':'UID tidak ditemukan.';
      if(box){
        box.className='pc-uid-nick-box state-error';
        box.innerHTML='<i class="fa-solid fa-triangle-exclamation"></i><span>'+msg+'</span>';
      }
    });
  },250);
}

function copyNhProofId(){
  const val=document.getElementById('nhProofId').textContent.trim();
  const btn=document.querySelector('.nh-proof-copy-btn');
  const icon=btn?btn.querySelector('i'):null;
  const label=btn?btn.querySelector('span'):null;
  function done(){
    if(!icon)return;
    const origIcon=icon.className;
    const origLabel=label?label.textContent:null;
    icon.className='fa-solid fa-check';
    if(label)label.textContent='Tersalin';
    setTimeout(()=>{icon.className=origIcon;if(label)label.textContent=origLabel;},1200);
  }
  if(navigator.clipboard&&navigator.clipboard.writeText){
    navigator.clipboard.writeText(val).then(done).catch(()=>{
      const ta=document.createElement('textarea');
      ta.value=val;document.body.appendChild(ta);ta.select();
      try{document.execCommand('copy');}catch(e){}
      document.body.removeChild(ta);done();
    });
  }else{
    const ta=document.createElement('textarea');
    ta.value=val;document.body.appendChild(ta);ta.select();
    try{document.execCommand('copy');}catch(e){}
    document.body.removeChild(ta);done();
  }
}

