function neEscape(s){
  return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

function neParse(raw){
  const tokenRe=/(\[[0-9A-Fa-f]{6}\]|\[b\]|\[\/b\]|\[i\]|\[\/i\]|\[u\]|\[\/u\])/g;
  const parts=raw.split(tokenRe);
  let html='';
  let colorOpen=false;
  parts.forEach(part=>{
    if(!part)return;
    let m=part.match(/^\[([0-9A-Fa-f]{6})\]$/);
    if(m){
      if(colorOpen) html+='</span>';
      html+='<span style="color:#'+m[1]+'">';
      colorOpen=true;
    }
    else if(part==='[b]'){ html+='<b>'; }
    else if(part==='[i]'){ html+='<i>'; }
    else if(part==='[u]'){ html+='<u>'; }
    else{ html+=neEscape(part); }
  });
  if(colorOpen) html+='</span>';
  return html;
}

function neUpdatePreview(){
  const inp=document.getElementById('neInput');
  const out=document.getElementById('neOutput');
  const cnt=document.getElementById('neCount');
  if(!inp||!out)return;
  const val=inp.value;
  cnt.textContent=val.length+' / 250';
  cnt.classList.toggle('warn',val.length>=250);
  out.innerHTML=val.trim()===''?'<span class="ne-empty">Preview akan muncul di sini...</span>':neParse(val);
  const copyBtn=document.getElementById('neCopyBtn');
  if(copyBtn)copyBtn.disabled=val.trim()==='';
}

function neClearInput(){
  const inp=document.getElementById('neInput');
  if(!inp||!inp.value)return;
  if(inp.value.trim().length>10 && !confirm('Hapus semua teks bio yang sudah kamu ketik?'))return;
  inp.value='';
  inp._neLastStart=0;inp._neLastEnd=0;
  neUpdatePreview();
  inp.focus();
}

function neWrap(open,close){
  const inp=document.getElementById('neInput');
  if(!inp)return;
  const start=inp._neLastStart!=null?inp._neLastStart:inp.value.length;
  const end=inp._neLastEnd!=null?inp._neLastEnd:inp.value.length;
  const val=inp.value;
  const selected=val.slice(start,end);
  const insertText=open+selected+close;
  const newVal=val.slice(0,start)+insertText+val.slice(end);
  if(newVal.length>250){
    inp.classList.remove('pc-shake');void inp.offsetWidth;inp.classList.add('pc-shake');
    inp.style.boxShadow='0 0 0 3px rgba(255,43,43,.35)';
    setTimeout(()=>{inp.style.boxShadow='';},900);
    return;
  }
  inp.value=newVal;
  inp.focus();
  const caret=start+insertText.length;
  inp.setSelectionRange(caret,caret);
  inp._neLastStart=caret;inp._neLastEnd=caret;
  neUpdatePreview();
}

function neInsertColor(hexColor){
  const inp=document.getElementById('neInput');
  if(!inp)return;
  const hex=hexColor.replace('#','').toUpperCase();
  const tag='['+hex+']';
  const start=inp._neLastStart!=null?inp._neLastStart:inp.value.length;
  const end=inp._neLastEnd!=null?inp._neLastEnd:inp.value.length;
  const val=inp.value;
  const newVal=val.slice(0,start)+tag+val.slice(end);
  if(newVal.length>250){
    inp.classList.remove('pc-shake');void inp.offsetWidth;inp.classList.add('pc-shake');
    inp.style.boxShadow='0 0 0 3px rgba(255,43,43,.35)';
    setTimeout(()=>{inp.style.boxShadow='';},900);
    return;
  }
  inp.value=newVal;
  inp.focus();
  const caret=start+tag.length;
  inp.setSelectionRange(caret,caret);
  inp._neLastStart=caret;inp._neLastEnd=caret;
  neUpdatePreview();
}

/* ── HSV (Hue / Saturation / Value) Custom Color Picker ── */
function neHsvToHex(h,s,v){
  s/=100; v/=100;
  const c=v*s;
  const x=c*(1-Math.abs((h/60)%2-1));
  const m=v-c;
  let r=0,g=0,b=0;
  if(h<60){r=c;g=x;b=0;}
  else if(h<120){r=x;g=c;b=0;}
  else if(h<180){r=0;g=c;b=x;}
  else if(h<240){r=0;g=x;b=c;}
  else if(h<300){r=x;g=0;b=c;}
  else{r=c;g=0;b=x;}
  const toHex=n=>Math.round((n+m)*255).toString(16).padStart(2,'0');
  return (toHex(r)+toHex(g)+toHex(b)).toUpperCase();
}

function neUpdateHsv(){
  const h=+document.getElementById('neHue').value;
  const s=+document.getElementById('neSat').value;
  const v=+document.getElementById('neVal').value;
  const hex=neHsvToHex(h,s,v);

  document.getElementById('neHueVal').textContent=h+'°';
  document.getElementById('neSatVal').textContent=s+'%';
  document.getElementById('neValVal').textContent=v+'%';
  document.getElementById('neHsvHex').textContent=hex;
  document.getElementById('neHsvPreview').style.background='#'+hex;

  // Update saturation & value slider gradients based on current hue
  const pureHue=neHsvToHex(h,100,100);
  document.getElementById('neSat').style.background=
    'linear-gradient(to right, #fff, #'+pureHue+')';
  document.getElementById('neVal').style.background=
    'linear-gradient(to right, #000, #'+pureHue+')';
}

