function neCopyCode(ev){
  const inp=document.getElementById('neInput');
  if(!inp||!inp.value)return;
  const btn=(ev&&ev.currentTarget)||document.querySelector('.ne-copy-btn');
  const showResult=(ok)=>{
    if(!btn)return;
    const old=btn.innerHTML;
    btn.innerHTML=ok?'<i class="fa-solid fa-check"></i> TERSALIN!':'<i class="fa-solid fa-xmark"></i> GAGAL, SALIN MANUAL';
    setTimeout(()=>{btn.innerHTML=old;},1600);
    if(ok)neShowCopyModal();
  };

  // Primary method: execCommand (paling kompatibel di webview/APK & konteks non-https)
  let copied=false;
  try{
    inp.focus();
    inp.setSelectionRange(0,inp.value.length);
    copied=document.execCommand('copy');
  }catch(e){ copied=false; }

  if(copied){
    inp.setSelectionRange(inp.value.length,inp.value.length);
    inp.blur();
    showResult(true);
    return;
  }

  // Fallback: Clipboard API modern (butuh secure context)
  if(navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(inp.value).then(()=>showResult(true)).catch(()=>showResult(false));
  }else{
    showResult(false);
  }
}

