let jgUidCheckTimer=null;
let jgUidCheckToken=0;
function scheduleJgUidCheck(uid){
  const box=document.getElementById('jgUidNickBox');
  if(!box) return;
  if(jgUidCheckTimer){clearTimeout(jgUidCheckTimer);jgUidCheckTimer=null;}
  const myToken=++jgUidCheckToken;
  if(uid.length<8||uid.length>13){
    box.style.display='none';
    box.className='jg-uid-nick-box';
    box.innerHTML='';
    return;
  }
  box.style.display='flex';
  box.className='jg-uid-nick-box state-loading';
  box.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i><span>Mengecek UID...</span>';
  jgUidCheckTimer=setTimeout(function(){
    fetchFFNickname(uid).then(function(nickname){
      if(myToken!==jgUidCheckToken) return;
      box.className='jg-uid-nick-box state-found';
      box.innerHTML='<i class="fa-solid fa-circle-check"></i><span>Nickname: '+nickname+'</span>';
    }).catch(function(e){
      if(myToken!==jgUidCheckToken) return;
      const msg=(e&&e.isNetwork)?'Gagal mengecek UID, coba lagi.':'UID tidak ditemukan.';
      box.className='jg-uid-nick-box state-error';
      box.innerHTML='<i class="fa-solid fa-triangle-exclamation"></i><span>'+msg+'</span>';
    });
  },250);
}
function jgUpdateProgress(){
  const get=function(id){return document.getElementById(id);};
  const checks=[
    !!get('jgName') && !!get('jgName').value.trim(),
    !!get('jgUid') && !!get('jgUid').value.trim(),
    !!get('jgLevel') && !!get('jgLevel').value,
    !!get('jgRankBR') && !!get('jgRankBR').value,
    !!get('jgRankCSR') && !!get('jgRankCSR').value,
    !!get('jgUmurAkun') && !!get('jgUmurAkun').value,
    jgSelectedPrime>=0,
    !!jgData.role,
    !!get('jgUmur') && !!get('jgUmur').value.trim(),
    !!jgData.gender,
    !!jgData.cn,
    !!get('jgNickname') && !!get('jgNickname').value.trim(),
    !!jgData.commit,
    !!jgData.aturan,
    !!jgData.kas,
    !!get('jgAlasan') && get('jgAlasan').value.trim().length>=50,
    !!get('jgConfirmCheck') && get('jgConfirmCheck').checked
  ];
  const filled=checks.filter(Boolean).length;
  const pct=Math.round((filled/checks.length)*100);
  const fill=get('jgProgressFill');
  const pctEl=get('jgProgressPct');
  if(fill) fill.style.width=pct+'%';
  if(pctEl) pctEl.textContent=pct+'%';
}

function jgCopyNickname(){
  const nameEl=document.getElementById('jgNickname');
  const btn=document.getElementById('jgCopyBtn');
  if(!nameEl || !nameEl.value.trim()) return;
  const text=nameEl.value.trim().toUpperCase()+' SDW';
  const done=function(){
    btn.classList.add('copied');
    btn.innerHTML='<i class="fa-solid fa-check"></i>';
    try{ navigator.vibrate && navigator.vibrate(30); }catch(e){}
    setTimeout(function(){
      btn.classList.remove('copied');
      btn.innerHTML='<i class="fa-regular fa-copy"></i>';
    },1400);
  };
  const fallbackCopy=function(){
    const ta=document.createElement('textarea');
    ta.value=text;document.body.appendChild(ta);ta.select();
    try{document.execCommand('copy');}catch(e){}
    document.body.removeChild(ta);done();
  };
  if(navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(text).then(done).catch(fallbackCopy);
  }else{
    fallbackCopy();
  }
}

function jgShake(el){
  if(!el)return;
  el.classList.remove('pc-shake');void el.offsetWidth;el.classList.add('pc-shake');
  el.style.borderColor='#ff2b2b';
  el.style.boxShadow='0 0 0 3px rgba(255,43,43,.22)';
  setTimeout(function(){el.style.boxShadow='';el.style.borderColor='';},900);
}
function jgOutline(el){
  if(!el)return;
  el.style.outline='1.5px solid #ff2b2b';el.style.borderRadius='13px';
  setTimeout(function(){el.style.outline='none';},900);
}

