/* Scramble animation */
function scramble(el,final,ms){
  const ch='0123456789';
  const len=Math.max(final.replace(/[^0-9]/g,'').length,3);
  const t=setInterval(()=>{
    el.textContent=Array.from({length:len},()=>ch[Math.floor(Math.random()*10)]).join('');
  },42);
  setTimeout(()=>{clearInterval(t);el.textContent=final;},ms);
}

/* Counter animation */
function counter(el,target,ms){
  const t0=performance.now();
  (function tick(now){
    const prog=Math.min((now-t0)/ms,1);
    const ease=1-Math.pow(1-prog,3);
    el.textContent='Rp '+Math.round(target*ease).toLocaleString('id-ID');
    if(prog<1)requestAnimationFrame(tick);
  })(performance.now());
}

function showResult(box,entries){
  box.classList.remove('show');void box.offsetWidth;box.classList.add('show');
  entries.forEach(([el,val,type])=>{
    if(type==='s') scramble(el,val,720);
    else{el.textContent='Rp 0';setTimeout(()=>counter(el,val,880),80);}
  });
}

