function prmGetDiamond(){
  var v=parseInt(localStorage.getItem('zusmo_diamond_balance'),10);
  return isNaN(v)?0:v;
}
function prmCalcLevel(diamond){
  var lvl=0;
  for(var i=0;i<primeLevels.length;i++){
    if(diamond>=primeLevels[i].dm) lvl=i+1; else break;
  }
  return lvl;
}
/* Riwayat naik level — dicatat di localStorage tiap kali level tertinggi berubah */
function prmGetHistory(){
  try{
    var raw=localStorage.getItem('zusmo_prime_history');
    var arr=raw?JSON.parse(raw):[];
    return Array.isArray(arr)?arr:[];
  }catch(e){return [];}
}
function prmSaveHistory(arr){
  try{localStorage.setItem('zusmo_prime_history',JSON.stringify(arr));}catch(e){}
}
function prmTrackLevelUp(level){
  var hist=prmGetHistory();
  var lastLvl=hist.length?hist[hist.length-1].level:0;
  if(level>lastLvl){
    for(var l=lastLvl+1;l<=level;l++){
      hist.push({level:l,name:primeLevels[l-1].name,ts:Date.now()});
    }
    prmSaveHistory(hist);
  }
  return hist;
}
function prmRenderHistory(hist){
  var list=document.getElementById('prmHistoryList');
  if(!list) return;
  if(!hist.length){
    list.innerHTML='<div class="prm-history-empty">Belum ada riwayat kenaikan level.</div>';
    return;
  }
  var html='';
  for(var i=hist.length-1;i>=0;i--){
    var h=hist[i];
    var tier=primeLevels[h.level-1];
    var d=new Date(h.ts);
    var dateStr=d.toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric'})+' &bull; '+d.toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'});
    html+='<div class="prm-history-item">'+
      '<img class="prm-history-icon" loading="lazy" decoding="async" src="'+(tier?tier.img:'')+'" alt="'+h.name+'"/>'+
      '<div class="prm-history-body">'+
        '<div class="prm-history-name">Naik ke '+h.name+'</div>'+
        '<div class="prm-history-date">'+dateStr+'</div>'+
      '</div>'+
    '</div>';
  }
  list.innerHTML=html;
}
/* Leaderboard Prime — pemain contoh (statis) dipadukan posisi kamu, diurut dari diamond terbanyak */
var PRM_LB_SAMPLE=[
  {name:'RzyGaming_ff',dm:1860000,lvl:8},
  {name:'ShadowXCloud',dm:1520000,lvl:8},
  {name:'DevilKing.ff',dm:980000,lvl:8},
  {name:'Zaqila_ff',dm:750000,lvl:8},
  {name:'NoobMaster99',dm:610000,lvl:8},
  {name:'Kirana_ff',dm:480000,lvl:8},
  {name:'AxelStorm_ff',dm:350000,lvl:8},
  {name:'Vhino.ff',dm:270000,lvl:8},
  {name:'Mikhaze_ff',dm:190000,lvl:8},
  {name:'Ghozy_ff',dm:125000,lvl:8},
];
function prmRenderLeaderboard(diamond,level){
  var list=document.getElementById('prmLbList');
  if(!list) return;
  var entries=PRM_LB_SAMPLE.map(function(e){return {name:e.name,dm:e.dm,lvl:e.lvl,me:false};});
  entries.push({name:'Kamu',dm:diamond,me:true});
  entries.sort(function(a,b){return b.dm-a.dm;});

  var html='';
  entries.forEach(function(e,i){
    var lvl=(typeof e.lvl==='number')?e.lvl:prmCalcLevel(e.dm);
    var tier=lvl>0?primeLevels[lvl-1]:null;
    var rank=i+1;
    var rankLabel=(e.me && rank>10)?'99+':rank;
    html+='<div class="prm-lb-item'+(e.me?' me':'')+'">'+
      '<div class="prm-lb-rank">'+rankLabel+'</div>'+
      (tier?'<img class="prm-lb-icon" loading="lazy" decoding="async" src="'+tier.img+'" alt="'+tier.name+'"/>':'<div class="prm-lb-icon"></div>')+
      '<div class="prm-lb-body">'+
        '<div class="prm-lb-name'+(e.me?' me':'')+'">'+e.name+'</div>'+
        '<div class="prm-lb-lvl">'+(tier?tier.name:'Belum Prime')+'</div>'+
      '</div>'+
      '<div class="prm-lb-dm"><img src="zusmo-asset/onzrii.png" alt="diamond"/>'+e.dm.toLocaleString('id-ID')+'</div>'+
    '</div>';
  });
  list.innerHTML=html;
}
function renderPrimePage(){
  var page=document.getElementById('prime');
  if(!page) return;
  var diamond=prmGetDiamond();
  var level=prmCalcLevel(diamond);
  var current=level>0?primeLevels[level-1]:null;
  var next=level<primeLevels.length?primeLevels[level]:null;

  var history=prmTrackLevelUp(level);
  prmRenderHistory(history);
  prmRenderLeaderboard(diamond,level);

  var barFill=document.getElementById('prmBarFill');
  var barText=document.getElementById('prmBarText');
  var totalEl=document.getElementById('prmDiamondTotal');

  prmActualLevel=level;
  prmBuildIconDots();
  prmApplyPreview(Math.max(level,1));
  if(totalEl) totalEl.textContent=diamond.toLocaleString('id-ID');

  if(next){
    var prevReq=current?current.dm:0;
    var span=next.dm-prevReq;
    var progressed=Math.max(0,diamond-prevReq);
    var pct=Math.min(100,Math.round((progressed/span)*100));
    if(barFill) barFill.style.width=pct+'%';
    if(barText) barText.innerHTML='<b>'+diamond.toLocaleString('id-ID')+'</b> / '+next.dm.toLocaleString('id-ID')+' Diamond menuju <i>'+next.name+'</i>';
  }else{
    if(barFill) barFill.style.width='100%';
    if(barText) barText.textContent='Level maksimum tercapai';
  }

  document.querySelectorAll('#prmBenefitList .prm-benefit').forEach(function(el){
    var need=parseInt(el.getAttribute('data-lvl'),10);
    var unlocked=level>=need;
    el.classList.toggle('unlocked',unlocked);
    el.classList.toggle('locked',!unlocked);
    var icn=el.querySelector('i');
    if(icn) icn.className='fa-solid '+(unlocked?'fa-circle-check':'fa-lock');
  });

  var grid=document.getElementById('prmTierGrid');
  if(grid && !grid.dataset.built){
    grid.dataset.built='1';
    primeLevels.forEach(function(t){
      var d=document.createElement('div');
      d.className='prm-tier';
      d.innerHTML='<img loading="lazy" decoding="async" src="'+t.img+'" alt="'+t.name+'"/><div class="prm-tier-name">'+t.name+'</div><div class="prm-tier-req">'+t.dm.toLocaleString('id-ID')+' DM</div>';
      grid.appendChild(d);
    });
  }
  if(grid){
    Array.prototype.forEach.call(grid.children,function(d,i){
      var achieved=level>=(i+1);
      d.classList.toggle('achieved',achieved);
      d.classList.toggle('locked',!achieved);
      d.classList.toggle('current',level===(i+1));
      var oldCheck=d.querySelector('.prm-tier-check');
      if(achieved && !oldCheck){
        var c=document.createElement('span');
        c.className='prm-tier-check';
        c.innerHTML='<i class="fa-solid fa-check"></i>';
        d.appendChild(c);
      }else if(!achieved && oldCheck){
        oldCheck.remove();
      }
    });
  }
}
function prmSwitchTab(panelId,btn){
  document.querySelectorAll('#prime .prm-panel').forEach(function(p){p.classList.toggle('active',p.id===panelId);});
  document.querySelectorAll('#prmTabbar .prm-tab-btn').forEach(function(b){b.classList.toggle('active',b===btn);});
}

/* ===== GESER LOGO PRIME: preview bebas level 1-8 (kiri & kanan), tidak mengubah level asli ===== */
var prmActualLevel=0;
var prmPreviewLevel=1;

function prmBuildIconDots(){
  var dots=document.getElementById('prmIconDots');
  if(!dots || dots.dataset.built) return;
  dots.dataset.built='1';
  var html='';
  for(var i=1;i<=primeLevels.length;i++){ html+='<span class="prm-icon-dot" data-lvl="'+i+'"></span>'; }
  dots.innerHTML=html;
}

function prmApplyPreview(lvl){
  lvl=Math.max(1,Math.min(primeLevels.length,lvl));
  prmPreviewLevel=lvl;
  var tier=primeLevels[lvl-1];
  var icon=document.getElementById('prmHeroIcon');
  var iconWrap=document.getElementById('prmIconWrap');
  var label=document.getElementById('prmIconLabel');
  var prevBtn=document.getElementById('prmIconPrev');
  var nextBtn=document.getElementById('prmIconNext');

  if(icon){
    icon.src=tier.img;
    icon.alt=tier.name;
    icon.classList.toggle('prm-hero-icon-locked', lvl>prmActualLevel);
  }
  if(iconWrap) iconWrap.setAttribute('data-level', String(lvl));
  if(label){
    var status=lvl===prmActualLevel && prmActualLevel>0 ? 'Level Kamu' : (lvl<=prmActualLevel ? 'Tercapai' : 'Terkunci');
    label.innerHTML=tier.name+' <span>'+status+'</span>';
  }
  if(prevBtn) prevBtn.disabled=(lvl<=1);
  if(nextBtn) nextBtn.disabled=(lvl>=primeLevels.length);
  document.querySelectorAll('#prmIconDots .prm-icon-dot').forEach(function(d){
    d.classList.toggle('active', parseInt(d.getAttribute('data-lvl'),10)===lvl);
  });
}

(function(){
  var wrap=document.getElementById('prmIconWrap');
  var icon=document.getElementById('prmHeroIcon');
  var prevBtn=document.getElementById('prmIconPrev');
  var nextBtn=document.getElementById('prmIconNext');
  if(!wrap || !icon) return;

  prevBtn && prevBtn.addEventListener('click', function(){ prmApplyPreview(prmPreviewLevel-1); });
  nextBtn && nextBtn.addEventListener('click', function(){ prmApplyPreview(prmPreviewLevel+1); });

  var dragging=false, startX=0, dx=0;
  var THRESHOLD=32;

  function onDown(x){
    dragging=true; startX=x; dx=0;
    icon.classList.add('prm-icon-swiping');
  }
  function onMove(x){
    if(!dragging) return;
    dx=x-startX;
    icon.style.transform='translateX('+(dx*.35)+'px)';
  }
  function onUp(){
    if(!dragging) return;
    dragging=false;
    icon.classList.remove('prm-icon-swiping');
    icon.style.transform='';
    if(dx>=THRESHOLD){ prmApplyPreview(prmPreviewLevel+1); }
    else if(dx<=-THRESHOLD){ prmApplyPreview(prmPreviewLevel-1); }
    dx=0;
  }

  wrap.addEventListener('pointerdown',function(e){ onDown(e.clientX); });
  wrap.addEventListener('pointermove',function(e){ onMove(e.clientX); });
  wrap.addEventListener('pointerup',onUp);
  wrap.addEventListener('pointercancel',onUp);
  wrap.addEventListener('pointerleave',function(){ if(dragging) onUp(); });
})();

