function zsFilterFaq(q){
var items=document.querySelectorAll('#faqPage .faq-item');
var query=(q||'').trim().toLowerCase();
var visible=0;
items.forEach(function(item){
var text=item.textContent.toLowerCase();
var match=!query||text.indexOf(query)!==-1;
item.classList.toggle('zs-hide',!match);
if(match)visible++;
});
var vc=document.getElementById('faqVisibleCount');
var tc=document.getElementById('faqTotalCount');
if(vc)vc.textContent=visible;
if(tc)tc.textContent=items.length;
var empty=document.getElementById('faqEmptyState');
if(empty)empty.classList.toggle('zs-show',visible===0);
}

var __pageBackStack=[];
