var __currentId=__current?__current.id:null;
if(__currentId){
  __pageScrollPos[__currentId]=window.scrollY||window.pageYOffset||0;
}
if(!fromBack && __currentId && __currentId!==id){
  __pageBackStack.push(__currentId);
}
