/* === HM NAME EDIT (max 12 karakter) === */
const HM_NAME_MAX=12;
(function(){
  const savedName=localStorage.getItem('hmDisplayName');
  if(savedName){
    const nameEl=document.getElementById('hmNameText');
    if(nameEl) nameEl.textContent=savedName;
  }
})();

let hmNameScrollY=0;

function hmLockScroll(){
  hmNameScrollY=window.scrollY||window.pageYOffset||0;
  document.documentElement.style.overscrollBehavior='none';
  document.body.style.position='fixed';
  document.body.style.top=(-hmNameScrollY)+'px';
  document.body.style.left='0';
  document.body.style.right='0';
  document.body.style.width='100%';
  document.body.style.overflow='hidden';
  document.addEventListener('touchmove',hmBlockScroll,{passive:false});
  document.addEventListener('wheel',hmBlockScroll,{passive:false});
}

function hmUnlockScroll(){
  document.documentElement.style.overscrollBehavior='';
  document.body.style.position='';
  document.body.style.top='';
  document.body.style.left='';
  document.body.style.right='';
  document.body.style.width='';
  document.body.style.overflow='';
  window.scrollTo(0,hmNameScrollY);
  document.removeEventListener('touchmove',hmBlockScroll,{passive:false});
  document.removeEventListener('wheel',hmBlockScroll,{passive:false});
}

function hmBlockScroll(e){
  // Blokir semua scroll/drag selagi popup terbuka, termasuk yang dimulai
  // dari dalam popup itu sendiri (popup tidak butuh scroll internal).
  if(e.touches && e.touches.length>1) return; // biarkan pinch-zoom gesture browser
  e.preventDefault();
}

function hmSyncOverlayViewport(){
  const overlay=document.getElementById('hmNameModalOverlay');
  if(!overlay||!overlay.classList.contains('show')) return;
  if(window.visualViewport){
    const vv=window.visualViewport;
    overlay.style.height=vv.height+'px';
    overlay.style.top=vv.offsetTop+'px';
  }else{
    overlay.style.height='100%';
    overlay.style.top='0';
  }
}
if(window.visualViewport){
  window.visualViewport.addEventListener('resize',hmSyncOverlayViewport);
  window.visualViewport.addEventListener('scroll',hmSyncOverlayViewport);
}

function openNameEditModal(){
  const overlay=document.getElementById('hmNameModalOverlay');
  const input=document.getElementById('hmNameInput');
  const nameEl=document.getElementById('hmNameText');
  const bar=document.querySelector('.app-bottombar');
  if(!overlay||!input) return;
  input.value=(nameEl?nameEl.textContent:'').trim();
  updateNameCount();
  overlay.classList.add('show');
  hmLockScroll();
  hmSyncOverlayViewport();
  if(bar){
    bar.style.setProperty('visibility','hidden','important');
    bar.style.setProperty('opacity','0','important');
  }
}

function closeNameEditModal(){
  const overlay=document.getElementById('hmNameModalOverlay');
  const input=document.getElementById('hmNameInput');
  const bar=document.querySelector('.app-bottombar');
  if(input) input.blur();
  if(overlay){
    overlay.classList.remove('show');
    overlay.style.height='';
    overlay.style.top='';
  }
  if(bar){
    bar.style.removeProperty('visibility');
    bar.style.removeProperty('opacity');
  }
  hmUnlockScroll();
}

function updateNameCount(){
  const input=document.getElementById('hmNameInput');
  const count=document.getElementById('hmNameCount');
  if(!input||!count) return;
  const len=input.value.length;
  count.textContent=len+' / '+HM_NAME_MAX;
  if(len>=HM_NAME_MAX){
    count.classList.add('limit-hit');
    input.classList.add('limit-hit');
  }else{
    count.classList.remove('limit-hit');
    input.classList.remove('limit-hit');
  }
}

function saveNameEdit(){
  const input=document.getElementById('hmNameInput');
  const nameEl=document.getElementById('hmNameText');
  if(!input) return;
  let val=input.value.trim().slice(0,HM_NAME_MAX);
  if(val.length===0) val='Guest';
  if(nameEl) nameEl.textContent=val;
  localStorage.setItem('hmDisplayName',val);
  closeNameEditModal();
}

/* ===== ADMIN PANEL ===== */
const AP_PASSWORD='151515';

function apOpenPasswordModal(){
  const overlay=document.getElementById('apPassModalOverlay');
  const input=document.getElementById('apPassInput');
  const err=document.getElementById('apPassError');
  const bar=document.querySelector('.app-bottombar');
  if(!overlay) return;
  if(input) input.value='';
  if(err) err.classList.remove('show');
  overlay.classList.add('show');
  hmLockScroll();
  hmSyncOverlayViewport();
  if(bar){
    bar.style.setProperty('visibility','hidden','important');
    bar.style.setProperty('opacity','0','important');
  }
  setTimeout(function(){ if(input) input.focus(); },50);
}

function apClosePasswordModal(){
  const overlay=document.getElementById('apPassModalOverlay');
  const input=document.getElementById('apPassInput');
  const bar=document.querySelector('.app-bottombar');
  if(input) input.blur();
  if(overlay){
    overlay.classList.remove('show');
    overlay.style.height='';
    overlay.style.top='';
  }
  if(bar){
    bar.style.removeProperty('visibility');
    bar.style.removeProperty('opacity');
  }
  hmUnlockScroll();
}

function apCheckPassword(){
  const input=document.getElementById('apPassInput');
  const err=document.getElementById('apPassError');
  const wrap=document.getElementById('apPassInputWrap');
  if(!input) return;
  if(input.value.trim()===AP_PASSWORD){
    if(err) err.classList.remove('show');
    apClosePasswordModal();
    setTimeout(apOpenPanelModal,180);
  }else{
    if(err) err.classList.add('show');
    if(wrap){
      wrap.classList.remove('shake');
      void wrap.offsetWidth;
      wrap.classList.add('shake');
    }
    input.value='';
    input.focus();
  }
}

function apOpenPanelModal(){
  const overlay=document.getElementById('apPanelModalOverlay');
  const bar=document.querySelector('.app-bottombar');
  if(!overlay) return;
  overlay.classList.add('show');
  hmLockScroll();
  hmSyncOverlayViewport();
  if(bar){
    bar.style.setProperty('visibility','hidden','important');
    bar.style.setProperty('opacity','0','important');
  }
}

function apClosePanelModal(){
  const overlay=document.getElementById('apPanelModalOverlay');
  const bar=document.querySelector('.app-bottombar');
  if(overlay){
    overlay.classList.remove('show');
    overlay.style.height='';
    overlay.style.top='';
  }
  if(bar){
    bar.style.removeProperty('visibility');
    bar.style.removeProperty('opacity');
  }
  hmUnlockScroll();
}

