/* ===== ADMIN PANEL: DIAMOND ===== */
var AP_DIAMOND_UNLIMITED=999999999;

function apResetDiamond(){
  if(typeof setDiamond==='function') setDiamond(0);
  apRefreshPrimeLevelGridState();
  apPrimeToast('Diamond berhasil direset ke 0');
}

function apUnlimitedDiamond(){
  if(typeof setDiamond==='function') setDiamond(AP_DIAMOND_UNLIMITED);
  apRefreshPrimeLevelGridState();
  apPrimeToast('Diamond diatur ke Unlimited');
}

function apToggleBebasDiamond(){
  var row=document.getElementById('apBebasDiamondRow');
  if(!row) return;
  var willShow=(row.style.display==='none' || !row.style.display);
  row.style.display=willShow?'flex':'none';
  if(willShow){
    var input=document.getElementById('apBebasDiamondInput');
    if(input){
      if(typeof getDiamond==='function') input.value=getDiamond();
      setTimeout(function(){ input.focus(); },50);
    }
  }
}

function apApplyBebasDiamond(){
  var input=document.getElementById('apBebasDiamondInput');
  if(!input) return;
  var val=parseInt(input.value,10);
  if(isNaN(val) || val<0){
    apPrimeToast('Masukkan angka yang valid');
    return;
  }
  if(typeof setDiamond==='function') setDiamond(val);
  apRefreshPrimeLevelGridState();
  apPrimeToast('Diamond diatur ke '+val.toLocaleString('id-ID'));
}
/* ===== END ADMIN PANEL: DIAMOND ===== */

/* ===== ADMIN PANEL: PRIME ===== */
function apPrimeToast(msg){
  var t=document.getElementById('apPrimeToast');
  if(!t){
    t=document.createElement('div');
    t.id='apPrimeToast';
    t.className='ap-prime-toast';
    document.body.appendChild(t);
  }
  t.textContent=msg;
  t.classList.remove('show');
  void t.offsetWidth;
  t.classList.add('show');
  clearTimeout(t._apHideTimer);
  t._apHideTimer=setTimeout(function(){ t.classList.remove('show'); },1800);
}

function apRefreshPrimeLevelGridState(){
  var grid=document.getElementById('apPrimeLevelGrid');
  if(!grid || typeof getDiamond!=='function' || typeof primeLevels==='undefined') return;
  var diamond=getDiamond();
  var activeIdx=-1;
  for(var i=0;i<primeLevels.length;i++){ if(diamond===primeLevels[i].dm) activeIdx=i; }
  grid.querySelectorAll('.ap-prime-lvl-btn').forEach(function(btn,idx){
    btn.classList.toggle('on', idx===activeIdx);
  });
}

var apBebasPrimeBuilt=false;
function apBuildBebasPrimeGrid(){
  var grid=document.getElementById('apPrimeLevelGrid');
  if(!grid || apBebasPrimeBuilt || typeof primeLevels==='undefined') return;
  primeLevels.forEach(function(p,i){
    var b=document.createElement('button');
    b.type='button';
    b.className='ap-prime-lvl-btn';
    b.innerHTML='<img loading="lazy" decoding="async" src="'+p.img+'" alt="'+p.name+'"><span>'+p.name+'</span>';
    b.onclick=function(){ apSetPrimeLevel(i+1); };
    grid.appendChild(b);
  });
  apBebasPrimeBuilt=true;
}

function apToggleBebasPrime(){
  apBuildBebasPrimeGrid();
  var grid=document.getElementById('apPrimeLevelGrid');
  if(!grid) return;
  var willShow=(grid.style.display==='none' || !grid.style.display);
  grid.style.display=willShow?'grid':'none';
  if(willShow) apRefreshPrimeLevelGridState();
}

function apResetPrime(){
  if(typeof setDiamond==='function') setDiamond(0);
  apRefreshPrimeLevelGridState();
  apPrimeToast('Prime berhasil direset ke 0');
}

function apPrimeMax(){
  var maxDm=200000;
  if(typeof primeLevels!=='undefined' && primeLevels.length) maxDm=primeLevels[primeLevels.length-1].dm;
  if(typeof setDiamond==='function') setDiamond(maxDm);
  apRefreshPrimeLevelGridState();
  apPrimeToast('Prime diatur ke MAX ('+maxDm.toLocaleString('id-ID')+')');
}

function apSetPrimeLevel(level){
  if(typeof primeLevels==='undefined' || !primeLevels[level-1]) return;
  var dm=primeLevels[level-1].dm;
  if(typeof setDiamond==='function') setDiamond(dm);
  apRefreshPrimeLevelGridState();
  apPrimeToast('Prime diatur ke Level '+level);
}
/* ===== END ADMIN PANEL: PRIME ===== */

document.addEventListener('DOMContentLoaded',function(){
  const apPassInput=document.getElementById('apPassInput');
  if(apPassInput){
    apPassInput.addEventListener('keydown',function(e){
      if(e.key==='Enter') apCheckPassword();
    });
  }
  const apBebasDiamondInput=document.getElementById('apBebasDiamondInput');
  if(apBebasDiamondInput){
    apBebasDiamondInput.addEventListener('keydown',function(e){
      if(e.key==='Enter') apApplyBebasDiamond();
    });
  }
});

document.addEventListener('DOMContentLoaded',function(){
  const input=document.getElementById('hmNameInput');
  const overlay=document.getElementById('hmNameModalOverlay');
  if(input){
    input.addEventListener('input',function(){
      if(this.value.length>HM_NAME_MAX) this.value=this.value.slice(0,HM_NAME_MAX);
      updateNameCount();
    });
    input.addEventListener('keydown',function(e){
      if(e.key==='Enter') saveNameEdit();
    });
  }
  if(overlay){
    overlay.addEventListener('click',function(e){
      if(e.target===overlay){
        e.preventDefault();
        e.stopPropagation();
      }
    });
    overlay.addEventListener('wheel',function(e){
      if(e.target===overlay) e.preventDefault();
    },{passive:false});
    overlay.addEventListener('touchmove',function(e){
      if(e.target===overlay) e.preventDefault();
    },{passive:false});
  }
});

/* === TIKTOK STEP LOGIC === */
var ttkClicked={1:false,2:false,3:false};
var ttkVerifying=false;

function showPasswordPopup(){
  ttkClicked={1:false,2:false,3:false};
  ttkVerifying=false;
  resetTtkButtons();
  document.getElementById('tiktokModal').style.display='flex';
}

function resetTtkButtons(){
  // Tombol 1 aktif, 2 & 3 dikunci
  var b1=document.getElementById('ttkBtn1');
  var b2=document.getElementById('ttkBtn2');
  var b3=document.getElementById('ttkBtn3');
  var lanjut=document.getElementById('ttkLanjutBtn');

  b1.disabled=false;
  b1.style.background='linear-gradient(135deg,#ff2b2b,#ff6b6b)';
  b1.style.color='#fff';
  b1.style.cursor='pointer';
  b1.innerHTML='<i class="fa-solid fa-heart" style="margin-right:8px"></i>Like';
  b1.onclick=function(){clickTiktokBtn(1);};

  b2.disabled=true;
  b2.style.background='#333';
  b2.style.color='#666';
  b2.style.cursor='not-allowed';
  b2.innerHTML='<i class="fa-solid fa-comment" style="margin-right:8px"></i>Komen';

  b3.disabled=true;
  b3.style.background='#333';
  b3.style.color='#666';
  b3.style.cursor='not-allowed';
  b3.innerHTML='🔗 Salin Tautan';

  lanjut.disabled=true;
  lanjut.style.background='#444';
  lanjut.style.color='#888';
  lanjut.style.cursor='not-allowed';
  lanjut.innerHTML='🔓 Lanjutkan';

  document.getElementById('ttkProgress').innerText='0 / 3 verifikasi';
}

function hideTiktokModal(){
  document.getElementById('tiktokModal').style.display='none';
}

function clickTiktokBtn(n){
  if(ttkVerifying) return;
  ttkVerifying=true;

  // Buka TikTok
  window.open('https://vt.tiktok.com/ZSCBa5hk8/','_blank');

  var btn=document.getElementById('ttkBtn'+n);
  // Loading state
  btn.disabled=true;
  btn.style.background='linear-gradient(135deg,#f0a500,#e08c00)';
  btn.style.color='#fff';
  btn.style.cursor='not-allowed';
  btn.innerHTML='<i class="fa-solid fa-spinner fa-spin" style="margin-right:8px"></i>Memverifikasi... 2s';

  // Countdown
  var sisa=2;
  var cd=setInterval(function(){
    sisa--;
    if(sisa>0){
      btn.innerHTML='<i class="fa-solid fa-spinner fa-spin" style="margin-right:8px"></i>Memverifikasi... '+sisa+'s';
    }
  },1000);

  setTimeout(function(){
    clearInterval(cd);
    // Hijau terverifikasi
    btn.style.background='linear-gradient(135deg,#1db954,#17a045)';
    btn.style.color='#fff';
    btn.innerHTML='<i class="fa-solid fa-circle-check" style="margin-right:8px"></i>✅ Terverifikasi!';
    ttkClicked[n]=true;
    ttkVerifying=false;

    var count=Object.values(ttkClicked).filter(Boolean).length;
    document.getElementById('ttkProgress').innerText=count+' / 3 tombol diklik';

    // Buka tombol berikutnya
    if(n<3){
      var next=document.getElementById('ttkBtn'+(n+1));
      next.disabled=false;
      next.style.background='linear-gradient(135deg,#ff2b2b,#ff6b6b)';
      next.style.color='#fff';
      next.style.cursor='pointer';
      next.onclick=function(){clickTiktokBtn(n+1);};
    }

    // Semua selesai → buka tombol Lanjutkan
    if(count>=3){
      var lanjut=document.getElementById('ttkLanjutBtn');
      lanjut.disabled=false;
      lanjut.style.background='linear-gradient(135deg,#ff2b2b,#ff6b6b)';
      lanjut.style.color='#fff';
      lanjut.style.cursor='pointer';
      lanjut.innerHTML='🔓 Lanjutkan Unlock';
      document.getElementById('ttkProgress').innerText='✅ Semua terverifikasi!';
    }
  },2000);
}

