/* ================= ISSUING KEY VIP OTOMATIS SAAT PEMBAYARAN SUKSES =================
   400 key total: index 0-99 = BASIC, 100-199 = ELITE, 200-299 = ULTIMATE, 300-399 = MAX.
   Key dipilih random dari range paket yg dibeli, dan dicatat di localStorage supaya
   tidak gampang muncul dobel di device yang sama. */
const VIP_TIER_RANGES={BASIC:[0,100],ELITE:[100,200],ULTIMATE:[200,300],MAX:[300,400]};
const LS_USED_VIP_KEYS='zusmoUsedVipKeys';
function formatVipKeyDisplay(raw){
  const body=raw.slice(3);
  return 'KZR-'+body.slice(0,4)+'-'+body.slice(4,8)+'-'+body.slice(8,12);
}
function getUsedVipKeys(){
  try{return JSON.parse(localStorage.getItem(LS_USED_VIP_KEYS))||[];}catch(e){return [];}
}
function markVipKeyUsed(raw){
  const used=getUsedVipKeys();
  if(used.indexOf(raw)===-1){
    used.push(raw);
    try{localStorage.setItem(LS_USED_VIP_KEYS,JSON.stringify(used));}catch(e){}
  }
}
function assignVipKey(tier){
  const range=VIP_TIER_RANGES[tier]||VIP_TIER_RANGES.BASIC;
  const used=getUsedVipKeys();
  let pool=[];
  for(let i=range[0];i<range[1];i++){
    if(used.indexOf(validKeys[i])===-1) pool.push(validKeys[i]);
  }
  if(pool.length===0){
    for(let i=range[0];i<range[1];i++) pool.push(validKeys[i]);
  }
  const raw=pool[Math.floor(Math.random()*pool.length)];
  markVipKeyUsed(raw);
  return raw;
}
function copyVipKeyResult(e){
  if(e) e.stopPropagation();
  const raw=vplSelected.assignedKeyRaw;
  if(!raw)return;
  const display=formatVipKeyDisplay(raw);
  const btn=document.getElementById('vpsKeyCopyBtn');
  const icon=btn?btn.querySelector('i'):null;
  const span=btn?btn.querySelector('span'):null;
  const done=function(){
    if(btn) btn.classList.add('copied');
    if(icon) icon.className='fa-solid fa-check';
    if(span) span.textContent='Tersalin';
    try{navigator.vibrate&&navigator.vibrate(30);}catch(err){}
    setTimeout(function(){
      if(btn) btn.classList.remove('copied');
      if(icon) icon.className='fa-regular fa-copy';
      if(span) span.textContent='Salin';
    },1400);
  };
  const fallback=function(){
    const ta=document.createElement('textarea');
    ta.value=display;document.body.appendChild(ta);ta.select();
    try{document.execCommand('copy');}catch(err){}
    document.body.removeChild(ta);done();
  };
  if(navigator.clipboard&&navigator.clipboard.writeText){
    navigator.clipboard.writeText(display).then(done).catch(fallback);
  }else{
    fallback();
  }
}

/* ================= RIWAYAT KEY VIP ================= */
const LS_VIP_KEY_HISTORY='zusmoVipKeyHistory';
const VIP_KEY_HISTORY_MAX=200;
function getVipKeyHistory(){
  try{return JSON.parse(localStorage.getItem(LS_VIP_KEY_HISTORY))||[];}catch(e){return [];}
}
function saveVipKeyHistoryEntry(entry){
  let list=getVipKeyHistory();
  list.unshift(entry);
  if(list.length>VIP_KEY_HISTORY_MAX) list=list.slice(0,VIP_KEY_HISTORY_MAX);
  try{localStorage.setItem(LS_VIP_KEY_HISTORY,JSON.stringify(list));}catch(e){}
}
function formatVkhDate(ts){
  const d=new Date(ts);
  const pad=n=>n<10?'0'+n:''+n;
  return pad(d.getDate())+'/'+pad(d.getMonth()+1)+'/'+d.getFullYear()+' '+pad(d.getHours())+':'+pad(d.getMinutes());
}
function renderVipKeyHistory(){
  const box=document.getElementById('vipKeyHistoryList');
  if(!box)return;
  const list=getVipKeyHistory();
  if(list.length===0){
    box.innerHTML='<div class="vkh-empty"><i class="fa-solid fa-key"></i><p>Belum ada Key VIP.<br>Key yang kamu dapat setelah pembelian akan muncul di sini.</p></div>';
    return;
  }
  let html='';
  list.forEach(function(it,i){
    html+='<div class="vkh-item '+it.tier+'">'+
      '<div class="vkh-top"><span class="vkh-tier '+it.tier+'">VIP '+it.tier+'</span><span class="vkh-date">'+formatVkhDate(it.ts)+'</span></div>'+
      '<div class="vkh-key-row"><div class="vkh-key-val">'+it.keyDisplay+'</div>'+
      '<button type="button" class="vkh-copy-btn" onclick="copyVkhKey(event,'+i+')"><i class="fa-regular fa-copy"></i></button></div>'+
      '<div class="vkh-meta">'+
      '<span>Order ID <b>'+it.orderId+'</b></span>'+
      '<span>UID <b>'+it.uid+'</b></span>'+
      '<span>Server <b>'+it.server+'</b></span>'+
      '</div></div>';
  });
  box.innerHTML=html+'<button type="button" class="vkh-clear-btn" onclick="clearVipKeyHistory()"><i class="fa-solid fa-trash"></i> Hapus Semua Riwayat</button>';
}
function copyVkhKey(e,idx){
  e.stopPropagation();
  const list=getVipKeyHistory();
  const it=list[idx];
  if(!it)return;
  const btn=e.currentTarget;
  const icon=btn.querySelector('i');
  const done=function(){
    btn.classList.add('copied');
    if(icon) icon.className='fa-solid fa-check';
    try{navigator.vibrate&&navigator.vibrate(30);}catch(err){}
    setTimeout(function(){
      btn.classList.remove('copied');
      if(icon) icon.className='fa-regular fa-copy';
    },1400);
  };
  const fallback=function(){
    const ta=document.createElement('textarea');
    ta.value=it.keyDisplay;document.body.appendChild(ta);ta.select();
    try{document.execCommand('copy');}catch(err){}
    document.body.removeChild(ta);done();
  };
  if(navigator.clipboard&&navigator.clipboard.writeText){
    navigator.clipboard.writeText(it.keyDisplay).then(done).catch(fallback);
  }else{
    fallback();
  }
}
function clearVipKeyHistory(){
  if(!confirm('Hapus semua riwayat Key VIP? Tindakan ini tidak bisa dibatalkan.'))return;
  try{localStorage.removeItem(LS_VIP_KEY_HISTORY);}catch(e){}
  renderVipKeyHistory();
}

function checkVipKey(){
 let key=document.getElementById('vipKey').value.toUpperCase().replace(/-/g,'').trim();
 let result=document.getElementById('vipResult');
 let input=document.getElementById('vipKey');
 const idx=validKeys.indexOf(key);
 if(idx!==-1){
   let role='BASIC',color='#a8a8a8';
   if(idx>=100&&idx<200){role='ELITE';color='#0a84ff';}
   else if(idx>=200&&idx<300){role='ULTIMATE';color='#A855F7';}
   else if(idx>=300){role='MAX';color='#ff3c3c';}
   localStorage.setItem('role',role);
   localStorage.setItem('roleColor',color);
   const badge=document.getElementById('roleBadge');
   if(badge){badge.textContent=role;badge.style.color=color;}
   result.className='successAnim';
   result.innerHTML='🎉 AKSES DITERIMA!<br>Selamat datang Member VIP';
   result.style.color='#00ff88';
   input.style.border='3px solid #00ff88';
   window.ZUSMO && window.ZUSMO.vibrate([100,50,100,50,300]);
   setTimeout(()=>window.open('https://whatsapp.com/channel/0029Vb8a3bU8V0tjsp1Orx0m','_blank'),1500);
 }else{
   result.innerHTML='❌ KEY VIP TIDAK VALID';
   result.style.color='#ff3b3b';
   input.classList.remove('shake');
   void input.offsetWidth;
   input.classList.add('shake');
   input.style.border='3px solid #ff3b3b';
   window.ZUSMO && window.ZUSMO.vibrate([200,100,200]);
 }
}

/* ===== VERIFIKASI KEY VIP UNTUK UPGRADE ZUSMO SHADOW ===== */
let upgSelected={from:'',to:'',price:0};
function ukvRoleFromIndex(idx){
  if(idx>=VIP_TIER_RANGES.MAX[0]) return 'MAX';
  if(idx>=VIP_TIER_RANGES.ULTIMATE[0]) return 'ULTIMATE';
  if(idx>=VIP_TIER_RANGES.ELITE[0]) return 'ELITE';
  return 'BASIC';
}
function openUpgradeKeyVerify(from,to,price){
  upgSelected={from:from,to:to,price:price};
  const pathEl=document.getElementById('ukvPathText');
  const priceEl=document.getElementById('ukvPriceText');
  if(pathEl) pathEl.textContent='VIP '+from+' \u2192 VIP '+to;
  if(priceEl) priceEl.textContent='Rp '+price.toLocaleString('id-ID');
  const input=document.getElementById('ukvKeyInput');
  if(input){input.value='';input.style.border='';input.classList.remove('shake');}
  const result=document.getElementById('ukvResult');
  if(result){result.innerHTML='';result.className='';}
  showPage('upgradeKeyVerify');
}
function checkUpgradeKey(){
  const inputEl=document.getElementById('ukvKeyInput');
  const resultEl=document.getElementById('ukvResult');
  if(!inputEl||!resultEl) return;
  const key=inputEl.value.toUpperCase().replace(/-/g,'').trim();
  const idx=validKeys.indexOf(key);
  if(idx===-1){
    resultEl.innerHTML='❌ KEY VIP TIDAK VALID';
    resultEl.style.color='#ff3b3b';
    inputEl.classList.remove('shake');
    void inputEl.offsetWidth;
    inputEl.classList.add('shake');
    inputEl.style.border='3px solid #ff3b3b';
    window.ZUSMO && window.ZUSMO.vibrate([200,100,200]);
    return;
  }
  const role=ukvRoleFromIndex(idx);
  if(role!==upgSelected.from){
    resultEl.innerHTML='⚠️ Key ini adalah VIP '+role+', bukan VIP '+upgSelected.from+'.<br>Upgrade ini khusus untuk pemilik VIP '+upgSelected.from+'.';
    resultEl.style.color='#ff3b3b';
    inputEl.classList.remove('shake');
    void inputEl.offsetWidth;
    inputEl.classList.add('shake');
    inputEl.style.border='3px solid #ff3b3b';
    window.ZUSMO && window.ZUSMO.vibrate([200,100,200]);
    return;
  }
  resultEl.className='successAnim';
  resultEl.innerHTML='🎉 KEY VALID!<br>Mengarahkan ke halaman pembayaran...';
  resultEl.style.color='#00ff88';
  inputEl.style.border='3px solid #00ff88';
  window.ZUSMO && window.ZUSMO.vibrate([100,50,100,50,300]);

  vplSelected.tier=upgSelected.to;
  vplSelected.price=upgSelected.price;
  vplSelected.payment=null;
  vplSelected.uid=key;
  vplSelected.server='ID';
  vplSelected.nickname='Upgrade dari VIP '+upgSelected.from;
  vplSelected.upgradeFrom=upgSelected.from;
  vplSelected.upgradeTo=upgSelected.to;

  document.querySelectorAll('.vpay-method').forEach(function(m){m.classList.remove('selected');});
  const confirmBtn=document.getElementById('vpayConfirmBtn');
  if(confirmBtn){confirmBtn.classList.remove('ready');confirmBtn.disabled=true;}

  const sT=document.getElementById('vpaySummaryTier');
  const sP=document.getElementById('vpaySummaryPrice');
  const sU=document.getElementById('vpaySummaryUid');
  const sN=document.getElementById('vpaySummaryNickname');
  if(sT) sT.textContent='VIP '+upgSelected.from+' \u27a1 VIP '+upgSelected.to;
  if(sP) sP.textContent='Rp '+upgSelected.price.toLocaleString('id-ID');
  if(sU) sU.textContent='Key VIP saat ini: '+key;
  if(sN) sN.textContent='Upgrade ke VIP '+upgSelected.to;

  setTimeout(function(){
    showPage('vippayment');
  },1000);
}

document.addEventListener('DOMContentLoaded',()=>{
 document.querySelectorAll('details').forEach(d=>{
   const s=d.querySelector('.faqArrow');
   const sync=()=>{ if(s) s.textContent=d.open?'▼':'▶'; };
   sync();
   d.addEventListener('toggle',sync);
 });
});

/* AUTO SLIDE BANNER */
const shadowBanners = [
'zusmo-asset/azd7bw.jpg',
'zusmo-asset/qv7019.jpg',
'zusmo-asset/kl35y3.jpg',
'zusmo-asset/jromt0.jpg'
];

let bannerIndex = 0;

document.addEventListener('DOMContentLoaded',()=>{
const banner=document.getElementById('shadowBanner');
if(!banner) return;

shadowBanners.forEach(url=>{
 const img=new Image();
 img.src=url;
});

banner.onerror=function(){
 bannerIndex=(bannerIndex+1)%shadowBanners.length;
 banner.src=shadowBanners[bannerIndex];
};

setInterval(()=>{
 banner.style.opacity='0';

 setTimeout(()=>{
   bannerIndex=(bannerIndex+1)%shadowBanners.length;
   banner.src=shadowBanners[bannerIndex];
   banner.style.opacity='1';
 },500);

},3000);

});

(function(){

const bar=document.querySelector('.app-bottombar');
if(!bar)return;

let indicator=document.createElement('div');
indicator.className='nav-indicator';
bar.appendChild(indicator);

const tabs=bar.querySelectorAll('.tab');

function moveIndicator(tab){
 let r=tab.getBoundingClientRect();
 let br=bar.getBoundingClientRect();

 indicator.style.width=r.width*.45+'px';
 indicator.style.left=(r.left-br.left+r.width/2-r.width*.225)+'px';
}

tabs.forEach(t=>{
 t.addEventListener('click',()=>{
  setTimeout(()=>moveIndicator(t),50);
 });
});

let active=bar.querySelector('.active');
if(active) moveIndicator(active);

})();

let oldScroll=0;

window.addEventListener('scroll',()=>{
 const bar=document.querySelector('.app-bottombar');
 if(!bar)return;

 let now=window.scrollY;

 if(now>oldScroll && now>40){
   bar.classList.add('hide');
 }else{
   bar.classList.remove('hide');
 }

 oldScroll=now;
});

(function(){
 const bar=document.querySelector('.app-bottombar');
 if(!bar)return;

 function updateActive(){
   bar.querySelectorAll('.tab').forEach(t=>{
     t.style.opacity = t.classList.contains('active') ? '1' : '.75';
   });
 }

 updateActive();

 new MutationObserver(updateActive)
 .observe(bar,{attributes:true,subtree:true,attributeFilter:['class']});

})();

document.addEventListener("click",function(e){

 let tab=e.target.closest(".tab, .app-bottombar button, .app-bottombar a");

 if(!tab) return;

 document.querySelectorAll(".app-bottombar .tab, .app-bottombar button, .app-bottombar a")
 .forEach(x=>{
   x.classList.remove("active");
   x.style.opacity=".75";
 });

 tab.classList.add("active");
 tab.style.opacity="1";

});

/* pastikan overlay tidak menutup banner */
document.querySelectorAll('.banner, .card, .preview').forEach(el=>{
 el.style.pointerEvents='auto';
});

document.querySelectorAll('.shadow-banner, .banner.shadow, .preview.shadow, .card.shadow-card')
.forEach(el=>{
 el.style.pointerEvents='none';
});

function openSideDrawer(){
  var overlay=document.getElementById('sideDrawerOverlay');
  if(!overlay) return;
  var name=document.getElementById('hmNameText');
  var role=document.getElementById('roleBadge');
  var avatar=document.querySelector('.hm-avatar');
  var diamond=document.getElementById('diamondBalanceTop');
  var sdName=document.getElementById('sdName');
  var sdRole=document.getElementById('sdRole');
  var sdAvatar=document.getElementById('sdAvatar');
  var sdDiamond=document.getElementById('sdDiamond');
  if(sdName && name) sdName.textContent=name.textContent;
  if(sdRole && role) sdRole.textContent=role.textContent;
  if(sdAvatar && avatar && avatar.src) sdAvatar.src=avatar.src;
  if(sdDiamond && diamond) sdDiamond.textContent=diamond.textContent;
  overlay.classList.add('open');
}
function closeSideDrawer(){
  var overlay=document.getElementById('sideDrawerOverlay');
  if(!overlay) return;
  overlay.classList.remove('open');
  setTimeout(function(){
    if(!overlay.classList.contains('open')) overlay.style.display='';
  },1000);
}
function toggleMenu(){
  var overlay=document.getElementById('sideDrawerOverlay');
  if(!overlay) return;
  if(overlay.classList.contains('open')) closeSideDrawer(); else openSideDrawer();
}
function sdPressAndClose(el,cb){
  if(el){
    el.classList.add('sd-pressed');
    setTimeout(function(){ el.classList.remove('sd-pressed'); },200);
  }
  if(cb) cb();
  closeSideDrawer();
}
function sdGo(page,el){
  sdPressAndClose(el,function(){ showPage(page); });
}

function openSettings(){ if(typeof openSettingsPanel==='function'){ openSettingsPanel(); } if(typeof markSettingsSeen==='function') markSettingsSeen(); }

