  /* ===================== RIWAYAT ORDER / TRANSAKSI DIAMOND ===================== */
  var LS_HISTORY  = 'zusmo_diamond_history';
  var HISTORY_MAX = 100;

  function getHistory(){
    try{
      var raw = JSON.parse(localStorage.getItem(LS_HISTORY) || '[]');
      if(!Array.isArray(raw)) raw = [];
      return raw;
    }catch(e){ return []; }
  }
  function addHistoryEntry(type, title, desc, amount){
    var list = getHistory();
    list.unshift({ type:type, title:title, desc:desc, amount:amount, ts:Date.now() });
    if(list.length > HISTORY_MAX) list = list.slice(0, HISTORY_MAX);
    try{ localStorage.setItem(LS_HISTORY, JSON.stringify(list)); }catch(e){}
    refreshOrderHistoryDot();
  }
  function formatHistoryDate(ts){
    var d = new Date(ts);
    var bulan = ['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'];
    var hh = d.getHours(), mm = d.getMinutes();
    return d.getDate()+' '+bulan[d.getMonth()]+' '+d.getFullYear()+', '+(hh<10?'0':'')+hh+':'+(mm<10?'0':'')+mm;
  }
  /* ===================== PROGRESS PAGE (UID acak, local storage only) ===================== */
  var LS_PROGRESS_ORDERS = 'zusmo_progress_orders';
  var PROGRESS_PRODUCTS  = ['Vip Zusmo Shadow','Suntik Like','Suntik Folls Craftland','Bot Glory'];
  // Bobot kemunculan produk di data progress: makin besar makin sering muncul.
  // Urutan terbanyak -> tersedikit: Vip Zusmo Shadow > Suntik Like > Suntik Folls Craftland > Bot Glory
  var PROGRESS_PRODUCT_WEIGHTS = {
    // Bobot ini cuma dipakai buat 3 produk non-Bot Glory (Bot Glory dibatasi terpisah, lihat buildProductPool)
    'Vip Zusmo Shadow':          70,
    'Suntik Like':                20,
    'Suntik Folls Craftland':     10
  };
  function buildProductPool(count){
    // Bot Glory dibatasi keras cuma 1-4 pesanan per hari, sisanya dibagi VIP ZS / Suntik Like / Suntik Folls CF pakai bobot
    var pool = [];
    var botCount = Math.min(1 + Math.floor(Math.random()*4), count); // 1-4
    for(var i=0;i<botCount;i++) pool.push('Bot Glory');
    var names = ['Vip Zusmo Shadow','Suntik Like','Suntik Folls Craftland'];
    var total = names.reduce(function(s,n){ return s + PROGRESS_PRODUCT_WEIGHTS[n]; }, 0);
    var remaining = count - botCount;
    for(var j=0;j<remaining;j++){
      var r = Math.random()*total, acc = 0;
      for(var k=0;k<names.length;k++){
        acc += PROGRESS_PRODUCT_WEIGHTS[names[k]];
        if(r <= acc){ pool.push(names[k]); break; }
      }
    }
    // acak urutan (Fisher-Yates) biar Bot Glory nggak selalu nangkring di awal array
    for(var s=pool.length-1;s>0;s--){
      var idx = Math.floor(Math.random()*(s+1));
      var tmp = pool[s]; pool[s] = pool[idx]; pool[idx] = tmp;
    }
    return pool;
  }
  var PROGRESS_PRICES = {
    'Suntik Like':               [5000,25000,60000,100000],
    'Bot Glory':                 [150000,300000,450000,600000],
    'Suntik Folls Craftland':    [150000,300000,450000,600000],
    'Vip Zusmo Shadow':          [3000,4000,7000,10000]
  };
  var VIP_TIER_INFO = {
    3000:  { name:'VIP BASIC',    cls:'vip-basic',    benefits:5 },
    4000:  { name:'VIP ELITE',    cls:'vip-elite',    benefits:6 },
    7000:  { name:'VIP ULTIMATE', cls:'vip-ultimate', benefits:7 },
    10000: { name:'VIP MAX',      cls:'vip-max',      benefits:9 }
  };
  // Distribusi order VIP Zusmo Shadow: makin tinggi tier makin sering dipilih (basic 10%, elite 20%, ultimate 30%, max 40%)
  var VIP_PRICE_WEIGHTS = [10,20,30,40]; // sejajar index dengan PROGRESS_PRICES['Vip Zusmo Shadow']
  function randVipPriceIdx(){
    var total = 0, i;
    for(i=0;i<VIP_PRICE_WEIGHTS.length;i++) total += VIP_PRICE_WEIGHTS[i];
    var r = Math.random()*total, cum = 0;
    for(i=0;i<VIP_PRICE_WEIGHTS.length;i++){
      cum += VIP_PRICE_WEIGHTS[i];
      if(r < cum) return i;
    }
    return VIP_PRICE_WEIGHTS.length-1;
  }
  var PROGRESS_LIKE_QTY  = [220,1100,3300,6600]; // sejajar index dengan PROGRESS_PRICES['Suntik Like']
  var PROGRESS_FOLLS_QTY = [600,1200,1800,2400]; // sejajar index dengan PROGRESS_PRICES['Suntik Folls Craftland']
  var PROGRESS_STATUSES  = ['pending','proses','sukses'];
  // UID pendek = akun lama/aktif -> like before cenderung banyak. UID panjang = akun baru -> like before sedikit.
  var LIKE_BEFORE_RANGE_BY_UIDLEN = {
    8:  [30000,50000],
    9:  [20000,35000],
    10: [10000,25000],
    11: [4000,12000],
    12: [1000,5000]
  };
  // Bot Glory: siklus mingguan serentak, mulai Senin 00:00 WIB, selesai Minggu 23:59 WIB (168 jam)
  var BOT_GLORY_POINT_BEFORE_MIN = 10000;
  var BOT_GLORY_POINT_BEFORE_MAX = 1000000;
  var BOT_GLORY_SQUAD_POINT_MIN  = 350000; // per 1 squad (4 bot)
  var BOT_GLORY_SQUAD_POINT_MAX  = 420000;

  // Siklus mingguan Bot Glory mulai Senin 05:00 WIB (bukan 00:00), selesai Senin berikutnya 05:00 WIB (168 jam)
  function getBotGloryUptimeElapsedHours(){
    var d = getWIBDateObj(); // getter WIB via getUTC* (lihat fungsi di bawah)
    var day = d.getUTCDay(); // 0=Minggu,1=Senin,...6=Sabtu
    var mondayIndex = (day+6)%7; // Senin=0 ... Minggu=6
    var hoursFromMonMidnight = mondayIndex*24 + d.getUTCHours() + d.getUTCMinutes()/60;
    var elapsed = hoursFromMonMidnight - 5; // geser start ke Senin 05:00 WIB
    if(elapsed < 0) elapsed += 168;
    if(elapsed > 168) elapsed = 168;
    if(elapsed < 0) elapsed = 0;
    return elapsed;
  }
  function getBotGloryWeekPercent(){
    var elapsed = getBotGloryUptimeElapsedHours();
    var percent = Math.round((elapsed/168)*100);
    if(percent>100) percent = 100;
    if(percent<0) percent = 0;
    return percent;
  }
  function formatBotGloryUptime(elapsedHours){
    var totalMinutes = Math.floor(elapsedHours*60);
    var days = Math.floor(totalMinutes/1440);
    var hours = Math.floor((totalMinutes%1440)/60);
    var minutes = totalMinutes%60;
    return days+'h '+hours+'j '+minutes+'m';
  }
  function rollBotGlorySquadCount(){
    // rata-rata hanya 1 squad, kadang 2 squad, tidak pernah 3/4 squad
    return Math.random() < 0.8 ? 1 : 2;
  }
  function rollBotGloryMembers(idLen){
    // format ##/##: gap antara digit awal & akhir harus dekat (ga boleh jauh"), dan lebih sering yang membernya banyak
    var multiples = [5,10,15,20,25,30,35,40,45,50,55];
    function pickLast(){
      // bobot naik sesuai besar angka -> lebih sering dapat member yang banyak/hampir penuh
      var total = 0, weights = multiples.map(function(v){ total += v; return v; });
      var r = Math.random()*total, cum = 0;
      for(var i=0;i<multiples.length;i++){ cum += weights[i]; if(r < cum) return multiples[i]; }
      return multiples[multiples.length-1];
    }
    var last = pickLast();
    // ID pendek (6,7,8 digit) -> makin sering member full/hampir full, tapi ga terlalu dominan
    var fullChance = idLen===6 ? 0.4 : idLen===7 ? 0.25 : idLen===8 ? 0.1 : 0;
    var gap;
    if(Math.random() < fullChance){
      if(last < 40) last = [45,50,55][Math.floor(Math.random()*3)];
      gap = Math.floor(Math.random()*2); // 0-1, hampir/pas penuh
    } else {
      // gap kecil biar deket (contoh boleh: 32/35, 49/50, 54/55, 22/25), bobot lebih besar ke gap kecil
      var gapWeights = [4,3,2,2,1]; // gap 1..5
      var totalW = 0; gapWeights.forEach(function(w){ totalW += w; });
      var r2 = Math.random()*totalW, cum2 = 0, gi = 4;
      for(var g=0; g<gapWeights.length; g++){ cum2 += gapWeights[g]; if(r2 < cum2){ gi = g; break; } }
      gap = gi+1; // 1..5
    }
    var first = last - gap;
    if(first < 1) first = 1;
    function pad2(n){ return (n<10?'0':'')+n; }
    return pad2(first)+'/'+pad2(last);
  }
  // Bot Glory pakai ID (bukan UID), panjang 6-9 digit, paling sering 9 lalu 8
  var BOT_GLORY_ID_LENGTH_TABLE = [[6,5],[7,12],[8,33],[9,50]];
  function randBotGloryIdLength(){
    var r = Math.random()*100, cum = 0;
    for(var i=0;i<BOT_GLORY_ID_LENGTH_TABLE.length;i++){
      cum += BOT_GLORY_ID_LENGTH_TABLE[i][1];
      if(r < cum) return BOT_GLORY_ID_LENGTH_TABLE[i][0];
    }
    return 9;
  }
  var PROGRESS_UID_TABLE = [[8,1],[9,4],[10,15],[11,30],[12,50]]; // panjang digit : bobot (dari 100)

  function randProgressUidLength(){
    var r = Math.random()*100, cum = 0;
    for(var i=0;i<PROGRESS_UID_TABLE.length;i++){
      cum += PROGRESS_UID_TABLE[i][1];
      if(r < cum) return PROGRESS_UID_TABLE[i][0];
    }
    return 12;
  }
  function generateMaskedUid(len){
    len = len || randProgressUidLength();
    var front = String(1+Math.floor(Math.random()*9)); // digit pertama tidak 0
    for(var i=0;i<3;i++) front += String(Math.floor(Math.random()*10));
    var back = '';
    for(var k=0;k<2;k++) back += String(Math.floor(Math.random()*10));
    var stars = '';
    for(var j=0;j<(len-6);j++) stars += '*';
    return front+stars+back;
  }
  // ID Bot Glory: cuma 2 digit depan & 2 digit belakang yang kebuka (bukan 4 digit depan seperti UID biasa)
  function generateBotGloryMaskedId(len){
    len = len || 9;
    var front = String(1+Math.floor(Math.random()*9)); // digit pertama tidak 0
    front += String(Math.floor(Math.random()*10)); // digit kedua
    var back = '';
    for(var k=0;k<2;k++) back += String(Math.floor(Math.random()*10));
    var stars = '';
    for(var j=0;j<(len-4);j++) stars += '*';
    return front+stars+back;
  }
  // Pola status Bot Glory per hari (WIB): Senin/Selasa -> sukses & proses (tanpa pending),
  // Sabtu/Minggu -> pending & proses (tanpa sukses), hari lain -> proses saja.
  function getBotGloryStatusPool(){
    var d = getWIBDateObj();
    var day = d.getUTCDay(); // 0=Minggu,1=Senin,...6=Sabtu
    if(day===1 || day===2) return ['sukses','proses'];
    if(day===6 || day===0) return ['pending','proses'];
    return ['proses'];
  }
  function progressStatusLabel(s){
    return s==='pending' ? 'Pending' : s==='sukses' ? 'Sukses' : 'Proses';
  }
  function progressStatusIcon(s){
    return s==='pending' ? 'fa-clock' : s==='sukses' ? 'fa-circle-check' : 'fa-hourglass-half';
  }
  function formatRupiah(n){
    return 'Rp '+String(n).replace(/\B(?=(\d{3})+(?!\d))/g,'.');
  }
  function formatCommaNum(n){
    return String(n).replace(/\B(?=(\d{3})+(?!\d))/g,',');
  }
  function getRandomLogoImg(){
    var idx = Math.floor(Math.random()*(LOGOS.length+1)); // +1 buat masukin logo default ke kolam acak (total 150)
    return idx===0 ? DEFAULT_LOGO_IMG : LOGOS[idx-1].img;
  }
  // ===== KODE PESANAN (nomor urut global, bertambah 100/hari sejak 01 Maret 2026) =====
  // Basis: 01 Mar 2026 = hari ke-1. Total kumulatif s/d akhir hari kemarin = (hariKe-1)*100.
  // Hari ini nambah bertahap 0->100 mengikuti jam berjalan (WIB 00:00 -> 23:59), bukan lompat langsung.
  var PROGRESS_CODE_EPOCH_UTC = Date.UTC(2026,2,1,0,0,0); // 01 Maret 2026, dihitung di kalender WIB
  var PROGRESS_CODE_PER_DAY = 100;
  function getProgressCodeDayIndex(){
    // hari ke berapa (1-based) dari epoch, berbasis tanggal kalender WIB
    var d = getWIBDateObj();
    var todayUTCMidnight = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate(), 0,0,0);
    var diffDays = Math.round((todayUTCMidnight - PROGRESS_CODE_EPOCH_UTC)/86400000);
    return diffDays + 1; // hari epoch sendiri = hari ke-1
  }
  function getProgressCodeTodayProgress(){
    // seberapa jauh hari ini berjalan (0..1), dipakai buat nambah kode 100/hari secara bertahap
    var d = getWIBDateObj();
    var msIntoDay = (d.getUTCHours()*3600 + d.getUTCMinutes()*60 + d.getUTCSeconds())*1000 + d.getUTCMilliseconds();
    return Math.min(1, msIntoDay/86400000);
  }
  function getProgressCodeState(){
    var dayIndex = getProgressCodeDayIndex();
    if(dayIndex < 1){ return { base:0, todayIssued:0, current:0 }; }
    var base = (dayIndex-1)*PROGRESS_CODE_PER_DAY; // total s/d akhir hari kemarin
    var todayIssued = Math.floor(getProgressCodeTodayProgress()*PROGRESS_CODE_PER_DAY); // nambah bertahap sepanjang hari ini
    return { base:base, todayIssued:todayIssued, current: base+todayIssued };
  }
  function formatProgressOrderCode(n){
    var s = String(Math.max(0,Math.floor(n)));
    while(s.length < 5) s = '0'+s;
    return '#'+s;
  }
  // Kasih kode urut ke tiap order berdasar urutan waktu (ts) terbaru -> terlama,
  // dimulai dari nomor kode paling baru (current) lalu mundur satu-satu ke bawah.
  function assignProgressOrderCodes(orders){
    var state = getProgressCodeState();
    var sorted = orders.slice().sort(function(a,b){ return b.ts - a.ts; });
    for(var i=0;i<sorted.length;i++){
      sorted[i].orderCode = Math.max(1, state.current - i);
    }
    return orders;
  }
  function generateProgressOrders(count){
    var arr = [];
    var productPool = buildProductPool(count);
    var botGloryUptimeStr = formatBotGloryUptime(getBotGloryUptimeElapsedHours()); // sama untuk semua order Bot Glory
    var botGloryElapsedPercent = getBotGloryWeekPercent(); // progress asli minggu berjalan, basis buat status "proses"
    for(var i=0;i<count;i++){
      var product = productPool[i];
      // Folls Craftland & Vip Zusmo Shadow: sistem otomatis -> selalu sukses, tidak ada proses/pending
      var status = (product==='Suntik Folls Craftland' || product==='Vip Zusmo Shadow') ? 'sukses' : PROGRESS_STATUSES[Math.floor(Math.random()*PROGRESS_STATUSES.length)];
      var uidLen = randProgressUidLength();
      var priceOptions = PROGRESS_PRICES[product];
      var priceIdx;
      if(product==='Vip Zusmo Shadow') priceIdx = randVipPriceIdx();
      else if(product==='Suntik Folls Craftland') priceIdx = 0; // layanan selain paket 600 followers/Rp150rb lagi error
      else priceIdx = Math.floor(Math.random()*priceOptions.length);
      var price = priceOptions[priceIdx];
      var percent = status==='pending' ? 0 : status==='sukses' ? 100 : (5+Math.floor(Math.random()*90));

      var order = {
        uid: generateMaskedUid(uidLen),
        logo: getRandomLogoImg(),
        product: product,
        price: price,
        status: status,
        percent: percent,
        ts: Date.now() - Math.floor(Math.random()*30*24*60*60*1000) // acak dalam 30 hari terakhir, buat sortir terbaru/terlama
      };

      if(product === 'Suntik Like'){
        // Dibeli = jumlah like yang dibeli, sejajar index dengan tier harga
        var dibeli = PROGRESS_LIKE_QTY[priceIdx];
        var totalSteps = Math.floor(dibeli/220); // rate pengiriman: 220 like per hari
        var sentSteps;
        if(status==='pending') sentSteps = 0;
        else if(status==='sukses') sentSteps = totalSteps;
        else sentSteps = totalSteps>1 ? (1+Math.floor(Math.random()*(totalSteps-1))) : 0;

        var dikirim = sentSteps*220;
        var tersisa = dibeli - dikirim;
        // like before terkait panjang uid: uid pendek -> like before lebih banyak, uid panjang -> like before sedikit
        var lbRange = LIKE_BEFORE_RANGE_BY_UIDLEN[uidLen] || [1000,50000];
        var likeBefore = lbRange[0] + Math.floor(Math.random()*(lbRange[1]-lbRange[0]+1));
        var likeAfter = likeBefore + dikirim;
        var realPercent = totalSteps>0 ? Math.round((sentSteps/totalSteps)*100) : (status==='sukses'?100:0);

        order.percent = realPercent; // progress bar disesuaikan dengan kalkulator dikirim, bukan asal acak
        order.likeBefore = likeBefore;
        order.likeAfter = likeAfter;
        order.dibeli = dibeli;
        order.dikirim = dikirim;
        order.tersisa = tersisa;
      }

      if(product === 'Suntik Folls Craftland'){
        // Sama seperti Suntik Like, tapi kelipatan pengiriman 600 followers & before selalu kecil (0-200 folls)
        var dibeliFolls = PROGRESS_FOLLS_QTY[priceIdx];
        var totalStepsFolls = Math.floor(dibeliFolls/600); // rate pengiriman: 600 followers per hari
        var sentStepsFolls;
        if(status==='pending') sentStepsFolls = 0;
        else if(status==='sukses') sentStepsFolls = totalStepsFolls;
        else sentStepsFolls = totalStepsFolls>1 ? (1+Math.floor(Math.random()*(totalStepsFolls-1))) : 0;

        var dikirimFolls = sentStepsFolls*600;
        var tersisaFolls = dibeliFolls - dikirimFolls;
        var follsBefore = Math.floor(Math.random()*201); // 0-200 folls
        var follsAfter = follsBefore + dikirimFolls;
        var realPercentFolls = totalStepsFolls>0 ? Math.round((sentStepsFolls/totalStepsFolls)*100) : (status==='sukses'?100:0);

        order.percent = realPercentFolls;
        order.follsBefore = follsBefore;
        order.follsAfter = follsAfter;
        order.dibeliFolls = dibeliFolls;
        order.dikirimFolls = dikirimFolls;
        order.tersisaFolls = tersisaFolls;
      }

      if(product === 'Bot Glory'){
        // Semua order Bot Glory serentak: mulai Senin 05:00 WIB, selesai Senin berikutnya, total 168 jam
        var squadCount = rollBotGlorySquadCount(); // 1 (mayoritas) atau 2, tidak pernah 3/4
        var pointTarget = 0;
        for(var s=0;s<squadCount;s++){
          pointTarget += BOT_GLORY_SQUAD_POINT_MIN + Math.floor(Math.random()*(BOT_GLORY_SQUAD_POINT_MAX-BOT_GLORY_SQUAD_POINT_MIN+1));
        }
        var pointBefore = BOT_GLORY_POINT_BEFORE_MIN + Math.floor(Math.random()*(BOT_GLORY_POINT_BEFORE_MAX-BOT_GLORY_POINT_BEFORE_MIN+1));
        // Status per hari (WIB): Senin/Selasa = sukses & proses, Sabtu/Minggu = pending & proses, hari lain = proses
        var bgPool = getBotGloryStatusPool();
        var bgStatus = bgPool[Math.floor(Math.random()*bgPool.length)];
        // Persen "proses" mengikuti waktu asli berjalan minggu ini (+jitter kecil per squad),
        // supaya point yang tampil selalu selaras: order 2 squad (~700rb-840rb target) tidak lagi
        // nyangkut di angka kecil kalau minggunya udah berjalan lama.
        var bgPercent;
        if(bgStatus==='pending') bgPercent = 0;
        else if(bgStatus==='sukses') bgPercent = 100;
        else {
          var jitter = -10 + Math.floor(Math.random()*21); // -10..+10
          bgPercent = botGloryElapsedPercent + jitter;
          if(bgPercent < 2) bgPercent = 2 + Math.floor(Math.random()*8); // lantai kecil kalau minggu baru mulai
          if(bgPercent > 98) bgPercent = 98; // status proses ga boleh nyentuh 100 (itu jatah "sukses")
        }
        var pointPlus = Math.round((bgPercent/100) * pointTarget); // sejajar dengan progress per order
        var pointAfter = pointBefore + pointPlus;
        var botGloryIdLen = randBotGloryIdLength(); // Bot Glory pakai ID (6-9 digit), bukan UID biasa

        order.uid = generateBotGloryMaskedId(botGloryIdLen); // ID khusus Bot Glory: 2 digit depan & 2 digit belakang kebuka
        order.percent = bgPercent;
        order.status = bgStatus;
        order.price = squadCount * 150000; // harga ikut jumlah squad asli (1 atau 2), bukan tier acak
        order.squadCount = squadCount;
        order.pointTarget = pointTarget;
        order.pointBefore = pointBefore;
        order.pointPlus = pointPlus;
        order.pointAfter = pointAfter;
        order.uptimeStr = botGloryUptimeStr;
        order.members = rollBotGloryMembers(botGloryIdLen); // ID makin pendek -> makin sering member penuh
        order.bgSchemaV = 4; // versi skema (persen proses selaras waktu asli + warna member/glory putih)
      }

      arr.push(order);
    }
    assignProgressOrderCodes(arr);
    return arr;
  }
  var PROGRESS_RESET_MS = 24*60*60*1000; // reset & acak ulang tiap 24 jam
  function getProgressOrders(){
    try{
      var raw = localStorage.getItem(LS_PROGRESS_ORDERS);
      if(raw){
        var parsed = JSON.parse(raw);
        if(parsed && Array.isArray(parsed.orders) && parsed.orders.length && typeof parsed.ts==='number'){
          var stillFresh = Date.now() - parsed.ts < PROGRESS_RESET_MS;
          var hasLogoField = !!parsed.orders[0].logo; // data lama (sebelum fitur logo) ga punya field ini
          var hasNewAssetPath = !parsed.orders[0].logo || parsed.orders[0].logo.indexOf('zusmo-asset/')===0; // data lama masih pakai path sebelum pindah ke folder zusmo-asset
          var hasMatchingLogoPool = parsed.logosCount === LOGOS.length; // data lama dibuat pas LOGOS masih beda jumlah (ada logo yg ditambah/dihapus) -> logo lama bisa nunjuk ke gambar yg udah gaada
          var hasValidProduct = PROGRESS_PRODUCTS.indexOf(parsed.orders[0].product) !== -1; // data lama pakai daftar produk lama
          var hasPriceField = typeof parsed.orders[0].price === 'number'; // data lama (sebelum fitur harga) ga punya field ini
          var hasFullCount = parsed.orders.length >= 175; // data lama cuma sampai 100 pesanan (skema lama), skema baru 175-250 acak per hari
          var likeOrder = parsed.orders.filter(function(o){ return o.product==='Suntik Like'; })[0];
          var hasLikeFields = !likeOrder || typeof likeOrder.dibeli === 'number'; // data lama belum punya field like
          var botOrder = parsed.orders.filter(function(o){ return o.product==='Bot Glory'; })[0];
          var hasBotGloryFields = !botOrder || (typeof botOrder.pointBefore === 'number' && typeof botOrder.members === 'string' && botOrder.bgSchemaV === 4); // data lama belum punya field point/member/id baru
          var follsOrder = parsed.orders.filter(function(o){ return o.product==='Suntik Folls Craftland'; })[0];
          var hasFollsFields = !follsOrder || typeof follsOrder.dibeliFolls === 'number'; // data lama belum punya field folls
          var follsOrders = parsed.orders.filter(function(o){ return o.product==='Suntik Folls Craftland'; });
          var vipOrders = parsed.orders.filter(function(o){ return o.product==='Vip Zusmo Shadow'; });
          var hasFollsAutoSukses = follsOrders.every(function(o){ return o.status==='sukses' && o.price===150000; }); // data lama masih ada proses/pending & harga selain 150rb
          var hasVipAutoSukses = vipOrders.every(function(o){ return o.status==='sukses'; }); // data lama masih ada proses/pending
          var hasTsField = typeof parsed.orders[0].ts === 'number'; // data lama belum punya field ts buat filter terbaru/terlama
          var hasOrderCode = typeof parsed.orders[0].orderCode === 'number'; // data lama belum punya kode pesanan
          if(stillFresh && hasLogoField && hasNewAssetPath && hasMatchingLogoPool && hasValidProduct && hasPriceField && hasFullCount && hasLikeFields && hasBotGloryFields && hasFollsFields && hasFollsAutoSukses && hasVipAutoSukses && hasTsField && hasOrderCode) return parsed.orders;
        }
      }
    }catch(e){}
    var fresh = generateProgressOrders(175 + Math.floor(Math.random()*76)); // acak 175-250 pesanan, berganti tiap 24 jam (ganti hari)
    try{ localStorage.setItem(LS_PROGRESS_ORDERS, JSON.stringify({ ts: Date.now(), orders: fresh, logosCount: LOGOS.length })); }catch(e){}
    return fresh;
  }
  var progressOrdersCache = null;
  var progressFilterState = { category:'all', sort:'semua', status:'all', search:'' };
  var PROGRESS_STATUS_RANK = { pending:0, proses:1, sukses:2 }; // urutan kemunculan alami: pending (baru) -> proses -> sukses (lama)
  window.renderProgressOrders = function(){
    var list = document.getElementById('progressOrderList');
    if(!list) return;
    progressOrdersCache = getProgressOrders();
    assignProgressOrderCodes(progressOrdersCache); // refresh kode tiap render biar nambah bertahap sepanjang hari, ga nunggu cache order reset 24 jam
    applyProgressFilterAndRender();
  };
  function applyProgressFilterAndRender(){
    var list = document.getElementById('progressOrderList');
    if(!list || !progressOrdersCache) return;
    var orders = progressOrdersCache.slice();
    if(progressFilterState.category !== 'all'){
      orders = orders.filter(function(o){ return o.product === progressFilterState.category; });
    }
    if(progressFilterState.status !== 'all'){
      orders = orders.filter(function(o){ return o.status === progressFilterState.status; });
    }
    if(progressFilterState.search){
      var q = progressFilterState.search.toLowerCase();
      orders = orders.filter(function(o){
        return (o.uid && o.uid.toLowerCase().indexOf(q)!==-1) || (o.product && o.product.toLowerCase().indexOf(q)!==-1);
      });
    }
    if(progressFilterState.sort==='terlama'){
      // Terlama: urut waktu dari yang paling lama duluan (kode pesanan ikut urut naik)
      orders.sort(function(a,b){ return a.ts - b.ts; });
    } else if(progressFilterState.sort==='terbaru'){
      // Terbaru: urut waktu dari yang paling baru duluan (kode pesanan ikut urut turun)
      orders.sort(function(a,b){ return b.ts - a.ts; });
    } else {
      // Semua: acak urutannya (kode pesanan jadi keliatan campur aduk, bukan urut)
      for(var s=orders.length-1;s>0;s--){
        var ridx = Math.floor(Math.random()*(s+1));
        var tmpO = orders[s]; orders[s] = orders[ridx]; orders[ridx] = tmpO;
      }
    }
    var totalEl = document.getElementById('progressTotalCount');
    if(totalEl) totalEl.textContent = orders.length;
    if(!orders.length){
      list.innerHTML = '<div class="prog-empty"><i class="fa-solid fa-box-open"></i><p>'+(progressFilterState.search ? 'Pesanan tidak ditemukan.' : 'Belum ada pesanan untuk kategori ini.')+'</p></div>';
      return;
    }
    list.innerHTML = orders.map(function(o, idx){
      var cardId = 'progCard-'+idx;
      return '<div class="prog-order-card" id="'+cardId+'">'+
        '<div class="prog-order-top">'+
          '<div class="prog-avatar"><img loading="lazy" decoding="async" class="'+((o.logo && o.logo!==DEFAULT_LOGO_IMG)?'logo-zoomed':'')+'" src="'+(o.logo||DEFAULT_LOGO_IMG)+'" alt=""/></div>'+
          '<div class="prog-order-info">'+
            '<div class="prog-order-uid">'+(o.product==='Bot Glory'?'ID':'UID')+': '+o.uid+'</div>'+
            '<div class="prog-order-product">'+o.product+'</div>'+
          '</div>'+
          '<div class="prog-order-badges">'+
            '<div class="prog-price-badge"><i class="fa-solid fa-tag"></i><span>'+formatRupiah(o.price)+'</span></div>'+
            '<div class="prog-status-badge status-'+o.status+'"><i class="fa-solid '+progressStatusIcon(o.status)+'"></i><span>'+progressStatusLabel(o.status)+'</span></div>'+
          '</div>'+
        '</div>'+
        '<div class="prog-bar-wrap">'+
          '<div class="prog-bar-labels"><span>Progress</span><span>'+o.percent+'%</span></div>'+
          '<div class="prog-bar-track'+(o.status==='pending'?' is-pending':'')+'"><div class="prog-bar-fill" style="width:'+o.percent+'%"></div></div>'+
        '</div>'+
        (o.product==='Suntik Like' ? (
          '<div class="prog-like-line">'+
            '<span class="pll-item"><span class="pll-val">'+formatCommaNum(o.likeBefore)+'❤️</span></span>'+
            '<span class="pll-item"><span class="pll-val pll-plus">+'+formatCommaNum(o.dikirim)+'❤️</span></span>'+
            '<span class="pll-item"><span class="pll-val">'+formatCommaNum(o.likeAfter)+'❤️</span></span>'+
          '</div>'+
          '<div class="prog-like-stats">'+
            '<div class="pls-item"><span class="pls-lbl">Dibeli</span><span class="pls-val pls-white">'+o.dibeli+'</span></div>'+
            '<div class="pls-item"><span class="pls-lbl">Dikirim</span><span class="pls-val pls-green">'+o.dikirim+'</span></div>'+
            '<div class="pls-item"><span class="pls-lbl">Tersisa</span><span class="pls-val pls-orange">'+o.tersisa+'</span></div>'+
          '</div>'
        ) : '') +
        (o.product==='Suntik Folls Craftland' ? (
          '<div class="prog-like-line">'+
            '<span class="pll-item"><span class="pll-val">'+formatCommaNum(o.follsBefore)+'👥</span></span>'+
            '<span class="pll-item"><span class="pll-val pll-plus">+'+formatCommaNum(o.dikirimFolls)+'👥</span></span>'+
            '<span class="pll-item"><span class="pll-val">'+formatCommaNum(o.follsAfter)+'👥</span></span>'+
          '</div>'+
          '<div class="prog-like-stats">'+
            '<div class="pls-item"><span class="pls-lbl">Dibeli</span><span class="pls-val pls-white">'+o.dibeliFolls+'</span></div>'+
            '<div class="pls-item"><span class="pls-lbl">Dikirim</span><span class="pls-val pls-green">'+o.dikirimFolls+'</span></div>'+
            '<div class="pls-item"><span class="pls-lbl">Tersisa</span><span class="pls-val pls-orange">'+o.tersisaFolls+'</span></div>'+
          '</div>'
        ) : '') +
        (o.product==='Bot Glory' ? (
          '<div class="bg-exp-block">'+
            '<div class="bg-exp-title">Exp Point Keaktifan</div>'+
            '<div class="prog-like-line bg-exp-line">'+
              '<span class="pll-item"><span class="pll-val">'+formatCommaNum(o.pointBefore)+'🏆</span></span>'+
              '<span class="pll-item"><span class="pll-val pll-plus">+'+formatCommaNum(o.pointPlus)+'🏆</span></span>'+
              '<span class="pll-item"><span class="pll-val">'+formatCommaNum(o.pointAfter)+'🏆</span></span>'+
            '</div>'+
            '<div class="prog-like-stats">'+
              '<div class="pls-item"><span class="pls-lbl">Uptime</span><span class="pls-val pls-white">'+o.uptimeStr+'</span></div>'+
              '<div class="pls-item"><span class="pls-lbl">Members</span><span class="pls-val pls-white">'+o.members+'</span></div>'+
              '<div class="pls-item"><span class="pls-lbl">Glory</span><span class="pls-val pls-white">'+formatCommaNum(o.pointAfter)+'🏆</span></div>'+
            '</div>'+
          '</div>'
        ) : '') +
        (o.product==='Vip Zusmo Shadow' ? (function(){
          var info = VIP_TIER_INFO[o.price] || VIP_TIER_INFO[3000];
          var checks = '';
          var chkCls = 'vip-chk'+(info.cls==='vip-max' ? ' vip-chk-max' : '');
          for(var c=0;c<info.benefits;c++){ checks += '<i class="fa-solid fa-circle-check '+chkCls+'"></i>'; }
          return '<div class="vip-tier-block">'+
            '<div class="vip-tier-name '+info.cls+'">'+info.name+'</div>'+
            '<div class="vip-check-row">'+checks+'</div>'+
          '</div>';
        })() : '') +
        '<button type="button" class="prog-dl-btn" data-html2canvas-ignore="true" onclick="downloadProgressCardPNG(\''+cardId+'\',this)"><i class="fa-solid fa-download"></i><span>Download Progress</span></button>'+
        '<div class="prog-order-code">'+formatProgressOrderCode(o.orderCode)+'</div>'+
      '</div>';
    }).join('');
  }
  window.downloadProgressCardPNG = function(cardId, btn){
    var card = document.getElementById(cardId);
    if(!card || typeof html2canvas === 'undefined') return;
    var btnEl = btn || card.querySelector('.prog-dl-btn');
    var btnLabel = btnEl ? btnEl.querySelector('span') : null;
    var originalLabel = btnLabel ? btnLabel.textContent : '';
    if(btnEl){ btnEl.classList.add('is-loading'); if(btnLabel) btnLabel.textContent = 'Memproses...'; }
    html2canvas(card, {
      backgroundColor: null,
      useCORS: true,
      logging: false,
      scale: 1
    }).then(function(canvas){
      try{
        var link = document.createElement('a');
        link.download = 'progress-'+cardId+'-'+Date.now()+'.png';
        link.href = canvas.toDataURL('image/png');
        link.click();
      }catch(err){
        if(btnEl){ btnEl.classList.remove('is-loading'); if(btnLabel) btnLabel.textContent = originalLabel; }
        openProgDownloadFailModal();
        return;
      }
      if(btnEl){
        btnEl.classList.remove('is-loading');
        btnEl.classList.add('is-done');
        if(btnLabel) btnLabel.textContent = 'Tersimpan!';
        setTimeout(function(){
          btnEl.classList.remove('is-done');
          if(btnLabel) btnLabel.textContent = originalLabel;
        }, 1800);
      }
      if(window.ZUSMO && window.ZUSMO.playClick) window.ZUSMO.playClick();
    }).catch(function(){
      if(btnEl){ btnEl.classList.remove('is-loading'); if(btnLabel) btnLabel.textContent = originalLabel; }
      openProgDownloadFailModal();
    });
  };
  window.pfDigitInput = function(el){
    el.value = el.value.replace(/[^0-9]/g,'').slice(0,1);
    el.classList.remove('pf-err');
    if(el.value){
      var next = el.nextElementSibling;
      if(next && next.classList.contains('prog-find-digit')) next.focus();
    }
    var msg = document.getElementById('progFindMsg');
    if(msg){ msg.textContent=''; msg.classList.remove('pf-msg-err'); }
  };
  window.pfDigitKeydown = function(e, el){
    if(e.key==='Backspace' && !el.value){
      var prev = el.previousElementSibling;
      if(prev && prev.classList.contains('prog-find-digit')){ prev.focus(); prev.value=''; }
    }
  };
  // Placeholder pencarian pesanan berdasarkan kode 5 digit.
  // TODO: sambungkan ke sistem/card pesanan custom di sini.
  window.submitProgressOrderCode = function(){
    var digits = document.querySelectorAll('#progFindCodeRow .prog-find-digit');
    var code = '';
    var allFilled = true;
    digits.forEach(function(d){
      if(!d.value) allFilled = false;
      code += d.value;
    });
    var msg = document.getElementById('progFindMsg');
    if(!allFilled){
      digits.forEach(function(d){ if(!d.value) d.classList.add('pf-err'); });
      if(msg){ msg.textContent = 'Lengkapi 5 digit kode pesanan dulu ya.'; msg.classList.add('pf-msg-err'); }
      if(window.ZUSMO && window.ZUSMO.playClick) window.ZUSMO.playClick();
      return;
    }
    if(typeof window.onProgressOrderCodeSubmit === 'function'){
      window.onProgressOrderCodeSubmit(code);
    } else if(msg){
      msg.textContent = 'Pesanan tidak ditemukan.';
      msg.classList.add('pf-msg-err');
    }
    if(window.ZUSMO && window.ZUSMO.playClick) window.ZUSMO.playClick();
  };
  window.openProgFindModal = function(){
    var overlay = document.getElementById('progFindOverlay');
    if(!overlay) return;
    overlay.classList.add('show');
    var digits = document.querySelectorAll('#progFindCodeRow .prog-find-digit');
    digits.forEach(function(d){ d.value=''; d.classList.remove('pf-err'); });
    var msg = document.getElementById('progFindMsg');
    if(msg){ msg.textContent=''; msg.classList.remove('pf-msg-err'); }
    if(digits[0]) setTimeout(function(){ digits[0].focus(); }, 250);
    if(window.ZUSMO && window.ZUSMO.playClick) window.ZUSMO.playClick();
  };
  window.closeProgFindModal = function(){
    var overlay = document.getElementById('progFindOverlay');
    if(overlay) overlay.classList.remove('show');
    if(window.ZUSMO && window.ZUSMO.playClick) window.ZUSMO.playClick();
  };
  window.openProgDownloadFailModal = function(){
    var overlay = document.getElementById('progDlFailOverlay');
    if(overlay) overlay.classList.add('show');
  };
  window.closeProgDownloadFailModal = function(){
    var overlay = document.getElementById('progDlFailOverlay');
    if(overlay) overlay.classList.remove('show');
  };
  window.copyProgDownloadLink = function(){
    var link = 'https://zusmoshadowx20.vercel.app';
    var icon = document.getElementById('progDlFailCopyIcon');
    function markCopied(){
      if(!icon) return;
      icon.classList.add('copied');
      icon.innerHTML = '<i class="fa-solid fa-check"></i>';
      setTimeout(function(){
        icon.classList.remove('copied');
        icon.innerHTML = '<i class="fa-regular fa-copy"></i>';
      }, 1600);
    }
    if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(link).then(markCopied).catch(function(){
        fallbackCopyProgLink(link, markCopied);
      });
    } else {
      fallbackCopyProgLink(link, markCopied);
    }
    if(window.ZUSMO && window.ZUSMO.playClick) window.ZUSMO.playClick();
  };
  function fallbackCopyProgLink(link, cb){
    var ta = document.createElement('textarea');
    ta.value = link;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    try{ document.execCommand('copy'); cb(); }catch(e){}
    document.body.removeChild(ta);
  }
  window.toggleProgressFilterPopup = function(e){
    if(e) e.stopPropagation();
    var popup = document.getElementById('progFilterPopup');
    if(!popup) return;
    var willOpen = !popup.classList.contains('open');
    popup.classList.toggle('open', willOpen);
    if(window.ZUSMO && window.ZUSMO.playClick) window.ZUSMO.playClick();
  };
  window.setProgressSort = function(btn, sortVal){
    progressFilterState.sort = sortVal;
    var opts = document.querySelectorAll('#progFilterPopup [data-sort]');
    for(var i=0;i<opts.length;i++){ opts[i].classList.toggle('on', opts[i]===btn); }
    applyProgressFilterAndRender();
    if(window.ZUSMO && window.ZUSMO.playClick) window.ZUSMO.playClick();
  };
  window.setProgressCategory = function(btn, cat){
    progressFilterState.category = cat;
    var opts = document.querySelectorAll('#progFilterPopup [data-cat]');
    for(var i=0;i<opts.length;i++){ opts[i].classList.toggle('on', opts[i]===btn); }
    applyProgressFilterAndRender();
    if(window.ZUSMO && window.ZUSMO.playClick) window.ZUSMO.playClick();
  };
  window.setProgressStatus = function(btn, st){
    progressFilterState.status = st;
    var opts = document.querySelectorAll('#progFilterPopup [data-status]');
    for(var i=0;i<opts.length;i++){ opts[i].classList.toggle('on', opts[i]===btn); }
    applyProgressFilterAndRender();
    if(window.ZUSMO && window.ZUSMO.playClick) window.ZUSMO.playClick();
  };
  window.onProgressSearchInput = function(val){
    progressFilterState.search = (val||'').trim();
    var clearBtn = document.getElementById('progSearchClear');
    if(clearBtn) clearBtn.style.display = progressFilterState.search ? 'flex' : 'none';
    applyProgressFilterAndRender();
  };
  window.clearProgressSearch = function(){
    var input = document.getElementById('progSearchInput');
    if(input) input.value = '';
    window.onProgressSearchInput('');
    if(window.ZUSMO && window.ZUSMO.playClick) window.ZUSMO.playClick();
  };
  document.addEventListener('click', function(e){
    var wrap = document.getElementById('progFilterWrap');
    var popup = document.getElementById('progFilterPopup');
    if(popup && wrap && !wrap.contains(e.target)) popup.classList.remove('open');
  });

  function renderOrderHistory(){
    var box = document.getElementById('orderHistoryList');
    if(!box) return;
    var list = getHistory();
    if(!list.length){
      box.innerHTML = '<div class="oh-empty"><i class="fa-solid fa-receipt"></i><p>Belum ada riwayat transaksi Diamond.</p></div>';
      return;
    }
    var iconMap = { buy:'fa-bag-shopping', claim:'fa-gift', redeem:'fa-ticket', mission:'fa-list-check' };
    var html = '';
    for(var i=0;i<list.length;i++){
      var it = list[i];
      var plus = it.amount >= 0;
      html += '<div class="oh-item">'+
                '<div class="oh-icon '+it.type+'"><i class="fa-solid '+(iconMap[it.type]||'fa-circle-info')+'"></i></div>'+
                '<div class="oh-body"><h5>'+it.title+'</h5><small>'+it.desc+' &middot; '+formatHistoryDate(it.ts)+'</small></div>'+
                '<div class="oh-amt '+(plus?'plus':'minus')+'">'+(plus?'+':'')+it.amount+'<img loading="lazy" decoding="async" src="'+DIAMOND_ICON+'" alt=""/></div>'+
              '</div>';
    }
    box.innerHTML = html;
  }
  function renderRedeemPageHistory(){
    var box = document.getElementById('redeemPageHistoryList');
    if(!box) return;
    var list = getHistory().filter(function(it){ return it.type === 'redeem'; });
    if(!list.length){
      box.innerHTML = '<div class="rdp-history-empty"><i class="fa-solid fa-ticket"></i><p>Belum ada kode redeem yang diklaim.</p></div>';
      return;
    }
    var html = '';
    for(var i=0;i<list.length;i++){
      var it = list[i];
      var plus = it.amount >= 0;
      var amtHtml = it.amount === 0 ? '' :
        '<div class="oh-amt '+(plus?'plus':'minus')+'" style="margin-left:auto;flex-shrink:0;">'+(plus?'+':'')+it.amount+'<img loading="lazy" decoding="async" src="'+DIAMOND_ICON+'" alt=""/></div>';
      html += '<div class="rdp-history-item">'+
                '<div class="rdp-history-icon"><i class="fa-solid fa-ticket"></i></div>'+
                '<div class="rdp-history-body"><h5>'+it.title+'</h5><small>'+it.desc+' &middot; '+formatHistoryDate(it.ts)+'</small></div>'+
                amtHtml+
              '</div>';
    }
    box.innerHTML = html;
  }
  function refreshOrderHistoryDot(){
    var dot = document.getElementById('orderHistoryDot');
    if(!dot) return;
    var seen = parseInt(localStorage.getItem('zusmo_seen_history_count'), 10) || 0;
    dot.classList.toggle('dot-show', getHistory().length > seen);
  }
