  // --- WIB (UTC+7) date helpers, resets at 00:00 WIB ---
  // Uses absolute UTC epoch time (Date.getTime() is always UTC-based),
  // so this works correctly no matter what timezone the device itself is set to.
  function getWIBDateObj(){
    var now = new Date();
    return new Date(now.getTime() + 7*3600000);
  }
  function getWIBDateStr(){
    var d = getWIBDateObj();
    return d.getUTCFullYear()+'-'+(d.getUTCMonth()+1)+'-'+d.getUTCDate();
  }
  function daysBetweenWIB(dateStrA, dateStrB){
    function parse(s){ var p=s.split('-'); return Date.UTC(+p[0], +p[1]-1, +p[2]); }
    return Math.round((parse(dateStrB)-parse(dateStrA))/86400000);
  }
  function msUntilNextWIBMidnight(){
    var d = getWIBDateObj();
    var nextMidnightUTC = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()+1, 0,0,0);
    var nowUTCasWIB = d.getTime();
    return nextMidnightUTC - nowUTCasWIB;
  }

  function hasClaimedToday(){
    return localStorage.getItem(LS_CLAIM_LAST) === getWIBDateStr();
  }
  function getClaimStreak(){
    var v = parseInt(localStorage.getItem(LS_CLAIM_STREAK), 10);
    return isNaN(v) ? 0 : v;
  }

  function updateDiamondDot(){
    var dot = document.getElementById('diamondDot');
    if(!dot) return;
    var hasReward = !hasClaimedToday() || (typeof hasUnclaimedCompletedMission === 'function' && hasUnclaimedCompletedMission());
    dot.classList.toggle('dot-show', hasReward);
  }
  window.updateDiamondDot = updateDiamondDot;
  document.addEventListener('DOMContentLoaded', updateDiamondDot);
  setInterval(updateDiamondDot, 30000);

  window.doClaimDaily = function(){
    if(hasClaimedToday()) return;
    var today = getWIBDateStr();
    var lastDate = localStorage.getItem(LS_CLAIM_LAST);
    var streak = getClaimStreak();
    if(lastDate && daysBetweenWIB(lastDate, today) === 1){
      streak = streak >= 7 ? 1 : streak + 1;
    } else {
      streak = 1;
    }
    localStorage.setItem(LS_CLAIM_LAST, today);
    localStorage.setItem(LS_CLAIM_STREAK, String(streak));
    setDiamond(getDiamond() + DAILY_CLAIM_AMOUNT);
    addHistoryEntry('claim', 'Klaim Diamond Harian', 'Hari ke-'+streak, DAILY_CLAIM_AMOUNT);
    renderDailyClaimUI();
    updateDiamondDot();
    if(typeof progressMission === 'function') progressMission('claim_daily', 1);
    if(window.ZUSMO && window.ZUSMO.playClick) window.ZUSMO.playClick();
  };

  function renderDailyClaimUI(){
    var grid = document.getElementById('claimWeekGrid');
    if(!grid) return;
    var claimedToday = hasClaimedToday();
    updateDiamondDot();
    var streak = getClaimStreak();
    var currentSlot = claimedToday ? streak : (streak >= 7 ? 1 : streak + 1);
    var html = '';
    for(var day=1; day<=7; day++){
      var doneClass = '';
      if(day < currentSlot || (day === currentSlot && claimedToday)) doneClass = ' done';
      var todayClass = (day === currentSlot && !claimedToday) ? ' today' : '';
      html += '<div class="claim-day'+doneClass+todayClass+'">'+
                '<div class="cd-check"><i class="fa-solid fa-check"></i></div>'+
                '<div class="cd-label">Hari '+day+'</div>'+
                '<div class="cd-amt">'+DAILY_CLAIM_AMOUNT+'</div>'+
              '</div>';
    }
    grid.innerHTML = html;

    var btn = document.getElementById('claimMainBtn');
    var btnText = document.getElementById('claimMainBtnText');
    var countdown = document.getElementById('claimCountdownText');
    if(claimedToday){
      btn.disabled = true;
      btnText.textContent = 'Sudah Diklaim Hari Ini';
      startClaimCountdown();
    } else {
      btn.disabled = false;
      btnText.textContent = 'Klaim '+DAILY_CLAIM_AMOUNT+' Diamond';
      if(countdown) countdown.textContent = '';
      if(window._claimCountdownTimer) clearInterval(window._claimCountdownTimer);
    }
  }

  function startClaimCountdown(){
    var countdown = document.getElementById('claimCountdownText');
    if(!countdown) return;
    if(window._claimCountdownTimer) clearInterval(window._claimCountdownTimer);
    function tick(){
      var ms = msUntilNextWIBMidnight();
      if(ms <= 0){ renderDailyClaimUI(); return; }
      var h = Math.floor(ms/3600000);
      var m = Math.floor((ms%3600000)/60000);
      var s = Math.floor((ms%60000)/1000);
      countdown.textContent = 'Reset dalam '+(h<10?'0':'')+h+':'+(m<10?'0':'')+m+':'+(s<10?'0':'')+s+' (WIB)';
    }
    tick();
    window._claimCountdownTimer = setInterval(tick, 1000);
  }

