  // Animate a number counting down/up across every diamond balance display
  function zxAnimateDiamondCount(from, to, duration){
    var els = [document.getElementById('diamondBalanceTop'), document.getElementById('diamondBalanceBack'), document.getElementById('bannerDetailDiamondBalance'), document.getElementById('shopDiamondBalance'), document.getElementById('eventDiamondBalance')].filter(Boolean);
    if(!els.length || from === to){ return; }
    var startTime = null;
    function step(ts){
      if(!startTime) startTime = ts;
      var progress = Math.min((ts - startTime) / duration, 1);
      var eased = 1 - Math.pow(1 - progress, 3);
      var current = Math.round(from + (to - from) * eased);
      els.forEach(function(el){ el.textContent = current; });
      if(progress < 1) requestAnimationFrame(step); else els.forEach(function(el){ el.textContent = to; });
    }
    requestAnimationFrame(step);
  }

  // Small confetti burst centered on a modal, purely decorative
  function zxSpawnConfetti(container){
    if(!container) return;
    var colors = ['#ff2b2b','#ffd166','#00e676','#4da3ff','#ffffff'];
    for(var i=0;i<14;i++){
      var piece = document.createElement('span');
      piece.className = 'zx-confetti-piece';
      var angle = Math.random() * Math.PI * 2;
      var dist = 60 + Math.random() * 70;
      piece.style.setProperty('--zx-x', (Math.cos(angle) * dist) + 'px');
      piece.style.setProperty('--zx-y', (Math.sin(angle) * dist - 20) + 'px');
      piece.style.setProperty('--zx-r', (Math.random() * 360 - 180) + 'deg');
      piece.style.background = colors[i % colors.length];
      piece.style.animationDelay = (Math.random() * 0.08) + 's';
      container.appendChild(piece);
      (function(el){ setTimeout(function(){ if(el.parentNode) el.parentNode.removeChild(el); }, 1100); })(piece);
    }
  }

  // Lightweight reusable toast for quick confirmations
  var zxToastTimer = null;
  function zxShowToast(message, type){
    var toast = document.getElementById('zxGlobalToast');
    if(!toast){
      toast = document.createElement('div');
      toast.id = 'zxGlobalToast';
      toast.className = 'zx-toast';
      toast.innerHTML = '<i class="fa-solid fa-circle-check"></i><span></span>';
      document.body.appendChild(toast);
    }
    var icon = toast.querySelector('i');
    var isError = type==='error';
    toast.classList.toggle('error', isError);
    if(icon) icon.className = isError ? 'fa-solid fa-circle-exclamation' : 'fa-solid fa-circle-check';
    toast.querySelector('span').textContent = message;
    clearTimeout(zxToastTimer);
    requestAnimationFrame(function(){ toast.classList.add('show'); });
    zxToastTimer = setTimeout(function(){ toast.classList.remove('show'); }, 2200);
  }

  window.confirmBuyBanner = function(){
    if(!pendingBuyBannerId) return;
    var b = null;
    for(var i=0;i<BANNERS.length;i++){ if(BANNERS[i].id===pendingBuyBannerId){ b = BANNERS[i]; break; } }
    if(!b) return;

    var confirmBtn = document.getElementById('buyBannerConfirmBtn');
    var cancelBtn = document.querySelector('#buyBannerModal .zx-btn-cancel');
    var modal = document.getElementById('buyBannerModal');
    if(!confirmBtn || confirmBtn.classList.contains('loading') || confirmBtn.classList.contains('success')) return;

    // Not enough diamond: shake instead of silently doing nothing
    if(getDiamond() < b.price){
      var note = document.getElementById('buyBannerBalanceNote');
      [modal, note].forEach(function(el){
        if(!el) return;
        el.classList.remove('shake'); void el.offsetWidth; el.classList.add('shake');
      });
      if(window.ZUSMO && window.ZUSMO.playClick) window.ZUSMO.playClick();
      setTimeout(function(){
        modal.classList.remove('shake');
        if(note) note.classList.remove('shake');
      }, 550);
      return;
    }

    var originalBtnHTML = confirmBtn.innerHTML;
    confirmBtn.classList.add('loading');
    confirmBtn.innerHTML = '<span class="zx-spinner"></span>';
    if(cancelBtn) cancelBtn.disabled = true;
    if(window.ZUSMO && window.ZUSMO.playClick) window.ZUSMO.playClick();

    // Brief "processing" beat before confirming, so it doesn't feel instant/flat
    setTimeout(function(){
      var startVal = getDiamond();
      var endVal = startVal - b.price;
      setDiamond(endVal);
      zxAnimateDiamondCount(startVal, endVal, 550);

      addHistoryEntry('buy', 'Beli Banner: '+b.name, 'Pembelian item di Toko Zusmo', -b.price);
      ownBanner(b.id);

      confirmBtn.classList.remove('loading');
      confirmBtn.classList.add('success');
      confirmBtn.innerHTML = '<i class="fa-solid fa-check"></i> Berhasil';

      modal.classList.add('pop-success');
      var thumb = modal.querySelector('.zx-modal-thumb');
      if(thumb) thumb.classList.add('zx-thumb-bounce');
      zxSpawnConfetti(modal);
      if(window.ZUSMO && window.ZUSMO.playClick) window.ZUSMO.playClick();

      var boughtId = b.id;

      setTimeout(function(){
        document.getElementById('buyBannerOverlay').classList.remove('open');
        pendingBuyBannerId = null;
        confirmBtn.classList.remove('success','loading','insufficient');
        confirmBtn.innerHTML = originalBtnHTML;
        if(cancelBtn) cancelBtn.disabled = false;
        modal.classList.remove('pop-success');
        if(thumb) thumb.classList.remove('zx-thumb-bounce');

        onSelectBanner(boughtId);
        var dGrid = document.getElementById('bannerDetailGrid');
        if(dGrid){
          var card = dGrid.querySelector('[data-banner-id="'+boughtId+'"]');
          if(card){
            card.classList.remove('locked');
            var lockEl = card.querySelector('.bd-lock'); if(lockEl) lockEl.remove();
            var priceEl = card.querySelector('.bd-price'); if(priceEl) priceEl.remove();
            card.classList.add('zx-just-bought');
            setTimeout(function(){ card.classList.remove('zx-just-bought'); }, 700);
          }
          updateBannerDetailActiveState();
        }
        zxShowToast('Banner "'+b.name+'" berhasil dibeli!');
      }, 950);
    }, 550);
  };
