  /* ================= END DIAMOND / SHOP / DAILY CLAIM SYSTEM ================= */

  function getBannerData(){
    var id = localStorage.getItem(LS_BANNER_ID) || 'sukuna';
    for(var i=0;i<BANNERS.length;i++){ if(BANNERS[i].id===id) return BANNERS[i]; }
    return BANNERS[0];
  }

  function renderBannerGrid(){
    var grid = document.getElementById('bannerGrid');
    if(!grid) return;
    var activeId = getBannerData().id;
    grid.innerHTML = BANNERS.map(function(b){
      var owned = isBannerOwned(b.id);
      var extra = owned ? '' :
        '<div class="banner-opt-lock"><i class="fa-solid fa-lock"></i></div>';
      return '<div class="banner-opt'+(b.id===activeId?' active':'')+(owned?'':' locked')+'" onclick="onSelectBanner(\''+b.id+'\')" title="'+b.name+'">'+
        '<div class="banner-opt-thumb"><img loading="lazy" decoding="async" src="'+b.img+'" alt="'+b.name+'"/></div>'+
        extra+
        '<div class="banner-opt-check"><i class="fa-solid fa-check"></i></div>'+
        '<div class="banner-opt-name">'+b.name+'</div>'+
      '</div>';
    }).join('');
  }

  var bannerDetailInitialized = false;
  var bannerFilterMode = 'all';
  var bannerDetailObserver = null;

  function renderBannerDetailGrid(){
    var grid = document.getElementById('bannerDetailGrid');
    if(!grid) return;
    var activeId = getBannerData().id;
    grid.innerHTML = BANNERS.map(function(b){
      var owned = isBannerOwned(b.id);
      var isActive = b.id===activeId;
      var extra = owned ? '' :
        '<div class="bd-lock"><i class="fa-solid fa-lock"></i></div>'+
        '<div class="bd-price"><img loading="lazy" decoding="async" src="'+DIAMOND_ICON+'" alt=""/>'+b.price+'</div>';
      var ownedBadge = (owned && b.price>0 && !isActive) ? '<div class="bd-owned">Dimiliki</div>' : '';
      return '<div class="banner-detail-card'+(isActive?' active':'')+(owned?'':' locked')+'" data-banner-id="'+b.id+'" onclick="onSelectBannerDetail(\''+b.id+'\')" title="'+b.name+'">'+
        '<img loading="lazy" decoding="async" class="bd-img" data-src="'+b.img+'" alt=""/>'+
        '<video class="bd-video" muted loop playsinline preload="none" data-src="'+b.video+'"></video>'+
        '<div class="bd-spinner"></div>'+
        extra+
        ownedBadge+
        '<div class="bd-check"><i class="fa-solid fa-check"></i></div>'+
        '<div class="bd-name">'+b.name+'</div>'+
      '</div>';
    }).join('');

    // Lazy load: nothing downloads until a card scrolls near the viewport.
    // Once a card is visible, its PNG loads first; the moment THAT banner's
    // own video finishes downloading enough to play smoothly, it swaps in
    // place (independently of the other cards, loaded or not).
    if(bannerDetailObserver) bannerDetailObserver.disconnect();

    function loadCard(card){
      var img = card.querySelector('.bd-img');
      var video = card.querySelector('.bd-video');
      if(img && !img.src && img.dataset.src){
        img.src = img.dataset.src;
        img.onload = function(){ card.classList.add('loaded'); };
      }
      if(video && !video.src && video.dataset.src){
        video.src = video.dataset.src;
        video.load();
        var onReady = function(){
          card.classList.add('video-ready');
          card.classList.add('loaded');
          var ov = document.getElementById('bannerDetailOverlay');
          if(ov && ov.classList.contains('open')){
            video.play().catch(function(){});
          }
          video.removeEventListener('canplaythrough', onReady);
        };
        video.addEventListener('canplaythrough', onReady);
      }
    }

    if('IntersectionObserver' in window){
      bannerDetailObserver = new IntersectionObserver(function(entries){
        entries.forEach(function(entry){
          if(entry.isIntersecting){
            loadCard(entry.target);
            bannerDetailObserver.unobserve(entry.target);
          }
        });
      }, { root: document.getElementById('bannerDetailBody') || null, rootMargin: '200px 0px', threshold: 0.01 });

      Array.prototype.forEach.call(grid.querySelectorAll('.banner-detail-card'), function(card){
        bannerDetailObserver.observe(card);
      });
    }else{
      // Fallback for browsers without IntersectionObserver: load everything.
      Array.prototype.forEach.call(grid.querySelectorAll('.banner-detail-card'), loadCard);
    }
    applyBannerFilter();
  }

  function updateBannerDetailActiveState(){
    var grid = document.getElementById('bannerDetailGrid');
    if(!grid) return;
    var activeId = getBannerData().id;
    Array.prototype.forEach.call(grid.querySelectorAll('.banner-detail-card'), function(card){
      var id = card.getAttribute('data-banner-id');
      var isActive = id===activeId;
      card.classList.toggle('active', isActive);
      var badge = card.querySelector('.bd-owned');
      var b = null;
      for(var i=0;i<BANNERS.length;i++){ if(BANNERS[i].id===id){ b = BANNERS[i]; break; } }
      if(b && b.price>0 && isBannerOwned(id)){
        if(isActive && badge){ badge.remove(); }
        else if(!isActive && !badge){
          var nb = document.createElement('div');
          nb.className = 'bd-owned';
          nb.textContent = 'Dimiliki';
          card.appendChild(nb);
        }
      }
    });
    applyBannerFilter();
  }

  function updateBannerStatsBar(){
    var totalEl = document.getElementById('bannerStatTotal');
    var ownedEl = document.getElementById('bannerStatOwned');
    if(totalEl) totalEl.textContent = BANNERS.length;
    if(ownedEl){
      var ownedCount = 0;
      for(var i=0;i<BANNERS.length;i++){ if(isBannerOwned(BANNERS[i].id)) ownedCount++; }
      ownedEl.textContent = ownedCount;
    }
  }

  function applyBannerFilter(){
    var grid = document.getElementById('bannerDetailGrid');
    if(!grid) return;
    var visibleCount = 0;
    Array.prototype.forEach.call(grid.querySelectorAll('.banner-detail-card'), function(card){
      var id = card.getAttribute('data-banner-id');
      var show = bannerFilterMode==='all' || isBannerOwned(id);
      card.style.display = show ? '' : 'none';
      if(show) visibleCount++;
    });
    var emptyEl = document.getElementById('bannerFilterEmpty');
    if(emptyEl) emptyEl.classList.toggle('show', bannerFilterMode==='owned' && visibleCount===0);
    updateBannerStatsBar();
  }

  window.onSetBannerFilter = function(mode){
    bannerFilterMode = mode;
    var allBtn = document.getElementById('bannerFilterAll');
    var ownedBtn = document.getElementById('bannerFilterOwned');
    if(allBtn) allBtn.classList.toggle('active', mode==='all');
    if(ownedBtn) ownedBtn.classList.toggle('active', mode==='owned');
    applyBannerFilter();
    playFilterSlideAnim('bannerDetailGrid', mode);
    if(window.ZUSMO && window.ZUSMO.playClick) window.ZUSMO.playClick();
  };

  window.openBannerDetail = function(){
    var elBd = document.getElementById('bannerDetailDiamondBalance');
    if(elBd) elBd.textContent = getDiamond();
    if(!bannerDetailInitialized){
      // First open: create the grid, images show immediately, videos start
      // downloading in the background per-card.
      renderBannerDetailGrid();
      bannerDetailInitialized = true;
    }else{
      // Re-opening: don't rebuild (keeps whatever already finished
      // downloading), just refresh which card is marked active.
      updateBannerDetailActiveState();
    }
    var ov = document.getElementById('bannerDetailOverlay');
    if(ov) ov.classList.add('open');
    var grid = document.getElementById('bannerDetailGrid');
    if(grid){
      // Resume playback for any cards whose video already finished loading.
      Array.prototype.forEach.call(grid.querySelectorAll('.banner-detail-card.video-ready .bd-video'), function(v){
        v.play().catch(function(){});
      });
    }
    if(window.ZUSMO && window.ZUSMO.playClick) window.ZUSMO.playClick();
  };

  window.closeBannerDetail = function(){
    var ov = document.getElementById('bannerDetailOverlay');
    if(ov) ov.classList.remove('open');
    var grid = document.getElementById('bannerDetailGrid');
    if(grid){
      // Pause videos while the page is closed (saves battery/CPU); the
      // already-downloaded data stays cached so it resumes instantly.
      Array.prototype.forEach.call(grid.querySelectorAll('.bd-video'), function(v){ v.pause(); });
    }
    if(window.ZUSMO && window.ZUSMO.playClick) window.ZUSMO.playClick();
  };

  window.onSelectBannerDetail = function(id){
    if(!isBannerOwned(id)){ openBuyBanner(id); return; }
    onSelectBanner(id);
    updateBannerDetailActiveState();
  };

  window.onSelectBanner = function(id){
    if(!isBannerOwned(id)){ openBuyBanner(id); return; }
    localStorage.setItem(LS_BANNER_ID, id);
    // Selecting a banner automatically switches to animated (with) version,
    // unless the user has explicitly turned Banner Animation off.
    if(getAnimasi()){
      applyBannerState(true);
    }else{
      applyBannerState(false);
    }
    renderBannerGrid();
    if(window.ZUSMO && window.ZUSMO.playClick) window.ZUSMO.playClick();
  };

