  // Generic lazy-load helper: an element with a data-src attribute only
  // gets its real src (and starts downloading) once its container scrolls
  // near the viewport. Safe to call repeatedly - it no-ops once loaded.
  function lazyLoadMedia(container, el){
    if(!el || !el.dataset || !el.dataset.src) return;
    if(el.getAttribute('src')) return; // already loaded
    var assign = function(){
      if(el.getAttribute('src')) return;
      el.src = el.dataset.src;
      if(el.tagName==='VIDEO'){
        el.load();
        el.play().catch(function(){});
      }
    };
    if(!('IntersectionObserver' in window)){
      assign();
      return;
    }
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(entry){
        if(entry.isIntersecting){
          assign();
          io.unobserve(entry.target);
        }
      });
    }, { rootMargin: '300px 0px', threshold: 0.01 });
    io.observe(container);
  }

  function applyBannerState(on){
    var wrap = document.querySelector('.hm-video-wrap');
    if(!wrap) return;
    var data = getBannerData();
    var existing = wrap.querySelector('video, img.hm-banner-img');
    if(on){
      if(existing && existing.tagName==='VIDEO' && existing.dataset.src===data.video){
        lazyLoadMedia(wrap, existing);
        return;
      }
      if(existing) existing.remove();
      var vid = document.createElement('video');
      vid.loop = true; vid.muted = true; vid.playsInline = true;
      vid.preload = 'none';
      vid.dataset.src = data.video;
      wrap.insertBefore(vid, wrap.firstChild);
      lazyLoadMedia(wrap, vid);
    }else{
      if(existing && existing.tagName==='IMG' && existing.dataset.src===data.img){
        lazyLoadMedia(wrap, existing);
        return;
      }
      if(existing) existing.remove();
      var img = document.createElement('img');
      img.className = 'hm-banner-img';
      img.loading = 'lazy';
      img.decoding = 'async';
      img.dataset.src = data.img;
      img.style.width='100%';
      img.style.height='100%';
      img.style.objectFit='cover';
      img.style.display='block';
      wrap.insertBefore(img, wrap.firstChild);
      lazyLoadMedia(wrap, img);
    }
  }

  function applyBlurState(on){
    var styleTag = document.getElementById('bgBlurOverrideStyle');
    if(!styleTag){
      styleTag = document.createElement('style');
      styleTag.id = 'bgBlurOverrideStyle';
      document.head.appendChild(styleTag);
    }
    styleTag.textContent = on ? '' : 'body:before{backdrop-filter:none !important;}';
  }

  function applyVolumeToMusic(vol){
    var frac = Math.max(0,Math.min(100,vol))/100;
    var bgEl = document.getElementById('bgMusic');
    if(bgEl) bgEl.volume = frac;
  }

  // Centralized sound + vibration API used across the app
  window.ZUSMO = window.ZUSMO || {};
  window.ZUSMO.playClick = function(){
    if(!getSfx()) return;
    try{
      var ctx = window._ctx || (window._ctx = new (window.AudioContext||window.webkitAudioContext)());
      if(ctx.state==='suspended') ctx.resume();
      var vol = getVolume()/100;
      var o=ctx.createOscillator(), g=ctx.createGain();
      o.type='triangle';
      o.frequency.setValueAtTime(1400,ctx.currentTime);
      o.frequency.exponentialRampToValueAtTime(700,ctx.currentTime+0.05);
      g.gain.setValueAtTime(0.25*vol,ctx.currentTime);
      g.gain.exponentialRampToValueAtTime(0.0001,ctx.currentTime+0.08);
      o.connect(g); g.connect(ctx.destination);
      o.start(); o.stop(ctx.currentTime+0.08);
    }catch(e){}
  };
  window.ZUSMO.vibrate = function(pattern){
    if(!getVibrate()) return;
    if(navigator.vibrate){
      try{ navigator.vibrate(pattern); }catch(e){}
    }
  };

