  function dtResetScope(scopeEl){
    if(!scopeEl) return;
    var pkgItems=scopeEl.querySelectorAll('.dt-pkg-item');
    pkgItems.forEach(function(it){it.classList.remove('selected');});
    var methods=scopeEl.querySelectorAll('.vpay-method');
    methods.forEach(function(m){m.classList.remove('selected');});
    var methodSection=scopeEl.querySelector('.dt-method-section');
    if(methodSection) methodSection.style.display='none';
    var confirmBtn=scopeEl.querySelector('.dt-confirm-btn');
    if(confirmBtn) confirmBtn.style.display='none';
    var summaryEl=scopeEl.querySelector('.dt-selected-summary');
    if(summaryEl) summaryEl.innerHTML='';
    var btn=scopeEl.querySelector('.dt-continue-btn');
    if(btn){btn.disabled=true;btn.classList.remove('ready');}
  }
  function dtUpdateContinueBtn(scopeEl){
    if(!scopeEl) return;
    var btn=scopeEl.querySelector('.dt-continue-btn');
    if(!btn) return;
    var ready=dtState.idx!==null && !!dtState.payment;
    btn.disabled=!ready;
    btn.classList.toggle('ready', ready);
  }
