    dtState.payment=null;
    var confirmBtn=scope.querySelector('.dt-confirm-btn');
    if(confirmBtn) confirmBtn.style.display='flex';
    var selectedPkgEl=scope.querySelector('.dt-pkg-item.selected');
    if(selectedPkgEl) selectedPkgEl.scrollIntoView({behavior:'smooth',block:'center'});
