(function(){
  var kb=document.getElementById('customKeyboard');
  var keysArea=document.getElementById('ckKeysArea');
  var backdrop=document.getElementById('ckBackdrop');
  var activeInput=null;
  var shift=false;
  var capsLock=false;
  var lastShiftTap=0;

  /* ===== Custom blinking caret (inputs are readonly, so native caret is unreliable) ===== */
  var caret=document.createElement('div');
  caret.id='ckCaret';
  document.body.appendChild(caret);
  var measureSpan=null;
  function getMeasurer(cs){
    if(!measureSpan){
      measureSpan=document.createElement('span');
      measureSpan.style.position='fixed';
      measureSpan.style.visibility='hidden';
      measureSpan.style.whiteSpace='pre';
      measureSpan.style.top='-9999px';
      measureSpan.style.left='-9999px';
      document.body.appendChild(measureSpan);
    }
    measureSpan.style.font=cs.font;
    measureSpan.style.letterSpacing=cs.letterSpacing;
    measureSpan.style.textTransform=cs.textTransform;
    return measureSpan;
  }
  function updateCaretPosition(){
    if(!activeInput || !kb.classList.contains('open')){
      caret.style.display='none';
      return;
    }
    var el=activeInput;
    var rect=el.getBoundingClientRect();
    if(rect.width===0 && rect.height===0){ caret.style.display='none'; return; }
    var cs=getComputedStyle(el);
    var pos=el.selectionStart!=null?el.selectionStart:(el.value||'').length;
    var textBefore=(el.value||'').substring(0,pos);
    var m=getMeasurer(cs);
    m.textContent=textBefore;
    var textWidth=m.getBoundingClientRect().width;
    var paddingLeft=parseFloat(cs.paddingLeft)||0;
    var paddingRight=parseFloat(cs.paddingRight)||0;
    var borderLeft=parseFloat(cs.borderLeftWidth)||0;
    var left=rect.left+borderLeft+paddingLeft+textWidth-(el.scrollLeft||0);
    var maxLeft=rect.right-paddingRight-1;
    if(left>maxLeft) left=maxLeft;
    if(left<rect.left) left=rect.left;
    var fontSize=parseFloat(cs.fontSize)||14;
    var vPad=Math.max(2,(rect.height-fontSize)/2-1);
    caret.style.left=left+'px';
    caret.style.top=(rect.top+vPad)+'px';
    caret.style.height=Math.max(10,rect.height-vPad*2)+'px';
    caret.style.display='block';
  }
  var caretLoopActive=false;
  function caretLoop(){
    if(!activeInput || !kb.classList.contains('open')){ caretLoopActive=false; return; }
    updateCaretPosition();
    requestAnimationFrame(caretLoop);
  }
  function startCaretLoop(){
    if(caretLoopActive) return;
    caretLoopActive=true;
    requestAnimationFrame(caretLoop);
  }
  /* ===== end custom caret ===== */

  var rowsAlpha=[
    ['1','2','3','4','5','6','7','8','9','0'],
    ['q','w','e','r','t','y','u','i','o','p'],
    ['a','s','d','f','g','h','j','k','l'],
    ['shift','z','x','c','v','b','n','m','back'],
    ['space','enter']
  ];
  var rowsNumeric=[
    ['1','2','3'],
    ['4','5','6'],
    ['7','8','9'],
    ['back','0','enter']
  ];

  var mode='alpha';

  function isNumericInput(el){
    if(!el) return false;
    var type=(el.getAttribute('type')||'').toLowerCase();
    var inputmode=(el.getAttribute('inputmode')||'').toLowerCase();
    return type==='number' || inputmode==='numeric' || inputmode==='decimal' || type==='tel';
  }

  function labelFor(k){
    if(k==='back') return '⌫';
    if(k==='enter') return '⏎';
    if(k==='shift') return '⇧';
    if(k==='space') return 'Spasi';
    return (shift||capsLock) ? k.toUpperCase() : k;
  }

  function classFor(k){
    if(k==='space') return 'ck-key space';
    if(k==='shift') return capsLock ? 'ck-key wide caps-on' : 'ck-key wide';
    if(k==='back') return 'ck-key wide';
    if(k==='enter') return 'ck-key enter';
    return 'ck-key';
  }

  function render(){
    var rows = mode==='numeric' ? rowsNumeric : rowsAlpha;

    keysArea.innerHTML='';
    rows.forEach(function(row){
      var rowEl=document.createElement('div');
      rowEl.className='ck-row';
      row.forEach(function(k){
        var btn=document.createElement('div');
        btn.className=classFor(k);
        btn.textContent=labelFor(k);
        var press=function(){
          btn.classList.add('pressed');
          if(window.ZUSMO){ try{window.ZUSMO.vibrate(8);}catch(e){} }
        };
        var release=function(){ btn.classList.remove('pressed'); stopRepeat(); };
        var repeatTimer=null, repeatInterval=null;
        var stopRepeat=function(){
          if(repeatTimer){ clearTimeout(repeatTimer); repeatTimer=null; }
          if(repeatInterval){ clearInterval(repeatInterval); repeatInterval=null; }
        };
        var startPress=function(){
          press();
          handleKey(k);
          if(k==='back'){
            stopRepeat();
            repeatTimer=setTimeout(function(){
              repeatInterval=setInterval(function(){
                handleKey(k);
                if(window.ZUSMO){ try{window.ZUSMO.vibrate(5);}catch(e){} }
              },45);
            },350);
          }
        };
        btn.addEventListener('touchstart',function(e){e.preventDefault();startPress();},{passive:false});
        btn.addEventListener('touchend',function(e){e.preventDefault();release();},{passive:false});
        btn.addEventListener('touchcancel',release);
        btn.addEventListener('mousedown',function(e){e.preventDefault();startPress();});
        btn.addEventListener('mouseup',release);
        btn.addEventListener('mouseleave',release);
        rowEl.appendChild(btn);
      });
      keysArea.appendChild(rowEl);
    });
  }

  function setNativeValue(el,value){
    var proto = el instanceof HTMLTextAreaElement ? window.HTMLTextAreaElement.prototype : window.HTMLInputElement.prototype;
    var setter = Object.getOwnPropertyDescriptor(proto,'value').set;
    setter.call(el,value);
    el.dispatchEvent(new Event('input',{bubbles:true}));
  }

  function insertAtCursor(el,text){
    var start=el.selectionStart!=null?el.selectionStart:el.value.length;
    var end=el.selectionEnd!=null?el.selectionEnd:el.value.length;
    var val=el.value||'';
    var newVal=val.slice(0,start)+text+val.slice(end);
    setNativeValue(el,newVal);
    var pos=start+text.length;
    try{el.setSelectionRange(pos,pos);}catch(e){}
    updateCaretPosition();
  }

  function backspaceAtCursor(el){
    var start=el.selectionStart!=null?el.selectionStart:el.value.length;
    var end=el.selectionEnd!=null?el.selectionEnd:el.value.length;
    var val=el.value||'';
    if(start===end){
      if(start===0) return;
      var newVal=val.slice(0,start-1)+val.slice(end);
      setNativeValue(el,newVal);
      try{el.setSelectionRange(start-1,start-1);}catch(e){}
    }else{
      var newVal2=val.slice(0,start)+val.slice(end);
      setNativeValue(el,newVal2);
      try{el.setSelectionRange(start,start);}catch(e){}
    }
    updateCaretPosition();
  }

  function handleKey(k){
    if(!activeInput) return;
    if(k==='back'){ backspaceAtCursor(activeInput); return; }
    if(k==='space'){ insertAtCursor(activeInput,' '); return; }
    if(k==='enter'){
      activeInput.blur();
      closeKeyboard();
      var form=activeInput.closest && activeInput.closest('form');
      if(form){ var evt; try{evt=new Event('submit',{cancelable:true});form.dispatchEvent(evt);}catch(e){} }
      return;
    }
    if(k==='shift'){
      var now=Date.now();
      if(now-lastShiftTap<350){
        capsLock=!capsLock;
        shift=false;
      }else{
        if(capsLock){ capsLock=false; shift=false; }
        else{ shift=!shift; }
      }
      lastShiftTap=now;
      render();
      return;
    }
    var ch=(shift||capsLock) ? k.toUpperCase() : k;
    insertAtCursor(activeInput,ch);
    if(shift && !capsLock){ shift=false; render(); }
  }

  function openKeyboard(el){
    activeInput=el;
    mode = isNumericInput(el) ? 'numeric' : 'alpha';
    shift=false;
    capsLock=false;
    render();
    kb.classList.add('open');
    backdrop.classList.add('open');
    var modalOv = el.closest && el.closest('.zx-modal-overlay');
    if(modalOv) modalOv.classList.add('kb-open');
    updateCaretPosition();
    startCaretLoop();
  }

  function closeKeyboard(){
    kb.classList.remove('open');
    backdrop.classList.remove('open');
    activeInput=null;
    caret.style.display='none';
    var openModals = document.querySelectorAll('.zx-modal-overlay.kb-open');
    Array.prototype.forEach.call(openModals, function(m){ m.classList.remove('kb-open'); });
  }

  document.getElementById('ckCloseBtn').addEventListener('click',function(){
    if(activeInput) activeInput.blur();
    closeKeyboard();
  });
  backdrop.addEventListener('click',function(){
    if(activeInput) activeInput.blur();
    closeKeyboard();
  });

  // Keyboard kustom OFF secara default -> pakai keyboard bawaan HP.
  // Diaktifkan lewat Pengaturan > Keyboard > "Keyboard Kustom Kzrizusmo".
  var enabled=false;

  function onFocusHandler(e){
    e.preventDefault();
    openKeyboard(this);
  }
  function onClickHandler(e){
    openKeyboard(this);
    setTimeout(updateCaretPosition,0);
  }

  function attachToInput(el){
    if(!enabled){
      detachFromInput(el);
      return;
    }
    if(el.dataset.ckAttached) return;
    el.dataset.ckAttached='1';
    if(el.hasAttribute('inputmode')) el.dataset.ckOrigInputmode=el.getAttribute('inputmode');
    el.setAttribute('readonly','readonly');
    el.setAttribute('inputmode','none');
    el.addEventListener('focus',onFocusHandler);
    el.addEventListener('click',onClickHandler);
  }

  function detachFromInput(el){
    if(!el.dataset.ckAttached) return;
    delete el.dataset.ckAttached;
    el.removeAttribute('readonly');
    if(el.dataset.ckOrigInputmode){
      el.setAttribute('inputmode',el.dataset.ckOrigInputmode);
      delete el.dataset.ckOrigInputmode;
    }else{
      el.removeAttribute('inputmode');
    }
    el.removeEventListener('focus',onFocusHandler);
    el.removeEventListener('click',onClickHandler);
  }

  function scanInputs(){
    var els=document.querySelectorAll('input[type="text"],input[type="number"],input[type="password"],input[type="tel"],input[type="email"],input[type="search"],input:not([type]),textarea');
    els.forEach(enabled ? attachToInput : detachFromInput);
  }

  document.addEventListener('DOMContentLoaded',scanInputs);
  window.addEventListener('load',scanInputs);
  var mo=new MutationObserver(function(){ scanInputs(); });
  mo.observe(document.body,{childList:true,subtree:true});

  // rescan periodically as a safety net for dynamically shown pages
  setInterval(scanInputs,1500);

  window.ZKB = {
    setEnabled: function(on){
      enabled = !!on;
      if(!enabled){
        if(activeInput) activeInput.blur();
        closeKeyboard();
      }
      scanInputs();
    },
    isEnabled: function(){ return enabled; }
  };
})();

(function(){
  var LATEST_NOTIF_ID = '2026-08-14-b'; // bump this whenever a new notif card is added, so old "seen" state resets
  var LS_SEEN_NOTIF = 'zusmo_seen_notif_id';
  var LS_SEEN_SETTINGS = 'zusmo_seen_settings';

  function refreshNotifDot(){
    var dot = document.getElementById('notifDot');
    if(!dot) return;
    var seen = localStorage.getItem(LS_SEEN_NOTIF);
    dot.classList.toggle('dot-show', seen !== LATEST_NOTIF_ID);
  }
  window.markNotifSeen = function(){
    localStorage.setItem(LS_SEEN_NOTIF, LATEST_NOTIF_ID);
    refreshNotifDot();
  };

  function refreshSettingsDot(){
    var dot = document.getElementById('settingsDot');
    if(!dot) return;
    dot.classList.toggle('dot-show', localStorage.getItem(LS_SEEN_SETTINGS) !== '1');
  }
  window.markSettingsSeen = function(){
    localStorage.setItem(LS_SEEN_SETTINGS, '1');
    refreshSettingsDot();
  };

  document.addEventListener('DOMContentLoaded', function(){
    refreshNotifDot();
    refreshSettingsDot();
  });
})();

/* ================= MEDIA CACHE (Service Worker) =================
   Nyimpen gambar/video/audio/font di cache browser biar pas dibuka
   lagi loading-nya langsung instan, gak download ulang dari internet
   sama sekali — walau app ditutup total / dihapus dari recent apps.
   WAJIB: upload file sw.js di folder yang SAMA dengan index.html ini. */
if('serviceWorker' in navigator){
  window.addEventListener('load',function(){
    navigator.serviceWorker.register('sw.js').catch(function(err){
      console.warn('SW gagal daftar (media cache nonaktif):',err);
    });
  });
}
// Minta browser jangan pernah auto-hapus cache ini walau storage device
// lagi menipis, biar media yang udah ke-cache aman kesimpen selamanya.
if(navigator.storage && navigator.storage.persist){
  navigator.storage.persist().catch(function(){});
}

