    function hardHideScreen(screen) {
      if (!screen) return;
      screen.classList.remove('active');
      screen.setAttribute('aria-hidden', 'true');
      screen.style.display = 'none';
      screen.style.visibility = 'hidden';
      screen.style.pointerEvents = 'none';
    }

    function hardShowScreen(screen) {
      if (!screen) return;
      screen.style.display = 'block';
      screen.style.visibility = 'visible';
      screen.style.pointerEvents = 'auto';
      void screen.offsetHeight;
      screen.classList.add('active');
      screen.setAttribute('aria-hidden', 'false');
    }

    function initHackerRain() {
      if (!hackerRain || hackerRain.dataset.ready === '1') return;
      hackerRain.dataset.ready = '1';

      const snippets = [
        'root@zusmo:~$ run',
        'ACCESS_GRANTED',
        '01001010 10110100',
        'proxy.connect()',
        'ssh shadow@vpn',
        'encrypt_packet();',
        'ZUSMO::ACTIVE',
        'TOKEN_SCAN_OK',
        'GATEWAY_LOCKED',
        '{ auth: true }'
      ];

      const totalStreams = window.innerWidth <= 380 ? 8 : 12;
      const fragment = document.createDocumentFragment();

      for (let i = 0; i < totalStreams; i += 1) {
        const stream = document.createElement('span');
        stream.className = 'code-stream';
        if (i % 5 === 0) stream.classList.add('red-code');
        if (i % 9 === 0) stream.classList.add('bright-code');

        const textPack = Array.from({ length: 2 }, () => snippets[Math.floor(Math.random() * snippets.length)]).join('  //  ');
        stream.textContent = textPack;
        stream.style.left = ((i / totalStreams) * 100 + Math.random() * 4 - 2).toFixed(2) + '%';
        stream.style.setProperty('--fall-speed', (32 + Math.random() * 16).toFixed(2) + 's');
        stream.style.setProperty('--fall-delay', (-Math.random() * 36).toFixed(2) + 's');
        stream.style.setProperty('--stream-size', (8 + Math.random() * 2.5).toFixed(1) + 'px');
        stream.style.setProperty('--stream-opacity', (0.18 + Math.random() * 0.16).toFixed(2));
        fragment.appendChild(stream);
      }

      hackerRain.appendChild(fragment);
    }

    let hackerAudioCtx = null;
    let clickFlashTimer = null;

    function playHackerClick() {
      try {
        const AudioContextClass = window.AudioContext || window.webkitAudioContext;
        if (!AudioContextClass) return;
        if (!hackerAudioCtx) hackerAudioCtx = new AudioContextClass();
        if (hackerAudioCtx.state === 'suspended') hackerAudioCtx.resume();

        const now = hackerAudioCtx.currentTime;
        const gain = hackerAudioCtx.createGain();
        const filter = hackerAudioCtx.createBiquadFilter();
        const osc = hackerAudioCtx.createOscillator();
        const noiseBuffer = hackerAudioCtx.createBuffer(1, Math.floor(hackerAudioCtx.sampleRate * 0.035), hackerAudioCtx.sampleRate);
        const noiseData = noiseBuffer.getChannelData(0);
        for (let i = 0; i < noiseData.length; i += 1) {
          noiseData[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / noiseData.length, 2.2);
        }
        const noise = hackerAudioCtx.createBufferSource();
        noise.buffer = noiseBuffer;

        filter.type = 'bandpass';
        filter.frequency.setValueAtTime(1800, now);
        filter.Q.setValueAtTime(8, now);
        osc.type = 'square';
        osc.frequency.setValueAtTime(820, now);
        osc.frequency.exponentialRampToValueAtTime(360, now + 0.045);
        gain.gain.setValueAtTime(0.0001, now);
        gain.gain.exponentialRampToValueAtTime(0.075, now + 0.006);
        gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.06);

        osc.connect(filter);
        noise.connect(filter);
        filter.connect(gain);
        gain.connect(hackerAudioCtx.destination);
        osc.start(now);
        noise.start(now);
        osc.stop(now + 0.065);
        noise.stop(now + 0.045);
      } catch (error) {
        // Sound is optional and can be blocked by browser settings.
      }
    }

    function flashHackerTap(event) {
      if (!hackerClickFlash) return;
      const phone = document.querySelector('.phone');
      const rect = phone ? phone.getBoundingClientRect() : { left: 0, top: 0, width: window.innerWidth, height: window.innerHeight };
      const clientX = event && typeof event.clientX === 'number' ? event.clientX : rect.left + rect.width / 2;
      const clientY = event && typeof event.clientY === 'number' ? event.clientY : rect.top + rect.height / 2;
      hackerClickFlash.style.setProperty('--tap-x', ((clientX - rect.left) / Math.max(rect.width, 1) * 100).toFixed(2) + '%');
      hackerClickFlash.style.setProperty('--tap-y', ((clientY - rect.top) / Math.max(rect.height, 1) * 100).toFixed(2) + '%');
      hackerClickFlash.classList.add('show');
      clearTimeout(clickFlashTimer);
      clickFlashTimer = setTimeout(() => hackerClickFlash.classList.remove('show'), 145);
    }

